const ASSET_SUMMARY_STORAGE_KEY = "lms.assetSummaryCollapsed.v1";
const ASSET_FILTER_STORAGE_KEY = "lms.assetFiltersCollapsed.v1";

const $ = (id) => document.getElementById(id);
const esc = (v) => String(v ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#039;" }[c]));
const money = (n) => {
  const value = Number(n || 0);
  const accountingValue = Math.abs(value) <= 0.0050001 ? 0 : Math.round((value + Number.EPSILON) * 100) / 100;
  return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(accountingValue);
};
const today = () => new Date().toISOString().slice(0, 10);
const localToday = () => dateTimeLocalValue(new Date().toISOString()).slice(0, 10);

boot().catch((error) => {
  console.error("LMS Imports startup failed", error);

  // Keep the shell usable even when authentication, profile loading, or a
  // remote request fails during startup. Previously an unhandled rejection
  // left users on a completely empty Dashboard with no navigation.
  try {
    renderNav();
  } catch (navError) {
    console.error("Could not render navigation after startup failure", navError);
  }

  const content = $("content");
  if (content) {
    const message = escapeHtml(error?.message || "The application could not finish loading.");
    content.innerHTML = `
      <section class="card" style="max-width:760px;margin:24px auto;padding:24px;">
        <h2>Unable to finish loading</h2>
        <p>The application encountered a startup problem. Your data was not changed.</p>
        <p class="muted">${message}</p>
        <button class="primary" type="button" onclick="window.location.reload()">Try again</button>
      </section>`;
  }
});

async function boot() {
  const publicScan = hasAssetHash();
  renderNav();
  bindChrome();
  const { data } = await supabase.auth.getSession();
  session = data.session;
  if (session) await loadProfile();
  if (session) await loadAccountingCloseDate();
  renderNav();
  updateAuthView();
  if (publicScan) {
    await handleAssetHash();
  } else if (session) {
    await loadView(defaultView());
    await handleSharedDocumentHash();
  }
  window.addEventListener("hashchange", async () => {
    if (hasAssetHash()) await handleAssetHash();
    else if (session) await handleSharedDocumentHash();
  });
}

