function parsePastedDate(value) {
  const text = String(value || "").trim();
  if (!text) return "";

  let year;
  let month;
  let day;
  let match = text.match(/^(\d{4})[\/.\-](\d{1,2})[\/.\-](\d{1,2})$/);
  if (match) {
    [, year, month, day] = match;
  } else {
    match = text.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2}|\d{4})$/);
    if (match) {
      [, month, day, year] = match;
      if (year.length === 2) year = Number(year) >= 70 ? `19${year}` : `20${year}`;
    } else {
      const parsed = new Date(text);
      if (Number.isNaN(parsed.getTime())) return null;
      year = parsed.getFullYear();
      month = parsed.getMonth() + 1;
      day = parsed.getDate();
    }
  }

  year = Number(year);
  month = Number(month);
  day = Number(day);
  if (!Number.isInteger(year) || year < 1000 || year > 9999 || month < 1 || month > 12 || day < 1 || day > 31) return null;
  const candidate = new Date(year, month - 1, day);
  if (candidate.getFullYear() !== year || candidate.getMonth() !== month - 1 || candidate.getDate() !== day) return null;
  return `${String(year).padStart(4, "0")}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
}

function setupFlexibleDatePasteControls() {
  document.addEventListener("paste", (event) => {
    const input = event.target;
    if (!(input instanceof HTMLInputElement) || input.type !== "date" || input.disabled || input.readOnly) return;
    const pasted = event.clipboardData?.getData("text")?.trim() || "";
    if (!pasted) return;

    event.preventDefault();
    const parsed = parsePastedDate(pasted);
    if (!parsed) {
      input.setCustomValidity(`"${pasted}" is not a valid date. Paste a date such as MM/DD/YYYY.`);
      input.reportValidity();
      return;
    }

    input.setCustomValidity("");
    input.value = parsed;
    input.dispatchEvent(new Event("input", { bubbles: true }));
    input.dispatchEvent(new Event("change", { bubbles: true }));
  }, true);

  document.addEventListener("input", (event) => {
    const input = event.target;
    if (input instanceof HTMLInputElement && input.type === "date") input.setCustomValidity("");
  }, true);
}

function isPartsOrLaborNumberInput(input) {
  if (!(input instanceof HTMLInputElement) || input.type !== "number") return false;
  const fieldIdentity = [
    input.name,
    input.id,
    ...Object.values(input.dataset || {}),
    input.dataset.field,
    input.dataset.adminPart,
    input.dataset.laborField,
    input.dataset.clockPart,
    input.dataset.partRequestReview,
    input.dataset.acceptPart,
    input.dataset.issueNow,
    input.dataset.shipNow,
  ].filter(Boolean).join(" ").toLowerCase();
  const quantityOrLaborField = /qty|quantity|accepted|needed|hours?|hourly.?rate|unit.?cost|selling.?price|markup/.test(fieldIdentity);
  const context = input.closest("[data-admin-part-row], [data-labor-row], #clockPartBody, #adminPartBody, .parts-requested, .parts-section, .labor-section, [data-partial-line]");
  return quantityOrLaborField || Boolean(context);
}

function setupPositivePartsAndLaborControls() {
  const applyMinimum = (root = document) => {
    root.querySelectorAll?.('input[type="number"]').forEach((input) => {
      if (!isPartsOrLaborNumberInput(input)) return;
      input.min = "0";
      input.inputMode = "decimal";
    });
  };
  applyMinimum();
  document.addEventListener("keydown", (event) => {
    const input = event.target;
    if (!isPartsOrLaborNumberInput(input)) return;
    if (event.key === "-" || event.key === "Subtract") event.preventDefault();
  }, true);
  document.addEventListener("input", (event) => {
    const input = event.target;
    if (!isPartsOrLaborNumberInput(input)) return;
    input.setCustomValidity("");
    if (input.value !== "" && Number(input.value) < 0) {
      input.value = "";
      input.setCustomValidity("Negative values are not allowed. Enter a positive quantity or amount.");
    }
  }, true);
  document.addEventListener("change", (event) => {
    const input = event.target;
    if (!isPartsOrLaborNumberInput(input)) return;
    if (input.value !== "" && Number(input.value) < 0) {
      input.value = "";
      input.setCustomValidity("Negative values are not allowed. Enter a positive quantity or amount.");
      input.reportValidity();
    }
  }, true);
  new MutationObserver((mutations) => {
    mutations.forEach((mutation) => mutation.addedNodes.forEach((node) => {
      if (!(node instanceof Element)) return;
      if (node.matches?.('input[type="number"]') && isPartsOrLaborNumberInput(node)) {
        node.min = "0";
        node.inputMode = "decimal";
      }
      applyMinimum(node);
    }));
  }).observe(document.body, { childList: true, subtree: true });
}

function setModalMaximized(maximized) {
  const modal = $("modal");
  const box = modal?.querySelector(".modalbox");
  const button = $("modalMaximize");
  if (!modal || !box || !button) return;
  box.classList.toggle("maximized-modal", Boolean(maximized));
  modal.classList.toggle("modal-is-maximized", Boolean(maximized));
  button.textContent = maximized ? "Restore" : "Maximize";
  button.setAttribute("aria-label", maximized ? "Restore popup size" : "Maximize popup");
  button.title = maximized ? "Restore popup size" : "Maximize popup";
}

function toggleModalMaximize() {
  const box = $("modal")?.querySelector(".modalbox");
  setModalMaximized(!box?.classList.contains("maximized-modal"));
}

function setupModalResizeControls() {
  const modal = $("modal");
  const box = modal?.querySelector(".modalbox");
  if (!modal || !box || box.dataset.resizeBound === "1") return;
  box.dataset.resizeBound = "1";
  box.querySelectorAll("[data-modal-resize]").forEach((handle) => {
    handle.addEventListener("pointerdown", (event) => {
      if (window.matchMedia("(max-width: 640px)").matches || box.classList.contains("maximized-modal")) return;
      event.preventDefault();
      const edge = handle.dataset.modalResize || "se";
      const rect = box.getBoundingClientRect();
      const startX = event.clientX;
      const startY = event.clientY;
      const minimumWidth = Math.min(520, window.innerWidth - 16);
      const minimumHeight = Math.min(320, window.innerHeight - 16);
      box.style.position = "fixed";
      box.style.left = `${rect.left}px`;
      box.style.top = `${rect.top}px`;
      box.style.width = `${rect.width}px`;
      box.style.height = `${rect.height}px`;
      box.style.maxWidth = "none";
      box.style.maxHeight = "none";
      document.body.classList.add("modal-resizing");
      handle.setPointerCapture?.(event.pointerId);

      const move = (moveEvent) => {
        const dx = moveEvent.clientX - startX;
        const dy = moveEvent.clientY - startY;
        let left = rect.left;
        let top = rect.top;
        let width = rect.width;
        let height = rect.height;
        if (edge.includes("e")) width = Math.min(window.innerWidth - rect.left - 4, Math.max(minimumWidth, rect.width + dx));
        if (edge.includes("s")) height = Math.min(window.innerHeight - rect.top - 4, Math.max(minimumHeight, rect.height + dy));
        if (edge.includes("w")) {
          left = Math.max(4, Math.min(rect.right - minimumWidth, rect.left + dx));
          width = rect.right - left;
        }
        if (edge.includes("n")) {
          top = Math.max(4, Math.min(rect.bottom - minimumHeight, rect.top + dy));
          height = rect.bottom - top;
        }
        box.style.left = `${left}px`;
        box.style.top = `${top}px`;
        box.style.width = `${width}px`;
        box.style.height = `${height}px`;
      };
      const stop = () => {
        document.removeEventListener("pointermove", move);
        document.removeEventListener("pointerup", stop);
        document.removeEventListener("pointercancel", stop);
        document.body.classList.remove("modal-resizing");
      };
      document.addEventListener("pointermove", move);
      document.addEventListener("pointerup", stop);
      document.addEventListener("pointercancel", stop);
    });
  });
}

function makePopupMovable(box, handle) {
  if (!box || !handle || box.dataset.moveBound === "1") return;
  box.dataset.moveBound = "1";
  handle.classList.add("movable-popup-handle");
  handle.addEventListener("pointerdown", (event) => {
    if (event.button !== 0 || event.target.closest("button, input, select, textarea, a") || box.classList.contains("maximized-modal") || box.closest(".maximized")) return;
    if (window.matchMedia("(max-width: 640px)").matches) return;
    event.preventDefault();
    const rect = box.getBoundingClientRect();
    const startX = event.clientX;
    const startY = event.clientY;
    box.style.position = "fixed";
    box.style.left = `${rect.left}px`;
    box.style.top = `${rect.top}px`;
    box.style.margin = "0";
    box.style.maxWidth = "none";
    handle.setPointerCapture?.(event.pointerId);
    document.body.classList.add("popup-moving");
    const move = (moveEvent) => {
      const maxLeft = Math.max(4, window.innerWidth - box.offsetWidth - 4);
      const maxTop = Math.max(4, window.innerHeight - Math.min(box.offsetHeight, 90) - 4);
      box.style.left = `${Math.max(4, Math.min(maxLeft, rect.left + moveEvent.clientX - startX))}px`;
      box.style.top = `${Math.max(4, Math.min(maxTop, rect.top + moveEvent.clientY - startY))}px`;
    };
    const stop = () => {
      document.removeEventListener("pointermove", move);
      document.removeEventListener("pointerup", stop);
      document.removeEventListener("pointercancel", stop);
      document.body.classList.remove("popup-moving");
    };
    document.addEventListener("pointermove", move);
    document.addEventListener("pointerup", stop);
    document.addEventListener("pointercancel", stop);
  });
}

function setupMovablePopups() {
  const bind = (root = document) => {
    const modalBox = root.matches?.(".modalbox") ? root : root.querySelector?.(".modalbox");
    if (modalBox) makePopupMovable(modalBox, modalBox.querySelector(".modalhead"));
    const quickDialogs = [
      ...(root.matches?.(".quick-part-dialog") ? [root] : []),
      ...(root.querySelectorAll?.(".quick-part-dialog") || []),
    ];
    quickDialogs.forEach((dialog) => makePopupMovable(dialog, dialog.querySelector(":scope > header")));
  };
  bind();
  new MutationObserver((mutations) => mutations.forEach((mutation) => mutation.addedNodes.forEach((node) => {
    if (node instanceof Element) bind(node);
  }))).observe(document.body, { childList: true, subtree: true });
}

function documentReferenceType(value) {
  const ref = String(value || "").trim();
  if (/^PO-\d+$/i.test(ref)) return "purchasing";
  if (/^SO-\d+$/i.test(ref)) return "orders";
  if (/^(?:WO-\d+|W\d{5,})$/i.test(ref)) return "repairs";
  return "";
}

function enhanceDocumentReferenceLinks(root = $("content")) {
  if (!root) return;
  root.querySelectorAll("td, dd, small, .badge").forEach((element) => {
    if (element.dataset.documentReferenceEnhanced === "1" || element.closest("button, a, input, select, textarea")) return;
    if (element.children.length) return;
    const ref = String(element.textContent || "").trim();
    const view = documentReferenceType(ref);
    if (!view) return;
    element.dataset.documentReferenceEnhanced = "1";
    element.innerHTML = `<button type="button" class="document-reference-link" data-document-reference="${esc(ref)}" data-document-view="${esc(view)}" title="Open ${esc(ref)}">${esc(ref)}</button>`;
  });
}

async function handleDocumentReferenceClick(event) {
  const button = event.target.closest?.("[data-document-reference]");
  if (!button) return;
  event.preventDefault();
  event.stopPropagation();
  const ref = String(button.dataset.documentReference || "").trim();
  const view = button.dataset.documentView || documentReferenceType(ref);
  if (!view || !canAccess(view)) return alert(`Your user does not have access to open ${ref}.`);
  const returnState = captureDocumentReturnState();
  if (view === "invoices") {
    const documentData = await loadCustomerInvoiceDocument(ref);
    if (!documentData?.inv) return alert(`Invoice ${ref} was not found.`);
    await openInvoiceModal(documentData.inv, true);
    return installDocumentReturnAction(returnState);
  }
  await loadView(view);
  if (view === "purchasing") {
    const row = (currentRows || []).find((item) => String(item.po_no || "").toLowerCase() === ref.toLowerCase());
    if (row) {
      await openPurchaseOrderRecord(row);
      return installDocumentReturnAction(returnState);
    }
  }
  if (view === "receipts") {
    const rows = (currentRows || []).filter((item) => {
      const grNo = String(item.gr_no || "").toLowerCase();
      const target = ref.toLowerCase();
      return grNo === target || grNo.startsWith(`${target}-`);
    });
    if (rows.length) {
      await openGoodsReceiptRecord(rows, ref);
      return installDocumentReturnAction(returnState);
    }
  }
  if (view === "orders") {
    const row = (currentRows || []).find((item) => String(item.order_no || "").toLowerCase() === ref.toLowerCase());
    if (row) {
      await openSalesOrderModal(row);
      return installDocumentReturnAction(returnState);
    }
  }
  if (view === "repairs") {
    const row = (currentRows || []).find((item) => String(item.wo_no || "").toLowerCase() === ref.toLowerCase());
    if (row) {
      await openWorkOrderEditModal(row);
      return installDocumentReturnAction(returnState);
    }
  }
  if (view === "quotes") {
    const row = (currentRows || []).find((item) => String(item.quote_no || "").toLowerCase() === ref.toLowerCase());
    if (row) {
      await openQuotationModal(row);
      return installDocumentReturnAction(returnState);
    }
  }
  await restoreDocumentReturnState(returnState);
  alert(`${ref} was not found in the current records.`);
}

function captureDocumentReturnState() {
  const controls = [...document.querySelectorAll("#content input, #content select")]
    .filter((control) => control.id || control.name || control.dataset.col !== undefined)
    .map((control) => ({
      id: control.id || "",
      name: control.name || "",
      col: control.dataset.col,
      className: control.className || "",
      value: control.value,
      checked: control.checked,
    }));
  return { view: currentView, controls };
}

async function restoreDocumentReturnState(state) {
  closeModal();
  if (!state?.view) return;
  await loadView(state.view);
  (state.controls || []).forEach((saved) => {
    let control = saved.id ? document.getElementById(saved.id) : null;
    if (!control && saved.name) control = document.querySelector(`#content [name="${CSS.escape(saved.name)}"]`);
    if (!control && saved.col !== undefined) {
      const selector = saved.className.includes("column-sort") ? ".column-sort" : ".column-filter";
      control = document.querySelector(`#content ${selector}[data-col="${CSS.escape(String(saved.col))}"]`);
    }
    if (!control) return;
    control.value = saved.value;
    if ("checked" in control) control.checked = saved.checked;
    control.dispatchEvent(new Event(control.tagName === "SELECT" ? "change" : "input", { bubbles: true }));
  });
}

function installDocumentReturnAction(state) {
  const cancel = $("modalCancel");
  if (!cancel || $("modal").style.display === "none") return;
  cancel.textContent = "Back to previous screen";
  cancel.onclick = () => restoreDocumentReturnState(state);
}

function createPartButtonMarkup(label = "Create new part") {
  return `<button class="rowbtn" type="button" data-create-part>${esc(label)}</button>`;
}

function handleCreatePartButtonClick(event) {
  const button = event.target.closest("[data-create-part]");
  if (!button) return;
  event.preventDefault();
  event.stopPropagation();
  openQuickPartOverlay();
}

function moduleSearchStorageKey(input) {
  const field = input.id || input.name || input.placeholder || "search";
  return `${transientViewEpoch}:${currentView}:${field}`;
}

function isPersistentModuleSearch(input) {
  return input instanceof HTMLInputElement
    && input.closest("#content")
    && !input.closest("#modal")
    && (input.matches(".searchbox, input[type='search']") || input.id === "search" || /search/i.test(input.placeholder || ""));
}

function rememberModuleSearch(event) {
  const input = event.target;
  if (!isPersistentModuleSearch(input)) return;
  transientModuleSearchState.set(moduleSearchStorageKey(input), input.value || "");
}

function restoreModuleSearches() {
  document.querySelectorAll("#content input").forEach((input) => {
    if (!isPersistentModuleSearch(input) || input.dataset.searchRestored === "1" || input.value) return;
    input.dataset.searchRestored = "1";
    const saved = transientModuleSearchState.get(moduleSearchStorageKey(input));
    if (!saved) return;
    input.value = saved;
    input.dispatchEvent(new Event("input", { bubbles: true }));
  });
}

function clearTransientViewState() {
  transientViewEpoch += 1;
  transientModuleSearchState.clear();
  transientTableFilterState.clear();
  productColumnFilterState = {};
  productColumnExcelFilterState = {};
}

function transientTableKey(wrap) {
  const table = wrap?.querySelector?.("table");
  if (!table) return "";
  const heads = [...table.querySelectorAll("thead tr:first-child th")].map((th) => getHeaderLabel(th)).join("|");
  const peers = [...document.querySelectorAll("#content .table-wrap")];
  return `${transientViewEpoch}:${currentView}:${peers.indexOf(wrap)}:${heads}`;
}

function rememberTransientTableState(wrap) {
  const key = transientTableKey(wrap);
  if (key) transientTableFilterState.set(key, collectCurrentTableView(wrap));
}

function restoreTransientTableState(wrap) {
  const state = transientTableFilterState.get(transientTableKey(wrap));
  if (!state) return;
  wrap.querySelectorAll(".column-filter").forEach((input) => {
    const saved = state.filters?.find((item) => item.col === (input.dataset.col || ""));
    input.value = saved?.value || "";
    setSelectedExcelFilterValues(input, saved?.selected || []);
  });
  wrap.querySelectorAll(".column-sort").forEach((select) => {
    select.value = state.sorts?.find((item) => item.col === (select.dataset.col || ""))?.value || "";
  });
  wrap.classList.toggle("filters-hidden", !!state.filtersHidden);
  tableFilterRows(wrap).forEach((row) => { row.hidden = !!state.filtersHidden; });
  const button = wrap.previousElementSibling?.querySelector?.("[data-toggle-table-filters]");
  if (button) button.textContent = state.filtersHidden ? "Show filters" : "Hide filters";
  applyColumnFilters({ target: wrap.querySelector("table") });
}

function initializeCollapsedSections(root = document) {
  root?.querySelectorAll?.("details:not([data-collapse-initialized])").forEach((details) => {
    if (details.matches(".nav-major, .action-menu, .row-action-menu, .table-view-menu")) return;
    details.dataset.collapseInitialized = "1";
    details.removeAttribute("open");
  });
}

function resetOpenModalToTop() {
  const body = $("modalBody");
  const box = document.querySelector(".modalbox");
  const reset = () => {
    if ($("modal")) $("modal").scrollTop = 0;
    if (body) body.scrollTop = 0;
    if (box) box.scrollTop = 0;
  };
  reset();
  requestAnimationFrame(reset);
  initializeCollapsedSections(body);
}

function userColumnPreferenceStorageKey() {
  const userKey = String(profile?.id || profile?.email || session?.user?.id || session?.user?.email || "anonymous").toLowerCase();
  return `lms.columnPreferences.${userKey}`;
}

function userColumnPreferences() {
  const remote = profile?.column_preferences;
  if (remote && typeof remote === "object" && !Array.isArray(remote)) return { ...remote };
  try { return JSON.parse(localStorage.getItem(userColumnPreferenceStorageKey()) || "{}") || {}; } catch { return {}; }
}

function tableColumnLabels(table) {
  return [...(table?.querySelectorAll("thead tr:first-child th") || [])].map((th, index) => String(th.textContent || "").trim() || `Column ${index + 1}`);
}

function tableColumnPreferenceKey(table, tableIndex, scope = currentView) {
  return `${scope}|${tableIndex}|${tableColumnLabels(table).join("~")}`;
}

function applyTableHiddenColumns(table, hiddenLabels = []) {
  const hidden = new Set(hiddenLabels || []);
  const labels = tableColumnLabels(table);
  labels.forEach((label, index) => {
    const shouldHide = hidden.has(label);
    table.querySelectorAll("tr").forEach((row) => {
      const cell = row.children[index];
      if (cell) cell.style.display = shouldHide ? "none" : "";
    });
  });
}

function applySavedColumnPreferences(root = $("content")) {
  if (!root) return;
  const preferences = userColumnPreferences();
  [...root.querySelectorAll("table")].forEach((table, index) => {
    applyTableHiddenColumns(table, preferences[tableColumnPreferenceKey(table, index)] || []);
  });
}

function openCurrentViewColumnSettings() {
  const tables = [...$("content")?.querySelectorAll("table") || []].filter((table) => tableColumnLabels(table).length > 1);
  if (!tables.length) return alert("This screen does not currently contain a table with configurable columns.");
  const preferences = userColumnPreferences();
  $("modalTitle").textContent = `Show / Hide Columns - ${$("viewTitle")?.textContent || currentView}`;
  $("modalBody").innerHTML = tables.map((table, tableIndex) => {
    const labels = tableColumnLabels(table);
    const key = tableColumnPreferenceKey(table, tableIndex);
    const hidden = new Set(preferences[key] || []);
    return `<section class="subpanel column-settings-table" data-column-table-key="${esc(key)}"><div class="panel-title"><strong>Table ${tableIndex + 1}</strong><span>${esc(labels.slice(0, 4).join(" · "))}</span></div><div class="column-chooser">${labels.map((label, index) => `<label class="checkline"><input type="checkbox" data-user-column-label="${esc(label)}" ${hidden.has(label) ? "" : "checked"}> ${esc(label)}</label>`).join("")}</div></section>`;
  }).join("") + `<p class="notice">Unchecked columns collapse completely to save screen space. These choices are saved for your user and this specific module/table.</p><div class="actions"><button type="button" id="resetCurrentViewColumnsBtn">Reset all columns on this screen</button></div>`;
  $("modalSave").style.display = "";
  $("modalSave").textContent = "Save Column Layout";
  $("modalSave").onclick = saveCurrentViewColumnSettings;
  $("modalCancel").textContent = "Cancel";
  $("modal").style.display = "flex";
  $("resetCurrentViewColumnsBtn").onclick = () => document.querySelectorAll('[data-user-column-label]').forEach((input) => { input.checked = true; });
}

async function saveCurrentViewColumnSettings() {
  const preferences = userColumnPreferences();
  document.querySelectorAll("[data-column-table-key]").forEach((section) => {
    preferences[section.dataset.columnTableKey] = [...section.querySelectorAll("[data-user-column-label]")]
      .filter((input) => !input.checked)
      .map((input) => input.dataset.userColumnLabel);
  });
  localStorage.setItem(userColumnPreferenceStorageKey(), JSON.stringify(preferences));
  if (profile) profile.column_preferences = preferences;
  if (profile?.id) {
    await updateOneWithOptionalColumns("app_profiles", { column_preferences: preferences }, "id", profile.id, ["column_preferences"], "Column layout saved on this device. Run the user-column-preferences SQL migration to save it across devices.");
  }
  closeModal(true);
  applySavedColumnPreferences($("content"));
}

function setupModalSafetyControls() {
  const modal = $("modal");
  const body = $("modalBody");
  const save = $("modalSave");
  const draft = $("modalDraft");
  if (!modal || modal.dataset.safetyBound === "1") return;
  modal.dataset.safetyBound = "1";

  const noteUserEdit = (event) => {
    if (!event.isTrusted || modal.style.display === "none") return;
    if (!event.target.matches?.("input, select, textarea")) return;
    modalDirty = true;
    event.target.classList.remove("field-error");
    body.querySelector(".modal-validation-summary")?.remove();
    if (modalSaveInProgress) resetModalSaveButton();
  };
  modal.addEventListener("input", noteUserEdit, true);
  modal.addEventListener("change", noteUserEdit, true);

  save.addEventListener("click", (event) => {
    if (modalSaveInProgress) {
      event.preventDefault();
      event.stopImmediatePropagation();
      return;
    }
    if (!validateVisibleModalFields()) {
      event.preventDefault();
      event.stopImmediatePropagation();
      return;
    }
    const saveHandler = save.onclick;
    if (typeof saveHandler !== "function") return;
    event.preventDefault();
    event.stopImmediatePropagation();
    modalSaveInProgress = true;
    save.disabled = true;
    save.classList.add("modal-save-busy");
    save.dataset.normalText = save.textContent || "Save";
    save.textContent = "Saving…";
    clearTimeout(modalSaveResetTimer);
    modalSaveResetTimer = setTimeout(() => {
      if (modal.style.display !== "none") resetModalSaveButton();
    }, 30000);
    Promise.resolve()
      .then(() => saveHandler.call(save, event))
      .catch((error) => alert(error?.message || error || "Could not save this record."))
      .finally(() => {
        if (modal.style.display !== "none") resetModalSaveButton();
      });
  }, true);

  draft.onclick = saveCurrentModalDraft;
  new MutationObserver(() => {
    if (modal.style.display === "none" || !modal.style.display) return;
    prepareOpenModalSafety();
  }).observe(modal, { attributes: true, attributeFilter: ["style"] });

  window.addEventListener("beforeunload", (event) => {
    if (modal.style.display === "none" || !modalDirty || modalSaveInProgress) return;
    event.preventDefault();
    event.returnValue = "";
  });
  document.addEventListener("keydown", (event) => {
    if (modal.style.display === "none") return;
    if (event.key === "Escape" && !isSuggestPicker(event.target)) {
      event.preventDefault();
      closeModal();
    }
    if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "s") {
      event.preventDefault();
      if (!save.disabled && save.style.display !== "none") save.click();
    }
  });
}

function prepareOpenModalSafety() {
  modalDirty = false;
  resetOpenModalToTop();
  resetModalSaveButton();
  $("modalBody")?.querySelector(".modal-validation-summary")?.remove();
  const fields = [...$("modalBody").querySelectorAll("input:not([type=file]):not([type=hidden]), select, textarea")]
    .filter((field) => !field.disabled && !field.readOnly);
  const isNewEntry = /^new\b/i.test($("modalTitle")?.textContent || "");
  const draft = $("modalDraft");
  draft.hidden = !(isNewEntry && fields.length >= 3);
  if (!draft.hidden) restoreCurrentModalDraft(fields);
}

function modalDraftKey() {
  return `lms.modalDraft.v1.${currentView}`;
}

function modalDraftFields() {
  return [...$("modalBody").querySelectorAll("input, select, textarea")]
    .filter((field) => !field.disabled && !field.readOnly && !["file", "password", "hidden"].includes(field.type));
}

function modalFieldKey(field, index) {
  return field.name || field.dataset.field || field.dataset.userField || field.dataset.equipmentRequestField || field.id || `field-${index}`;
}

function saveCurrentModalDraft() {
  const values = {};
  modalDraftFields().forEach((field, index) => {
    values[modalFieldKey(field, index)] = field.type === "checkbox" || field.type === "radio" ? field.checked : field.value;
  });
  localStorage.setItem(modalDraftKey(), JSON.stringify({ savedAt: new Date().toISOString(), values }));
  modalDirty = false;
  alert("Draft saved on this device. Attachments and drawn signatures are not included.");
}

function restoreCurrentModalDraft(fields) {
  let draft = null;
  try { draft = JSON.parse(localStorage.getItem(modalDraftKey()) || "null"); } catch { draft = null; }
  if (!draft?.values || !confirm(`A draft saved ${new Date(draft.savedAt).toLocaleString()} is available. Restore it?`)) return;
  fields.forEach((field, index) => {
    const key = modalFieldKey(field, index);
    if (!(key in draft.values)) return;
    if (field.type === "checkbox" || field.type === "radio") field.checked = Boolean(draft.values[key]);
    else field.value = draft.values[key] ?? "";
    field.dispatchEvent(new Event("input", { bubbles: true }));
    field.dispatchEvent(new Event("change", { bubbles: true }));
  });
  modalDirty = true;
}

function validateVisibleModalFields() {
  const body = $("modalBody");
  body.querySelectorAll(".field-error").forEach((field) => field.classList.remove("field-error"));
  body.querySelector(".modal-validation-summary")?.remove();
  const invalid = [...body.querySelectorAll("input, select, textarea")]
    .filter((field) => field.required && !field.disabled && field.offsetParent !== null && !field.checkValidity());
  if (!invalid.length) return true;
  invalid.forEach((field) => field.classList.add("field-error"));
  const first = invalid[0];
  const label = first.closest("label, .field")?.querySelector("label")?.textContent?.trim()
    || first.closest("label")?.childNodes?.[0]?.textContent?.trim()
    || first.name || "Required field";
  const summary = document.createElement("div");
  summary.className = "modal-validation-summary";
  summary.innerHTML = `<strong>${invalid.length} required field${invalid.length === 1 ? " is" : "s are"} missing.</strong><span>Complete ${esc(label)} first. It has been highlighted below.</span>`;
  body.prepend(summary);
  first.scrollIntoView({ behavior: "smooth", block: "center" });
  setTimeout(() => first.focus({ preventScroll: true }), 250);
  return false;
}

function resetModalSaveButton() {
  clearTimeout(modalSaveResetTimer);
  modalSaveInProgress = false;
  const save = $("modalSave");
  if (!save) return;
  save.disabled = false;
  save.classList.remove("modal-save-busy");
  if (save.textContent === "Saving…") save.textContent = save.dataset.normalText || "Save";
}

let activeSuggestInput = null;
let activeSuggestMenu = null;

function isSuggestPicker(el) {
  return !!el?.matches?.("input.suggest-input[list], input.suggest-input[data-suggest-source], input.column-filter");
}

function datalistOptions(input) {
  const listId = input?.getAttribute?.("list");
  const list = listId ? document.getElementById(listId) : null;
  return list ? [...list.querySelectorAll("option")].map((option) => option.value || option.textContent || "") : [];
}

function columnFilterOptions(input) {
  const table = input?.closest?.("table");
  const col = Number(input?.dataset?.col || 0);
  if (!table || Number.isNaN(col)) return [];
  return [...table.querySelectorAll("tbody tr")]
    .filter((row) => row.style.display !== "none" && !row.querySelector(".empty"))
    .map((row) => (row.children[col]?.textContent || "").replace(/\s+/g, " ").trim())
    .filter(Boolean);
}

function suggestOptions(input) {
  if (input?.dataset?.suggestSource === "rental_items") return rentalItemSuggestOptions(input);
  if (input?.dataset?.suggestSource === "trucking_drivers") return truckingDriverSuggestOptions(input);
  if (input?.dataset?.suggestSource === "trucking_rate_equipment") return truckingRateEquipmentSuggestOptions(input);
  if (input?.dataset?.suggestSource === "trucking_people") return truckingPeopleSuggestOptions(input);
  if (isProductSuggestInput(input)) return productSuggestOptions(input);
  if (isWorkOrderSuggestInput(input)) return workOrderSuggestOptions(input);
  if (isLocationSuggestInput(input)) return locationSuggestOptions(input);
  if (isTruckingJobsiteSuggestInput(input)) return truckingJobsiteSuggestOptions(input);
  if (isPurchaseJobsiteSuggestInput(input)) return purchaseJobsiteSuggestOptions(input);
  if (isEquipmentSuggestInput(input)) return equipmentSuggestOptions(input);
  if (isCustomerSuggestInput(input)) return customerSuggestOptions(input);
  if (isVendorSuggestInput(input)) return vendorSuggestOptions(input);
  if (isAccountSuggestInput(input)) return accountSuggestOptions(input);
  if (isInvoiceSuggestInput(input)) return invoiceSuggestOptions(input);
  const values = input?.classList?.contains("column-filter") ? columnFilterOptions(input) : datalistOptions(input);
  return [...new Set(values.map((value) => String(value || "").trim()).filter(Boolean))];
}

function rankedTruckingSuggestOptions(input, rows, valueFor, searchFor) {
  const terms = String(input?.value || "").toLowerCase().split(/\s+/).filter(Boolean);
  if (!terms.length) return [];
  const query = terms.join(" ");
  const matches = (rows || []).map((row) => {
    const value = String(valueFor(row) || "").trim();
    const haystack = String(searchFor(row) || value).toLowerCase();
    if (!value || !terms.every((term) => haystack.includes(term))) return null;
    const lower = value.toLowerCase();
    return { value, rank: lower === query ? 0 : lower.startsWith(query) ? 1 : lower.includes(query) ? 2 : 3 };
  }).filter(Boolean).sort((a, b) => a.rank - b.rank || a.value.localeCompare(b.value, undefined, { numeric: true, sensitivity: "base" }));
  return [...new Map(matches.map((item) => [item.value.toLowerCase(), item.value])).values()].slice(0, 80);
}

function truckingDriverSuggestOptions(input) {
  return rankedTruckingSuggestOptions(input, productMeta.truckingDrivers, (row) => row.name, (row) => `${row.name || ""} ${row.email || ""} trucking driver`);
}

function truckingRateEquipmentSuggestOptions(input) {
  const rows = (productMeta.truckingRates || []).filter((row) => !/inactive/i.test(row.status || "") && String(row.category || "").toLowerCase() !== "tipping fee");
  return rankedTruckingSuggestOptions(input, rows, (row) => row.service || row.subcategory || row.parent_service, (row) => `${row.service || ""} ${row.subcategory || ""} ${row.parent_service || ""} ${row.category || ""} ${row.rate_type || ""} ${row.rate || ""}`);
}

function truckingPeopleSuggestOptions(input) {
  return rankedTruckingSuggestOptions(input, productMeta.truckingLaborProfiles, (row) => row.name, (row) => `${row.name || ""} ${row.email || ""} ${row.role || ""}`);
}

function isTruckingMasterSuggestInput(input) {
  return ["trucking_drivers", "trucking_rate_equipment", "trucking_people"].includes(input?.dataset?.suggestSource);
}

function rentalItemSuggestOptions(input) {
  const terms = String(input?.value || "").toLowerCase().split(/\s+/).filter(Boolean);
  if (!terms.length) return [];
  const requestedType = String(input?.dataset?.rentalItemType || "");
  const rows = [
    ...(requestedType === "Product" ? [] : (productMeta.assets || []).map((row) => ({ type: "Asset", ref: row.asset_tag, name: row.name || row.description, detail: [row.make, row.model, row.serial_no, row.plate].filter(Boolean).join(" ") }))),
    ...(requestedType === "Asset" ? [] : (productMeta.products || []).map((row) => ({ type: "Product", ref: row.sku, name: row.name || row.description, detail: [row.category, row.source_vendor].filter(Boolean).join(" ") }))),
  ];
  return rows.map((row) => {
    const label = `${row.ref || ""} | ${row.name || ""} | ${row.type}${row.detail ? ` | ${row.detail}` : ""}`;
    const haystack = label.toLowerCase();
    if (!terms.every((term) => haystack.includes(term))) return null;
    const query = terms.join(" ");
    const ref = String(row.ref || "").toLowerCase();
    return { label, rank: ref === query ? 0 : ref.startsWith(query) ? 1 : ref.includes(query) ? 2 : 3 };
  }).filter(Boolean).sort((a, b) => a.rank - b.rank || a.label.localeCompare(b.label, undefined, { numeric: true, sensitivity: "base" })).slice(0, 80).map((row) => row.label);
}

function isProductSuggestInput(input) {
  return input?.dataset?.suggestSource === "products"
    || ["poProductOptions", "blanketReceiptProductOptions", "workOrderAdminProductOptions", "partRequestSkuOptions"].includes(input?.getAttribute?.("list"));
}

function isWorkOrderSuggestInput(input) {
  return ["work_orders", "work-order", "open_work_orders"].includes(input?.dataset?.suggestSource);
}

function isPurchaseJobsiteSuggestInput(input) {
  return input?.dataset?.suggestSource === "purchase_jobsites";
}

function isLocationSuggestInput(input) {
  return input?.dataset?.suggestSource === "locations";
}

function isTruckingJobsiteSuggestInput(input) {
  return input?.dataset?.suggestSource === "trucking_jobsites";
}

function truckingJobsiteSuggestRows() {
  return productMeta.truckingJobsiteRows || [];
}

function truckingJobsiteSuggestOptions(input) {
  const terms = String(input?.value || "").toLowerCase().split(/\s+/).filter(Boolean);
  if (!terms.length) return [];
  const query = terms.join(" ");
  return truckingJobsiteSuggestRows().map((row) => {
    const name = String(row.name || "").trim();
    const source = String(row.source || "Saved Location").trim();
    const haystack = `${name} ${source}`.toLowerCase();
    if (!name || !terms.every((term) => haystack.includes(term))) return null;
    const lower = name.toLowerCase();
    return { name, rank: lower === query ? 0 : lower.startsWith(query) ? 1 : lower.includes(query) ? 2 : 3 };
  }).filter(Boolean).sort((a, b) => a.rank - b.rank || a.name.localeCompare(b.name, undefined, { numeric: true, sensitivity: "base" })).slice(0, 60).map((row) => row.name);
}

function locationSuggestRows() {
  const sourceByName = new Map();
  const add = (value, source) => {
    const name = String(value || "").trim();
    if (!name) return;
    const key = name.toLowerCase();
    if (!sourceByName.has(key)) sourceByName.set(key, { name, sources: new Set() });
    sourceByName.get(key).sources.add(source);
  };
  (productMeta.locations || []).forEach((value) => add(value, "Location Master"));
  (productMeta.assets || []).forEach((row) => add(row.location, "Fleet & Equipment"));
  (productMeta.outsideFleet || []).forEach((row) => add(row.location, "Outside Customer Fleet"));
  (productMeta.workOrders || []).forEach((row) => {
    add(row.jobsite_location, "Work Order Jobsite");
    add(row.actual_location, "Equipment Location");
  });
  return [...sourceByName.values()].map((row) => ({ name: row.name, source: [...row.sources].join(" / ") })).sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true, sensitivity: "base" }));
}

function locationSuggestOptions(input) {
  const terms = String(input?.value || "").toLowerCase().split(/\s+/).filter(Boolean);
  if (!terms.length) return [];
  const query = terms.join(" ");
  return locationSuggestRows().map((row) => {
    const lower = row.name.toLowerCase();
    const haystack = `${row.name} ${row.source}`.toLowerCase();
    if (!terms.every((term) => haystack.includes(term))) return null;
    const rank = lower === query ? 0 : lower.startsWith(query) ? 1 : lower.includes(query) ? 2 : 3;
    return { ...row, rank };
  }).filter(Boolean).sort((a, b) => a.rank - b.rank || a.name.localeCompare(b.name, undefined, { numeric: true, sensitivity: "base" })).slice(0, 60).map((row) => row.name);
}

function isEquipmentSuggestInput(input) {
  return input?.dataset?.suggestSource === "equipment";
}

function isCustomerSuggestInput(input) {
  return ["customer", "customers"].includes(input?.dataset?.suggestSource);
}

function isVendorSuggestInput(input) {
  return input?.dataset?.suggestSource === "vendors";
}

function isAccountSuggestInput(input) {
  return input?.dataset?.suggestSource === "accounts";
}

function isInvoiceSuggestInput(input) {
  return input?.dataset?.suggestSource === "invoices";
}

function invoiceSuggestOptions(input) {
  const terms = String(input?.value || "").toLowerCase().split(/\s+/).filter(Boolean);
  if (!terms.length) return [];
  const query = terms.join(" ");
  return (productMeta.invoiceRows || []).map((invoice) => {
    const invoiceNo = String(invoice.invoice_no || "").trim();
    const customer = String(invoice.customer || "").trim();
    const type = String(invoice.type || "").trim();
    const source = String(invoice.source_ref || "no source").trim();
    const balance = invoiceBalance(invoice);
    const label = `${invoiceNo} | ${customer} | ${type} | ${source} | balance ${money(balance)}`;
    const haystack = `${invoiceNo} ${customer} ${type} ${source} ${invoice.invoice_date || ""} ${invoice.status || ""} ${balance} ${money(balance)}`.toLowerCase();
    if (balance <= 0 || !terms.every((term) => haystack.includes(term))) return null;
    const numberLower = invoiceNo.toLowerCase();
    const customerLower = customer.toLowerCase();
    const sourceLower = source.toLowerCase();
    const rank = numberLower === query ? 0
      : numberLower.startsWith(query) ? 1
      : customerLower.startsWith(query) ? 2
      : sourceLower.startsWith(query) ? 3
      : numberLower.includes(query) ? 4
      : customerLower.includes(query) ? 5
      : 6;
    return { label, rank };
  }).filter(Boolean)
    .sort((a, b) => a.rank - b.rank || a.label.localeCompare(b.label, undefined, { numeric: true, sensitivity: "base" }))
    .slice(0, 80)
    .map((row) => row.label);
}

function accountSuggestRows() {
  return (productMeta.journalAccounts || []).filter((row) => !/inactive|disabled|closed/i.test(`${row.status || ""} ${row.notes || ""}`));
}

function accountSuggestOptions(input) {
  const terms = String(input?.value || "").toLowerCase().split(/\s+/).filter(Boolean);
  if (!terms.length) return [];
  const query = terms.join(" ");
  return accountSuggestRows().map((row) => {
    const account = String(row.account || "").trim();
    const code = String(row.account_code || row.code || "").trim();
    const type = String(row.type || "").trim();
    const group = String(row.report_group || row.group || "").trim();
    const haystack = `${code} ${account} ${type} ${group}`.toLowerCase();
    if (!account || !terms.every((term) => haystack.includes(term))) return null;
    const lower = account.toLowerCase();
    const codeLower = code.toLowerCase();
    const rank = lower === query ? 0 : codeLower === query ? 1 : lower.startsWith(query) ? 2 : codeLower.startsWith(query) ? 3 : lower.includes(query) ? 4 : 5;
    return { account, rank };
  }).filter(Boolean).sort((a, b) => a.rank - b.rank || a.account.localeCompare(b.account, undefined, { numeric: true, sensitivity: "base" })).slice(0, 80).map((row) => row.account);
}

async function ensurePartyMasterSuggestRows(force = false) {
  if (partyMasterMeta.loaded && !force) return partyMasterMeta;
  const [customers, vendors] = await Promise.all([
    getAll("customers").catch(() => []),
    getAll("vendors").catch(() => []),
  ]);
  partyMasterMeta = {
    customers: customers.sort((a, b) => String(a.name || "").localeCompare(String(b.name || ""), undefined, { numeric: true, sensitivity: "base" })),
    vendors: vendors.sort((a, b) => String(a.name || "").localeCompare(String(b.name || ""), undefined, { numeric: true, sensitivity: "base" })),
    loaded: true,
  };
  return partyMasterMeta;
}

function partySuggestOptions(input, rows = []) {
  const terms = String(input?.value || "").toLowerCase().split(/\s+/).filter(Boolean);
  if (!terms.length) return [];
  const query = terms.join(" ");
  const matches = (rows || []).map((row) => {
    const name = canonicalPartyName(row.name || row.customer || row.vendor || "");
    const reference = String(row.reference || "").trim();
    const email = String(row.email || "").trim();
    const phone = String(row.phone || "").trim();
    const termsValue = String(row.terms || "").trim();
    const status = String(row.credit_status || row.status || "").trim();
    const haystack = `${reference} ${name} ${email} ${phone} ${termsValue} ${status}`.toLowerCase();
    if (!name || !terms.every((term) => haystack.includes(term))) return null;
    const nameLower = name.toLowerCase();
    const referenceLower = reference.toLowerCase();
    const rank = nameLower === query ? 0
      : referenceLower === query ? 1
      : nameLower.startsWith(query) ? 2
      : referenceLower.startsWith(query) ? 3
      : nameLower.includes(query) ? 4
      : referenceLower.includes(query) ? 5
      : 6;
    return { rank, name };
  }).filter(Boolean)
    .sort((a, b) => a.rank - b.rank || a.name.localeCompare(b.name, undefined, { numeric: true, sensitivity: "base" }));
  const uniqueByName = new Map();
  matches.forEach((item) => {
    const key = String(item.name || "").trim().toLowerCase();
    if (key && !uniqueByName.has(key)) uniqueByName.set(key, item.name);
  });
  return [...uniqueByName.values()].slice(0, 80);
}

function customerSuggestOptions(input) {
  return partySuggestOptions(input, partyMasterMeta.customers || []);
}

function vendorSuggestOptions(input) {
  return partySuggestOptions(input, partyMasterMeta.vendors || []);
}

function equipmentSuggestRows(input) {
  const source = String(input?.dataset?.equipmentSource || "master").toLowerCase();
  if (source === "fuel") {
    return (productMeta.fuelAssets || []).map((asset) => ({
      value: fuelAssetLabel(asset),
      assetTag: asset.asset_tag || "",
      name: asset.display_name || asset.equipment_name || "",
      type: asset.type_model || asset.type || "",
      plate: asset.plate || "",
      serial: asset.serial || asset.vin || "",
      location: asset.location || asset.jobsite || "",
      status: asset.status || "",
      source: asset.source || "Fleet",
    }));
  }
  if (source === "trucking") {
    return (productMeta.truckingAssets || []).map((asset) => ({
      value: asset.label || [asset.asset_tag, asset.name].filter(Boolean).join(" | "),
      assetTag: asset.asset_tag || "",
      name: asset.name || "",
      type: asset.type_model || asset.type || "",
      plate: asset.plate || "",
      serial: asset.vin || asset.serial || "",
      location: asset.location || "",
      status: asset.status || "",
      source: asset.source || "Fleet",
    }));
  }
  return [
    ...(productMeta.assets || []).map((asset) => ({
      value: [asset.asset_tag, asset.name || asset.description].filter(Boolean).join(" | "),
      assetTag: asset.asset_tag || asset.asset_no || asset.reference || "",
      name: asset.name || asset.description || "",
      type: [asset.type || asset.general_type, [asset.make, asset.model].filter(Boolean).join(" "), asset.size].filter(Boolean).join(" / "),
      plate: asset.plate || asset.plate_no || asset.license_plate || "",
      serial: asset.vin_serial || asset.vin || asset.serial_no || "",
      location: asset.location || asset.jobsite || "",
      status: asset.status || "",
      source: "Fleet & Equipment",
    })),
    ...(productMeta.outsideFleet || []).map((asset) => ({
      value: [asset.reference || asset.asset_tag || asset.vin, asset.description || [asset.make, asset.model].filter(Boolean).join(" ")].filter(Boolean).join(" | "),
      assetTag: asset.reference || asset.asset_tag || asset.vin || "",
      name: asset.description || [asset.make, asset.model].filter(Boolean).join(" ") || asset.customer_name || "",
      type: [asset.type || asset.general_type, [asset.make, asset.model].filter(Boolean).join(" "), asset.size].filter(Boolean).join(" / "),
      plate: asset.plate || asset.plate_no || asset.license_plate || "",
      serial: asset.vin || asset.vin_serial || asset.serial_no || "",
      location: asset.location || asset.jobsite || "",
      status: asset.status || "",
      source: asset.customer_name ? `Outside - ${asset.customer_name}` : "Outside Customer Fleet",
    })),
  ];
}

function equipmentSuggestOptions(input) {
  const terms = String(input?.value || "").toLowerCase().split(/\s+/).filter(Boolean);
  if (!terms.length) return [];
  const query = terms.join(" ");
  const matches = [];
  for (const equipment of equipmentSuggestRows(input)) {
    const assetTag = String(equipment.assetTag || "").trim();
    const name = String(equipment.name || "").trim();
    const type = String(equipment.type || "").trim();
    const plate = String(equipment.plate || "").trim();
    const serial = String(equipment.serial || "").trim();
    const location = String(equipment.location || "").trim();
    const status = String(equipment.status || "").trim();
    const source = String(equipment.source || "").trim();
    const haystack = `${assetTag} ${name} ${status} ${type} ${plate} ${serial} ${location} ${source}`.toLowerCase();
    if (!terms.every((term) => haystack.includes(term))) continue;
    const tagLower = assetTag.toLowerCase();
    const plateLower = plate.toLowerCase();
    const serialLower = serial.toLowerCase();
    const nameLower = name.toLowerCase();
    const rank = tagLower === query ? 0
      : plateLower === query ? 1
      : serialLower === query ? 2
      : tagLower.startsWith(query) ? 3
      : plateLower.startsWith(query) ? 4
      : serialLower.startsWith(query) ? 5
      : nameLower.startsWith(query) ? 6
      : tagLower.includes(query) ? 7
      : plateLower.includes(query) ? 8
      : serialLower.includes(query) ? 9
      : nameLower.includes(query) ? 10
      : 11;
    matches.push({ rank, value: String(equipment.value || [assetTag, name].filter(Boolean).join(" | ")).trim() });
  }
  return [...new Map(matches
    .sort((a, b) => a.rank - b.rank || a.value.localeCompare(b.value, undefined, { numeric: true, sensitivity: "base" }))
    .map((item) => [item.value.toLowerCase(), item.value])).values()].slice(0, 80);
}

function workOrderSuggestRows(input) {
  return input?.dataset?.suggestSource === "open_work_orders"
    ? (productMeta.openWorkOrders || [])
    : (productMeta.workOrders || []);
}

function normalizeProductLookupText(value) {
  return String(value || "")
    .normalize("NFKC")
    .replace(/[\u200B-\u200D\u2060\uFEFF]/g, "")
    .replace(/[\u2010-\u2015\u2212]/g, "-")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim()
    .replace(/\s+/g, " ");
}

function compactProductLookupText(value) {
  return normalizeProductLookupText(value).replace(/\s+/g, "");
}

function productLookupQuery(value) {
  return String(value || "")
    .normalize("NFKC")
    .replace(/[\u200B-\u200D\u2060\uFEFF]/g, "")
    .split("|")[0]
    .trim();
}

function productSuggestOptions(input) {
  const rawQuery = productLookupQuery(input?.value);
  const normalizedQuery = normalizeProductLookupText(rawQuery);
  const compactQuery = compactProductLookupText(rawQuery);
  const terms = normalizedQuery.split(/\s+/).filter(Boolean);
  if (!terms.length) return [];
  const matches = [];
  for (const product of productMeta.products || []) {
    const sku = String(product.sku || "").trim();
    const name = String(product.name || "").trim();
    const vendor = String(product.source_vendor || "No preferred vendor").trim();
    const alternates = (product._alternate_part_numbers || []).map((value) => String(value || "").trim()).filter(Boolean);
    const crossReferences = (product._cross_reference_numbers || []).map((value) => String(value || "").trim()).filter(Boolean);
    const aliases = [...alternates, ...crossReferences];
    const skuNormalized = normalizeProductLookupText(sku);
    const nameNormalized = normalizeProductLookupText(name);
    const vendorNormalized = normalizeProductLookupText(vendor);
    const aliasNormalized = aliases.map(normalizeProductLookupText).join(" ");
    const aliasCompacts = aliases.map(compactProductLookupText).filter(Boolean);
    const haystack = `${skuNormalized} ${nameNormalized} ${vendorNormalized} ${aliasNormalized}`.trim();
    const skuCompact = compactProductLookupText(sku);
    const nameCompact = compactProductLookupText(name);
    const vendorCompact = compactProductLookupText(vendor);
    const identityCompact = `${skuCompact}${nameCompact}`;
    const termMatch = terms.every((term) => haystack.includes(term) || skuCompact.includes(term));
    const compactMatch = Boolean(compactQuery) && (
      skuCompact.includes(compactQuery)
      || nameCompact.includes(compactQuery)
      || vendorCompact.includes(compactQuery)
      || aliasCompacts.some((alias) => alias.includes(compactQuery) || compactQuery.includes(alias))
      || identityCompact.includes(compactQuery)
      || compactQuery.includes(identityCompact)
    );
    if (!termMatch && !compactMatch) continue;
    const rank = skuCompact === compactQuery ? 0
      : identityCompact === compactQuery ? 1
      : skuCompact.startsWith(compactQuery) ? 2
      : nameCompact.startsWith(compactQuery) ? 3
      : skuCompact.includes(compactQuery) ? 4
      : nameCompact.includes(compactQuery) ? 5
      : aliasCompacts.some((alias) => alias === compactQuery) ? 2
      : aliasCompacts.some((alias) => alias.startsWith(compactQuery)) ? 3
      : vendorCompact.startsWith(compactQuery) ? 6
      : 7;
    matches.push({ rank, label: `${sku} - ${name} | preferred ${vendor} | on hand ${product.qty ?? 0}` });
  }
  return matches
    .sort((a, b) => a.rank - b.rank || a.label.localeCompare(b.label, undefined, { numeric: true, sensitivity: "base" }))
    .slice(0, 80)
    .map((item) => item.label);
}

function workOrderSuggestOptions(input) {
  const terms = String(input?.value || "").toLowerCase().split(/\s+/).filter(Boolean);
  if (!terms.length) return [];
  const query = terms.join(" ");
  const matches = [];
  for (const workOrder of workOrderSuggestRows(input)) {
    const woNo = String(workOrder.wo_no || "").trim();
    const asset = String(workOrder.asset_tag || "No asset").trim();
    const customer = String(workOrder.bill_to_customer || "Internal").trim();
    const status = String(workOrder.status || "Open").trim();
    const haystack = `${woNo} ${asset} ${customer} ${status}`.toLowerCase();
    if (!terms.every((term) => haystack.includes(term))) continue;
    const woLower = woNo.toLowerCase();
    const assetLower = asset.toLowerCase();
    const customerLower = customer.toLowerCase();
    const rank = woLower === query ? 0
      : woLower.startsWith(query) ? 1
      : assetLower.startsWith(query) ? 2
      : customerLower.startsWith(query) ? 3
      : woLower.includes(query) ? 4
      : assetLower.includes(query) ? 5
      : customerLower.includes(query) ? 6
      : 7;
    matches.push({ rank, label: workOrderOptionLabel(workOrder) });
  }
  return matches
    .sort((a, b) => a.rank - b.rank || a.label.localeCompare(b.label, undefined, { numeric: true, sensitivity: "base" }))
    .slice(0, 60)
    .map((item) => item.label);
}

function purchaseJobsiteSuggestOptions(input) {
  const terms = String(input?.value || "").toLowerCase().split(/\s+/).filter(Boolean);
  if (!terms.length) return [];
  const query = terms.join(" ");
  return (productMeta.purchaseJobsiteRows || [])
    .map((row) => {
      const name = String(row.name || "").trim();
      const source = String(row.source || "Saved Location").trim();
      const haystack = `${name} ${source}`.toLowerCase();
      if (!terms.every((term) => haystack.includes(term))) return null;
      const lower = name.toLowerCase();
      const rank = lower === query ? 0 : lower.startsWith(query) ? 1 : lower.includes(query) ? 2 : 3;
      return { rank, name };
    })
    .filter(Boolean)
    .sort((a, b) => a.rank - b.rank || a.name.localeCompare(b.name, undefined, { numeric: true, sensitivity: "base" }))
    .slice(0, 60)
    .map((item) => item.name);
}

function matchingSuggestOptions(input) {
  if (isTruckingMasterSuggestInput(input)) {
    input.dataset.suggestShowAll = "";
    return suggestOptions(input);
  }
  if (isProductSuggestInput(input)) {
    const values = productSuggestOptions(input);
    input.dataset.suggestShowAll = "";
    return values;
  }
  if (isWorkOrderSuggestInput(input)) {
    const values = workOrderSuggestOptions(input);
    input.dataset.suggestShowAll = "";
    return values;
  }
  if (isLocationSuggestInput(input)) {
    input.dataset.suggestShowAll = "";
    return locationSuggestOptions(input);
  }
  if (isTruckingJobsiteSuggestInput(input)) {
    input.dataset.suggestShowAll = "";
    return truckingJobsiteSuggestOptions(input);
  }
  if (isPurchaseJobsiteSuggestInput(input)) {
    const values = purchaseJobsiteSuggestOptions(input);
    input.dataset.suggestShowAll = "";
    return values;
  }
  if (isEquipmentSuggestInput(input)) {
    const values = equipmentSuggestOptions(input);
    input.dataset.suggestShowAll = "";
    return values;
  }
  if (isCustomerSuggestInput(input)) {
    const values = customerSuggestOptions(input);
    input.dataset.suggestShowAll = "";
    return values;
  }
  if (isVendorSuggestInput(input)) {
    const values = vendorSuggestOptions(input);
    input.dataset.suggestShowAll = "";
    return values;
  }
  if (isAccountSuggestInput(input)) {
    const values = accountSuggestOptions(input);
    input.dataset.suggestShowAll = "";
    return values;
  }
  if (isInvoiceSuggestInput(input)) {
    const values = invoiceSuggestOptions(input);
    input.dataset.suggestShowAll = "";
    return values;
  }
  if (input?.dataset?.suggestShowAll === "1") {
    input.dataset.suggestShowAll = "";
    const values = suggestOptions(input);
    if (!String(input?.value || "").trim() && values.length > 25) return [];
    return values
      .sort((a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: "base" }))
      .slice(0, 120);
  }
  const terms = String(input?.value || "").toLowerCase().split(/\s+/).filter(Boolean);
  return suggestOptions(input)
    .filter((value) => terms.every((term) => value.toLowerCase().includes(term)))
    .sort((a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: "base" }))
    .slice(0, 80);
}

function ensureSuggestMenu() {
  if (activeSuggestMenu) return activeSuggestMenu;
  activeSuggestMenu = document.createElement("div");
  activeSuggestMenu.className = "suggest-menu";
  activeSuggestMenu.hidden = true;
  document.body.appendChild(activeSuggestMenu);
  activeSuggestMenu.addEventListener("pointerdown", (event) => event.preventDefault());
  activeSuggestMenu.addEventListener("click", (event) => {
    const option = event.target.closest("[data-suggest-value]");
    if (!option || !activeSuggestInput) return;
    selectSuggestOption(activeSuggestInput, option.dataset.suggestValue || "");
  });
  return activeSuggestMenu;
}

function positionSuggestMenu(input) {
  const menu = ensureSuggestMenu();
  const rect = input.getBoundingClientRect();
  menu.style.left = `${Math.max(8, rect.left)}px`;
  menu.style.top = `${rect.bottom + 4}px`;
  const availableWidth = Math.max(260, window.innerWidth - Math.max(8, rect.left) - 14);
  const preferredWidth = isEquipmentSuggestInput(input) ? 1040 : isProductSuggestInput(input) || isWorkOrderSuggestInput(input) || isCustomerSuggestInput(input) || isVendorSuggestInput(input) || isAccountSuggestInput(input) || isInvoiceSuggestInput(input) ? 860 : isPurchaseJobsiteSuggestInput(input) || isLocationSuggestInput(input) || isTruckingJobsiteSuggestInput(input) || isTruckingMasterSuggestInput(input) ? 560 : 220;
  menu.style.width = `${Math.min(availableWidth, Math.max(preferredWidth, rect.width))}px`;
  menu.style.maxWidth = `${availableWidth}px`;
}

function productSuggestOptionMarkup(value) {
  const product = resolveProductLookup(value);
  if (!product) return `<button type="button" class="suggest-option" data-suggest-value="${esc(value)}">${esc(value)}</button>`;
  return `<button type="button" class="suggest-option product-suggest-row" data-suggest-value="${esc(value)}">
    <span class="product-suggest-cell product-suggest-sku" data-label="SKU">${esc(product.sku || "-")}</span>
    <span class="product-suggest-cell product-suggest-name" data-label="Product">${esc(product.name || "-")}${(product._alternate_part_numbers || []).length ? `<small>Alternate: ${esc(product._alternate_part_numbers.join(", "))}</small>` : ""}${(product._cross_reference_numbers || []).length ? `<small>Cross-reference: ${esc(product._cross_reference_numbers.join(", "))}</small>` : ""}</span>
    <span class="product-suggest-cell" data-label="Vendor">${esc(product.source_vendor || "-")}</span>
    <span class="product-suggest-cell product-suggest-qty" data-label="On Hand">${esc(product.qty ?? 0)}</span>
  </button>`;
}

function workOrderSuggestOptionMarkup(value) {
  const workOrder = resolveWorkOrderSuggestLookup(value, activeSuggestInput);
  if (!workOrder) return `<button type="button" class="suggest-option" data-suggest-value="${esc(value)}">${esc(value)}</button>`;
  return `<button type="button" class="suggest-option work-order-suggest-row" data-suggest-value="${esc(value)}">
    <span class="work-order-suggest-cell work-order-suggest-number" data-label="Work Order">${esc(workOrder.wo_no || "-")}</span>
    <span class="work-order-suggest-cell work-order-suggest-asset" data-label="Asset">${esc(workOrder.asset_tag || "No asset")}</span>
    <span class="work-order-suggest-cell" data-label="Customer">${esc(workOrder.bill_to_customer || "Internal")}</span>
    <span class="work-order-suggest-cell" data-label="Status">${badge(workOrder.status || "Open")}</span>
  </button>`;
}

function resolveWorkOrderSuggestLookup(value, input) {
  const text = String(value || "").trim();
  if (!text) return null;
  const directWo = text.split("|")[0].trim().toLowerCase();
  const lower = text.toLowerCase();
  return workOrderSuggestRows(input).find((workOrder) => {
    const woNo = String(workOrder.wo_no || "").trim().toLowerCase();
    const label = workOrderOptionLabel(workOrder).toLowerCase();
    return woNo === directWo || label === lower || (woNo && lower.includes(woNo));
  }) || null;
}

function purchaseJobsiteSuggestOptionMarkup(value) {
  const row = (productMeta.purchaseJobsiteRows || []).find((item) => String(item.name || "").toLowerCase() === String(value || "").toLowerCase());
  if (!row) return `<button type="button" class="suggest-option" data-suggest-value="${esc(value)}">${esc(value)}</button>`;
  return `<button type="button" class="suggest-option jobsite-suggest-row" data-suggest-value="${esc(row.name)}">
    <span class="jobsite-suggest-cell jobsite-suggest-name" data-label="Jobsite / Location">${esc(row.name)}</span>
    <span class="jobsite-suggest-cell" data-label="Source">${esc(row.source || "Saved Location")}</span>
  </button>`;
}

function locationSuggestOptionMarkup(value) {
  const row = locationSuggestRows().find((item) => item.name.toLowerCase() === String(value || "").toLowerCase());
  if (!row) return `<button type="button" class="suggest-option" data-suggest-value="${esc(value)}">${esc(value)}</button>`;
  return `<button type="button" class="suggest-option jobsite-suggest-row" data-suggest-value="${esc(row.name)}"><span class="jobsite-suggest-cell jobsite-suggest-name" data-label="Jobsite / Location">${esc(row.name)}</span><span class="jobsite-suggest-cell" data-label="Source">${esc(row.source)}</span></button>`;
}

function truckingJobsiteSuggestOptionMarkup(value) {
  const row = truckingJobsiteSuggestRows().find((item) => String(item.name || "").toLowerCase() === String(value || "").toLowerCase());
  if (!row) return `<button type="button" class="suggest-option" data-suggest-value="${esc(value)}">${esc(value)}</button>`;
  return `<button type="button" class="suggest-option jobsite-suggest-row" data-suggest-value="${esc(row.name)}"><span class="jobsite-suggest-cell jobsite-suggest-name" data-label="Project / Jobsite">${esc(row.name)}</span><span class="jobsite-suggest-cell" data-label="Source">${esc(row.source || "Saved Location")}</span></button>`;
}

function resolveEquipmentSuggestLookup(value, input) {
  const exact = String(value || "").trim().toLowerCase();
  const key = exact.split("|")[0].trim();
  return equipmentSuggestRows(input).find((equipment) => {
    const optionValue = String(equipment.value || "").trim().toLowerCase();
    return optionValue === exact || (key && String(equipment.assetTag || "").trim().toLowerCase() === key);
  }) || null;
}

function equipmentSuggestOptionMarkup(value, input) {
  const equipment = resolveEquipmentSuggestLookup(value, input);
  if (!equipment) return `<button type="button" class="suggest-option" data-suggest-value="${esc(value)}">${esc(value)}</button>`;
  return `<button type="button" class="suggest-option equipment-suggest-row" data-suggest-value="${esc(value)}">
    <span class="equipment-suggest-cell equipment-suggest-tag" data-label="Asset #">${esc(equipment.assetTag || "-")}</span>
    <span class="equipment-suggest-cell equipment-suggest-name" data-label="Equipment">${esc(equipment.name || "-")}<small>${esc(equipment.source || "")}</small></span>
    <span class="equipment-suggest-cell" data-label="Status">${esc(equipment.status || "-")}</span>
    <span class="equipment-suggest-cell" data-label="Type / Model">${esc(equipment.type || "-")}</span>
    <span class="equipment-suggest-cell" data-label="Plate #">${esc(equipment.plate || "-")}</span>
    <span class="equipment-suggest-cell" data-label="Serial / VIN">${esc(equipment.serial || "-")}</span>
    <span class="equipment-suggest-cell" data-label="Location">${esc(equipment.location || "-")}</span>
  </button>`;
}

function partySuggestRow(value, rows = []) {
  const exact = normalizedMasterName(canonicalPartyName(value));
  return (rows || []).find((row) => normalizedMasterName(canonicalPartyName(row.name || row.customer || row.vendor || "")) === exact) || null;
}

async function requirePartyMasterSelection(table, value, label = "party") {
  const entered = String(value || "").trim();
  if (!entered) return null;
  const rows = await getAll(table);
  const selected = rows.find((row) => normalizedMasterName(canonicalPartyName(row.name || row.customer || row.vendor || "")) === normalizedMasterName(canonicalPartyName(entered)));
  if (!selected) {
    alert(`Select ${label} from ${table === "vendors" ? "Vendor" : "Customer"} Master.\n\n“${entered}” is not a saved master record and cannot be used.`);
    return null;
  }
  return selected;
}

