function trainingGuideCatalog() {
  const assigned = userModules();
  const allowAll = assigned.includes("all");
  return modules.map((group) => ({
    ...group,
    items: group.items.filter(([id]) => id === "dashboard" || allowAll || assigned.includes(id)).map(([id, label]) => ({
      id,
      label,
      subtitle: tableMap[id]?.sub || ({
        equipmentrepairqueue: "Assets reported or scanned as needing repair before work-order assignment.",
        truckingassigned: "Driver assignments, operational updates, signatures and finalization.",
        truckingtickets: "Completed trucking tickets, customer delivery and billing-summary workflow.",
      }[id] || "Step-by-step operating workflow and controls."),
      steps: [...(moduleTrainingDetails[id] || []), ...(moduleTrainingExtraDetails[id] || [])].length
        ? [...(moduleTrainingDetails[id] || []), ...(moduleTrainingExtraDetails[id] || [])]
        : ["Open the module and review its subtitle and current records.", "Use search, filters and tabs to locate the correct record before editing.", "Save, verify the result, and export only the filtered information when needed."],
    })),
  })).filter((group) => group.items.length);
}

function openModuleTrainingGuide() {
  if (!session) return alert("Log in first, then open the Detailed Module Training Guide.");
  endTraining();
  const overlay = document.createElement("div");
  overlay.id = "moduleTrainingOverlay";
  overlay.className = "module-training-overlay";
  const catalog = trainingGuideCatalog();
  const moduleChoices = catalog.flatMap((group) => group.items.map((item) => `<option value="${esc(item.id)}">${esc(group.group)} — ${esc(item.label)}</option>`)).join("");
  overlay.innerHTML = `<section class="module-training-dialog">
    <header><div><span class="training-kicker">LMS Imports system training</span><h2>Detailed Module Training Guide</h2><p>Each module includes its subtitle, operating workflow, controls and key cautions. Only modules assigned to your login are shown.</p></div><button type="button" id="closeModuleTrainingBtn">Close</button></header>
    <div class="module-training-runner"><label>Choose a module to simulate<select id="moduleTrainingSelect">${moduleChoices}</select></label><button type="button" class="primary" id="runSelectedModuleTrainingBtn">Run selected module tutorial</button><small>Practice mode opens screens and safe popups but never saves, posts, finalizes, voids, deletes or resets live data.</small></div>
    <div class="module-training-search"><input id="moduleTrainingSearch" placeholder="Search module, purpose, workflow or caution"></div>
    <div id="moduleTrainingBody">${moduleTrainingGuideHtml(catalog)}</div>
  </section>`;
  document.body.appendChild(overlay);
  $("closeModuleTrainingBtn").onclick = () => overlay.remove();
  $("runSelectedModuleTrainingBtn").onclick = () => startModuleSimulation($("moduleTrainingSelect").value, overlay);
  overlay.onclick = (event) => { if (event.target === overlay) overlay.remove(); };
  $("moduleTrainingSearch").oninput = (event) => {
    const query = event.target.value.trim().toLowerCase();
    overlay.querySelectorAll("[data-training-module]").forEach((card) => card.hidden = Boolean(query) && !card.textContent.toLowerCase().includes(query));
    overlay.querySelectorAll("[data-training-group]").forEach((group) => group.hidden = !group.querySelector("[data-training-module]:not([hidden])"));
  };
  overlay.querySelectorAll("[data-open-training-view]").forEach((button) => button.onclick = async () => {
    overlay.remove();
    await loadView(button.dataset.openTrainingView);
  });
  overlay.querySelectorAll("[data-run-module-training]").forEach((button) => button.onclick = () => startModuleSimulation(button.dataset.runModuleTraining, overlay));
}

function moduleTrainingGuideHtml(groups) {
  return groups.map((group) => `<section class="module-training-group" data-training-group><h3>${esc(group.group)}</h3><div class="module-training-grid">${group.items.map((item) => `<details class="module-training-card" data-training-module><summary><strong>${esc(item.label)}</strong><span>${esc(item.subtitle)}</span></summary><div class="module-training-content"><h4>How to use this module</h4><ol>${item.steps.map((step) => `<li>${esc(step)}</li>`).join("")}</ol><div class="training-actions"><button type="button" class="primary" data-run-module-training="${esc(item.id)}">Run tutorial</button><button type="button" data-open-training-view="${esc(item.id)}">Open module</button></div></div></details>`).join("")}</div></section>`).join("");
}

async function startModuleSimulation(view, guideOverlay) {
  guideOverlay?.remove();
  endTraining();
  await loadView(view);
  const catalogItem = trainingGuideCatalog().flatMap((group) => group.items.map((item) => ({ ...item, group: group.group }))).find((item) => item.id === view);
  if (!catalogItem) return alert("This module is not assigned to your login.");
  const intro = { view, group: catalogItem.group, title: catalogItem.label, subtitle: catalogItem.subtitle, details: catalogItem.steps, target: "#content", preserveView: true };
  activeTrainingSteps = [intro, ...collectModuleControlTrainingSteps(view, catalogItem)];
  trainingMode = "module";
  trainingIndex = 0;
  document.body.classList.add("training-active");
  renderTrainingOverlay(activeTrainingSteps[0]);
}

function collectModuleControlTrainingSteps(view, item) {
  const seen = new Set();
  return [...document.querySelectorAll("#content button, #content .tabbtn, #content summary")]
    .filter((control) => control.offsetParent !== null && !control.disabled)
    .map((control, index) => {
      const label = String(control.innerText || control.textContent || control.getAttribute("aria-label") || control.title || "Control").trim().replace(/\s+/g, " ");
      const key = label.toLowerCase().replace(/\d+/g, "#");
      if (!label || seen.has(key)) return null;
      seen.add(key);
      const marker = `${view}-${index}`;
      control.dataset.trainingControl = marker;
      const safePopup = /^(new|add|edit|dispatch|view|details|time|actions)/i.test(label) && !/save|post|final|delete|reset|void|reverse|cancel|close work|invoice|email|send|approve|deny|issue|receive|convert/i.test(label);
      return {
        view,
        group: item.group,
        title: `${item.label}: ${label}`,
        subtitle: `Screen control — ${label}`,
        details: [describeTrainingControl(label), "Training will not execute any transaction-changing action. Review the affected record and required fields before using this control in live work."],
        target: `[data-training-control="${marker}"]`,
        preserveView: true,
        practiceControl: safePopup ? marker : "",
      };
    }).filter(Boolean);
}

function describeTrainingControl(label) {
  if (/new|add|create/i.test(label)) return "Opens a data-entry popup. Confirm required master data and supporting documents before entering a live transaction.";
  if (/edit/i.test(label)) return "Opens the existing record with saved information. Change only fields supported by source documents and preserve signatures/history unless intentionally corrected.";
  if (/tab|pending|open|scheduled|finalized|cancelled|billed|unbilled|ready/i.test(label)) return "Changes the status view only. Use it to separate work by workflow stage; it does not change the transaction itself.";
  if (/excel|export/i.test(label)) return "Exports the currently visible, filtered records. Apply filters and verify the row count before downloading.";
  if (/pdf|print/i.test(label)) return "Builds the printable document for review. Verify layout, details, totals and signatures before distribution.";
  if (/filter|column|sort|view/i.test(label)) return "Controls how records are displayed. Use it to narrow, arrange or save the view without changing source data.";
  if (/refresh/i.test(label)) return "Reloads current live information after another user or module has posted changes.";
  return "Review what this control does, the record status it expects and whether it opens a popup or changes workflow state before using it.";
}

function openPracticePopup(marker) {
  const control = document.querySelector(`[data-training-control="${CSS.escape(marker)}"]`);
  if (!control) return;
  control.click();
  setTimeout(() => {
    const modal = $("modal");
    if (!modal || modal.style.display === "none") return;
    const popupTitle = $("modalTitle")?.textContent?.trim() || "Popup";
    const popupSteps = collectPopupTrainingSteps(popupTitle);
    activeTrainingSteps.splice(trainingIndex + 1, 0, ...popupSteps);
    moveTraining(1);
  }, 250);
}

function collectPopupTrainingSteps(popupTitle) {
  const steps = [];
  [...document.querySelectorAll("#modalBody .field, #modalBody label, #modalBody .subpanel")].filter((element) => element.offsetParent !== null).forEach((element, index) => {
    const label = String(element.querySelector?.("label")?.textContent || element.textContent || "Popup field").trim().replace(/\s+/g, " ").slice(0, 180);
    if (!label) return;
    const marker = `popup-${Date.now()}-${index}`;
    element.dataset.trainingPopupField = marker;
    steps.push({ title: `${popupTitle}: ${label}`, subtitle: "Practice popup field", details: ["Review this field’s source, format and whether it is required before entering live information.", "Use master-data search/dropdowns when provided so reporting and linked transactions remain consistent."], target: `[data-training-popup-field="${marker}"]`, preserveView: true });
  });
  steps.push({ title: `${popupTitle}: popup buttons`, subtitle: "Practice only — no posting", details: ["Save commits the record after validation. Cancel or X closes the popup without intentionally saving changes.", "This simulation will close the popup without pressing Save, Post, Finalize, Delete, Void, Reset or another live action."], target: "#modalSave", preserveView: true, closePracticePopup: true });
  return steps;
}

function startMobileRequestTutorial(type) {
  endTraining();
  const equipment = type === "equipment";
  const title = equipment ? "Equipment Request Mobile Tutorial" : "Trucking Move Request Mobile Tutorial";
  const subtitle = equipment
    ? "Practice every part of an equipment request without submitting live data."
    : "Practice every part of a trucking move request without submitting live data.";
  const sourceSteps = equipment
    ? [...(moduleTrainingDetails.equipmentrequests || []), ...(moduleTrainingExtraDetails.equipmentrequests || [])]
    : [...(moduleTrainingDetails.truckingrequests || []), ...(moduleTrainingExtraDetails.truckingrequests || [])];
  const fields = equipment
    ? [...document.querySelectorAll("#modalBody .equipment-request-form > .field")]
    : [...document.querySelectorAll("#modalBody .move-request-form > .form-grid > label, #modalBody .move-request-form > .form-grid > fieldset, #modalBody .move-request-equipment, #modalBody .move-request-description")];
  const fieldSteps = fields.filter((field) => field.offsetParent !== null).map((field, index) => {
    const label = String(field.querySelector("label")?.textContent || field.querySelector("legend")?.textContent || field.childNodes[0]?.textContent || "Request field").trim().replace(/\s+/g, " ").slice(0, 120);
    const marker = `mobile-${type}-${index}`;
    field.dataset.mobileTrainingField = marker;
    return {
      title: label || "Request field",
      subtitle: mobileRequestFieldSubtitle(type, label),
      details: mobileRequestFieldInstructions(type, label),
      target: `[data-mobile-training-field="${marker}"]`,
      preserveView: true,
    };
  });
  const specialServiceStep = equipment ? [] : [{
    title: "Service-specific fields",
    subtitle: "The form changes based on Service Needed",
    details: [
      "Equipment Move opens equipment lookup from Fleet & Equipment; verify the exact asset or plate.",
      "Container/Trailer Move requires move type, size and the configured container/trailer reference.",
      "High Deck, Highbed and Flatrack services require materials, unit of measurement, weight and dimensions.",
      "Dump Truck and End Dump require materials loaded, number of loads and CY/load; Total CY calculates automatically.",
      "Roll Off Service opens bin size/capacity, optional tons and tipping fee. Tipping fee applies only to Roll Off.",
      "Waste Water Pump Services opens portable toilet/sink or tank-capacity choices configured in the Rate Sheet.",
      "If a required service choice is missing, contact an administrator instead of entering the service under the wrong category.",
    ],
    target: '#modalBody [name="service_choice"]',
    preserveView: true,
  }];
  activeTrainingSteps = [{ title, subtitle, details: sourceSteps, target: "#modalBody", preserveView: true }, ...fieldSteps, ...specialServiceStep, {
    title: "Review and submit",
    subtitle: "Final mobile request check",
    details: equipment ? [
      "Confirm every requested equipment row, location, requestor, required email, PO attachment, date range and signature.",
      "Press Save only when the request is complete. A successful mobile submission displays the request number.",
      "This tutorial does not press Save and does not create a request.",
    ] : [
      "Confirm customer, jobsite, required email, delivery date/time, trip/payment type, service fields and required Move Description.",
      "If payment is PO, confirm PO number. Review every equipment line and optional origin/destination.",
      "Press Save only when complete. A successful mobile submission confirms the generated LMS request number.",
      "This tutorial does not press Save and does not create a request.",
    ],
    target: "#modalSave",
    preserveView: true,
  }];
  trainingMode = "mobile";
  trainingIndex = 0;
  document.body.classList.add("training-active");
  renderTrainingOverlay(activeTrainingSteps[0]);
}

function mobileRequestFieldSubtitle(type, label) {
  const text = String(label || "").toLowerCase();
  if (/request #|entry date|request date/.test(text)) return "System-controlled request identification";
  if (/email/.test(text)) return "Required notification recipient";
  if (/signature/.test(text)) return "Required requestor authorization";
  if (/po/.test(text)) return "Customer purchase-order support";
  if (/equipment/.test(text)) return "Select the exact Fleet & Equipment record";
  if (/service/.test(text)) return "Choose the service pattern before dependent details";
  if (/description/.test(text)) return "Required operational instructions";
  return `${type === "equipment" ? "Equipment" : "Trucking move"} request field`;
}

function mobileRequestFieldInstructions(type, label) {
  const text = String(label || "").toLowerCase();
  if (/request #/.test(text)) return ["The system generates this number. Do not replace it with a handwritten or external reference.", "Use this number when following up on approval, dispatch or status."];
  if (/entry date|request date/.test(text)) return ["The system uses the date the request was created.", "Do not change the entry date to the requested delivery or equipment-use date."];
  if (/customer/.test(text)) return ["Select the customer from Customer Master so contact and reporting remain consistent.", "If the customer is missing, ask an authorized user to create the master record."];
  if (/project|jobsite/.test(text)) return ["Search the available Fleet & Equipment jobsite/location list.", "Select the jobsite related to the request so charging and operational reporting are correct."];
  if (/email/.test(text)) return ["Enter the email of the person who should receive request notifications.", "This field is required and must not default to the shared request login unless that is the intended recipient.", "Check spelling before submission because confirmation and follow-up depend on it."];
  if (/equipment requested|equipment/.test(text)) return ["Search by asset number, description, make/model, VIN/serial, plate or location.", "Select the exact equipment record and verify its photo/description.", "Use Add Equipment Row for multiple units; do not overwrite the first row."];
  if (/location/.test(text)) return ["Enter the physical location or requested delivery/use location.", "Choose an existing location when available so Fleet reporting uses consistent names."];
  if (/requested by/.test(text)) return ["Enter the actual requestor’s name, even when a shared login is used.", "This name is used for approval follow-up and operational accountability."];
  if (/po upload/.test(text)) return ["Attach the customer PO image or PDF before submitting.", "Open the attachment once to verify it is readable and belongs to this request.", "Keep files reasonably small for reliable mobile submission."];
  if (/po #/.test(text)) return ["Enter the customer PO number exactly as shown on the attachment.", "For trucking, this becomes mandatory when Mode of Payment is PO."];
  if (/from when|to when|delivery date/.test(text)) return ["Enter the actual required-use or delivery date.", "For equipment requests, To date cannot be before From date.", "For trucking, this is separate from the fixed entry date."];
  if (/signature/.test(text)) return ["Sign inside the box using a finger or stylus.", "Do not clear the signature when editing unless the requestor intends to replace it.", "Review the signature before submission."];
  if (/service/.test(text)) return ["Choose the correct Service Needed super-parent first.", "Complete every dependent field that appears for that service.", "Do not place one service under another category just to bypass a required field."];
  if (/trip type/.test(text)) return ["Choose One-Way for a single movement or Round Trip when the equipment/load returns.", "Round Trip doubles fixed charges only; it does not double hourly rates."];
  if (/mode of payment/.test(text)) return ["Choose Cash, Credit Card or PO.", "Selecting PO opens the mandatory PO-number field."];
  if (/origin|destination/.test(text)) return ["Origin and Destination are optional, but enter them when known to help dispatch and the driver.", "Search existing jobsites for consistent naming."];
  if (/description/.test(text)) return ["Describe what must be moved or provided, timing and special instructions.", "This field is required and appears later on the dispatcher record and ticket."];
  return ["Complete this field from the requestor’s actual information.", "Review the value before submission; use a provided lookup instead of free typing when available."];
}

