function startTraining(mode) {
  if (!session) {
    alert("Log in first, then click Quick overview or Full tutorial.");
    return;
  }
  trainingMode = mode;
  trainingIndex = 0;
  activeTrainingSteps = mode === "full" ? buildDetailedFullTrainingSteps() : (trainingTours[mode] || []);
  document.body.classList.add("training-active");
  showTrainingStep();
}

function buildDetailedFullTrainingSteps() {
  return trainingGuideCatalog().flatMap((group) => group.items.map((item) => ({
    view: item.id,
    group: group.group,
    title: item.label,
    subtitle: item.subtitle,
    details: item.steps,
    target: "#content",
  })));
}

async function showTrainingStep() {
  const steps = activeTrainingSteps;
  const step = steps[trainingIndex];
  if (!step) return endTraining();
  clearTimeout(trainingAutoplay);
  if (!step.preserveView) {
    closeModal();
    await loadView(step.view);
  } else if (step.view && currentView !== step.view) {
    await loadView(step.view);
  }
  setTimeout(() => renderTrainingOverlay(step), 250);
}

function renderTrainingOverlay(step) {
  removeTrainingHighlight();
  const target = document.querySelector(step.target) || $("content");
  target?.classList.add("training-highlight");
  target?.scrollIntoView({ behavior: "smooth", block: "center", inline: "nearest" });
  let overlay = $("trainingOverlay");
  if (!overlay) {
    overlay = document.createElement("div");
    overlay.id = "trainingOverlay";
    overlay.className = "training-overlay";
    document.body.appendChild(overlay);
  }
  const total = activeTrainingSteps.length;
  overlay.innerHTML = `
    <div class="training-card">
      <div class="training-kicker">${trainingMode === "quick" ? "Quick overview" : trainingMode === "module" ? `${step.group || "Module"} · Transaction simulation` : `${step.group || "Full tutorial"} · Full tutorial`} ${trainingIndex + 1} of ${total}</div>
      <h2>${esc(step.title)}</h2>
      ${step.subtitle ? `<p class="training-subtitle">${esc(step.subtitle)}</p>` : ""}
      ${step.details?.length ? `<div class="training-step-detail"><h3>How to use this module</h3><ol>${step.details.map((detail) => `<li>${esc(detail)}</li>`).join("")}</ol></div>` : `<p>${esc(step.body)}</p>`}
      <div class="training-actions">
        ${step.practiceControl ? `<button id="trainingPracticeBtn">Open practice popup</button>` : ""}
        <button id="trainingBackBtn" ${trainingIndex === 0 ? "disabled" : ""}>Back</button>
        <button id="trainingNextBtn" class="primary">${trainingIndex >= total - 1 ? "Finish" : "Next"}</button>
        <button id="trainingAutoBtn">Auto play</button>
        <button id="trainingEndBtn">End training</button>
      </div>
    </div>`;
  $("trainingBackBtn").onclick = () => moveTraining(-1);
  $("trainingNextBtn").onclick = () => moveTraining(1);
  $("trainingAutoBtn").onclick = autoPlayTraining;
  $("trainingEndBtn").onclick = endTraining;
  if ($("trainingPracticeBtn")) $("trainingPracticeBtn").onclick = () => openPracticePopup(step.practiceControl);
}

function moveTraining(delta) {
  clearTimeout(trainingAutoplay);
  if (delta > 0 && activeTrainingSteps[trainingIndex]?.closePracticePopup) closeModal();
  const total = activeTrainingSteps.length;
  trainingIndex += delta;
  if (trainingIndex < 0) trainingIndex = 0;
  if (trainingIndex >= total) return endTraining();
  showTrainingStep();
}

function autoPlayTraining() {
  clearTimeout(trainingAutoplay);
  trainingAutoplay = setTimeout(() => {
    const total = activeTrainingSteps.length;
    if (trainingIndex >= total - 1) return endTraining();
    trainingIndex += 1;
    showTrainingStep();
  }, 8500);
}

function removeTrainingHighlight() {
  document.querySelectorAll(".training-highlight").forEach((el) => el.classList.remove("training-highlight"));
}

function endTraining() {
  if (trainingMode === "module") closeModal();
  clearTimeout(trainingAutoplay);
  removeTrainingHighlight();
  $("trainingOverlay")?.remove();
  document.body.classList.remove("training-active");
  trainingMode = null;
  trainingIndex = 0;
  activeTrainingSteps = [];
}

function renderNav() {
  const assignedModules = [...userModules()];
  if (assignedModules.includes("truckingtickets") && !isTruckingDriverUser()) {
    ["truckingticketentry", "truckinglabor", "truckingreport"].forEach((moduleId) => {
      if (!assignedModules.includes(moduleId)) assignedModules.push(moduleId);
    });
  }
  const permittedModules = assignedModules.includes("all")
    ? modules
    : modules
      .map((group) => ({
        ...group,
        items: group.items.filter(([id]) => id === "dashboard" || assignedModules.includes(id)),
      }))
      .filter((group) => group.items.length);
  const truckingDriverModules = () => {
    const driverIds = new Set(["trucking_driver", "truckingassigned", "truckingtickets"]);
    const extraGroups = permittedModules
      .map((group) => ({
        ...group,
        items: group.items.filter(([id]) => id !== "dashboard" && !driverIds.has(id) && assignedModules.includes(id)),
      }))
      .filter((group) => group.items.length);
    return [
      { group: "Trucking Driver", items: [["truckingassigned", "Assigned Driver"], ["truckingtickets", "Tickets"]] },
      ...extraGroups,
    ];
  };
  const visibleModules = isDualRequestPortalUser()
    ? [{ group: "Requests", items: [["requestportal", "Request Choices"], ["equipmentrequests", "Equipment Requests"], ["truckingrequests", "Move Requests"], ["equipmentrepairqueue", "Equipment Repair Requests"]] }]
    : isMechanicUser()
    ? [{ group: "Mechanic", items: [["repairs", "Work Orders"]] }]
    : isEquipmentRequestUser()
      ? [{ group: "Equipment Request", items: [["equipmentrequests", "Equipment Requests"]] }]
      : isFuelUser()
        ? [{ group: "Fuel", items: [["fuel", "Fuel Portal"]] }]
        : isTruckingDriverUser() && !assignedModules.includes("all")
          ? truckingDriverModules()
          : isTruckingRequestorUser()
            ? [{ group: "Move Request", items: [["truckingrequests", "Move Requests"]] }]
            : permittedModules;
  visibleNavigationModules = visibleModules;
  $("nav").innerHTML = `
    <div class="module-search-wrap">
      <input id="moduleSearch" class="module-search" type="search" placeholder="Search the whole system" aria-label="Search the whole system" autocomplete="off">
      <small>Find modules, work orders, POs, invoices, customers, vendors, equipment, parts, AP, AR, checks, and references.</small>
      <div id="systemSearchResults" class="system-search-results" hidden></div>
    </div>
  ` + visibleModules.map((group) => `
    <details class="nav-group nav-major" data-nav-group="${esc(group.group)}" ${group.items.some(([id]) => id === currentView) ? "open" : ""}>
      <summary class="nav-title nav-major-title"><span>${esc(group.group)}</span><span class="nav-major-count">${group.items.length}</span></summary>
      <div class="nav-segments">${group.items.map(([id, label]) => `<button class="nav-btn" data-view="${id}">${esc(label)}</button>`).join("")}</div>
    </details>
  `).join("");
  document.querySelectorAll("[data-view]").forEach((btn) => btn.onclick = async () => {
    closeSystemSearchResults();
    await loadView(btn.dataset.view);
  });
  document.querySelectorAll("#nav .nav-major").forEach((group) => {
    const key = navGroupStorageKey(group.dataset.navGroup);
    if (!group.querySelector(`.nav-btn[data-view="${CSS.escape(currentView)}"]`)) group.open = localStorage.getItem(key) === "1";
    group.ontoggle = () => localStorage.setItem(key, group.open ? "1" : "0");
  });
  $("moduleSearch").oninput = scheduleSystemSearch;
  $("moduleSearch").onfocus = () => {
    if ($("moduleSearch").value.trim()) scheduleSystemSearch();
  };
  $("moduleSearch").onkeydown = (event) => {
    if (event.key === "Escape") {
      closeSystemSearchResults();
      return;
    }
    if (event.key === "Enter") {
      const firstMatch = $("systemSearchResults")?.querySelector("[data-system-search-result]");
      if (!firstMatch) return;
      event.preventDefault();
      firstMatch.click();
    }
  };
}

function navGroupStorageKey(group) {
  const identity = profile?.email || profile?.username || session?.user?.email || "local";
  return `lms.navGroup.v2:${identity}:${group || "Other"}`;
}

function closeSystemSearchResults() {
  const host = $("systemSearchResults");
  if (host) host.hidden = true;
}

function scheduleSystemSearch() {
  clearTimeout(systemSearchTimer);
  systemSearchTimer = setTimeout(runSystemSearch, 260);
}

