function accessibleNavigationIds() {
  return new Set(visibleNavigationModules.flatMap((group) => group.items.map(([id]) => id)));
}

function systemSearchRef(provider, row) {
  return String(typeof provider.ref === "function" ? provider.ref(row) : row[provider.ref] || "").trim();
}

async function runSystemSearch() {
  const input = $("moduleSearch");
  const host = $("systemSearchResults");
  if (!input || !host) return;
  const query = input.value.trim();
  const requestId = ++systemSearchRequest;
  systemSearchResultMap.clear();
  if (!query) return closeSystemSearchResults();
  host.hidden = false;
  host.innerHTML = `<div class="system-search-state">${query.length < 2 ? "Type at least 2 characters." : "Searching the system…"}</div>`;
  if (query.length < 2) return;
  const allowed = accessibleNavigationIds();
  const moduleResults = visibleNavigationModules.flatMap((group) => group.items
    .filter(([id, label]) => `${group.group} ${id} ${label}`.toLowerCase().includes(query.toLowerCase()))
    .map(([view, label]) => ({ kind: "module", view, title: label, reference: group.group, detail: "Open module" })));
  const safe = query.replace(/[,%_()]/g, " ").replace(/\s+/g, " ").trim();
  const providers = systemSearchProviders.filter((provider) => allowed.has(provider.view) || (provider.view === "accounting" && allowed.has("accounting")));
  const groups = await Promise.all(providers.map(async (provider) => {
    try {
      const filter = provider.fields.map((field) => `${field}.ilike.%${safe}%`).join(",");
      const { data, error } = await supabase.from(provider.table).select(provider.columns).or(filter).limit(6);
      if (error) return [];
      return (data || []).map((row) => ({
        kind: "record",
        view: provider.view,
        tab: provider.tab || "",
        title: provider.name,
        reference: systemSearchRef(provider, row),
        detail: (provider.detail(row) || []).filter(Boolean).join(" • "),
      }));
    } catch {
      return [];
    }
  }));
  if (requestId !== systemSearchRequest) return;
  const combined = [...moduleResults, ...groups.flat()];
  const unique = [...new Map(combined.map((result) => [`${result.kind}|${result.view}|${result.tab}|${result.reference}`, result])).values()].slice(0, 60);
  if (!unique.length) {
    host.innerHTML = `<div class="system-search-state">No accessible results found for “${esc(query)}”.</div>`;
    return;
  }
  host.innerHTML = `<div class="system-search-heading">Search results <span>${unique.length}</span></div><div class="system-search-columns"><span>Category</span><span>Reference / Number</span><span>Details</span><span>Module</span></div>${unique.map((result, index) => {
    const key = `r${index}`;
    systemSearchResultMap.set(key, result);
    const moduleLabel = userModuleChoices.find((item) => item.id === result.view)?.label || result.title;
    return `<button type="button" class="system-search-result" data-system-search-result="${key}"><span class="system-search-kind" data-label="Category">${esc(result.title)}</span><strong data-label="Reference / Number">${esc(result.reference || result.title)}</strong><small data-label="Details">${esc(result.detail || "Open result")}</small><span class="system-search-module" data-label="Module">${esc(moduleLabel)}</span></button>`;
  }).join("")}`;
  host.querySelectorAll("[data-system-search-result]").forEach((button) => button.onclick = () => openSystemSearchResult(systemSearchResultMap.get(button.dataset.systemSearchResult)));
}

async function openSystemSearchResult(result) {
  if (!result) return;
  closeSystemSearchResults();
  $("moduleSearch").value = "";
  if (result.tab) accountingTab = result.tab;
  await loadView(result.view);
  if (result.kind === "module") return;
  const ref = result.reference;
  if (result.view === "purchasing" || result.view === "orders" || result.view === "repairs") {
    const config = {
      purchasing: { table: "purchase_orders", column: "po_no", open: openPurchaseOrderModal },
      orders: { table: "sales_orders", column: "order_no", open: openSalesOrderModal },
      repairs: { table: "work_orders", column: "wo_no", open: openWorkOrderEditModal },
    }[result.view];
    let row = (currentRows || []).find((item) => String(item[config.column] || "").toLowerCase() === ref.toLowerCase());
    if (!row) {
      const response = await supabase.from(config.table).select("*").ilike(config.column, ref).limit(1).maybeSingle();
      row = response.data || null;
    }
    if (row) return config.open(row);
  }
  if (result.view === "invoices") {
    const row = (currentRows || []).find((item) => String(item.invoice_no || "").toLowerCase() === ref.toLowerCase());
    if (row) return openInvoiceModal(row);
  }
  if (result.view === "fuel") return openFuelReportModal(ref);
  const search = document.querySelector("#content .searchbox, #content input[type='search']");
  if (search) {
    search.value = ref;
    search.dispatchEvent(new Event("input", { bubbles: true }));
    search.focus();
  }
}

function isMechanicUser() {
  const role = String(profile?.role || "");
  const mods = userModules().filter((m) => m && m !== "dashboard");
  return /mechanic/i.test(role) || (!userModules().includes("all") && mods.length === 1 && mods[0] === "repairs");
}

function isMechanicManagerUser() {
  return /mechanic\s*manager/i.test(String(profile?.role || ""));
}

function userModules() {
  const mods = normalizeModules(profile?.modules);
  return mods.length ? mods : ["dashboard"];
}

function normalizeModules(value) {
  if (Array.isArray(value)) return value.map((m) => String(m || "").trim()).filter(Boolean);
  if (typeof value !== "string") return [];
  const text = value.trim();
  if (!text) return [];
  if (text.startsWith("[")) {
    try {
      const parsed = JSON.parse(text);
      if (Array.isArray(parsed)) return parsed.map((m) => String(m || "").trim()).filter(Boolean);
    } catch {}
  }
  return text
    .replace(/[{}"]/g, "")
    .split(",")
    .map((m) => m.trim())
    .filter(Boolean);
}

function normalizeProfile(row, user) {
  const email = String(user?.email || row?.email || "").trim().toLowerCase();
  const modules = normalizeModules(row?.modules);
  const ownerAdmin = isBryanOwner({ ...row, email });
  return {
    ...row,
    email: row?.email || email,
    username: row?.username || email,
    full_name: row?.full_name || row?.username || email,
    role: ownerAdmin ? "Administrator" : (row?.role || "User"),
    modules: ownerAdmin ? ["all"] : (modules.length ? modules : ["dashboard"]),
  };
}

function isBryanOwner(row = profile) {
  const email = String(row?.email || session?.user?.email || "").trim().toLowerCase();
  const username = String(row?.username || row?.full_name || "").trim().toLowerCase();
  return email === "bryan.dy@lmsfm.com" || username === "bryan.dy";
}

function isAdminUser() {
  const role = String(profile?.role || "");
  return isBryanOwner() || /admin|administrator|owner/i.test(role) || userModules().includes("all");
}

function canApproveInventoryControl() {
  return isAdminUser() || /manager|controller|accounting/i.test(String(profile?.role || ""));
}

function assertBalancedLedgerRows(rows, label = "Accounting entry") {
  const debit = (rows || []).reduce((sum, row) => sum + Number(row.debit || 0), 0);
  const credit = (rows || []).reduce((sum, row) => sum + Number(row.credit || 0), 0);
  if (Math.abs(debit - credit) > 0.005) throw new Error(`${label} is not balanced. Debit ${money(debit)} does not equal credit ${money(credit)}.`);
  return true;
}

async function enforceCustomerCreditControl(customerName, newAmount = 0, sourceLabel = "transaction") {
  const customers = productMeta.customerRows?.length ? productMeta.customerRows : await getAll("customers");
  const customer = (customers || []).find((row) => String(row.name || "").trim().toLowerCase() === String(customerName || "").trim().toLowerCase());
  if (!customer) return true;
  if (/hold|blocked|inactive/i.test(`${customer.credit_status || ""} ${customer.status || ""}`)) {
    if (!canApproveInventoryControl()) {
      alert(`${customer.name} is on credit hold. A Manager or Administrator must approve this ${sourceLabel}.`);
      return false;
    }
    if (!confirm(`${customer.name} is on credit hold. Override and continue with this ${sourceLabel}?`)) return false;
  }
  const creditLimit = Number(customer.credit_limit || 0);
  if (!(creditLimit > 0)) return true;
  const [invoices, lines, payments] = await Promise.all([getAll("invoices"), getAll("invoice_lines"), getAll("customer_payments")]);
  const openBalance = invoices.filter((invoice) => String(invoice.customer || "").trim().toLowerCase() === String(customer.name || "").trim().toLowerCase() && !/void|reversed/i.test(invoice.status || "")).reduce((sum, invoice) => {
    const total = lines.filter((line) => line.invoice_id === invoice.id).reduce((lineSum, line) => lineSum + Number(line.qty || 0) * Number(line.rate || 0), 0);
    const paid = payments.filter((payment) => payment.invoice_no === invoice.invoice_no && !/void|reversed/i.test(payment.status || "")).reduce((paymentSum, payment) => paymentSum + Number(payment.amount || 0), 0);
    return sum + Math.max(0, total - paid);
  }, 0);
  const projected = openBalance + Number(newAmount || 0);
  if (projected <= creditLimit + 0.005) return true;
  const message = `${customer.name} would exceed the ${money(creditLimit)} credit limit. Current open balance: ${money(openBalance)}; projected: ${money(projected)}.`;
  if (!canApproveInventoryControl()) {
    alert(`${message} Manager or Administrator approval is required.`);
    return false;
  }
  return confirm(`${message}\n\nApprove this credit-limit override?`);
}

function adminOnly(action) {
  if (!isAdminUser()) {
    alert("Only administrators can use this control.");
    return;
  }
  return action();
}

async function openTransactionResetControl() {
  if (!isBryanOwner()) return alert("Only bryan.dy@lmsfm.com can access Transaction Reset.");
  const { data, error } = await supabase.rpc("transaction_reset_status");
  if (error) return alert(error.message || "Could not load transaction reset status.");
  const runs = Array.isArray(data) ? data : [];
  const recoverable = runs.find((run) => run.status === "Recoverable");
  $("modalTitle").textContent = "Owner-Only Recoverable Transaction Reset";
  $("modalBody").innerHTML = `
    <div class="notice danger-notice">
      This clears approved transactional tables only. Fleet & Equipment, QR codes, Fuel Logs, Fuel Jobsites,
      Chart of Accounts, users, and master data remain unchanged. Loaded beginning balances are included in the reset.
    </div>
    ${recoverable ? `
      <div class="panel">
        <p><strong>Recoverable reset:</strong> ${esc(recoverable.id)}</p>
        <p>Created ${esc(formatDateTime(recoverable.created_at))} by ${esc(recoverable.created_by)}</p>
        <div class="actions">
          <button type="button" class="primary" id="recoverTransactionResetBtn">Recover Deleted Transactions</button>
          <button type="button" class="danger" id="finalizeTransactionResetBtn">Finalize Permanently</button>
        </div>
      </div>` : `
      <div class="panel">
        <p>No recoverable reset is currently open.</p>
        <button type="button" class="danger" id="createTransactionResetBtn">Create Snapshot & Clear Transactions</button>
      </div>`}
    <div class="tablewrap"><table>
      <thead><tr><th>Date</th><th>Reset ID</th><th>Status</th><th>Recovered</th><th>Finalized</th></tr></thead>
      <tbody>${runs.map((run) => `<tr><td>${esc(formatDateTime(run.created_at))}</td><td>${esc(run.id)}</td><td>${badge(run.status)}</td><td>${esc(formatDateTime(run.recovered_at))}</td><td>${esc(formatDateTime(run.finalized_at))}</td></tr>`).join("") || `<tr><td colspan="5">No reset history.</td></tr>`}</tbody>
    </table></div>`;
  $("modalSave").style.display = "none";
  $("modalCancel").textContent = "Close";
  $("modal").style.display = "flex";
  if ($("createTransactionResetBtn")) $("createTransactionResetBtn").onclick = createRecoverableTransactionReset;
  if ($("recoverTransactionResetBtn")) $("recoverTransactionResetBtn").onclick = () => recoverTransactionReset(recoverable.id);
  if ($("finalizeTransactionResetBtn")) $("finalizeTransactionResetBtn").onclick = () => finalizeTransactionReset(recoverable.id);
}

async function createRecoverableTransactionReset() {
  const confirmation = prompt('Type exactly "RESET TRANSACTIONAL DATA" to create a snapshot and clear transactional records.');
  if (confirmation !== "RESET TRANSACTIONAL DATA") return alert("Reset cancelled. The confirmation text did not match.");
  if (!confirm("Create the recovery snapshot and clear transactional data now?")) return;
  const { data, error } = await supabase.rpc("create_recoverable_transaction_reset");
  if (error) return alert(error.message || "Transaction reset failed. No partial reset was committed.");
  alert(`Transactional data was cleared.\nRecovery ID: ${data}\n\nUse Recover before Finalize if you need to restore it.`);
  location.reload();
}

async function recoverTransactionReset(resetId) {
  const confirmation = prompt('Type exactly "RECOVER TRANSACTIONAL DATA" to restore the saved snapshot.');
  if (confirmation !== "RECOVER TRANSACTIONAL DATA") return alert("Recovery cancelled. The confirmation text did not match.");
  const { error } = await supabase.rpc("recover_transaction_reset", { p_reset_id: resetId });
  if (error) return alert(error.message || "Could not recover the transactional data.");
  alert("Transactional data was recovered successfully.");
  location.reload();
}

async function finalizeTransactionReset(resetId) {
  const confirmation = prompt('Type exactly "FINALIZE PERMANENTLY" to destroy the recovery snapshot. This cannot be undone.');
  if (confirmation !== "FINALIZE PERMANENTLY") return alert("Finalization cancelled. The confirmation text did not match.");
  if (!confirm("Permanently remove the recovery snapshot? This cannot be undone.")) return;
  const { error } = await supabase.rpc("finalize_transaction_reset", { p_reset_id: resetId });
  if (error) return alert(error.message || "Could not finalize the transaction reset.");
  alert("The reset was finalized. The deleted transactional data can no longer be recovered from this snapshot.");
  await openTransactionResetControl();
}

function isEquipmentRequestUser() {
  const mods = userModules();
  const visible = mods.filter((m) => m && m !== "dashboard");
  return !isMechanicUser() && !isFuelUser() && !mods.includes("all") && visible.length === 1 && visible[0] === "equipmentrequests";
}

function isDualRequestPortalUser() {
  const mods = userModules();
  const visible = mods.filter((m) => m && m !== "dashboard");
  return !mods.includes("all")
    && visible.length >= 2
    && visible.includes("equipmentrequests")
    && visible.includes("truckingrequests")
    && visible.every((moduleId) => ["equipmentrequests", "truckingrequests", "equipmentrepairqueue", "propertyrequests"].includes(moduleId));
}

function isPropertyMaintenanceRequestUser() {
  const mods = userModules();
  const visible = mods.filter((m) => m && m !== "dashboard");
  return !mods.includes("all") && visible.length === 1 && visible[0] === "propertyrequests";
}

function dualRequestPortalTabs(activeView) {
  if (!isDualRequestPortalUser()) return "";
  return `<nav class="request-portal-switcher" aria-label="Request type">
    <button type="button" class="${activeView === "requestportal" ? "active" : ""}" data-request-portal-view="requestportal">Request choices</button>
    <button type="button" class="${activeView === "equipmentrequests" ? "active" : ""}" data-request-portal-view="equipmentrequests">Equipment Requests</button>
    <button type="button" class="${activeView === "truckingrequests" ? "active" : ""}" data-request-portal-view="truckingrequests">Trucking Move Requests</button>
    <button type="button" class="${activeView === "equipmentrepairqueue" ? "active" : ""}" data-request-portal-view="equipmentrepairqueue">Equipment Repair Requests</button>
    <button type="button" class="${activeView === "propertyrequests" ? "active" : ""}" data-request-portal-view="propertyrequests">Property Maintenance Requests</button>
  </nav>`;
}

function bindDualRequestPortalTabs(root = document) {
  root.querySelectorAll("[data-request-portal-view]").forEach((button) => {
    button.onclick = () => loadView(button.dataset.requestPortalView);
  });
}

function usesEquipmentRequestMobileView() {
  return isEquipmentRequestUser() || isDualRequestPortalUser();
}

function usesTruckingRequestMobileView() {
  return isTruckingRequestorUser() || isDualRequestPortalUser();
}

function isFuelUser() {
  const role = String(profile?.role || "");
  const mods = userModules();
  const visible = mods.filter((m) => m && m !== "dashboard");
  return /fuel/i.test(role) || (!mods.includes("all") && visible.length === 1 && visible[0] === "fuel");
}

function isTruckingDriverUser() {
  const role = String(profile?.role || "");
  const mods = userModules();
  const visible = mods.filter((m) => m && m !== "dashboard");
  const driverOnlyModules = visible.includes("truckingassigned")
    && visible.every((moduleId) => ["trucking_driver", "truckingassigned", "truckingtickets"].includes(moduleId));
  return /trucking\s*driver/i.test(role)
    || (!mods.includes("all") && (visible.includes("trucking_driver") || driverOnlyModules));
}

function usesTruckingDriverMobileMode() {
  if (!isTruckingDriverUser()) return false;
  const driverModules = new Set(["dashboard", "trucking_driver", "truckingassigned", "truckingtickets"]);
  return !userModules().some((moduleId) => !driverModules.has(moduleId));
}

function isTruckingRequestorUser() {
  const role = String(profile?.role || "");
  const mods = userModules();
  const visible = mods.filter((m) => m && m !== "dashboard");
  return /requestor/i.test(role) || (!mods.includes("all") && (visible.includes("trucking_requestor") || (visible.length === 1 && visible[0] === "truckingrequests")));
}

function defaultView() {
  if (isDualRequestPortalUser()) return "requestportal";
  if (isPropertyMaintenanceRequestUser()) return "propertyrequests";
  if (isMechanicUser()) return "repairs";
  if (isEquipmentRequestUser()) return "equipmentrequests";
  if (isFuelUser()) return "fuel";
  if (isTruckingDriverUser()) return "truckingassigned";
  if (isTruckingRequestorUser()) return "truckingrequests";
  return "dashboard";
}

const LOGIN_MEMORY_KEY = "lms_login_memory";

async function loadRememberedLogin() {
  try {
    const saved = JSON.parse(localStorage.getItem(LOGIN_MEMORY_KEY) || "{}");
    let migratedLegacyPassword = false;
    if (saved.email && $("email")) $("email").value = saved.email;
    if ($("rememberLogin")) $("rememberLogin").checked = saved.remember !== false;
    // Older versions stored the password in browser storage. Remove it as soon as
    // the app opens after handing it to the browser's protected password manager.
    if (saved.password) {
      if ($("password")) $("password").value = saved.password;
      if (saved.email && navigator.credentials?.store && window.PasswordCredential) {
        try {
          await navigator.credentials.store(new PasswordCredential({ id: saved.email, name: saved.email, password: saved.password }));
        } catch {}
      }
      localStorage.setItem(LOGIN_MEMORY_KEY, JSON.stringify({ remember: saved.remember !== false, email: saved.email || "" }));
      migratedLegacyPassword = true;
    }
    if (!migratedLegacyPassword && saved.remember === true && navigator.credentials?.get && window.PasswordCredential) {
      const credential = await navigator.credentials.get({ password: true, mediation: "optional" });
      if (credential?.type === "password") {
        if ($("email")) $("email").value = credential.id || saved.email || "";
        if ($("password")) $("password").value = credential.password || "";
      }
    }
  } catch {}
}

async function saveRememberedLogin(email, password) {
  const remember = $("rememberLogin") ? $("rememberLogin").checked : true;
  try {
    if (remember) localStorage.setItem(LOGIN_MEMORY_KEY, JSON.stringify({ remember: true, email }));
    else localStorage.removeItem(LOGIN_MEMORY_KEY);
  } catch {}
  try {
    if (remember && password && navigator.credentials?.store && window.PasswordCredential) {
      await navigator.credentials.store(new PasswordCredential({
        id: email,
        name: profile?.full_name || email,
        password,
      }));
    } else if (!remember && navigator.credentials?.preventSilentAccess) {
      await navigator.credentials.preventSilentAccess();
    }
  } catch {}
}

async function login() {
  $("loginMsg").textContent = "";
  const email = $("email").value.trim().toLowerCase();
  const password = $("password").value;
  const { data, error } = await supabase.auth.signInWithPassword({ email, password });
  if (error) {
    $("loginMsg").textContent = error.message;
    return;
  }
  session = data.session;
  await loadProfile();
  await saveRememberedLogin(email, password);
  renderNav();
  updateAuthView();
  await loadView(defaultView());
  await handleAssetHash();
}

async function logout() {
  await supabase.auth.signOut();
  session = null;
  profile = null;
  updateAuthView();
}

function validatePasswordChange(currentPassword, newPassword, confirmation) {
  if (!currentPassword) return "Enter your current password.";
  if (!newPassword) return "Enter a new password.";
  if (newPassword.length < 8) return "The new password must contain at least 8 characters.";
  if (newPassword === currentPassword) return "The new password must be different from the current password.";
  if (newPassword !== confirmation) return "The new password and confirmation do not match.";
  return "";
}

function openChangePasswordModal() {
  if (!session?.user) return alert("Please log in before changing your password.");
  document.querySelector(".modalbox")?.classList.remove("wide-modal");
  $("modalTitle").textContent = "Change Password";
  $("modalBody").innerHTML = `
    <div class="form-grid password-change-form">
      <div class="field wide"><label>Current Password *</label><input id="currentPasswordInput" type="password" autocomplete="current-password" required></div>
      <div class="field wide"><label>New Password *</label><input id="newPasswordInput" type="password" autocomplete="new-password" minlength="8" required></div>
      <div class="field wide"><label>Confirm New Password *</label><input id="confirmPasswordInput" type="password" autocomplete="new-password" minlength="8" required></div>
    </div>
    <label class="checkline password-visibility-toggle"><input id="showPasswordChangeFields" type="checkbox"> Show passwords</label>
    <p class="notice">Use at least 8 characters. After the password is changed, you will be signed out and must log in again with the new password.</p>
  `;
  $("modalSave").style.display = "";
  $("modalSave").textContent = "Update Password";
  $("modalSave").onclick = saveCurrentUserPassword;
  $("modalCancel").textContent = "Cancel";
  $("modal").style.display = "flex";
  $("showPasswordChangeFields").onchange = (event) => {
    const type = event.target.checked ? "text" : "password";
    ["currentPasswordInput", "newPasswordInput", "confirmPasswordInput"].forEach((id) => { $(id).type = type; });
  };
  queueMicrotask(() => $("currentPasswordInput")?.focus());
}

async function saveCurrentUserPassword() {
  const currentPassword = $("currentPasswordInput")?.value || "";
  const newPassword = $("newPasswordInput")?.value || "";
  const confirmation = $("confirmPasswordInput")?.value || "";
  const validationError = validatePasswordChange(currentPassword, newPassword, confirmation);
  if (validationError) throw new Error(validationError);

  const email = String(session?.user?.email || "").trim().toLowerCase();
  if (!email) throw new Error("This login does not have an email address that can be verified.");

  const verified = await supabase.auth.signInWithPassword({ email, password: currentPassword });
  if (verified.error) throw new Error("The current password is incorrect.");

  const changed = await supabase.auth.updateUser({
    password: newPassword,
    current_password: currentPassword,
  });
  if (changed.error) throw new Error(changed.error.message || "The password could not be changed.");

  try {
    const remembered = JSON.parse(localStorage.getItem(LOGIN_MEMORY_KEY) || "{}");
    localStorage.setItem(LOGIN_MEMORY_KEY, JSON.stringify({ remember: remembered.remember !== false, email }));
  } catch {}
  try {
    const remembered = JSON.parse(localStorage.getItem(LOGIN_MEMORY_KEY) || "{}");
    if (remembered.remember === true && navigator.credentials?.store && window.PasswordCredential) {
      await navigator.credentials.store(new PasswordCredential({ id: email, name: profile?.full_name || email, password: newPassword }));
    }
  } catch {}
  closeModal(true);
  await supabase.auth.signOut();
  session = null;
  profile = null;
  updateAuthView();
  if ($("email")) $("email").value = email;
  if ($("password")) $("password").value = "";
  alert("Password changed successfully. Please log in again with your new password.");
}

async function loadProfile() {
  const user = session?.user;
  if (!user) return;
  const email = String(user.email || "").trim().toLowerCase();
  let { data } = await supabase.from("app_profiles").select("*").eq("id", user.id).maybeSingle();
  if (!data && email) {
    const byEmail = await supabase.from("app_profiles").select("*").ilike("email", email).maybeSingle();
    data = byEmail.data;
  }
  if (!data && email) {
    const byUsername = await supabase.from("app_profiles").select("*").ilike("username", email).maybeSingle();
    data = byUsername.data;
  }
  const fallbackRole = /bryan\.dy@lmsfm\.com/i.test(email) ? "Administrator" : "User";
  const fallbackModules = fallbackRole === "Administrator" ? ["all"] : ["dashboard"];
  profile = normalizeProfile(data || { username: email, full_name: email, email, role: fallbackRole, modules: fallbackModules }, user);
}

function updateAuthView() {
  if (document.body.classList.contains("public-scan")) return;
  document.body.classList.toggle("logged-out", !session);
  document.body.classList.toggle("mechanic-mode", Boolean(session && isMechanicUser()));
  document.body.classList.toggle("equipment-request-mode", Boolean(session && usesEquipmentRequestMobileView()));
  document.body.classList.toggle("fuel-mode", Boolean(session && isFuelUser()));
  document.body.classList.toggle("trucking-driver-mode", Boolean(session && usesTruckingDriverMobileMode()));
  document.body.classList.toggle("trucking-requestor-mode", Boolean(session && usesTruckingRequestMobileView()));
  $("loginPanel").style.display = session ? "none" : "block";
  $("content").style.display = session ? "block" : "none";
  $("sessionBox").innerHTML = session ? `Logged in as<br><strong>${esc(profile?.full_name || session.user.email)}</strong><br>${esc(profile?.role || "User")}` : "Not logged in";
  $("logoutBtn").style.display = session ? "inline-block" : "none";
  $("changePasswordBtn").style.display = session ? "inline-block" : "none";
  $("mobileChangePasswordBtn").hidden = !session;
  if ($("columnSettingsBtn")) $("columnSettingsBtn").style.display = session ? "inline-block" : "none";
  ["exportBtn", "cloneExportBtn", "offlineCloneBtn"].forEach((id) => {
    if ($(id)) $(id).style.display = session && isAdminUser() ? "" : "none";
  });
  if ($("transactionResetBtn")) $("transactionResetBtn").hidden = !(session && isBryanOwner());
}

function hasAssetHash() {
  return /^#asset=/.test(location.hash || "");
}

function canAccess(view) {
  if (isDualRequestPortalUser()) return ["requestportal", "equipmentrequests", "truckingrequests", "equipmentrepairqueue", "propertyrequests"].includes(view);
  if (isPropertyMaintenanceRequestUser()) return view === "propertyrequests";
  if (isMechanicUser()) return view === "repairs";
  if (isEquipmentRequestUser()) return view === "equipmentrequests";
  if (isFuelUser()) return view === "fuel";
  if (isTruckingDriverUser()) {
    const mods = userModules();
    return view === "truckingassigned" || view === "truckingtickets" || mods.includes("all") || mods.includes(view);
  }
  if (isTruckingRequestorUser()) return view === "truckingrequests";
  const mods = userModules();
  if (["truckingticketentry", "truckinglabor", "truckingreport"].includes(view) && mods.includes("truckingtickets")) return true;
  return mods.includes("all") || mods.includes(view) || view === "dashboard";
}

async function loadView(view) {
  if (!session) return;
  if (isDualRequestPortalUser() && !["requestportal", "equipmentrequests", "truckingrequests", "equipmentrepairqueue", "propertyrequests"].includes(view)) view = "requestportal";
  const mechanicManagerCustomerForms = isMechanicManagerUser()
    && view === "customerforms"
    && canAccess("customerforms");
  if (isMechanicUser() && !mechanicManagerCustomerForms) view = "repairs";
  if (!isDualRequestPortalUser() && isEquipmentRequestUser()) view = "equipmentrequests";
  if (!isDualRequestPortalUser() && isPropertyMaintenanceRequestUser()) view = "propertyrequests";
  if (isFuelUser()) view = "fuel";
  if (isTruckingDriverUser()
      && !["truckingassigned", "truckingtickets"].includes(view)
      && !userModules().includes("all")
      && !userModules().includes(view)) view = "truckingassigned";
  if (!isDualRequestPortalUser() && isTruckingRequestorUser()) view = "truckingrequests";
  if (!canAccess(view)) {
    $("content").innerHTML = `<div class="panel"><div class="empty">Your user does not have access to this module.</div></div>`;
    return;
  }
  if (view !== currentView) clearTransientViewState();
  currentView = view;
  document.querySelectorAll(".nav-btn").forEach((b) => b.classList.toggle("active", b.dataset.view === view));
  const activeNavButton = document.querySelector(`.nav-btn[data-view="${CSS.escape(view)}"]`);
  const activeMajor = activeNavButton?.closest(".nav-major");
  if (activeMajor) activeMajor.open = true;
  $("content").innerHTML = `<div class="empty">Loading...</div>`;
  try {
    await ensurePartyMasterSuggestRows();
    if (view === "requestportal") return await renderRequestPortalHome();
    if (view === "dashboard") return await renderDashboard();
    if (view === "products") return await renderProductsView();
    if (view === "movements") return await renderStockMovementView();
    if (view === "inventory") return await renderInventoryBalanceView();
    if (view === "partsreport") return await renderPartsReportView();
    if (view === "purchasing") return await renderPurchasingView();
    if (view === "receipts") return await renderGoodsReceiptsView();
    if (view === "quotes") return await renderQuotationsView();
    if (view === "orders") return await renderSalesOrdersView();
    if (view === "salesrates") return await renderSalesPricingRatesView();
    if (view === "laborrates") return await renderLaborPricingRatesView();
    if (view === "salestopurchase") return await renderSalesPartsToOrderView();
    if (view === "rentalbids") return await renderEquipmentRentalBidsView();
    if (view === "rentals") return await renderRentalsView();
    if (view === "rentalrates") return await renderEquipmentRentalRatesView();
    if (view === "invoices") return await renderInvoicesView();
    if (view === "payments") return await renderCustomerPaymentsView();
    if (view === "accounting") return await renderAccountingView();
    if (view === "coa") return await renderChartOfAccountsView();
    if (view === "checkrun") return await renderCheckRunView();
    if (view === "bank") return await renderBankReconciliationView();
    if (view === "assets") return await renderAssetsView();
    if (view === "fleetreport") return await renderFleetEquipmentReportView();
    if (view === "outsidefleet") return await renderOutsideCustomerFleetView();
    if (view === "equipmentrepairquotes") return await renderEquipmentRepairQuotesView();
    if (view === "repairreport") return await renderRepairReportView();
    if (view === "equipmentrequests") return await renderEquipmentRequestsView();
    if (view === "customerforms") return await renderCustomerEquipmentFormsView();
    if (view === "fuel") return await renderFuelPortalView();
    if (view === "truckingrequests") return await renderTruckingRequestsView();
    if (view === "truckingquotes") return await renderTruckingQuotationsView();
    if (view === "trucking") return await renderTruckingSchedulerView();
    if (view === "truckingassigned") return await renderAssignedDriverView();
    if (view === "truckingticketentry") return await renderTruckingTicketEntryView();
    if (view === "truckingtickets") return await renderTruckingTicketsView();
    if (view === "truckinglabor") return await renderTruckingLaborDetailsView();
    if (view === "truckingreport") return await renderTruckingReportView();
    if (view === "truckingrates") return await renderTruckingRatesView();
    if (view === "propertymaster") return await renderPropertyMasterView();
    if (view === "propertyrequests") return await renderPropertyRequestsView();
    if (view === "propertyworkorders") return await renderPropertyWorkOrdersView();
    if (view === "propertyreport") return await renderPropertyMaintenanceReportView();
    if (view === "equipmentrepairqueue") return await renderEquipmentRepairQueueView();
    if (view === "repairs") return await renderRepairsView();
    if (view === "partsrequests") return await renderPartsRequestsView();
    if (view === "supplies") return await renderSuppliesIssuanceView();
    if (view === "aging") return await renderAgingSummaryView();
    if (view === "settings") return await renderSettingsView();
    if (tableMap[view]?.derived) return await renderDerived(view);
    currentCfg = tableMap[view];
    $("viewTitle").textContent = currentCfg.title;
    $("viewSub").textContent = currentCfg.sub;
    const { data, error } = await supabase.from(currentCfg.table).select("*").order(currentCfg.heads[0], { ascending: false }).limit(500);
    if (error) throw error;
    currentRows = data || [];
    renderTableModule();
  } catch (error) {
    console.error(error);
    $("content").innerHTML = `<section class="panel"><div class="panel-head"><div class="panel-title"><strong>Could not load ${esc(tableMap[view]?.title || view)}</strong><span>The module stopped on a database or browser error.</span></div><div class="actions"><button id="retryLoadView">Retry</button></div></div><div class="empty">${esc(error.message || error)}</div></section>`;
    $("retryLoadView").onclick = () => loadView(view);
  }
}

async function renderDashboard() {
  $("viewTitle").textContent = "Dashboard";
  $("viewSub").textContent = "A clear view of stock, value, alerts, and movement.";
  $("content").innerHTML = `<section class="panel"><div class="empty">Loading live dashboard summary...</div></section>`;
  const [products, sales, po, assets, repairs, rentals, invoices, gl] = await Promise.all([
    // Product Master commonly exceeds Supabase's 1,000-row response limit.
    // Use the paginated loader so Dashboard value/quantity exactly matches
    // the complete live Product Master instead of only its first page.
    getAll("products"),
    getDashboardRows("sales_orders", "status"),
    getDashboardRows("purchase_orders", "payment_status,match_status"),
    getDashboardRows("assets", "id,status"),
    getDashboardRows("work_orders", "status"),
    getDashboardRows("rentals", "status"),
    getDashboardRows("invoices", "status"),
    getDashboardRows("general_ledger", "debit,credit")
  ]);
  const inventoryValue = products.reduce((s, p) => s + Number(p.qty || 0) * Number(p.cost || 0), 0);
  const low = products.filter((p) => Number(p.qty || 0) <= Number(p.reorder_point || 0)).length;
  const openSales = sales.filter((s) => !["Fulfilled", "Paid", "Cancelled"].includes(s.status)).length;
  const apControl = po.filter((p) => p.payment_status !== "Paid").length;
  const fleetRepair = repairs.filter((r) => !["Complete", "Invoiced", "Cancelled"].includes(r.status)).length;
  const rentalsOut = rentals.filter((r) => ["Out", "Overdue", "Reserved"].includes(r.status)).length;
  const debit = gl.reduce((s, r) => s + Number(r.debit || 0), 0);
  const credit = gl.reduce((s, r) => s + Number(r.credit || 0), 0);

  $("content").innerHTML = `
    <div class="stats fleet-stats">
      ${stat("Inventory Value", money(inventoryValue), `${products.reduce((s, p) => s + Number(p.qty || 0), 0)} units on hand, ${low} low stock`)}
      ${stat("Open Sales / AR", openSales, `${invoices.filter((i) => i.status !== "Paid").length} open invoices`)}
      ${stat("AP To Control", apControl, "POs and payable exposure")}
      ${stat("Fleet & Repairs", assets.length, `${fleetRepair} open repair jobs`)}
      ${stat("Rentals Out", rentalsOut, `${rentals.length} rental records`)}
      ${stat("Net Position", money(debit - credit), "GL debit minus credit check")}
    </div>
    <section class="panel accounting-panel">
      <div class="panel-head"><div class="panel-title"><strong>Action Needed</strong><span>Operational exceptions from across the system</span></div></div>
      <div class="table-wrap"><table><tbody>
        <tr><td>${low} inventory item${low === 1 ? "" : "s"} at or below reorder point.</td><td><button data-jump="products">Review</button></td></tr>
        <tr><td>${po.filter((p) => p.match_status === "Mismatch").length} purchase order${po.length === 1 ? "" : "s"} need PO/GR/invoice matching review.</td><td><button data-jump="purchasing">Review</button></td></tr>
        <tr><td>${fleetRepair} work order${fleetRepair === 1 ? "" : "s"} open or waiting.</td><td><button data-jump="repairs">Review</button></td></tr>
      </tbody></table></div>
    </section>
    <section class="panel">
      <div class="panel-head"><div class="panel-title"><strong>Quick Access</strong><span>Jump into the most-used modules</span></div></div>
      <div class="quick-grid">
        ${quick("products", "Inventory", "Products, parts, preferred vendors, photos")}
        ${quick("purchasing", "Purchasing", "PO, goods receipt, matching, pay readiness")}
        ${quick("orders", "Sales", "Customer PO, issue goods, AR flow")}
        ${quick("assets", "Fleet", "Equipment photos, QR codes, readings")}
        ${quick("equipmentrequests", "Equipment Requests", "Request equipment, signatures, approvals")}
        ${quick("equipmenthistory", "Equipment History", "Parts used, problems, repair timeline")}
        ${quick("repairs", "Repairs", "Work orders, parts, labor clocking")}
        ${quick("supplies", "Supplies", "Issue supplies to people or WOs")}
        ${quick("accounting", "Accounting", "GL, AP, AR, statements, bank rec")}
        ${quick("rentals", "Rentals", "Checkout, returns, deposits, income")}
      </div>
    </section>`;
  document.querySelectorAll("[data-jump],[data-quick]").forEach((b) => b.onclick = () => loadView(b.dataset.jump || b.dataset.quick));
}

async function getDashboardRows(table, columns = "*", limit = 1000) {
  try {
    const { data, error } = await supabase.from(table).select(columns).limit(limit);
    if (error) throw error;
    return data || [];
  } catch (error) {
    console.warn(`Dashboard skipped ${table}`, error);
    return [];
  }
}

function stat(label, value, note) {
  return `<div class="stat"><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(note)}</small></div>`;
}

function quick(view, title, text) {
  return `<button class="quick-card" data-quick="${view}"><strong>${esc(title)}</strong><span>${esc(text)}</span></button>`;
}

async function renderDerived(view) {
  const cfg = tableMap[view];
  $("viewTitle").textContent = cfg.title;
  $("viewSub").textContent = cfg.sub;
  $("content").innerHTML = `<section class="panel"><div class="empty">This live report shell is ready. The detailed Supabase report logic will be filled in the next passes.</div></section>`;
}

const fleetReportSectionDefaults = ["location_history", "activity_summary", "current_location", "event_detail"];

function fleetReportDate(value) {
  return String(value || "").slice(0, 10);
}

function fleetReportPreviousDate(value) {
  const date = new Date(`${fleetReportDate(value)}T00:00:00Z`);
  if (Number.isNaN(date.getTime())) return fleetReportDate(value);
  date.setUTCDate(date.getUTCDate() - 1);
  return date.toISOString().slice(0, 10);
}

function fleetReportAssetTagsFromRequest(row = {}) {
  const tags = [row.asset_tag];
  const items = Array.isArray(row.asset_items) ? row.asset_items : [];
  items.forEach((item) => tags.push(typeof item === "string" ? item : item?.asset_tag || item?.asset_no || item?.reference));
  return [...new Set(tags.map((value) => String(value || "").trim()).filter(Boolean))];
}

function buildFleetLocationEvents(data) {
  const events = [];
  const add = (assetTag, date, location, source, reference = "", detail = "", explicitTo = "") => {
    const tag = String(assetTag || "").trim();
    const eventDate = fleetReportDate(date);
    const place = String(location || "").trim();
    if (!tag || !eventDate || !place) return;
    events.push({ asset_tag: tag, event_date: eventDate, location: place, source, reference: String(reference || ""), detail: String(detail || ""), explicit_to: fleetReportDate(explicitTo) });
  };
  (data.equipmentRequests || []).forEach((row) => fleetReportAssetTagsFromRequest(row).forEach((tag) => add(tag, row.from_date || row.request_date, row.location, "Equipment Request", row.request_no, row.customer_name || row.requested_by, row.to_date)));
  (data.fuelLogs || []).forEach((row) => add(row.asset_tag, row.fuel_date, row.jobsite, "Fuel Run", row.report_no, `${Number(row.gallons || 0).toFixed(2)} gal`));
  (data.workOrders || []).forEach((row) => add(row.asset_tag, row.wo_date, row.actual_location || row.jobsite_location, "Work Order", row.wo_no, row.description || row.status, row.closed_date));
  const requestByNo = new Map((data.truckingRequests || []).map((row) => [String(row.request_no || ""), row]));
  (data.truckingRequestLines || []).forEach((line) => {
    const request = requestByNo.get(String(line.request_no || "")) || {};
    add(line.asset_tag, request.needed_date || request.request_date, request.project_jobsite || request.jobsite || request.destination || line.destination, "Move Request", line.request_no, line.equipment_label || line.notes);
  });
  (data.assets || []).forEach((asset) => add(asset.asset_tag, asset.last_update_date || asset.scanned_date || asset.created_at || today(), asset.location, "Current Fleet Record", asset.asset_tag, asset.status));
  return [...new Map(events.map((row) => [[row.asset_tag.toLowerCase(), row.event_date, row.location.toLowerCase(), row.source, row.reference].join("|"), row])).values()]
    .sort((a, b) => a.asset_tag.localeCompare(b.asset_tag, undefined, { numeric: true, sensitivity: "base" }) || a.event_date.localeCompare(b.event_date) || a.source.localeCompare(b.source));
}

function buildFleetLocationIntervals(events, assets) {
  const assetByTag = new Map((assets || []).map((row) => [String(row.asset_tag || "").toLowerCase(), row]));
  const groups = new Map();
  events.forEach((event) => groups.set(event.asset_tag, [...(groups.get(event.asset_tag) || []), event]));
  const intervals = [];
  groups.forEach((rows, assetTag) => {
    const changes = [];
    rows.sort((a, b) => a.event_date.localeCompare(b.event_date) || a.source.localeCompare(b.source)).forEach((event) => {
      const previous = changes[changes.length - 1];
      if (previous && previous.location.toLowerCase() === event.location.toLowerCase()) {
        previous.sources.add(event.source);
        if (event.reference) previous.references.add(event.reference);
        if (event.explicit_to && (!previous.explicit_to || event.explicit_to > previous.explicit_to)) previous.explicit_to = event.explicit_to;
      } else changes.push({ ...event, sources: new Set([event.source]), references: new Set(event.reference ? [event.reference] : []) });
    });
    const asset = assetByTag.get(String(assetTag).toLowerCase()) || {};
    changes.forEach((change, index) => {
      const next = changes[index + 1];
      let toDate = next ? fleetReportPreviousDate(next.event_date) : (change.explicit_to || "Present");
      if (toDate !== "Present" && toDate < change.event_date) toDate = change.event_date;
      intervals.push({
        asset_tag: assetTag,
        equipment_type: asset.type || asset.general_type || "",
        description: asset.name || asset.description || "",
        location: change.location,
        from_date: change.event_date,
        to_date: toDate,
        duration_days: toDate === "Present" ? Math.max(1, Math.ceil((Date.now() - new Date(`${change.event_date}T00:00:00`).getTime()) / 86400000) + 1) : Math.max(1, Math.ceil((new Date(`${toDate}T00:00:00`).getTime() - new Date(`${change.event_date}T00:00:00`).getTime()) / 86400000) + 1),
        evidence: [...change.sources].join(" / "),
        references: [...change.references].join(", "),
        status: asset.status || "",
      });
    });
  });
  return intervals.sort((a, b) => a.asset_tag.localeCompare(b.asset_tag, undefined, { numeric: true, sensitivity: "base" }) || b.from_date.localeCompare(a.from_date));
}

function fleetReportFilters() {
  return {
    from: $("fleetReportFrom")?.value || "",
    to: $("fleetReportTo")?.value || "",
    asset: $("fleetReportAsset")?.value || "",
    location: $("fleetReportLocation")?.value || "",
    type: $("fleetReportType")?.value || "",
    status: $("fleetReportStatus")?.value || "",
    sections: [...document.querySelectorAll("[data-fleet-report-section]:checked")].map((box) => box.value),
  };
}

function filteredFleetReportData(filters = fleetReportFilters()) {
  const data = productMeta.fleetReportData || {};
  const assets = (data.assets || []).filter((asset) => (!filters.asset || asset.asset_tag === filters.asset) && (!filters.type || (asset.type || asset.general_type) === filters.type) && (!filters.status || asset.status === filters.status) && (!filters.location || asset.location === filters.location));
  const allowed = new Set(assets.map((asset) => String(asset.asset_tag || "").toLowerCase()));
  const events = (data.events || []).filter((row) => allowed.has(String(row.asset_tag || "").toLowerCase()) && (!filters.from || row.event_date >= filters.from) && (!filters.to || row.event_date <= filters.to) && (!filters.location || row.location === filters.location));
  const intervals = (data.intervals || []).filter((row) => allowed.has(String(row.asset_tag || "").toLowerCase()) && (!filters.from || row.to_date === "Present" || row.to_date >= filters.from) && (!filters.to || row.from_date <= filters.to) && (!filters.location || row.location === filters.location));
  const activity = assets.map((asset) => {
    const rows = events.filter((row) => String(row.asset_tag).toLowerCase() === String(asset.asset_tag).toLowerCase());
    const fuel = rows.filter((row) => row.source === "Fuel Run");
    const gallons = fuel.reduce((sum, row) => sum + Number(String(row.detail).match(/[\d.]+/)?.[0] || 0), 0);
    return { asset_tag: asset.asset_tag, equipment_type: asset.type || asset.general_type || "", description: asset.name || "", current_location: asset.location || "", fuel_runs: fuel.length, gallons, work_orders: new Set(rows.filter((row) => row.source === "Work Order").map((row) => row.reference)).size, move_requests: new Set(rows.filter((row) => row.source === "Move Request").map((row) => row.reference)).size, location_changes: intervals.filter((row) => String(row.asset_tag).toLowerCase() === String(asset.asset_tag).toLowerCase()).length, last_activity: rows.map((row) => row.event_date).sort().pop() || "", status: asset.status || "" };
  });
  const currentByLocation = [...assets.reduce((map, asset) => { const key = asset.location || "Unassigned"; const row = map.get(key) || { location: key, equipment_count: 0, active: 0, repair: 0, other: 0 }; row.equipment_count += 1; if (/repair|service|down/i.test(asset.status || "")) row.repair += 1; else if (/active|service|available|in service/i.test(asset.status || "")) row.active += 1; else row.other += 1; map.set(key, row); return map; }, new Map()).values()].sort((a, b) => b.equipment_count - a.equipment_count || a.location.localeCompare(b.location));
  return { assets, events, intervals, activity, currentByLocation, filters };
}

function fleetReportTable(rows, fields, labels, format = {}) {
  return truckingSimpleTable(rows, fields, { filters: false, wrapClass: "fleet-report-table", labels, format, empty: "No records match the selected filters." });
}

function fleetEquipmentReportMarkup(report, printMode = false) {
  const sections = new Set(report.filters.sections?.length ? report.filters.sections : fleetReportSectionDefaults);
  const period = `${report.filters.from ? formatDisplayDate(report.filters.from) : "Beginning"} – ${report.filters.to ? formatDisplayDate(report.filters.to) : "Current"}`;
  const locationHistory = fleetReportTable(report.intervals, ["asset_tag", "equipment_type", "description", "location", "from_date", "to_date", "duration_days", "evidence", "references"], ["Asset #", "Type", "Description", "Location", "From", "To", "Days", "Source", "Reference"], { from_date: (value) => esc(formatDisplayDate(value)), to_date: (value) => value === "Present" ? "Present" : esc(formatDisplayDate(value)) });
  const activity = fleetReportTable(report.activity, ["asset_tag", "equipment_type", "description", "current_location", "fuel_runs", "gallons", "work_orders", "move_requests", "location_changes", "last_activity", "status"], ["Asset #", "Type", "Description", "Current Location", "Fuel Runs", "Gallons", "Work Orders", "Moves", "Locations", "Last Activity", "Status"], { gallons: (value) => Number(value || 0).toFixed(2), last_activity: (value) => value ? esc(formatDisplayDate(value)) : "—" });
  const current = fleetReportTable(report.currentByLocation, ["location", "equipment_count", "active", "repair", "other"], ["Current Location", "Equipment", "Active / Available", "Repair / Down", "Other"]);
  const detail = fleetReportTable(report.events, ["event_date", "asset_tag", "location", "source", "reference", "detail"], ["Date", "Asset #", "Location", "Event Source", "Reference", "Details"], { event_date: (value) => esc(formatDisplayDate(value)) });
  return `<div class="fleet-report-document${printMode ? " print" : ""}"><div class="document-title"><strong>LMS IMPORTS</strong><h2>Fleet & Equipment Report</h2><span>${esc(period)}</span><small>Operational history only · Location ranges may be inferred from the next recorded location event</small></div><div class="summary-grid"><div class="summary-card"><span>Equipment</span><strong>${report.assets.length}</strong></div><div class="summary-card"><span>Location Periods</span><strong>${report.intervals.length}</strong></div><div class="summary-card"><span>Activity Events</span><strong>${report.events.length}</strong></div><div class="summary-card"><span>Locations</span><strong>${report.currentByLocation.length}</strong></div></div>${sections.has("location_history") ? `<section><h3>Equipment Location History</h3>${locationHistory}</section>` : ""}${sections.has("activity_summary") ? `<section><h3>Equipment Activity Summary</h3>${activity}</section>` : ""}${sections.has("current_location") ? `<section><h3>Current Fleet by Location</h3>${current}</section>` : ""}${sections.has("event_detail") ? `<section><h3>Detailed Equipment Events</h3>${detail}</section>` : ""}</div>`;
}

async function renderFleetEquipmentReportView() {
  currentCfg = tableMap.fleetreport;
  $("viewTitle").textContent = currentCfg.title;
  $("viewSub").textContent = currentCfg.sub;
  const [assets, equipmentRequests, fuelLogs, workOrders, truckingRequests, truckingRequestLines] = await Promise.all([
    getAll("assets"), getAll("equipment_requests").catch(() => []), getAll("fuel_logs").catch(() => []), getAll("work_orders").catch(() => []), getAll("trucking_requests").catch(() => []), getAll("trucking_request_lines").catch(() => []),
  ]);
  const data = { assets, equipmentRequests, fuelLogs, workOrders, truckingRequests, truckingRequestLines };
  data.events = buildFleetLocationEvents(data);
  data.intervals = buildFleetLocationIntervals(data.events, assets);
  productMeta.fleetReportData = data;
  const unique = (values) => [...new Set(values.map((value) => String(value || "").trim()).filter(Boolean))].sort((a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: "base" }));
  const options = (values, label) => `<option value="">All ${label}</option>${unique(values).map((value) => `<option value="${esc(value)}">${esc(value)}</option>`).join("")}`;
  $("content").innerHTML = `<section class="panel fleet-report-controls"><div class="panel-head"><div class="panel-title"><strong>Fleet & Equipment Reports</strong><span>Select a period, equipment filters, and one or more report sections.</span></div></div><div class="fleet-report-filter-grid"><label>From<input type="date" id="fleetReportFrom"></label><label>To<input type="date" id="fleetReportTo" value="${today()}"></label><label>Asset #<select id="fleetReportAsset">${options(assets.map((row) => row.asset_tag), "assets")}</select></label><label>Location<select id="fleetReportLocation">${options(assets.map((row) => row.location), "locations")}</select></label><label>Equipment Type<select id="fleetReportType">${options(assets.map((row) => row.type || row.general_type), "types")}</select></label><label>Status<select id="fleetReportStatus">${options(assets.map((row) => row.status), "statuses")}</select></label></div><div class="fleet-report-section-picker">${[["location_history", "Location History"], ["activity_summary", "Activity Summary"], ["current_location", "Current Fleet by Location"], ["event_detail", "Detailed Events"]].map(([value, label]) => `<label><input type="checkbox" data-fleet-report-section value="${value}" checked> ${label}</label>`).join("")}</div><div class="actions"><button class="primary" id="fleetReportApply">Apply Report</button><button id="fleetReportExcel">Excel</button><button id="fleetReportPrint">PDF / Print</button></div></section><section class="panel"><div id="fleetReportHost"></div></section>`;
  $("fleetReportApply").onclick = renderFilteredFleetEquipmentReport;
  $("fleetReportExcel").onclick = exportFleetEquipmentReport;
  $("fleetReportPrint").onclick = printFleetEquipmentReport;
  renderFilteredFleetEquipmentReport();
}

function renderFilteredFleetEquipmentReport() {
  const report = filteredFleetReportData();
  if (!report.filters.sections.length) return alert("Select at least one report section.");
  currentRows = report.events;
  $("fleetReportHost").innerHTML = fleetEquipmentReportMarkup(report);
}

function exportFleetEquipmentReport() {
  const report = filteredFleetReportData();
  const sections = new Set(report.filters.sections);
  const rows = [];
  if (sections.has("location_history")) report.intervals.forEach((row) => rows.push({ report_section: "Location History", ...row }));
  if (sections.has("activity_summary")) report.activity.forEach((row) => rows.push({ report_section: "Activity Summary", ...row }));
  if (sections.has("current_location")) report.currentByLocation.forEach((row) => rows.push({ report_section: "Current Fleet by Location", ...row }));
  if (sections.has("event_detail")) report.events.forEach((row) => rows.push({ report_section: "Detailed Events", ...row }));
  exportRowsCsv(rows, "fleet-equipment-report.csv");
}

