async function syncPostedManualJournalSubledgers({ gl = [], invoices = [], invoiceLines = [], pos = [] } = {}) {
  const grouped = new Map();
  gl.filter((row) => /manual journal/i.test(row.source || "") && !/reverse|void/i.test(row.status || "")).forEach((row) => {
    const reference = String(row.reference || "").trim();
    if (!reference) return;
    if (!grouped.has(reference)) grouped.set(reference, []);
    grouped.get(reference).push(normalizeGlRow(row));
  });
  let changed = false;
  for (const [reference, rows] of grouped) {
    const apAmount = rows.filter((row) => subledgerAccountMatches(row.account, "Accounts Payable")).reduce((sum, row) => sum + Number(row.credit || 0) - Number(row.debit || 0), 0);
    const arAmount = rows.filter((row) => subledgerAccountMatches(row.account, "Accounts Receivable")).reduce((sum, row) => sum + Number(row.debit || 0) - Number(row.credit || 0), 0);
    const postingDate = rows.map((row) => row.posting_date).filter(Boolean).sort()[0] || today();
    const description = rows.find((row) => row.description)?.description || `Manual journal ${reference}`;
    const vendor = rows.find((row) => row.vendor)?.vendor || "";
    const customer = rows.find((row) => row.customer)?.customer || "";
    if (apAmount > 0.005 && vendor) {
      const obsoleteManualPo = pos.find((po) => po.po_no === reference && /manual journal ap/i.test(`${po.status || ""} ${po.notes || ""}`));
      if (obsoleteManualPo?.id) {
        const { error } = await supabase.from("purchase_orders").delete().eq("id", obsoleteManualPo.id);
        if (error) throw error;
        changed = true;
      }
    }
    if (arAmount > 0.005 && customer && !invoices.some((invoice) => invoice.invoice_no === reference)) {
      const saved = await upsertMany("invoices", [{ invoice_no: reference, invoice_date: postingDate, due_date: postingDate, customer, type: "Manual Journal AR", source_ref: reference, status: "Open", notes: `Manual Journal AR | ${description}` }], "invoice_no");
      const invoice = saved.find((row) => row.invoice_no === reference) || saved[0];
      if (invoice?.id && !invoiceLines.some((line) => line.invoice_id === invoice.id || line.invoice_no === reference)) {
        await upsertInvoiceLines([{ invoice_id: invoice.id, description, unit: "Journal", qty: 1, rate: arAmount }], "id");
      }
      changed = true;
    }
  }
  return changed;
}

function buildAccountingData(source) {
  const reportFrom = source.reportFrom || "";
  const reportTo = source.reportTo || "";
  const reportTab = source.reportTab || accountingTab;
  const isAsOfReport = ["bs", "coa"].includes(reportTab) || (reportTab === "tb" && !reportFrom);
  const inReportPeriod = (row) => {
    const date = String(row.posting_date || row.entry_date || "").slice(0, 10);
    if (!date) return true;
    if (reportTo && date > reportTo) return false;
    if (!isAsOfReport && reportFrom && date < reportFrom) return false;
    return true;
  };
  const invoices = source.invoices.map((inv) => ({
    ...inv,
    _lines: source.invoiceLines.filter((line) => line.invoice_id === inv.id || line.invoice_no === inv.invoice_no),
    _paid: source.payments.filter((p) => p.invoice_no === inv.invoice_no && !/void|reverse/i.test(p.status || "")).reduce((sum, p) => sum + Number(p.amount || 0), 0),
  }));
  const pos = source.pos.map((po) => ({
    ...po,
    _lines: source.poLines.filter((line) => line.po_id === po.id || line.po_no === po.po_no),
    _receipts: source.receipts.filter((gr) => gr.po_no === po.po_no),
  }));
  const salesOrders = source.salesOrders.map((order) => ({
    ...order,
    _lines: source.salesLines.filter((line) => line.order_id === order.id || line.order_no === order.order_no),
  }));
  const allGl = source.gl.map((row) => normalizeGlRow(row));
  const gl = allGl
    .filter(inReportPeriod)
    .sort((a, b) => String(b.posting_date || "").localeCompare(String(a.posting_date || "")) || String(a.account || "").localeCompare(String(b.account || "")));
  const revenue = gl.filter((row) => /revenue|sales/i.test(row.account || "")).reduce((sum, row) => sum + Number(row.credit || 0) - Number(row.debit || 0), 0);
  const expenses = gl.filter((row) => /expense|cost of goods|cogs|adjustment/i.test(row.account || "")).reduce((sum, row) => sum + Number(row.debit || 0) - Number(row.credit || 0), 0);
  const inventory = source.products.reduce((sum, p) => sum + Number(p.qty || 0) * Number(p.cost || 0), 0);
  return { ...source, invoices, pos, salesOrders, allGl, gl, summary: { revenue, expenses, inventory, net: revenue - expenses } };
}

function normalizeGlRow(row) {
  return {
    id: row.id || null,
    posting_date: row.posting_date || row.entry_date || row.date || "",
    account: row.account || "",
    customer: row.customer || "",
    vendor: row.vendor || "",
    invoice_no: row.invoice_no || row.invoiceNumber || "",
    invoice_date: row.invoice_date || row.invoiceDate || "",
    due_date: row.due_date || row.dueDate || "",
    mechanic: row.mechanic || "",
    asset: row.asset || "",
    description: row.description || row.notes || "",
    reference: row.reference || "",
    bank_reference: row.bank_reference || "",
    work_order_no: row.work_order_no || row.wo_no || "",
    jobsite: row.jobsite || "",
    equipment: row.equipment || "",
    debit: Number(row.debit || 0),
    credit: Number(row.credit || 0),
    source: row.source || "",
    status: row.status || "Posted",
  };
}

function accountingPanelHtml(data, tab) {
  if (tab === "invoicehistory") return accountingInvoiceHistoryHtml(data);
  if (tab === "coa") return accountingTable(coaRows(data), ["Code", "Account", "Report", "Type", "Normal Balance", "Debit", "Credit", "Balance"], (r) => [r.account_code || "", r.account, r.report_group || "", r.type, r.normal_balance, money(r.debit), money(r.credit), money(r.balance)]);
  if (tab === "ap") {
    const apRows = accountsPayableRowsForTab(accountsPayableRows(data), accountsPayableTab);
    return `<div class="actions"><button id="postApFromPoBtn">Post AP from PO</button><button data-jump="checkrun">Open check run</button>${beginningQuickActionsHtml("ap")}</div>
      <div class="tabs">
        <button class="${accountsPayableTab === "forcheck" ? "active" : ""}" data-ap-tab="forcheck">For Check Run ${accountsPayableRowsForTab(accountsPayableRows(data), "forcheck").length}</button>
        <button class="${accountsPayableTab === "posted" ? "active" : ""}" data-ap-tab="posted">Posted AP ${accountsPayableRowsForTab(accountsPayableRows(data), "posted").length}</button>
        <button class="${accountsPayableTab === "paid" ? "active" : ""}" data-ap-tab="paid">Paid ${accountsPayableRowsForTab(accountsPayableRows(data), "paid").length}</button>
        <button class="${accountsPayableTab === "review" ? "active" : ""}" data-ap-tab="review">Needs Review ${accountsPayableRowsForTab(accountsPayableRows(data), "review").length}</button>
        <button class="${accountsPayableTab === "all" ? "active" : ""}" data-ap-tab="all">All AP ${accountsPayableRowsForTab(accountsPayableRows(data), "all").length}</button>
      </div>
      ${accountingTable(apRows, ["Vendor", "PO", "PO Date", "Invoice #", "Invoice Date", "Due Date", "Invoice Amount", "Written Off", "Open Balance", "Match", "Payment", "Status", ""], (r) => [r.vendor, r.po_no, r.po_date, r.invoice_no, r.invoice_date, r.due_date, money(r.invoice_amount), money(r.written_off), money(r.balance), badge(r.match), apPaymentCell(r), badge(r.status), apRowActions(r)])}`;
  }
  if (tab === "ar") {
    const allArRows = accountsReceivableRows(data);
    const arRows = accountsReceivableRowsForTab(allArRows, accountsReceivableTab);
    return `<div class="actions"><button id="receiveSelectedArBtn" disabled>Process selected invoices</button><button id="receiveOneArPaymentBtn">Receive one payment</button><button data-jump="invoices">Open invoices</button>${beginningQuickActionsHtml("ar")}<span id="arSelectionSummary" class="selection-summary">0 invoices selected</span></div>
      <div class="tabs">
        <button class="${accountsReceivableTab === "unpaid" ? "active" : ""}" data-ar-invoice-tab="unpaid">Unpaid ${accountsReceivableRowsForTab(allArRows, "unpaid").length}</button>
        <button class="${accountsReceivableTab === "paid" ? "active" : ""}" data-ar-invoice-tab="paid">Paid ${accountsReceivableRowsForTab(allArRows, "paid").length}</button>
        <button class="${accountsReceivableTab === "all" ? "active" : ""}" data-ar-invoice-tab="all">All Invoices ${allArRows.length}</button>
      </div>
      ${accountsReceivableTableHtml(arRows)}`;
  }
  if (tab === "payments") {
    const rows = [...(data.payments || [])].sort((left, right) => String(right.payment_date || "").localeCompare(String(left.payment_date || "")) || String(right.receipt_no || "").localeCompare(String(left.receipt_no || ""), undefined, { numeric: true }));
    currentRows = rows;
    return `<div class="actions"><button class="primary" id="accountingReceivePaymentBtn">Receive payment</button><button data-jump="payments">Open full Customer Payments module</button></div>${paymentTableHtml(rows)}`;
  }
  if (tab === "sales") return accountingTable(salesAccountingRows(data), ["Date", "Sales Order", "Customer", "PO / Reference", "Payment Mode", "Status", "Lines", "Subtotal", "Invoice", "AR Balance"], (r) => [r.date, r.order_no, r.customer, r.customer_po, r.payment_mode || "PO", badge(r.status), r.lines, money(r.total), r.invoice_no || "", money(r.balance)]);
  if (tab === "purchases") return accountingTable(purchaseAccountingRows(data), ["Date", "PO", "Vendor", "Invoice", "PO Total", "Received", "AP", "Match", "Payment", "Status", ""], (r) => [r.date, r.po_no, r.vendor, r.invoice_no, money(r.po_total), money(r.received), money(r.ap), badge(r.match), badge(r.payment), badge(r.status), apRowActions(r)]);
  if (tab === "tb") return `${beginningSupportHtml(data)}${trialBalanceReportHtml(data)}`;
  if (tab === "bs") return financialStatementHtml("Balance Sheet", balanceSheetRows(data), ["Section", "Account", "Amount"], (r) => [r.section, accountDrillButton(r.account), money(r.amount)], data, "asOf");
  if (tab === "is") return financialStatementHtml("Income Statement", incomeStatementRows(data), ["Section", "Account", "Amount"], (r) => [r.section, accountDrillButton(r.account), money(r.amount)], data, "period");
  if (tab === "cf") return financialStatementHtml("Cash Flow", cashFlowRows(data), ["Section", "Description", "Amount"], (r) => [r.section, r.description, money(r.amount)], data, "period");
  if (tab === "bank") return accountingBankReportHtml(data);
  return accountingTable(data.gl, ["Posting Date", "Account", "Customer", "Vendor", "Invoice #", "Invoice Date", "Due Date", "Mechanic", "Asset", "Description", "Reference", "Bank Reference", "Debit", "Credit", "Source", "Status", "Control"], (r) => [r.posting_date, r.account, r.customer, r.vendor, r.invoice_no, r.invoice_date, r.due_date, r.mechanic, r.asset, r.description, r.reference, r.bank_reference, r.debit ? money(r.debit) : "", r.credit ? money(r.credit) : "", r.source, badge(r.status), /manual journal/i.test(r.source || "") && !/reversed|void/i.test(r.status || "") ? `<button type="button" class="rowbtn danger" data-reverse-manual-journal="${esc(r.reference)}">Reverse</button>` : ""]);
}

function accountingInvoiceHistoryRows(data) {
  const from = localStorage.getItem("lms.accountingReportFrom") || "";
  const to = localStorage.getItem("lms.accountingReportTo") || today();
  return (data.invoices || []).filter((invoice) => {
    const typeText = `${invoice.type || ""} ${invoice.notes || ""}`;
    if (!/parts|work order|repair/i.test(typeText)) return false;
    const invoiceDate = String(invoice.invoice_date || "").slice(0, 10);
    if (from && invoiceDate && invoiceDate < from) return false;
    if (to && invoiceDate && invoiceDate > to) return false;
    return true;
  }).map((invoice) => {
    const isRepair = /work order|repair/i.test(`${invoice.type || ""} ${invoice.notes || ""}`);
    const total = invoiceTotal(invoice);
    const paid = Number(invoice._paid || 0);
    return {
      ...invoice,
      category: isRepair ? "Repair Invoice" : "Parts Invoice",
      display_invoice_no: isRepair ? (invoice.source_ref || invoice.invoice_no) : invoice.invoice_no,
      work_order_no: isRepair ? (invoice.source_ref || "") : "",
      total,
      paid,
      balance: Math.max(0, total - paid),
      display_status: invoiceDisplayStatus(invoice),
      _pdfLookup: isRepair ? (invoice.source_ref || invoice.invoice_no) : invoice.invoice_no,
    };
  }).sort((left, right) => String(right.invoice_date || "").localeCompare(String(left.invoice_date || ""))
    || String(right.display_invoice_no || "").localeCompare(String(left.display_invoice_no || ""), undefined, { numeric: true }));
}

function accountingInvoiceHistoryHtml(data) {
  const rows = accountingInvoiceHistoryRows(data);
  currentRows = rows;
  const partsCount = rows.filter((row) => row.category === "Parts Invoice").length;
  const repairCount = rows.filter((row) => row.category === "Repair Invoice").length;
  const total = rows.reduce((sum, row) => sum + Number(row.total || 0), 0);
  const balance = rows.reduce((sum, row) => sum + Number(row.balance || 0), 0);
  return `<div class="stats accounting-invoice-history-summary">
      ${stat("Parts Invoices", partsCount, "Parts sales invoices in the selected period")}
      ${stat("Repair Invoices", repairCount, "Work-order invoices in the selected period")}
      ${stat("Invoice Total", money(total), "Combined parts and repair invoices")}
      ${stat("Open Balance", money(balance), "Remaining customer balance")}
    </div>
    <div class="notice"><strong>Combined Invoice History:</strong> Parts and repair/work-order invoices are shown together for Accounting review. This read-only report does not create or change accounting entries.</div>
    ${accountingTable(rows, ["Invoice Date", "Invoice #", "Category", "Customer", "Work Order #", "Source", "Total", "Paid", "Balance", "Status", "Actions"], (row) => [
      row.invoice_date,
      `<button type="button" class="table-text-button" data-accounting-invoice-view="${esc(row.id || row.invoice_no)}">${esc(row.display_invoice_no || "")}</button>`,
      badge(row.category),
      esc(row.customer || ""),
      esc(row.work_order_no || ""),
      esc(row.source_ref || ""),
      money(row.total),
      money(row.paid),
      money(row.balance),
      badge(row.display_status),
      `<div class="rowactions"><button type="button" class="rowbtn" data-accounting-invoice-pdf="${esc(row.id || row.invoice_no)}">PDF</button><button type="button" class="rowbtn" data-accounting-entries data-entry-invoice="${esc(row.invoice_no || "")}" data-entry-source="${esc(row.source_ref || "")}">Accounting Entries</button></div>`,
    ])}`;
}

function beginningQuickActionsHtml(side) {
  const isAp = side === "ap";
  const label = isAp ? "AP" : "AR";
  const prefix = isAp ? "Ap" : "Ar";
  return `<details class="action-menu">
    <summary>${label} beginning tools</summary>
    <div class="action-menu-panel">
      <button id="beginning${prefix}TemplateInlineBtn">${label} detail template</button>
      <button id="beginning${prefix}UploadInlineBtn">Upload ${label} detail</button>
      <button class="danger" id="clearBeginning${prefix}InlineBtn">Clear Beginning ${label}</button>
    </div>
  </details>`;
}

function accountingTable(rows, heads, mapper) {
  currentRows = rows;
  return `<div class="table-wrap"><table><thead><tr>${heads.map((h) => `<th>${esc(h)}</th>`).join("")}</tr><tr>${heads.map((h, i) => `<th><input class="column-filter" data-col="${i}" placeholder="Filter ${esc(h)}"></th>`).join("")}</tr></thead><tbody>${rows.length ? rows.map((row) => `<tr>${mapper(row).map((value, index) => `<td>${/date/i.test(heads[index] || "") ? esc(formatDisplayDate(value)) : value ?? ""}</td>`).join("")}</tr>`).join("") : `<tr><td colspan="${heads.length}" class="empty">No records yet.</td></tr>`}</tbody></table></div>`;
}

function beginningInventorySupportHtml(data) {
  const support = beginningInventorySupportSummary(data);
  const status = Math.abs(support.difference) <= 0.005 ? "OK" : "Needs review";
  return `<div class="notice">
    <strong>Beginning inventory detail:</strong>
    Product detail ${money(support.detailValue)} | Parts Inventory TB ${money(support.glBalance)} | Difference ${money(support.difference)} (${esc(status)}).
    Use Inventory detail template and Upload inventory detail above to build the SKU/location detail behind the beginning balance.
  </div>`;
}

function beginningSupportHtml(data) {
  return `<div class="support-grid">
    ${beginningInventorySupportHtml(data)}
    ${beginningSubledgerSupportHtml("Accounts Payable", beginningApSupportSummary(data), "AP detail", "data-beginning-ap-upload")}
    ${beginningSubledgerSupportHtml("Accounts Receivable", beginningArSupportSummary(data), "AR detail", "data-beginning-ar-upload")}
  </div>`;
}

function beginningSubledgerSupportHtml(label, support, buttonLabel, attr) {
  const status = Math.abs(support.difference) <= 0.005 ? "OK" : "Needs review";
  return `<div class="notice">
    <strong>${esc(label)} detail:</strong>
    Detail ${money(support.detailValue)} | TB ${money(support.glBalance)} | Difference ${money(support.difference)} (${esc(status)}).
    <button class="rowbtn" type="button" ${attr}="1">${esc(buttonLabel)}</button>
  </div>`;
}

function beginningDetailButton(account) {
  if (/parts inventory/i.test(account || "")) return `<button class="rowbtn" type="button" data-beginning-inventory-upload="1">Inventory detail</button>`;
  if (/accounts payable/i.test(account || "")) return `<button class="rowbtn" type="button" data-beginning-ap-upload="1">AP detail</button>`;
  if (/accounts receivable/i.test(account || "")) return `<button class="rowbtn" type="button" data-beginning-ar-upload="1">AR detail</button>`;
  return "";
}

function beginningInventorySupportSummary(data) {
  const detailValue = (data.movements || [])
    .filter((row) => /beginning inventory detail|opening balance/i.test(`${row.type || ""} ${row.document_no || ""} ${row.reason || ""}`))
    .reduce((sum, row) => sum + Number(row.total_fifo_cost || 0), 0);
  const glBalance = (data.gl || [])
    .filter((row) => /parts inventory/i.test(row.account || "") && /trial balance upload/i.test(row.source || ""))
    .reduce((sum, row) => sum + Number(row.debit || 0) - Number(row.credit || 0), 0);
  return { detailValue, glBalance, difference: detailValue - glBalance };
}

function beginningApSupportSummary(data) {
  const detailValue = (data.pos || [])
    .filter((po) => /beginning ap/i.test(`${po.status || ""} ${po.notes || ""}`))
    .reduce((sum, po) => sum + Number(po.vendor_invoice_amount || 0), 0);
  const glBalance = (data.gl || [])
    .filter((row) => subledgerAccountMatches(row.account, "Accounts Payable"))
    .reduce((sum, row) => sum + Number(row.credit || 0) - Number(row.debit || 0), 0);
  return { detailValue, glBalance, difference: detailValue - glBalance };
}

function beginningArSupportSummary(data) {
  const detailValue = (data.invoices || [])
    .filter((inv) => /beginning ar/i.test(`${inv.type || ""} ${inv.notes || ""}`))
    .reduce((sum, inv) => sum + invoiceBalance(inv), 0);
  const glBalance = (data.gl || [])
    .filter((row) => subledgerAccountMatches(row.account, "Accounts Receivable"))
    .reduce((sum, row) => sum + Number(row.debit || 0) - Number(row.credit || 0), 0);
  return { detailValue, glBalance, difference: detailValue - glBalance };
}

function subledgerAccountMatches(actualAccount = "", requestedAccount = "") {
  const normalize = (value) => String(value || "")
    .toLowerCase()
    .replace(/accounts?/g, "account")
    .replace(/[^a-z0-9]/g, "");
  const actual = normalize(actualAccount);
  const requested = normalize(requestedAccount);
  if (actual === requested) return true;
  if (/receivable/.test(requested)) return /accountreceivable|ar$/.test(actual);
  if (/payable/.test(requested)) return /accountpayable|ap$/.test(actual);
  return false;
}

async function renderChartOfAccountsView() {
  currentCfg = tableMap.coa;
  $("viewTitle").textContent = "Chart of Accounts";
  $("viewSub").textContent = "Account master and complete transaction history by account, period, or as-of date.";
  const [coa, glRows] = await Promise.all([getAll("chart_of_accounts"), getAll("general_ledger")]);
  const normalizedGl = glRows.map(normalizeGlRow);
  const accountNames = [...new Set([...coa.map((row) => row.account), ...normalizedGl.map((row) => row.account)].filter(Boolean))]
    .sort((a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: "base" }));
  const filteredTransactions = chartAccountHistoryRows(normalizedGl);
  const summaryRows = coaRows({ coa, gl: chartAccountHistoryRows(normalizedGl, { ignoreAccount: true }) });
  currentRows = coa;
  const debit = filteredTransactions.reduce((sum, row) => sum + Number(row.debit || 0), 0);
  const credit = filteredTransactions.reduce((sum, row) => sum + Number(row.credit || 0), 0);
  const rangeLabel = coaHistoryMode === "all"
    ? "All transaction history"
    : coaHistoryMode === "asof"
      ? `As of ${coaHistoryTo || today()}`
      : `Period ${coaHistoryFrom || "beginning"} to ${coaHistoryTo || today()}`;
  $("content").innerHTML = `
    <div class="stats">
      ${stat("Accounts", summaryRows.length, rangeLabel)}
      ${stat("Transactions", filteredTransactions.length, coaHistoryAccount || "All accounts")}
      ${stat("Total Debit", money(debit), rangeLabel)}
      ${stat("Total Credit", money(credit), `Difference ${money(debit - credit)}`)}
    </div>
    <section class="panel">
      <div class="panel-head">
        <div class="panel-title"><strong>Transaction History Filters</strong><span>Choose one account or pull the complete ledger across all accounts.</span></div>
        <div class="actions"><button class="primary" id="newCoaAccountBtn">Add account</button></div>
      </div>
      <div class="toolbar coa-history-toolbar">
        <label class="mini-filter">View
          <select id="coaHistoryMode">
            <option value="all" ${coaHistoryMode === "all" ? "selected" : ""}>All history</option>
            <option value="period" ${coaHistoryMode === "period" ? "selected" : ""}>Period</option>
            <option value="asof" ${coaHistoryMode === "asof" ? "selected" : ""}>As of</option>
          </select>
        </label>
        <label class="mini-filter">Account
          <select id="coaHistoryAccount"><option value="">All accounts</option>${accountNames.map((name) => `<option value="${esc(name)}" ${name === coaHistoryAccount ? "selected" : ""}>${esc(name)}</option>`).join("")}</select>
        </label>
        <label class="mini-filter">From <input type="date" id="coaHistoryFrom" value="${esc(coaHistoryFrom)}" ${coaHistoryMode !== "period" ? "disabled" : ""}></label>
        <label class="mini-filter">To / As of <input type="date" id="coaHistoryTo" value="${esc(coaHistoryTo || today())}" ${coaHistoryMode === "all" ? "disabled" : ""}></label>
        <button id="coaHistoryApplyBtn">Apply</button>
        <button id="coaHistoryAllBtn">All Accounts</button>
        <button id="coaHistoryExportBtn">Export Transactions</button>
        <button id="coaSummaryExportBtn">Export Account Summary</button>
        <button onclick="window.print()">PDF / Print</button>
      </div>
    </section>
    <section class="panel">
      <div class="panel-head"><div class="panel-title"><strong>Account Summary</strong><span>${esc(rangeLabel)}. Select History to drill into one account.</span></div></div>
      ${chartAccountSummaryTable(summaryRows)}
    </section>
    <section class="panel">
      <div class="panel-head"><div class="panel-title"><strong>${esc(coaHistoryAccount || "All Accounts")} Transaction History</strong><span>${esc(rangeLabel)}</span></div></div>
      <div id="coaTransactionHost">${chartAccountTransactionTable(filteredTransactions)}</div>
    </section>`;
  $("newCoaAccountBtn").onclick = () => openAccountingSourceModal("coa");
  $("coaHistoryMode").onchange = () => {
    const mode = $("coaHistoryMode").value;
    $("coaHistoryFrom").disabled = mode !== "period";
    $("coaHistoryTo").disabled = mode === "all";
  };
  $("coaHistoryApplyBtn").onclick = () => {
    coaHistoryMode = $("coaHistoryMode").value;
    coaHistoryAccount = $("coaHistoryAccount").value;
    coaHistoryFrom = $("coaHistoryFrom").value;
    coaHistoryTo = $("coaHistoryTo").value || today();
    renderChartOfAccountsView();
  };
  $("coaHistoryAllBtn").onclick = () => {
    coaHistoryAccount = "";
    renderChartOfAccountsView();
  };
  $("coaHistoryExportBtn").onclick = () => exportChartAccountTransactions(filteredTransactions);
  $("coaSummaryExportBtn").onclick = () => exportChartAccountSummary(summaryRows);
  document.querySelectorAll("[data-coa-history]").forEach((button) => {
    button.onclick = () => {
      coaHistoryAccount = button.dataset.coaHistory;
      renderChartOfAccountsView();
    };
  });
  document.querySelectorAll("[data-coa-edit]").forEach((button) => {
    button.onclick = () => {
      const account = button.dataset.coaEdit;
      const summary = summaryRows.find((row) => row.account === account) || {};
      openModal(coa.find((row) => row.account === account) || {
        account,
        account_code: summary.account_code || "",
        report_group: summary.report_group || "",
        type: summary.type || "",
        normal_balance: summary.normal_balance || "",
        notes: "",
      });
    };
  });
  document.querySelectorAll(".column-filter").forEach((input) => input.oninput = applyColumnFilters);
}

function chartAccountHistoryRows(rows, options = {}) {
  const to = coaHistoryTo || today();
  return (rows || [])
    .filter((row) => options.ignoreAccount || !coaHistoryAccount || row.account === coaHistoryAccount)
    .filter((row) => {
      const date = String(row.posting_date || "").slice(0, 10);
      if (coaHistoryMode === "all") return true;
      if (coaHistoryMode === "asof") return !date || date <= to;
      return (!coaHistoryFrom || !date || date >= coaHistoryFrom) && (!to || !date || date <= to);
    })
    .sort((a, b) => String(a.posting_date || "").localeCompare(String(b.posting_date || "")) || String(a.account || "").localeCompare(String(b.account || "")));
}

function chartAccountSummaryTable(rows) {
  const heads = ["Code", "Account", "Report", "Type", "Normal Balance", "Debit", "Credit", "Balance", "Actions"];
  return `<div class="table-wrap"><table><thead><tr>${heads.map((head) => `<th>${esc(head)}</th>`).join("")}</tr><tr>${heads.map((head, index) => index < heads.length - 1 ? `<th><input class="column-filter" data-col="${index}" placeholder="Filter ${esc(head)}"></th>` : "<th></th>").join("")}</tr></thead><tbody>${rows.length ? rows.map((row) => `<tr><td>${esc(row.account_code || "")}</td><td>${esc(row.account)}</td><td>${esc(row.report_group || "")}</td><td>${esc(row.type || "")}</td><td>${esc(row.normal_balance || "")}</td><td>${money(row.debit)}</td><td>${money(row.credit)}</td><td><strong>${money(row.balance)}</strong></td><td><div class="rowactions"><button class="rowbtn" data-coa-history="${esc(row.account)}">History</button><button class="rowbtn" data-coa-edit="${esc(row.account)}">Edit</button></div></td></tr>`).join("") : `<tr><td colspan="${heads.length}" class="empty">No accounts found.</td></tr>`}</tbody></table></div>`;
}

function chartAccountTransactionTable(rows) {
  const heads = ["Posting Date", "Account", "Customer", "Vendor", "Invoice #", "Description", "Reference", "Bank Reference", "Debit", "Credit", "Source", "Status"];
  return `<div class="table-wrap"><table><thead><tr>${heads.map((head) => `<th>${esc(head)}</th>`).join("")}</tr><tr>${heads.map((head, index) => `<th><input class="column-filter" data-col="${index}" placeholder="Filter ${esc(head)}"></th>`).join("")}</tr></thead><tbody>${rows.length ? rows.map((row) => `<tr><td>${esc(formatDisplayDate(row.posting_date))}</td><td>${esc(row.account)}</td><td>${esc(row.customer)}</td><td>${esc(row.vendor)}</td><td>${esc(row.invoice_no)}</td><td>${esc(row.description)}</td><td>${esc(row.reference)}</td><td>${esc(row.bank_reference)}</td><td>${row.debit ? money(row.debit) : ""}</td><td>${row.credit ? money(row.credit) : ""}</td><td>${esc(row.source)}</td><td>${badge(row.status)}</td></tr>`).join("") : `<tr><td colspan="${heads.length}" class="empty">No transactions for the selected filters.</td></tr>`}</tbody></table></div>`;
}

function exportChartAccountTransactions(rows) {
  downloadCsv([
    ["Posting Date", "Account", "Customer", "Vendor", "Invoice #", "Invoice Date", "Due Date", "Mechanic", "Asset", "Description", "Reference", "Bank Reference", "Debit", "Credit", "Source", "Status"],
    ...(rows || []).map((row) => [row.posting_date, row.account, row.customer, row.vendor, row.invoice_no, row.invoice_date, row.due_date, row.mechanic, row.asset, row.description, row.reference, row.bank_reference, row.debit, row.credit, row.source, row.status]),
  ], `chart-of-accounts-transactions-${coaHistoryMode}-${today()}.csv`);
}

function exportChartAccountSummary(rows) {
  downloadCsv([
    ["Code", "Account", "Report", "Type", "Normal Balance", "Debit", "Credit", "Balance"],
    ...(rows || []).map((row) => [row.account_code, row.account, row.report_group, row.type, row.normal_balance, row.debit, row.credit, row.balance]),
  ], `chart-of-accounts-summary-${coaHistoryMode}-${today()}.csv`);
}

function coaRows(data) {
  const accounts = new Map();
  data.coa.forEach((a) => accounts.set(a.account, { account_code: a.account_code || "", account: a.account, report_group: a.report_group || statementGroup(a.type || accountType(a.account)), type: a.type || accountType(a.account), normal_balance: a.normal_balance || normalBalance(a.type || accountType(a.account)), debit: 0, credit: 0 }));
  data.gl.forEach((row) => {
    if (!accounts.has(row.account)) accounts.set(row.account, { account_code: "", account: row.account, report_group: statementGroup(accountType(row.account)), type: accountType(row.account), normal_balance: normalBalance(accountType(row.account)), debit: 0, credit: 0 });
    const account = accounts.get(row.account);
    account.debit += Number(row.debit || 0);
    account.credit += Number(row.credit || 0);
  });
  return [...accounts.values()].map((a) => ({ ...a, balance: /credit/i.test(a.normal_balance) ? a.credit - a.debit : a.debit - a.credit })).sort((a, b) => a.account.localeCompare(b.account));
}

function statementGroup(type) {
  return /revenue|expense|cost|income/i.test(type || "") ? "Income Statement" : "Balance Sheet";
}

function accountType(account) {
  if (/cash|bank|receivable|inventory|equipment|asset/i.test(account || "")) return "Asset";
  if (/payable|credit card|liabil|accrual|parts in transit/i.test(account || "")) return "Liability";
  if (/equity|capital/i.test(account || "")) return "Equity";
  if (/revenue|sales|income/i.test(account || "")) return "Revenue";
  return "Expense";
}

function normalBalance(type) {
  return /liability|equity|revenue/i.test(type || "") ? "Credit" : "Debit";
}

function isBeginningBalanceApRecord(po = {}) {
  return /^BBAP-/i.test(String(po.po_no || "").trim())
    || /beginning ap/i.test(`${po.status || ""} ${po.notes || ""}`)
    || /^beginning balance$/i.test(String(po.jobsite_project || "").trim());
}

function accountsPayableRows(data) {
  const poRows = data.pos.map((po) => {
    const poTotalAmount = poTotal(po);
    const received = poReceivedTotal(po);
    const ap = poApSummary(po);
    const isBeginningAp = isBeginningBalanceApRecord(po);
    const isLandedAp = isLandedCostPayable(po);
    const isManualJournalAp = /manual journal ap/i.test(`${po.status || ""} ${po.notes || ""}`);
    const apPosted = isBeginningAp || isManualJournalAp || data.gl.some((row) => row.reference === po.po_no && ["Purchase Order", "Landed Cost Invoice", "Manual Journal"].includes(row.source));
    const writtenOff = (data.allGl || data.gl || []).filter((row) => row.reference === po.po_no && /ap write-off/i.test(row.source || "") && !/reverse|void/i.test(row.status || "")).reduce((sum, row) => /accounts payable/i.test(row.account || "") ? sum + Number(row.debit || 0) - Number(row.credit || 0) : sum, 0);
    const fullyPaid = /paid/i.test(`${po.payment_status || ""} ${po.status || ""}`);
    const rawBalance = fullyPaid ? 0 : roundCurrency(ap.invoice_amount) - Math.max(0, roundCurrency(writtenOff));
    const balance = Math.abs(rawBalance) <= 0.0050001 ? 0 : Math.max(0, roundCurrency(rawBalance));
    const writeOffStatus = balance <= 0.005 && writtenOff > 0 ? "Written Off" : isBeginningAp ? "Beginning AP" : isManualJournalAp ? "Manual Journal AP" : isLandedAp ? "Landed Cost AP" : apPosted ? "AP Posted" : ap.status;
    return { id: po.id, vendor: po.vendor, po_no: po.po_no, po_date: po.po_date, invoice_no: ap.invoice_no, invoice_date: ap.invoice_date, due_date: ap.due_date, po_total: poTotalAmount, received, invoice_amount: ap.invoice_amount, written_off: Math.max(0, writtenOff), balance, match: isManualJournalAp ? "Matched" : ap.match, payment: balance <= 0.005 && writtenOff > 0 ? "Written Off" : isManualJournalAp ? "Ready to Pay" : ap.payment, status: writeOffStatus, ap_posted: apPosted, beginning_ap: isBeginningAp, landed_cost_ap: isLandedAp, manual_journal_ap: isManualJournalAp };
  }).filter((row) => !/cancel/i.test(row.status) && Number(row.received || row.invoice_amount || 0) > 0);
  // Only genuine purchase orders suppress a direct AP row. Older builds
  // created hidden "Manual Journal AP" PO proxies; those proxies are excluded
  // below, so allowing them to suppress the current GL-backed row would also
  // hide the journal's updated WO, jobsite, and equipment details.
  const poReferences = new Set(poRows.filter((row) => !row.manual_journal_ap).map((row) => String(row.po_no || "").trim().toLowerCase()));
  const manualGroups = new Map();
  (data.allGl || data.gl || []).filter((row) => /manual journal/i.test(row.source || "") && !/reverse|void/i.test(row.status || "")).forEach((row) => {
    const reference = String(row.reference || "").trim();
    if (!reference || poReferences.has(reference.toLowerCase())) return;
    if (!manualGroups.has(reference)) manualGroups.set(reference, []);
    manualGroups.get(reference).push(normalizeGlRow(row));
  });
  const directRows = [...manualGroups.entries()].map(([reference, rows]) => {
    const apLines = rows.filter((row) => subledgerAccountMatches(row.account, "Accounts Payable"));
    const amount = apLines.reduce((sum, row) => sum + Number(row.credit || 0) - Number(row.debit || 0), 0);
    if (amount <= 0.005) return null;
    const apLine = apLines[0] || rows[0];
    const firstValue = (field) => rows.find((row) => String(row?.[field] || "").trim())?.[field] || "";
    const workOrderNo = firstValue("work_order_no");
    const description = firstValue("description");
    return {
      id: null,
      vendor: apLine.vendor || rows.find((row) => row.vendor)?.vendor || "",
      po_no: reference,
      po_date: apLine.posting_date || apLine.entry_date || "",
      invoice_no: apLine.invoice_no || reference,
      invoice_date: apLine.invoice_date || apLine.posting_date || "",
      due_date: apLine.due_date || apLine.posting_date || "",
      po_total: 0,
      received: 0,
      invoice_amount: amount,
      written_off: 0,
      balance: amount,
      match: "Matched",
      payment: "Ready to Pay",
      status: "Direct AP",
      ap_posted: true,
      beginning_ap: false,
      landed_cost_ap: false,
      manual_journal_ap: true,
      direct_ap: true,
      // Check Run is a view of the same manual journal transaction. Keep its
      // supporting fields sourced from the current GL rows so edits made in
      // Balanced Journal History appear here immediately after refresh.
      wo_no: workOrderNo,
      work_order_no: workOrderNo,
      jobsite: firstValue("jobsite"),
      equipment: firstValue("equipment"),
      parts_description: description,
      description,
    };
  }).filter(Boolean);
  return [...poRows.filter((row) => !row.manual_journal_ap), ...directRows]
    .map((row) => {
      const paidRun = checkRunPaymentForApRow(row, data.checkRuns || []);
      if (!paidRun) return { ...row, paid: /paid/i.test(`${row.payment || ""} ${row.status || ""}`) };
      return { ...row, balance: 0, paid: true, payment: paidRun.label, payment_reference: paidRun.reference, payment_check_run: paidRun.run.check_run_no || paidRun.run.reference || "" };
    })
    .sort((a, b) => String(b.po_date || "").localeCompare(String(a.po_date || "")));
}

function accountsPayableRowsForTab(rows, tab = "forcheck") {
  if (tab === "all") return rows;
  if (tab === "paid") return rows.filter((row) => row.paid);
  if (tab === "posted") return rows.filter((row) => row.ap_posted && !row.paid && !/paid|written off/i.test(`${row.payment || ""} ${row.status || ""}`));
  if (tab === "review") return rows.filter((row) => !row.ap_posted || /mismatch|pending|awaiting|not ready|hold/i.test(`${row.match || ""} ${row.payment || ""} ${row.status || ""}`));
  return rows.filter((row) => row.ap_posted && !row.paid && /matched/i.test(row.match || "") && /ready/i.test(row.payment || "") && !/paid/i.test(`${row.payment || ""} ${row.status || ""}`));
}

function checkRunPaymentForApRow(row, runs = []) {
  const poKey = normalizeCheckRunDocumentKey(row.po_no || row.reference);
  const invoiceKey = normalizeCheckRunDocumentKey(row.invoice_no);
  const vendorKey = normalizeCheckRunDocumentKey(row.vendor);
  const activeRuns = (runs || []).filter((run) => /printed|cleared/i.test(String(run.status || "")) && !/void|revers|cancel/i.test(String(run.status || "")));
  const run = activeRuns.find((candidate) => {
    const candidateVendor = normalizeCheckRunDocumentKey(candidate.vendor);
    const detail = parseCheckRunNotes(candidate.notes);
    const poKeys = new Set([
      ...splitCheckRunDocumentValues(candidate.reference || candidate.po_no),
      ...splitCheckRunDocumentValues(candidate.po_no),
      ...(detail.invoices || []).map((invoice) => invoice.po_no || invoice.reference),
    ].map(normalizeCheckRunDocumentKey).filter(Boolean));
    if (poKey && poKeys.has(poKey)) return !vendorKey || !candidateVendor || vendorKey === candidateVendor;
    const invoices = [
      ...splitCheckRunDocumentValues(candidate.invoice_no).map((value) => ({ invoice_no: value, vendor: candidate.vendor })),
      ...(detail.invoices || []),
    ];
    return Boolean(invoiceKey && invoices.some((invoice) => normalizeCheckRunDocumentKey(invoice.invoice_no) === invoiceKey
      && (!vendorKey || normalizeCheckRunDocumentKey(invoice.vendor || candidate.vendor) === vendorKey)));
  });
  if (!run) return null;
  const usesPrintedCheck = checkRunUsesPrintedCheck(run.payment_account || run.bank_account, run.payment_mode);
  const reference = usesPrintedCheck && run.check_no ? String(run.check_no) : String(run.check_run_no || run.reference || run.check_no || "Payment");
  return { run, reference, label: usesPrintedCheck && run.check_no ? `Check #${run.check_no}` : reference };
}

function apPaymentCell(row) {
  if (!row.payment_reference) return badge(row.payment);
  return `<button type="button" class="table-text-button" data-ap-payment-reference="${esc(row.payment_reference)}" data-ap-payment-run="${esc(row.payment_check_run || row.payment_reference)}" title="Open this payment in Check Run">${esc(row.payment)}</button>`;
}

function poApSummary(po) {
  const received = poReceivedTotal(po);
  const active = activeReceipts(po);
  const receiptInvoiceNo = [...new Set(active.map((gr) => gr.vendor_invoice_no).filter(Boolean))].join(", ");
  const receiptInvoiceDates = active.map((gr) => gr.vendor_invoice_date).filter(Boolean).sort();
  const receiptInvoiceAmount = active.reduce((sum, gr) => sum + Number(gr.vendor_invoice_amount || gr.received_amount || goodsReceiptBaseAmount(po, gr)), 0);
  const invoiceAmount = Number(po.vendor_invoice_amount || receiptInvoiceAmount || received || 0);
  const landedClear = landedClearAmountForInvoice(po, invoiceAmount, received);
  const expectedInvoice = received + landedClear;
  const invoiceNo = po.vendor_invoice_no || receiptInvoiceNo || "";
  const invoiceDate = po.vendor_invoice_date || receiptInvoiceDates[0] || po.invoice_date || "";
  const dueDate = po.due_date || invoiceDate || po.expected_date || "";
  const isBeginningAp = isBeginningBalanceApRecord(po);
  const isLandedAp = isLandedCostPayable(po);
  const isManualJournalAp = /manual journal ap/i.test(`${po.status || ""} ${po.notes || ""}`);
  const match = isBeginningAp || isLandedAp || isManualJournalAp ? "Matched" : !received ? "Awaiting Goods" : !invoiceAmount ? "Pending" : Math.abs(invoiceAmount - expectedInvoice) <= 0.005 ? "Matched" : "Mismatch";
  const payment = isLandedAp && po.payment_status ? po.payment_status : po.payment_status && !/not ready/i.test(po.payment_status) ? po.payment_status : match === "Matched" ? "Ready to Pay" : "Not Ready";
  const status = po.status || (received ? "Goods Received" : "Draft");
  return { invoice_no: invoiceNo, invoice_date: invoiceDate, due_date: dueDate, invoice_amount: invoiceAmount, match, payment, status };
}

function accountsReceivableRows(data) {
  const rows = data.invoices.map((inv) => {
    const total = invoiceTotal(inv);
    const paid = invoicePaid(inv);
    const storedInvoiceNo = inv.invoice_no;
    const invoiceNo = /work order|repair/i.test(inv.type || "") && inv.source_ref ? inv.source_ref : storedInvoiceNo;
    return { id: inv.id, customer: inv.customer, invoice_no: invoiceNo, stored_invoice_no: storedInvoiceNo, invoice_date: inv.invoice_date, due_date: inv.due_date, type: inv.type, source_ref: inv.source_ref, total, paid, balance: Math.max(0, total - paid), status: inv.status || "Open", credit_applied: 0, credit_remaining: total < 0 ? Math.abs(total) : 0 };
  }).filter((row) => !/void|reverse/i.test(row.status));

  // Negative Beginning AR documents are customer credits, not cash receipts.
  // Apply them to the same customer's open debit documents for subledger display:
  // exact-amount matches first, then oldest invoices. The imported Beginning AR
  // control balance is already net, so this must not create another GL entry.
  const customers = new Map();
  rows.forEach((row) => {
    const key = String(row.customer || "").trim().toLowerCase();
    if (!customers.has(key)) customers.set(key, []);
    customers.get(key).push(row);
  });
  customers.forEach((customerRows) => {
    const debits = customerRows.filter((row) => row.total > 0 && row.balance > 0.005);
    const credits = customerRows.filter((row) => row.total < -0.005 && row.credit_remaining > 0.005);
    credits.forEach((credit) => {
      const exact = debits.find((debit) => debit.balance > 0.005 && sameMoney(debit.balance, credit.credit_remaining));
      const ordered = [exact, ...debits
        .filter((debit) => debit !== exact && debit.balance > 0.005)
        .sort((left, right) => String(left.invoice_date || "").localeCompare(String(right.invoice_date || "")) || String(left.invoice_no || "").localeCompare(String(right.invoice_no || ""), undefined, { numeric: true }))]
        .filter(Boolean);
      ordered.forEach((debit) => {
        if (credit.credit_remaining <= 0.005 || debit.balance <= 0.005) return;
        const applied = Math.min(credit.credit_remaining, debit.balance);
        credit.credit_remaining = roundCurrency(credit.credit_remaining - applied);
        credit.credit_applied = roundCurrency(credit.credit_applied + applied);
        debit.credit_applied = roundCurrency(debit.credit_applied + applied);
        debit.paid = roundCurrency(debit.paid + applied);
        debit.balance = roundCurrency(debit.balance - applied);
      });
    });
  });
  rows.forEach((row) => {
    if (row.total < 0) {
      row.paid = row.credit_applied;
      row.balance = row.credit_remaining > 0.005 ? -row.credit_remaining : 0;
      row.status = row.credit_remaining <= 0.005 ? "Applied" : "Credit Available";
    } else if (row.balance <= 0.005) {
      row.balance = 0;
      row.status = /written off/i.test(row.status || "") ? "Written Off" : "Paid";
    } else if (row.paid > 0.005) {
      row.status = "Partial";
    }
  });
  return rows.sort((a, b) => String(b.invoice_date || "").localeCompare(String(a.invoice_date || "")));
}

function accountsReceivableRowsForTab(rows, tab = accountsReceivableTab) {
  if (tab === "all") return rows || [];
  if (tab === "paid") return (rows || []).filter((row) => Math.abs(Number(row.balance || 0)) <= 0.005 && /paid|applied|written off/i.test(row.status || ""));
  return (rows || []).filter((row) => Math.abs(Number(row.balance || 0)) > 0.005 || !/paid|applied|written off/i.test(row.status || ""));
}

function accountsReceivableTableHtml(rows) {
  currentRows = rows;
  const heads = ["", "Customer", "Invoice #", "Invoice Date", "Due Date", "Type", "Source", "Invoice Total", "Paid / Written Off", "Balance", "Status", ""];
  return `<div class="table-wrap ar-receivable-table"><table><thead><tr>${heads.map((head, index) => `<th>${index === 0 ? '<input id="selectVisibleArInvoices" type="checkbox" title="Select all visible invoices" aria-label="Select all visible invoices">' : esc(head)}</th>`).join("")}</tr><tr>${heads.map((head, index) => `<th>${index === 0 || index === heads.length - 1 ? "" : `<input class="column-filter" data-col="${index}" placeholder="Filter ${esc(head)}">`}</th>`).join("")}</tr></thead><tbody>${rows.length ? rows.map((row) => `<tr data-ar-invoice-row="${esc(row.invoice_no)}"><td><input class="ar-invoice-select" type="checkbox" value="${esc(row.invoice_no)}" ${Number(row.balance || 0) <= 0.005 ? "disabled" : ""} aria-label="Select invoice ${esc(row.invoice_no)}"></td><td>${esc(row.customer || "")}</td><td><button type="button" class="table-text-button" data-ar-invoice-view="${esc(row.invoice_no)}" title="Open invoice ${esc(row.invoice_no)}">${esc(row.invoice_no || "")}</button></td><td>${esc(formatDisplayDate(row.invoice_date))}</td><td>${esc(formatDisplayDate(row.due_date))}</td><td>${esc(row.type || "")}</td><td>${esc(row.source_ref || "")}</td><td>${money(row.total)}</td><td><button type="button" class="table-text-button money-link" data-ar-paid-history="${esc(row.invoice_no)}" title="View all payments and write-offs for ${esc(row.invoice_no)}">${money(row.paid)}</button></td><td>${money(row.balance)}</td><td>${badge(row.status)}</td><td>${arRowActions(row)}</td></tr>`).join("") : `<tr><td colspan="${heads.length}" class="empty">No records yet.</td></tr>`}</tbody></table></div>`;
}

function openArPaymentHistoryModal(data, invoiceNo) {
  const invoice = data.invoices.find((row) => row.invoice_no === invoiceNo);
  const payments = (data.payments || [])
    .filter((payment) => payment.invoice_no === invoiceNo)
    .sort((a, b) => String(a.payment_date || "").localeCompare(String(b.payment_date || "")) || String(a.receipt_no || "").localeCompare(String(b.receipt_no || "")));
  const active = payments.filter((payment) => !/void|reverse|cancel/i.test(payment.status || ""));
  const activeTotal = active.reduce((sum, payment) => sum + Number(payment.amount || 0), 0);
  const reversedTotal = payments.filter((payment) => /void|reverse|cancel/i.test(payment.status || "")).reduce((sum, payment) => sum + Number(payment.amount || 0), 0);
  $("modalTitle").textContent = `Payment history — ${invoiceNo}`;
  $("modalBody").innerHTML = `<div class="writeoff-summary ar-payment-history-summary">
      <div><span>Customer</span><strong>${esc(invoice?.customer || payments[0]?.customer || "")}</strong></div>
      <div><span>Invoice total</span><strong>${money(invoice ? invoiceTotal(invoice) : 0)}</strong></div>
      <div><span>Active paid / written off</span><strong>${money(activeTotal)}</strong></div>
      <div><span>Open balance</span><strong>${money(invoice ? Math.max(0, invoiceTotal(invoice) - activeTotal) : 0)}</strong></div>
    </div>
    <div class="table-wrap ar-payment-history-table"><table><thead><tr><th>Receipt / Batch Allocation</th><th>Date</th><th>Method</th><th>Bank / Check Reference</th><th>Amount</th><th>Status</th><th>Notes</th></tr></thead><tbody>
      ${payments.length ? payments.map((payment) => `<tr><td>${esc(payment.receipt_no || "")}</td><td>${esc(formatDisplayDate(payment.payment_date))}</td><td>${esc(payment.method || "")}</td><td>${esc(payment.bank_reference || "")}</td><td>${money(payment.amount)}</td><td>${badge(payment.status || "Posted")}</td><td class="preserve-lines">${esc(payment.notes || "")}</td></tr>`).join("") : '<tr><td colspan="7" class="empty">No payment or write-off records were found for this invoice.</td></tr>'}
    </tbody><tfoot><tr><th colspan="4">Active total</th><th>${money(activeTotal)}</th><th colspan="2"></th></tr>${reversedTotal > 0 ? `<tr><th colspan="4">Reversed / void history</th><th>${money(reversedTotal)}</th><th colspan="2"></th></tr>` : ""}</tfoot></table></div>
    <p class="notice">Every partial payment, batch allocation, write-off, reversal, and reference recorded for this invoice appears separately.</p>`;
  $("modalSave").textContent = "Close";
  $("modalSave").onclick = () => closeModal(true);
  $("modal").style.display = "flex";
}

function openAccountingEntriesModal(data, { invoiceNo = "", sourceRef = "" } = {}) {
  const keys = new Set([invoiceNo, sourceRef].map((value) => String(value || "").trim()).filter(Boolean));
  const rows = (data.allGl || data.gl || []).filter((row) => {
    const candidates = [row.invoice_no, row.reference, row.work_order_no, row.po_no, row.purchase_order_no]
      .map((value) => String(value || "").trim())
      .filter(Boolean);
    return candidates.some((value) => keys.has(value));
  }).sort((left, right) => String(left.posting_date || left.entry_date || "").localeCompare(String(right.posting_date || right.entry_date || ""))
    || String(left.account || "").localeCompare(String(right.account || "")));
  const debit = rows.reduce((sum, row) => sum + Number(row.debit || 0), 0);
  const credit = rows.reduce((sum, row) => sum + Number(row.credit || 0), 0);
  const titleRef = sourceRef || invoiceNo || "transaction";
  $("modalTitle").textContent = `Accounting entries — ${titleRef}`;
  $("modalBody").innerHTML = `<div class="table-wrap"><table><thead><tr><th>Posting Date</th><th>Account</th><th>Description</th><th>Reference</th><th>Debit</th><th>Credit</th><th>Source</th><th>Status</th></tr></thead><tbody>
      ${rows.length ? rows.map((row) => `<tr><td>${esc(formatDisplayDate(row.posting_date || row.entry_date))}</td><td>${esc(row.account || "")}</td><td>${esc(row.description || "")}</td><td>${esc(row.reference || row.invoice_no || "")}</td><td>${Number(row.debit || 0) ? money(row.debit) : ""}</td><td>${Number(row.credit || 0) ? money(row.credit) : ""}</td><td>${esc(row.source || "")}</td><td>${badge(row.status || "Posted")}</td></tr>`).join("") : '<tr><td colspan="8" class="empty">No accounting entries were found for this transaction.</td></tr>'}
    </tbody><tfoot><tr><th colspan="4">Totals</th><th>${money(debit)}</th><th>${money(credit)}</th><th colspan="2">${Math.abs(debit - credit) <= 0.005 ? "Balanced" : `Difference ${money(debit - credit)}`}</th></tr></tfoot></table></div>
    <p class="notice">This is a read-only view of the posted General Ledger entries linked to the invoice, payable, work order, or purchase order.</p>`;
  $("modalSave").textContent = "Close";
  $("modalSave").onclick = () => closeModal(true);
  $("modal").style.display = "flex";
}

function selectedArInvoiceRows(data) {
  const selected = new Set([...document.querySelectorAll(".ar-invoice-select:checked")].map((input) => input.value));
  return accountsReceivableRows(data).filter((row) => selected.has(row.invoice_no) && Number(row.balance || 0) > 0.005);
}

function syncArInvoiceSelection() {
  const boxes = [...document.querySelectorAll(".ar-invoice-select:not(:disabled)")];
  const checked = boxes.filter((input) => input.checked);
  const visible = boxes.filter((input) => input.closest("tr")?.style.display !== "none");
  const visibleChecked = visible.filter((input) => input.checked);
  const selectAll = document.getElementById("selectVisibleArInvoices");
  if (selectAll) {
    selectAll.checked = visible.length > 0 && visibleChecked.length === visible.length;
    selectAll.indeterminate = visibleChecked.length > 0 && visibleChecked.length < visible.length;
  }
  const button = document.getElementById("receiveSelectedArBtn");
  if (button) button.disabled = checked.length === 0;
  const summary = document.getElementById("arSelectionSummary");
  if (summary) summary.textContent = `${checked.length} invoice${checked.length === 1 ? "" : "s"} selected`;
}

async function openBatchArSettlementModal(data) {
  const rows = selectedArInvoiceRows(data);
  if (!rows.length) return alert("Select at least one open invoice.");
  const customers = [...new Set(rows.map((row) => String(row.customer || "").trim()).filter(Boolean))];
  if (customers.length !== 1) return alert("One receipt or write-off batch can only contain invoices for the same customer.");
  const receiptNo = await nextRefPreview("payment", "PAY-", "customer_payments", "receipt_no");
  const accounts = writeOffAccountOptions(data, "ar");
  const defaultAccount = accounts.find((account) => /bad debt|write.?off|expense/i.test(account)) || "";
  // This application reuses one modal footer. Remove transaction-specific
  // controls left by another editor before presenting customer-payment actions.
  ["salesOrderSaveOnlyBtn", "salesOrderPdfModalBtn", "salesOrderInvoiceModalBtn", "salesOrderInvoiceHistoryModalBtn", "salesOrderCreatePoModalBtn", "poSaveOnlyBtn", "poReceiveBtn", "journalSaveOnlyBtn", "workOrderSaveOnlyBtn", "closeFinalizeWoBtn"].forEach((id) => document.getElementById(id)?.remove());
  $("modalTitle").textContent = `Process ${rows.length} selected invoice${rows.length === 1 ? "" : "s"}`;
  $("modalBody").innerHTML = `<div class="form-grid ar-batch-header">
      ${productSelect("Action", "batch_action", ["Receive Payment", "Write Off"], "Receive Payment")}
      ${productInput("Receipt / batch #", "receipt_no", receiptNo)}
      ${productInput("Payment date", "payment_date", today(), "date")}
      ${productInput("Customer", "customer", customers[0])}
      <div class="field ar-payment-field">${productSelect("Payment method", "method", ["Cash", "Check", "ACH", "Credit Card", "Wire", "Other"], "Check").replace(/^<div class="field">|<\/div>$/g, "")}</div>
      <div class="field ar-payment-field">${productInput("Bank / check reference", "bank_reference", "").replace(/^<div class="field">|<\/div>$/g, "")}</div>
      <div class="field ar-writeoff-field" hidden>${productSelect("Write-off charge account", "offset_account", accounts, defaultAccount).replace(/^<div class="field">|<\/div>$/g, "")}</div>
      <div class="field wide"><label>Notes / reason</label><textarea data-product-field="notes" placeholder="Payment notes or required write-off reason"></textarea></div>
    </div>
    <div class="table-wrap ar-batch-allocation"><table><thead><tr><th>Invoice</th><th>Invoice Date</th><th>Due Date</th><th>Type</th><th>Source</th><th>Open Balance</th><th>Amount to Apply</th></tr></thead><tbody>
      ${rows.map((row) => `<tr data-batch-ar-row="${esc(row.invoice_no)}"><td><strong>${esc(row.invoice_no)}</strong></td><td>${esc(formatDisplayDate(row.invoice_date))}</td><td>${esc(formatDisplayDate(row.due_date))}</td><td>${esc(row.type || "")}</td><td>${esc(row.source_ref || "")}</td><td>${money(row.balance)}</td><td><input class="ar-batch-amount" type="number" min="0" max="${Number(row.balance || 0)}" step="0.01" value="${Number(row.balance || 0).toFixed(2)}" data-invoice-no="${esc(row.invoice_no)}"></td></tr>`).join("")}
    </tbody><tfoot><tr><th colspan="6">Combined total</th><th id="arBatchCombinedTotal">${money(rows.reduce((sum, row) => sum + Number(row.balance || 0), 0))}</th></tr></tfoot></table></div>
    <p id="arBatchAccountingNotice" class="notice"><strong>Accounting entry:</strong> Debit FHB Checking once for the combined payment and credit Accounts Receivable for each invoice allocation.</p>`;
  $("modalSave").textContent = "Save Final";
  $("modalSave").onclick = () => finalizeBatchArSettlement(data, rows);
  $("modal").style.display = "flex";
  queueMicrotask(() => {
    const draftButton = $("modalDraft");
    draftButton.hidden = false;
    draftButton.textContent = "Save Draft";
    draftButton.onclick = () => saveBatchArSettlementDraft(rows);
    restoreBatchArSettlementDraft(receiptNo, rows);
  });
  document.querySelector('[data-product-field="customer"]')?.setAttribute("readonly", "readonly");
  const updateTotal = () => {
    const total = [...document.querySelectorAll(".ar-batch-amount")].reduce((sum, input) => sum + Math.max(0, Number(input.value || 0)), 0);
    const target = document.getElementById("arBatchCombinedTotal");
    if (target) target.textContent = money(total);
  };
  document.querySelectorAll(".ar-batch-amount").forEach((input) => input.addEventListener("input", updateTotal));
  const action = document.querySelector('[data-product-field="batch_action"]');
  const syncAction = () => {
    const isWriteOff = action?.value === "Write Off";
    document.querySelectorAll(".ar-payment-field").forEach((field) => {
      field.hidden = isWriteOff;
      field.querySelectorAll("input, select, textarea").forEach((control) => { control.disabled = isWriteOff; });
    });
    document.querySelectorAll(".ar-writeoff-field").forEach((field) => {
      field.hidden = !isWriteOff;
      field.querySelectorAll("input, select, textarea").forEach((control) => { control.disabled = !isWriteOff; });
    });
    const notice = document.getElementById("arBatchAccountingNotice");
    if (notice) notice.innerHTML = isWriteOff
      ? "<strong>Accounting entry:</strong> Debit the selected charge account for the combined write-off and credit Accounts Receivable for each invoice allocation."
      : "<strong>Accounting entry:</strong> Debit FHB Checking once for the combined payment and credit Accounts Receivable for each invoice allocation.";
  };
  action?.addEventListener("change", syncAction);
  syncAction();
}

function batchArSettlementDraftRecord(rows) {
  const record = collectProductModalFields();
  record.allocations = [...document.querySelectorAll(".ar-batch-amount")].map((input) => ({
    invoice_no: input.dataset.invoiceNo,
    amount: Number(input.value || 0),
  })).filter((item) => item.invoice_no && item.amount > 0);
  record.invoices = rows.map((row) => ({ invoice_no: row.invoice_no, customer: row.customer, open_balance: Number(row.balance || 0) }));
  record.total = record.allocations.reduce((sum, item) => sum + item.amount, 0);
  record.saved_at = new Date().toISOString();
  return record;
}

function saveBatchArSettlementDraft(rows) {
  const draft = batchArSettlementDraftRecord(rows);
  if (!draft.receipt_no || !draft.allocations.length) return alert("Receipt/batch number and at least one positive invoice allocation are required.");
  localStorage.setItem(`lms.arPaymentDraft.${draft.receipt_no}`, JSON.stringify(draft));
  modalDirty = false;
  alert(`Draft ${draft.receipt_no} saved without an accounting entry. The consolidated payment popup will remain open.`);
}

function restoreBatchArSettlementDraft(receiptNo, rows) {
  let draft = null;
  try { draft = JSON.parse(localStorage.getItem(`lms.arPaymentDraft.${receiptNo}`) || "null"); } catch { draft = null; }
  if (!draft?.allocations?.length || !confirm(`Draft ${receiptNo} is available. Restore the consolidated payment?`)) return;
  const selectedInvoices = new Set(rows.map((row) => row.invoice_no));
  const fields = collectProductModalFields();
  Object.keys(fields).forEach((key) => {
    const input = document.querySelector(`[data-product-field="${CSS.escape(key)}"]`);
    if (input && draft[key] != null) input.value = draft[key];
  });
  draft.allocations.forEach((allocation) => {
    if (!selectedInvoices.has(allocation.invoice_no)) return;
    const input = document.querySelector(`.ar-batch-amount[data-invoice-no="${CSS.escape(allocation.invoice_no)}"]`);
    if (input) input.value = Number(allocation.amount || 0).toFixed(2);
  });
  document.querySelector('[data-product-field="batch_action"]')?.dispatchEvent(new Event("change", { bubbles: true }));
  document.querySelector(".ar-batch-amount")?.dispatchEvent(new Event("input", { bubbles: true }));
  modalDirty = true;
}

async function finalizeBatchArSettlement(data, rows) {
  const enteredDate = prompt("Posting date for this consolidated customer payment\n\nEnter as mm/dd/yyyy. The accounting and cash entries will use this date.", formatDisplayDate(today()));
  if (enteredDate === null) return;
  const postingDate = parseFlexibleDate(enteredDate);
  if (!postingDate) return alert("Enter a valid posting date as mm/dd/yyyy.");
  if (isLockedAccountingDate(postingDate)) return alert(`Posting date ${formatDisplayDate(postingDate)} is inside a closed accounting period. Choose a date in an open period.`);
  await saveBatchArSettlement(data, rows, postingDate);
}

async function saveBatchArSettlement(data, rows, finalPostingDate = "") {
  const record = collectProductModalFields();
  const isWriteOff = record.batch_action === "Write Off";
  const allocations = [...document.querySelectorAll(".ar-batch-amount")].map((input) => {
    const row = rows.find((item) => item.invoice_no === input.dataset.invoiceNo);
    return { row, amount: Number(input.value || 0) };
  }).filter((item) => item.row && item.amount > 0);
  const total = allocations.reduce((sum, item) => sum + item.amount, 0);
  const receiptNo = String(record.receipt_no || "").trim();
  const postingDate = finalPostingDate || "";
  const notes = String(record.notes || "").trim();
  if (!receiptNo || !record.payment_date || !postingDate || total <= 0) return alert("Receipt/batch number, payment date, posting date, and at least one positive allocation are required.");
  if (isWriteOff && (!record.offset_account || !notes)) return alert("Write-off charge account and reason are required.");
  if (!isWriteOff && (!record.method || (!/cash/i.test(record.method) && !String(record.bank_reference || "").trim()))) return alert("Payment method and bank/check reference are required for non-cash payments.");
  if (isLockedAccountingDate(postingDate)) return alert("This posting date is inside the closed accounting period.");
  const invalid = allocations.find((item) => item.amount > Number(item.row.balance || 0) + 0.005);
  if (invalid) return alert(`${invalid.row.invoice_no} cannot exceed its open balance of ${money(invalid.row.balance)}.`);
  const payments = await getAll("customer_payments");
  if (payments.some((payment) => String(payment.receipt_no || "").startsWith(`${receiptNo}-`))) return alert(`Batch ${receiptNo} already exists.`);
  if (!isWriteOff && record.bank_reference && payments.some((payment) => String(payment.bank_reference || "").trim().toLowerCase() === String(record.bank_reference).trim().toLowerCase() && !/void|reversed/i.test(payment.status || ""))) return alert(`Bank/check reference ${record.bank_reference} is already used.`);
  const paymentRows = allocations.map((item, index) => ({ receipt_no: `${receiptNo}-${String(index + 1).padStart(2, "0")}`, payment_date: record.payment_date, customer: item.row.customer, invoice_no: item.row.invoice_no, amount: item.amount, method: isWriteOff ? "Write-Off" : record.method, bank_reference: isWriteOff ? null : record.bank_reference || null, status: isWriteOff ? "Written Off" : "Posted", notes: `${notes || (isWriteOff ? "Write-off" : "Customer payment")} | Batch ${receiptNo} | Posted ${formatDisplayDate(postingDate)}` }));
  const offsetAccount = isWriteOff ? record.offset_account : "FHB Checking";
  const ledgerRows = [
    { entry_date: postingDate, posting_date: postingDate, account: offsetAccount, customer: rows[0].customer, description: `${isWriteOff ? "AR write-off" : "Customer payment"} batch ${receiptNo}`, reference: receiptNo, bank_reference: isWriteOff ? null : record.bank_reference || null, debit: total, credit: 0, source: isWriteOff ? "AR Write-Off" : "Customer Payment", status: "Posted" },
    ...allocations.map((item) => ({ entry_date: postingDate, posting_date: postingDate, account: "Accounts Receivable (A/R)", customer: item.row.customer, invoice_no: item.row.invoice_no, invoice_date: item.row.invoice_date, due_date: item.row.due_date, description: `${item.row.invoice_no} ${isWriteOff ? "write-off" : "payment"} allocation`, reference: receiptNo, bank_reference: isWriteOff ? null : record.bank_reference || null, debit: 0, credit: item.amount, source: isWriteOff ? "AR Write-Off" : "Customer Payment", status: "Posted" })),
  ];
  assertBalancedLedgerRows(ledgerRows, `${receiptNo} selected invoice batch`);
  try {
    await upsertManyWithOptionalColumns("customer_payments", paymentRows, "receipt_no", []);
    await upsertManyWithOptionalColumns("general_ledger", ledgerRows, "id", ["bank_reference"]);
    if (!isWriteOff) await upsertOneWithOptionalColumns("bank_transactions", {
      tx_date: postingDate,
      bank_account: "FHB Checking",
      description: `Customer payment ${rows[0].customer} (${allocations.length} invoices)`,
      reference: record.bank_reference || receiptNo,
      amount: total,
      status: "Matched",
      matched_reference: receiptNo,
      notes: ["Account: FHB Checking", notes].filter(Boolean).join(" | "),
    }, "id", ["bank_account"], "Customer payment posted. Run the bank account SQL update to store its reconciliation account directly.");
    for (const item of allocations) {
      if (isWriteOff) await supabase.from("invoices").update({ status: item.amount >= Number(item.row.balance || 0) - 0.005 ? "Written Off" : "Partial" }).eq("id", item.row.id);
      else await updateInvoicePaymentStatus(item.row.invoice_no);
    }
    await writeAuditLog({ tableName: "customer_payments", action: isWriteOff ? "Batch Write-Off Posted" : "Batch Payment Posted", afterData: { batch: receiptNo, posting_date: postingDate, customer: rows[0].customer, total, allocations: paymentRows, offset_account: offsetAccount, bank_reference: record.bank_reference || null } });
    localStorage.removeItem(`lms.arPaymentDraft.${receiptNo}`);
    await incrementSequence("payment");
    productMeta.invoiceRows = null;
    closeModal(true);
    await renderAccountingView();
  } catch (error) {
    alert(`Could not post selected invoices. ${error.message || error}`);
  }
}

function salesAccountingRows(data) {
  return data.salesOrders.map((order) => {
    const invoice = data.invoices.find((inv) => inv.invoice_no === order.invoice_no || inv.source_ref === order.order_no);
    const lines = order._lines || [];
    const total = lines.reduce((sum, line) => sum + Number(line.qty || 0) * Number(line.unit_price || line.price || 0), 0);
    return { date: order.order_date, order_no: order.order_no, customer: order.customer, customer_po: order.customer_po || "", payment_mode: order.payment_mode || "PO", status: order.status || "", lines: lines.length, total, invoice_no: invoice?.invoice_no || order.invoice_no || "", balance: invoice ? invoiceBalance(invoice) : 0 };
  }).sort((a, b) => String(b.date || "").localeCompare(String(a.date || "")));
}

function purchaseAccountingRows(data) {
  return accountsPayableRows(data).map((row) => ({ ...row, date: row.po_date, ap: row.invoice_amount }));
}

function apRowActions(row) {
  const needsResolve = /mismatch|pending|awaiting/i.test(`${row.match} ${row.status}`) || Number(row.invoice_amount || 0) !== Number(row.received || row.po_total || 0);
  const canPay = row.ap_posted && /matched/i.test(row.match || "") && !/paid/i.test(row.payment || "");
  return `<div class="rowactions">${row.ap_posted ? "" : `<button class="rowbtn" type="button" data-ap-post="${esc(row.po_no)}">Post</button>`}${(row.direct_ap || needsResolve) && !row.landed_cost_ap ? `<button class="rowbtn" type="button" data-ap-resolve="${esc(row.po_no)}">${row.direct_ap ? "Review" : "Resolve"}</button>` : ""}${row.direct_ap ? `<button class="rowbtn danger" type="button" data-ap-reverse-edit="${esc(row.po_no)}">Reverse to Edit</button>` : ""}${canPay ? `<button class="rowbtn" type="button" data-ap-check="${esc(row.po_no)}">Check</button>` : ""}${row.ap_posted && Number(row.balance || 0) > 0.005 && !/paid|written off/i.test(`${row.payment || ""} ${row.status || ""}`) ? `<button class="rowbtn danger" type="button" data-ap-writeoff="${esc(row.po_no)}">Write off</button>` : ""}<button class="rowbtn" type="button" data-accounting-entries data-entry-invoice="${esc(row.invoice_no || "")}" data-entry-source="${esc(row.po_no || "")}">Accounting Entries</button></div>`;
}

function arRowActions(row) {
  const paymentActions = Number(row.balance || 0) > 0 ? `<button class="rowbtn" type="button" data-ar-receive="${esc(row.invoice_no)}">Receive</button><button class="rowbtn danger" type="button" data-ar-writeoff="${esc(row.invoice_no)}">Write off</button>` : "";
  return `<div class="rowactions">${paymentActions}<button class="rowbtn" type="button" data-ar-invoice-pdf="${esc(row.id || row.invoice_no)}">PDF</button><button class="rowbtn" type="button" data-accounting-entries data-entry-invoice="${esc(row.stored_invoice_no || row.invoice_no || "")}" data-entry-source="${esc(row.source_ref || "")}">Accounting Entries</button></div>`;
}

function writeOffAccountOptions(data, side) {
  return (data.coa || []).filter((row) => !/inactive|disabled/i.test(row.status || "Active"))
    .map((row) => row.account || row.name || "")
    .filter((account) => account && !(side === "ar" ? /accounts receivable/i : /accounts payable/i).test(account))
    .sort((a, b) => a.localeCompare(b));
}

function openAccountingWriteOffModal(data, side, reference) {
  const isAr = side === "ar";
  const row = isAr ? accountsReceivableRows(data).find((item) => item.invoice_no === reference) : accountsPayableRows(data).find((item) => item.po_no === reference);
  if (!row || Number(row.balance || 0) <= 0.005) return alert(`${reference} does not have an open balance to write off.`);
  const accounts = writeOffAccountOptions(data, side);
  const defaultAccount = accounts.find((account) => isAr ? /bad debt|write.?off|expense/i.test(account) : /other income|write.?off|income/i.test(account)) || "";
  $("modalTitle").textContent = `${isAr ? "Accounts Receivable" : "Accounts Payable"} write-off — ${reference}`;
  $("modalBody").innerHTML = `<div class="writeoff-summary">
      <div><span>${isAr ? "Customer" : "Vendor"}</span><strong>${esc(isAr ? row.customer : row.vendor)}</strong></div>
      <div><span>${isAr ? "Invoice" : "Purchase Order"}</span><strong>${esc(reference)}</strong></div>
      <div><span>Open balance</span><strong>${money(row.balance)}</strong></div>
    </div>
    <div class="form-grid">
      ${productInput("Posting date", "posting_date", today(), "date")}
      ${productInput("Write-off amount", "amount", Number(row.balance || 0), "number")}
      ${productSelect(isAr ? "Debit / charge account" : "Credit / offset account", "offset_account", accounts, defaultAccount)}
      <div class="field wide"><label>Write-off reason</label><textarea data-product-field="reason" required placeholder="Explain why this balance is being written off"></textarea></div>
    </div>
    <p class="notice"><strong>Accounting entry:</strong> ${isAr ? "Debit the selected charge account and credit Accounts Receivable." : "Debit Accounts Payable and credit the selected offset account."} The original document remains available for audit history.</p>`;
  $("modalSave").textContent = "Post Write-Off";
  $("modalSave").onclick = () => saveAccountingWriteOff(data, side, row);
  $("modal").style.display = "flex";
  const amount = document.querySelector('[data-product-field="amount"]');
  if (amount) { amount.min = "0.01"; amount.max = String(Number(row.balance || 0)); amount.step = "0.01"; }
}

async function saveAccountingWriteOff(data, side, row) {
  const record = collectProductModalFields();
  const amount = Number(record.amount || 0);
  const balance = Number(row.balance || 0);
  const postingDate = record.posting_date || "";
  const offsetAccount = String(record.offset_account || "").trim();
  const reason = String(record.reason || "").trim();
  const isAr = side === "ar";
  if (!postingDate || amount <= 0 || !offsetAccount || !reason) return alert("Posting date, a positive amount, offset account, and write-off reason are required.");
  if (amount > balance + 0.005) return alert(`Write-off cannot exceed the open balance of ${money(balance)}.`);
  if (isLockedAccountingDate(postingDate)) return alert("This write-off date is inside the closed accounting period.");
  const allowedAccounts = new Set(writeOffAccountOptions(data, side).map((account) => account.toLowerCase()));
  if (!allowedAccounts.has(offsetAccount.toLowerCase())) return alert("Choose an active account from the Chart of Accounts.");
  const uniqueSuffix = `${Date.now()}`;
  const writeOffNo = `WOFF-${isAr ? "AR" : "AP"}-${uniqueSuffix}`;
  const documentReference = isAr ? row.invoice_no : row.po_no;
  const party = isAr ? { customer: row.customer } : { vendor: row.vendor };
  const ledgerRows = isAr ? [
    { entry_date: postingDate, posting_date: postingDate, account: offsetAccount, ...party, invoice_no: row.invoice_no, invoice_date: row.invoice_date, due_date: row.due_date, description: `${row.invoice_no} write-off: ${reason}`, reference: writeOffNo, debit: amount, credit: 0, source: "AR Write-Off", status: "Posted" },
    { entry_date: postingDate, posting_date: postingDate, account: "Accounts Receivable (A/R)", ...party, invoice_no: row.invoice_no, invoice_date: row.invoice_date, due_date: row.due_date, description: `${row.invoice_no} write-off: ${reason}`, reference: writeOffNo, debit: 0, credit: amount, source: "AR Write-Off", status: "Posted" },
  ] : [
    { entry_date: postingDate, posting_date: postingDate, account: "Accounts Payable (A/P)", ...party, invoice_no: row.invoice_no, invoice_date: row.invoice_date, due_date: row.due_date, description: `${row.po_no} write-off: ${reason}`, reference: row.po_no, debit: amount, credit: 0, source: "AP Write-Off", status: "Posted" },
    { entry_date: postingDate, posting_date: postingDate, account: offsetAccount, ...party, invoice_no: row.invoice_no, invoice_date: row.invoice_date, due_date: row.due_date, description: `${row.po_no} write-off: ${reason}`, reference: row.po_no, debit: 0, credit: amount, source: "AP Write-Off", status: "Posted" },
  ];
  assertBalancedLedgerRows(ledgerRows, `${documentReference} write-off`);
  try {
    if (isAr) {
      await upsertOne("customer_payments", { receipt_no: writeOffNo, payment_date: postingDate, customer: row.customer, invoice_no: row.invoice_no, amount, method: "Write-Off", bank_reference: null, status: "Written Off", notes: reason }, "receipt_no");
      await upsertManyWithOptionalColumns("general_ledger", ledgerRows, "id", ["bank_reference"]);
      const fullyWrittenOff = amount >= balance - 0.005;
      await supabase.from("invoices").update({ status: fullyWrittenOff ? "Written Off" : "Partial" }).eq("id", row.id);
    } else {
      await upsertManyWithOptionalColumns("general_ledger", ledgerRows, "id", ["bank_reference"]);
      const po = (data.pos || []).find((item) => item.po_no === row.po_no);
      const existingNotes = String(po?.notes || "").trim();
      const notes = [existingNotes, `${formatDisplayDate(postingDate)} | Write-off ${money(amount)} to ${offsetAccount} | ${reason} | ${writeOffNo}`].filter(Boolean).join("\n");
      const update = { notes };
      if (amount >= balance - 0.005) Object.assign(update, { payment_status: "Written Off", status: "Written Off" });
      const { error } = await supabase.from("purchase_orders").update(update).eq("id", row.id);
      if (error) throw error;
    }
    await writeAuditLog({ tableName: isAr ? "invoices" : "purchase_orders", action: "Write-Off Posted", beforeData: row, afterData: { reference: documentReference, write_off_no: writeOffNo, posting_date: postingDate, amount, offset_account: offsetAccount, reason } });
    closeModal(true);
    await renderAccountingView();
  } catch (error) {
    alert(`Could not post write-off. ${error.message || error}`);
  }
}

function trialBalanceRows(data) {
  return coaRows(data).map((row) => {
    const debitBalance = /credit/i.test(row.normal_balance) ? Math.max(0, -row.balance) : Math.max(0, row.balance);
    const creditBalance = /credit/i.test(row.normal_balance) ? Math.max(0, row.balance) : Math.max(0, -row.balance);
    return { account: row.account, type: row.type, debit: debitBalance, credit: creditBalance };
  }).filter((row) => row.debit || row.credit);
}

function trialBalanceSection(type = "") {
  const value = String(type || "").toLowerCase();
  if (/asset/.test(value)) return "Assets";
  if (/liabilit/.test(value)) return "Liabilities";
  if (/equity|capital/.test(value)) return "Equity";
  if (/revenue|income|sales/.test(value)) return "Revenue";
  if (/expense|cost|cogs/.test(value)) return "Expenses";
  return "Other Accounts";
}

function trialBalanceReportHtml(data) {
  const rows = trialBalanceRows(data).map((row) => ({ ...row, section: trialBalanceSection(row.type) }));
  const sectionOrder = ["Assets", "Liabilities", "Equity", "Revenue", "Expenses", "Other Accounts"];
  const from = localStorage.getItem("lms.accountingReportFrom") || "";
  const to = localStorage.getItem("lms.accountingReportTo") || today();
  const periodLabel = from
    ? `For the period ${formatDisplayDate(from)} through ${formatDisplayDate(to)}`
    : `As of ${formatDisplayDate(to)}`;
  const body = sectionOrder.map((section) => {
    const sectionRows = rows.filter((row) => row.section === section);
    if (!sectionRows.length) return "";
    const debit = sectionRows.reduce((sum, row) => sum + Number(row.debit || 0), 0);
    const credit = sectionRows.reduce((sum, row) => sum + Number(row.credit || 0), 0);
    return `<tr class="trial-balance-section"><th colspan="4">${esc(section)}</th></tr>
      ${sectionRows.map((row) => `<tr class="trial-balance-account-row" data-tb-search-row="1">
        <td><button type="button" class="trial-balance-account-link" data-tb-history data-tb-account="${esc(row.account)}">${esc(row.account)}</button></td>
        <td>${esc(row.type || "")}</td>
        <td class="num">${row.debit ? `<button type="button" class="trial-balance-amount-link" data-tb-history data-tb-account="${esc(row.account)}">${money(row.debit)}</button>` : ""}</td>
        <td class="num">${row.credit ? `<button type="button" class="trial-balance-amount-link" data-tb-history data-tb-account="${esc(row.account)}">${money(row.credit)}</button>` : ""}</td>
      </tr>`).join("")}
      <tr class="trial-balance-subtotal">
        <th colspan="2"><button type="button" class="trial-balance-total-link" data-tb-history data-tb-section="${esc(section)}">Total ${esc(section)}</button></th>
        <th class="num"><button type="button" class="trial-balance-total-link" data-tb-history data-tb-section="${esc(section)}">${money(debit)}</button></th>
        <th class="num"><button type="button" class="trial-balance-total-link" data-tb-history data-tb-section="${esc(section)}">${money(credit)}</button></th>
      </tr>`;
  }).join("");
  const totalDebit = rows.reduce((sum, row) => sum + Number(row.debit || 0), 0);
  const totalCredit = rows.reduce((sum, row) => sum + Number(row.credit || 0), 0);
  const difference = totalDebit - totalCredit;
  return `<article class="financial-report trial-balance-report">
    <header class="financial-report-header">
      <div class="financial-company">LMS Imports</div>
      <h2>Trial Balance</h2>
      <div>${esc(periodLabel)}</div>
      <small>Unaudited — For management use</small>
    </header>
    <p class="financial-report-help">Click any account, debit, credit, subtotal, or grand total to review the postings included in that amount.</p>
    <div class="trial-balance-table-wrap"><table class="financial-statement-table trial-balance-table">
      <thead><tr><th>Account</th><th>Type</th><th class="num">Debit</th><th class="num">Credit</th></tr></thead>
      <tbody>${body || `<tr class="statement-empty"><td colspan="4">No posted balances for this period.</td></tr>`}
        <tr class="trial-balance-grand-total">
          <th colspan="2"><button type="button" class="trial-balance-total-link" data-tb-history>Grand Total</button></th>
          <th class="num"><button type="button" class="trial-balance-total-link" data-tb-history>${money(totalDebit)}</button></th>
          <th class="num"><button type="button" class="trial-balance-total-link" data-tb-history>${money(totalCredit)}</button></th>
        </tr>
        <tr class="trial-balance-check ${Math.abs(difference) <= 0.005 ? "balanced" : "out-of-balance"}"><th colspan="3">Difference</th><th class="num"><button type="button" class="trial-balance-total-link" data-tb-history>${money(difference)}</button></th></tr>
      </tbody>
    </table></div>
  </article>`;
}

function trialBalanceHistoryRows(data, filters = {}) {
  return (data.gl || []).filter((row) => {
    if (filters.account && row.account !== filters.account) return false;
    if (filters.section && trialBalanceSection(accountType(row.account || "")) !== filters.section) return false;
    if (filters.side === "debit" && Number(row.debit || 0) <= 0) return false;
    if (filters.side === "credit" && Number(row.credit || 0) <= 0) return false;
    return true;
  }).slice().sort((a, b) => String(a.posting_date || "").localeCompare(String(b.posting_date || "")) || String(a.account || "").localeCompare(String(b.account || "")));
}

function openTrialBalanceHistoryModal(data, filters = {}) {
  const rows = trialBalanceHistoryRows(data, filters);
  const from = localStorage.getItem("lms.accountingReportFrom") || "";
  const to = localStorage.getItem("lms.accountingReportTo") || today();
  const scope = filters.account || filters.section || "All accounts";
  const sideLabel = filters.side ? ` — ${filters.side === "debit" ? "Debit" : "Credit"}` : "";
  const periodLabel = from ? `${formatDisplayDate(from)} through ${formatDisplayDate(to)}` : `Beginning through ${formatDisplayDate(to)}`;
  const totalDebit = rows.reduce((sum, row) => sum + Number(row.debit || 0), 0);
  const totalCredit = rows.reduce((sum, row) => sum + Number(row.credit || 0), 0);
  $("modalTitle").textContent = `Trial Balance History — ${scope}${sideLabel}`;
  $("modalBody").innerHTML = `<div class="trial-balance-history-summary">
      <div><span>Period</span><strong>${esc(periodLabel)}</strong></div>
      <div><span>Rows</span><strong>${rows.length}</strong></div>
      <div><span>Debit</span><strong>${money(totalDebit)}</strong></div>
      <div><span>Credit</span><strong>${money(totalCredit)}</strong></div>
    </div>
    <div class="actions"><button type="button" id="trialBalanceHistoryExcelBtn">Download Excel</button></div>
    <div class="table-wrap trial-balance-history-table"><table><thead><tr><th>Posting Date</th><th>Account</th><th>Description</th><th>Reference</th><th>Customer / Vendor</th><th>Debit</th><th>Credit</th><th>Source</th><th>Status</th></tr></thead><tbody>
      ${rows.length ? rows.map((row) => `<tr><td>${esc(formatDisplayDate(row.posting_date))}</td><td>${esc(row.account)}</td><td class="preserve-lines">${esc(row.description || "")}</td><td>${esc(row.reference || "")}</td><td>${esc(row.customer || row.vendor || "")}</td><td class="numcell">${row.debit ? money(row.debit) : ""}</td><td class="numcell">${row.credit ? money(row.credit) : ""}</td><td>${esc(row.source || "")}</td><td>${esc(row.status || "")}</td></tr>`).join("") : `<tr><td colspan="9" class="empty">No posting history is included in this amount.</td></tr>`}
    </tbody></table></div>`;
  $("modalSave").style.display = "none";
  $("modalCancel").textContent = "Close";
  $("modal").style.display = "flex";
  $("trialBalanceHistoryExcelBtn").onclick = () => exportTrialBalanceHistoryCsv(rows, scope, from, to);
}

function exportTrialBalanceHistoryCsv(rows, scope, from, to) {
  const columns = ["Posting Date", "Account", "Description", "Reference", "Customer", "Vendor", "Debit", "Credit", "Source", "Status"];
  const csvCell = (value) => `"${String(value ?? "").replace(/"/g, '""')}"`;
  const lines = [columns.map(csvCell).join(","), ...(rows || []).map((row) => [row.posting_date, row.account, row.description, row.reference, row.customer, row.vendor, row.debit || 0, row.credit || 0, row.source, row.status].map(csvCell).join(","))];
  const blob = new Blob(["\ufeff" + lines.join("\r\n")], { type: "text/csv;charset=utf-8" });
  const link = document.createElement("a");
  link.href = URL.createObjectURL(blob);
  link.download = `trial-balance-history-${String(scope || "all").replace(/[^a-z0-9]+/gi, "-").replace(/^-|-$/g, "").toLowerCase()}-${from || "beginning"}-to-${to || today()}.csv`;
  link.click();
  URL.revokeObjectURL(link.href);
}

function balanceSheetRows(data) {
  const asOf = localStorage.getItem("lms.accountingReportTo") || today();
  const year = Number(String(asOf).slice(0, 4)) || new Date().getFullYear();
  const fiscalYearStart = `${year}-01-01`;
  const rows = coaRows(data)
    .filter((row) => /asset|liability|equity/i.test(row.type))
    .map((row) => ({ section: row.type, account: row.account, amount: row.balance }));
  const earnings = fiscalEarningsByCutoff(data.gl || [], fiscalYearStart, asOf);
  const addEquity = (account, amount) => {
    const existing = rows.find((row) => String(row.account || "").toLowerCase() === account.toLowerCase());
    if (existing) existing.amount = Number(existing.amount || 0) + Number(amount || 0);
    else if (Math.abs(Number(amount || 0)) > 0.00001) rows.push({ section: "Equity", account, amount: Number(amount || 0) });
  };
  addEquity("Retained Earnings", earnings.priorYears);
  addEquity("Current Year Earnings", earnings.currentYear);
  return rows.sort((a, b) => String(a.section || "").localeCompare(String(b.section || "")) || String(a.account || "").localeCompare(String(b.account || "")));
}

function incomeStatementRows(data) {
  return coaRows(data).filter((row) => /revenue|income|expense|cost/i.test(row.type)).map((row) => ({ section: row.type, account: row.account, amount: row.balance }));
}

function fiscalEarningsByCutoff(glRows, fiscalYearStart, asOf) {
  let priorYears = 0;
  let currentYear = 0;
  (glRows || []).forEach((row) => {
    const type = accountType(row.account || "");
    if (!/revenue|expense/i.test(type)) return;
    const date = String(row.posting_date || row.entry_date || "").slice(0, 10);
    if (date && asOf && date > asOf) return;
    const activity = /revenue/i.test(type)
      ? Number(row.credit || 0) - Number(row.debit || 0)
      : Number(row.credit || 0) - Number(row.debit || 0);
    if (date && date < fiscalYearStart) priorYears += activity;
    else currentYear += activity;
  });
  return { priorYears, currentYear };
}

function cashFlowRows(data) {
  const isCashAccount = (account) => /cash|bank|checking|savings/i.test(account || "") && !/charges|fees|expense|payable|receivable/i.test(account || "");
  return data.gl.filter((row) => isCashAccount(row.account)).map((row) => ({
    section: Number(row.debit || 0) >= Number(row.credit || 0) ? "Cash In" : "Cash Out",
    description: row.description || row.reference,
    amount: Number(row.debit || 0) - Number(row.credit || 0),
  }));
}

function financialStatementHtml(title, rows, heads, mapper, data, basis = "period") {
  const from = localStorage.getItem("lms.accountingReportFrom") || "Beginning";
  const to = localStorage.getItem("lms.accountingReportTo") || today();
  const periodLabel = basis === "asOf"
    ? `As of ${formatDisplayDate(to)}`
    : `${from ? formatDisplayDate(from) : "Beginning"} through ${formatDisplayDate(to)}`;
  return title === "Balance Sheet"
    ? balanceSheetReportHtml(rows, data, periodLabel)
    : incomeStatementReportHtml(rows, data, periodLabel);
}

function statementAccountRows(rows, data) {
  const visible = (rows || []).filter((row) => Math.abs(Number(row.amount || 0)) > 0.004);
  if (!visible.length) return `<tr class="statement-empty"><td colspan="2">No posted activity for this section.</td></tr>`;
  return visible.map((row) => {
    const ledgerRows = (data.gl || []).filter((entry) => entry.account === row.account).slice().sort((a, b) => String(a.posting_date || "").localeCompare(String(b.posting_date || "")));
    let running = 0;
    const details = ledgerRows.map((entry) => {
      const normalCredit = /liability|equity|revenue|income/i.test(row.section || accountType(row.account));
      running += normalCredit ? Number(entry.credit || 0) - Number(entry.debit || 0) : Number(entry.debit || 0) - Number(entry.credit || 0);
      return `<tr><td>${esc(formatDisplayDate(entry.posting_date))}</td><td>${esc(entry.description || "")}</td><td>${esc(entry.reference || "")}</td><td>${esc(entry.customer || entry.vendor || "")}</td><td class="num">${entry.debit ? money(entry.debit) : ""}</td><td class="num">${entry.credit ? money(entry.credit) : ""}</td><td class="num">${money(running)}</td></tr>`;
    }).join("");
    return `<tr class="statement-account-row"><td><button type="button" class="statement-account-button" data-financial-expand aria-expanded="false"><span class="statement-caret">▶</span>${esc(row.account)}</button></td><td class="num">${money(row.amount)}</td></tr>
      <tr class="statement-drill-row" hidden><td colspan="2"><div class="statement-drill"><strong>${esc(row.account)} — Transaction Detail</strong><div class="table-wrap"><table><thead><tr><th>Date</th><th>Description</th><th>Reference</th><th>Customer / Vendor</th><th class="num">Debit</th><th class="num">Credit</th><th class="num">Running Balance</th></tr></thead><tbody>${details || `<tr><td colspan="7">No transactions found for the selected dates.</td></tr>`}</tbody></table></div></div></td></tr>`;
  }).join("");
}

function statementSection(title, rows, data, totalLabel = `Total ${title}`) {
  const total = (rows || []).reduce((sum, row) => sum + Number(row.amount || 0), 0);
  return `<tbody class="statement-section"><tr class="statement-section-title"><th colspan="2">${esc(title)}</th></tr>${statementAccountRows(rows, data)}<tr class="statement-subtotal"><th>${esc(totalLabel)}</th><th class="num">${money(total)}</th></tr></tbody>`;
}

function financialReportHeader(title, periodLabel) {
  return `<header class="financial-report-header"><div class="financial-company">LMS Imports</div><h2>${esc(title)}</h2><div>${esc(periodLabel)}</div><small>Unaudited — For management use</small></header>`;
}

function incomeStatementReportHtml(rows, data, periodLabel) {
  const revenue = rows.filter((row) => /revenue|income/i.test(row.section || ""));
  const cogs = rows.filter((row) => /cogs|cost of goods/i.test(`${row.section || ""} ${row.account || ""}`));
  const expenses = rows.filter((row) => !revenue.includes(row) && !cogs.includes(row));
  const revenueTotal = revenue.reduce((sum, row) => sum + Number(row.amount || 0), 0);
  const cogsTotal = cogs.reduce((sum, row) => sum + Number(row.amount || 0), 0);
  const expenseTotal = expenses.reduce((sum, row) => sum + Number(row.amount || 0), 0);
  const grossProfit = revenueTotal - cogsTotal;
  const netIncome = grossProfit - expenseTotal;
  return `<article class="financial-report income-statement-report">${financialReportHeader("Income Statement", periodLabel)}<p class="financial-report-help">Click any account to expand its General Ledger transactions for this reporting period.</p><table class="financial-statement-table">${statementSection("Revenue", revenue, data, "Total Revenue")}${statementSection("Cost of Goods Sold", cogs, data, "Total Cost of Goods Sold")}<tbody><tr class="statement-key-total"><th>Gross Profit</th><th class="num">${money(grossProfit)}</th></tr></tbody>${statementSection("Operating Expenses", expenses, data, "Total Operating Expenses")}<tfoot><tr class="statement-grand-total"><th>Net Income</th><th class="num">${money(netIncome)}</th></tr></tfoot></table></article><div id="financialDetailHost"></div>`;
}

function balanceSheetReportHtml(rows, data, periodLabel) {
  const assets = rows.filter((row) => /asset/i.test(row.section || ""));
  const liabilities = rows.filter((row) => /liability/i.test(row.section || ""));
  const equity = rows.filter((row) => /equity/i.test(row.section || ""));
  const assetTotal = assets.reduce((sum, row) => sum + Number(row.amount || 0), 0);
  const liabilityTotal = liabilities.reduce((sum, row) => sum + Number(row.amount || 0), 0);
  const equityTotal = equity.reduce((sum, row) => sum + Number(row.amount || 0), 0);
  const liabilityEquityTotal = liabilityTotal + equityTotal;
  const difference = assetTotal - liabilityEquityTotal;
  return `<article class="financial-report balance-sheet-report">${financialReportHeader("Balance Sheet", periodLabel)}<p class="financial-report-help">Click any account to expand all General Ledger transactions through the as-of date. Fiscal year: January 1–December 31.</p><table class="financial-statement-table">${statementSection("Assets", assets, data, "Total Assets")}${statementSection("Liabilities", liabilities, data, "Total Liabilities")}${statementSection("Equity", equity, data, "Total Equity")}<tfoot><tr class="statement-key-total"><th>Total Liabilities and Equity</th><th class="num">${money(liabilityEquityTotal)}</th></tr><tr class="statement-balance-check ${Math.abs(difference) <= 0.005 ? "balanced" : "out-of-balance"}"><th>Balance Check (Assets − Liabilities & Equity)</th><th class="num">${money(difference)}</th></tr></tfoot></table></article><div id="financialDetailHost"></div>`;
}

function accountDrillButton(account) {
  return `<button class="link-btn" data-account-drill="${esc(account)}">${esc(account)}</button>`;
}

function bankSummaryHtml(data) {
  const rows = bankReconciliationRows(data);
  const book = rows.filter((r) => r.source === "Book").reduce((sum, row) => sum + Number(row.debit || 0) - Number(row.credit || 0), 0);
  const bank = data.bankRows.filter((row) => !/ignored/i.test(row.status || "")).reduce((sum, row) => sum + Number(row.amount || 0), 0);
  const unmatched = data.bankRows.filter((row) => /unmatched|review/i.test(row.status || "")).length;
  return `<div class="stats">${stat("Book Cash", money(book), "Cash account from ledger")}${stat("Bank Activity", money(bank), "Bank imported or entered amount")}${stat("Unmatched", unmatched, "Items needing review")}${stat("Difference", money(book - bank), "Book cash less bank activity")}</div>`;
}

function bankReconciliationRows(data) {
  const cashRows = data.gl.filter((row) => /cash|bank|operating bank/i.test(row.account || "")).map((row) => ({ date: row.posting_date, source: "Book", description: row.description, reference: row.reference, debit: row.debit, credit: row.credit, bank_amount: "", status: row.status || "Posted" }));
  const bankRows = data.bankRows.map((row) => ({ date: row.tx_date, source: "Bank", description: row.description, reference: row.reference, debit: "", credit: "", bank_amount: Number(row.amount || 0), status: row.status || "Unmatched" }));
  return [...cashRows, ...bankRows].sort((a, b) => String(b.date || "").localeCompare(String(a.date || "")));
}

function accountingBankReportHtml(data) {
  const accounts = reconciliationAccountOptions(data.coa || [], data.allGl || data.gl || []);
  const savedAccount = localStorage.getItem("lms.bankRecBank") || "";
  const selectedAccount = accounts.includes(savedAccount) ? savedAccount : accounts[0] || "Operating Bank";
  const periodTo = data.reportTo || today();
  const periodFrom = data.reportFrom || monthStart(periodTo);
  const accountKind = reconciliationAccountKind(selectedAccount);
  const beginning = Number(getBankBeginningBalance(selectedAccount).amount || 0);
  const statement = buildBankStatement(data.allGl || data.gl || [], data.bankRows || [], selectedAccount, periodFrom, periodTo, beginning);
  return `<div class="financial-report-actions no-print">
      <label>Cash / Credit Card Account
        <select id="accountingBankReportAccount">${accounts.map((account) => `<option value="${esc(account)}" ${account === selectedAccount ? "selected" : ""}>${esc(account)} â€” ${esc(reconciliationAccountKind(account))}</option>`).join("")}</select>
      </label>
      <button id="accountingBankBeginningBtn">Set beginning balance</button>
      <button id="accountingBankReportExcelBtn">Excel</button>
      <button data-jump="bank">Open matching workbench</button>
    </div>
    ${bankStatementHtml(statement, selectedAccount, periodFrom, periodTo, accountKind)}`;
}

function bindAccountingView(data) {
  const bindClick = (id, handler) => {
    const el = $(id);
    if (el) el.onclick = handler;
  };
  const toggleAccountingSummaryBtn = $("toggleAccountingSummaryBtn");
  if (toggleAccountingSummaryBtn) toggleAccountingSummaryBtn.onclick = () => {
    const nextCollapsed = localStorage.getItem(ACCOUNTING_SUMMARY_STORAGE_KEY) !== "1";
    localStorage.setItem(ACCOUNTING_SUMMARY_STORAGE_KEY, nextCollapsed ? "1" : "0");
    renderAccountingView();
  };
  document.querySelectorAll("[data-accounting-tab]").forEach((btn) => btn.onclick = () => {
    accountingTab = btn.dataset.accountingTab;
    renderAccountingView();
  });
  document.querySelectorAll("[data-accounting-switch]").forEach((btn) => btn.onclick = () => {
    accountingTab = btn.dataset.accountingSwitch;
    renderAccountingView();
  });
  document.querySelectorAll("[data-ap-tab]").forEach((btn) => btn.onclick = () => {
    accountsPayableTab = btn.dataset.apTab;
    renderAccountingView();
  });
  document.querySelectorAll("[data-ar-invoice-tab]").forEach((btn) => btn.onclick = () => {
    accountsReceivableTab = btn.dataset.arInvoiceTab;
    renderAccountingView();
  });
  document.querySelectorAll("[data-ap-payment-reference]").forEach((btn) => btn.onclick = async () => {
    const searchValue = btn.dataset.apPaymentRun || btn.dataset.apPaymentReference || "";
    checkRunTab = "printed";
    await loadView("checkrun");
    const search = $("checkRunSearch");
    if (search) {
      search.value = searchValue;
      search.dispatchEvent(new Event("input", { bubbles: true }));
    }
  });
  $("accountingApplyDatesBtn").onclick = () => {
    localStorage.setItem("lms.accountingReportFrom", $("accountingReportFrom").value || "");
    localStorage.setItem("lms.accountingReportTo", $("accountingReportTo").value || "");
    renderAccountingView();
  };
  document.querySelectorAll("[data-jump]").forEach((btn) => btn.onclick = () => loadView(btn.dataset.jump));
  const postBtn = $("postApFromPoBtn");
  if (postBtn) postBtn.onclick = () => openPostApFromPoModal(data);
  const accountingSearch = $("accountingSearch");
  if (accountingSearch) accountingSearch.oninput = applyAccountingSearch;
  bindClick("newAccountBtn", () => openAccountingSourceModal("coa"));
  bindClick("newBankItemBtn", () => openAccountingSourceModal("bank"));
  bindClick("newJournalBtn", () => openBalancedJournalModal(data));
  bindClick("journalHistoryBtn", () => openBalancedJournalHistoryModal(data));
  bindClick("periodCloseChecklistBtn", async () => openPeriodCloseChecklist(await accountingControlData($("accountingReportTo")?.value || today())));
  bindClick("transactionPostingAuditBtn", openTransactionPostingAudit);
  bindClick("trialBalanceTemplateBtn", downloadTrialBalanceTemplate);
  bindClick("trialBalanceUploadBtn", () => $("trialBalanceFileImport").click());
  if ($("trialBalanceFileImport")) $("trialBalanceFileImport").onchange = importTrialBalanceFile;
  bindClick("beginningInventoryTemplateBtn", downloadBeginningInventoryTemplate);
  bindClick("beginningInventoryUploadBtn", () => $("beginningInventoryFileImport").click());
  if ($("beginningInventoryFileImport")) $("beginningInventoryFileImport").onchange = importBeginningInventoryFile;
  bindClick("beginningApTemplateBtn", downloadBeginningApTemplate);
  bindClick("beginningApTemplateInlineBtn", downloadBeginningApTemplate);
  bindClick("beginningApUploadBtn", () => $("beginningApFileImport").click());
  bindClick("beginningApUploadInlineBtn", () => $("beginningApFileImport").click());
  if ($("beginningApFileImport")) $("beginningApFileImport").onchange = importBeginningApFile;
  bindClick("clearBeginningApBtn", clearBeginningApDetail);
  bindClick("clearBeginningApInlineBtn", clearBeginningApDetail);
  bindClick("beginningArTemplateBtn", downloadBeginningArTemplate);
  bindClick("beginningArTemplateInlineBtn", downloadBeginningArTemplate);
  bindClick("beginningArUploadBtn", () => $("beginningArFileImport").click());
  bindClick("beginningArUploadInlineBtn", () => $("beginningArFileImport").click());
  if ($("beginningArFileImport")) $("beginningArFileImport").onchange = importBeginningArFile;
  bindClick("clearBeginningArBtn", clearBeginningArDetail);
  bindClick("clearBeginningArInlineBtn", clearBeginningArDetail);
  document.querySelectorAll("[data-beginning-inventory-upload]").forEach((btn) => btn.onclick = () => $("beginningInventoryFileImport").click());
  document.querySelectorAll("[data-beginning-ap-upload]").forEach((btn) => btn.onclick = () => $("beginningApFileImport").click());
  document.querySelectorAll("[data-beginning-ar-upload]").forEach((btn) => btn.onclick = () => $("beginningArFileImport").click());
  bindClick("accountingCsvBtn", exportAccountingCsv);
  bindClick("accountingPrintBtn", () => window.print());
  const accountingBankReportAccount = $("accountingBankReportAccount");
  if (accountingBankReportAccount) accountingBankReportAccount.onchange = () => {
    localStorage.setItem("lms.bankRecBank", accountingBankReportAccount.value);
    renderAccountingView();
  };
  bindClick("accountingBankBeginningBtn", () => openBankBeginningModal($("accountingBankReportAccount")?.value || "Operating Bank"));
  bindClick("accountingBankReportExcelBtn", () => {
    const account = $("accountingBankReportAccount")?.value || "Operating Bank";
    const from = $("accountingReportFrom")?.value || monthStart($("accountingReportTo")?.value || today());
    const to = $("accountingReportTo")?.value || today();
    const statement = buildBankStatement(data.allGl || data.gl || [], data.bankRows || [], account, from, to, Number(getBankBeginningBalance(account).amount || 0));
    exportBankStatementCsv(statement, account, from, to);
  });
  document.querySelectorAll("[data-account-drill]").forEach((btn) => btn.onclick = () => showAccountDrill(data, btn.dataset.accountDrill));
  document.querySelectorAll("[data-tb-history]").forEach((btn) => btn.onclick = () => openTrialBalanceHistoryModal(data, {
    account: btn.dataset.tbAccount || "",
    section: btn.dataset.tbSection || "",
    side: btn.dataset.tbSide || "",
  }));
  document.querySelectorAll("[data-financial-expand]").forEach((btn) => btn.onclick = () => {
    const detailRow = btn.closest("tr")?.nextElementSibling;
    if (!detailRow?.classList.contains("statement-drill-row")) return;
    const opening = detailRow.hidden;
    detailRow.hidden = !opening;
    btn.setAttribute("aria-expanded", String(opening));
    const caret = btn.querySelector(".statement-caret");
    if (caret) caret.textContent = opening ? "▼" : "▶";
  });
  document.querySelectorAll("[data-ap-post]").forEach((btn) => btn.onclick = () => openPostApFromPoModal(data, btn.dataset.apPost));
  document.querySelectorAll("[data-ap-resolve]").forEach((btn) => btn.onclick = () => openResolveApMismatchModal(data, btn.dataset.apResolve));
  document.querySelectorAll("[data-ap-reverse-edit]").forEach((btn) => btn.onclick = () => reverseDirectApToEdit(data, btn.dataset.apReverseEdit));
  document.querySelectorAll("[data-ap-check]").forEach((btn) => btn.onclick = () => createCheckRunFromPo(data, btn.dataset.apCheck));
  document.querySelectorAll("[data-ap-writeoff]").forEach((btn) => btn.onclick = () => openAccountingWriteOffModal(data, "ap", btn.dataset.apWriteoff));
  document.querySelectorAll("[data-ar-receive]").forEach((btn) => btn.onclick = () => {
    const inv = data.invoices.find((row) => row.invoice_no === btn.dataset.arReceive);
    openCustomerPaymentModal(inv);
  });
  document.querySelectorAll("[data-ar-invoice-view]").forEach((btn) => btn.onclick = () => {
    const invoice = data.invoices.find((row) => row.invoice_no === btn.dataset.arInvoiceView);
    if (!invoice) return alert(`Invoice ${btn.dataset.arInvoiceView} could not be found.`);
    openInvoiceModal(invoice, true);
  });
  document.querySelectorAll("[data-accounting-invoice-view]").forEach((btn) => btn.onclick = () => {
    const key = String(btn.dataset.accountingInvoiceView || "");
    const invoice = data.invoices.find((row) => String(row.id || row.invoice_no || "") === key);
    if (!invoice) return alert("This invoice could not be found.");
    openInvoiceModal(invoice, true);
  });
  document.querySelectorAll("[data-accounting-invoice-pdf]").forEach((btn) => btn.onclick = () => {
    const key = String(btn.dataset.accountingInvoicePdf || "");
    const row = accountingInvoiceHistoryRows(data).find((invoice) => String(invoice.id || invoice.invoice_no || "") === key);
    if (!row) return alert("This invoice could not be found.");
    printCustomerInvoice(row._pdfLookup || row.invoice_no);
  });
  document.querySelectorAll("[data-ar-invoice-pdf]").forEach((btn) => btn.onclick = () => {
    const key = String(btn.dataset.arInvoicePdf || "");
    const invoice = data.invoices.find((row) => String(row.id || row.invoice_no || "") === key);
    if (!invoice) return alert("This invoice could not be found.");
    printCustomerInvoice(/work order|repair/i.test(invoice.type || "") ? (invoice.source_ref || invoice.invoice_no) : invoice.invoice_no);
  });
  document.querySelectorAll("[data-accounting-entries]").forEach((btn) => btn.onclick = () => openAccountingEntriesModal(data, {
    invoiceNo: btn.dataset.entryInvoice || "",
    sourceRef: btn.dataset.entrySource || "",
  }));
  document.querySelectorAll("[data-ar-paid-history]").forEach((btn) => btn.onclick = () => openArPaymentHistoryModal(data, btn.dataset.arPaidHistory));
  document.querySelectorAll("[data-ar-writeoff]").forEach((btn) => btn.onclick = () => openAccountingWriteOffModal(data, "ar", btn.dataset.arWriteoff));
  bindClick("receiveSelectedArBtn", () => openBatchArSettlementModal(data));
  bindClick("receiveOneArPaymentBtn", () => {
    if (selectedArInvoiceRows(data).length) return openBatchArSettlementModal(data);
    loadView("payments");
  });
  bindClick("accountingReceivePaymentBtn", () => openCustomerPaymentModal());
  const selectVisibleArInvoices = $("selectVisibleArInvoices");
  if (selectVisibleArInvoices) selectVisibleArInvoices.onchange = () => {
    document.querySelectorAll(".ar-invoice-select:not(:disabled)").forEach((input) => {
      if (input.closest("tr")?.style.display !== "none") input.checked = selectVisibleArInvoices.checked;
    });
    syncArInvoiceSelection();
  };
  document.querySelectorAll(".ar-invoice-select").forEach((input) => input.onchange = syncArInvoiceSelection);
  document.querySelectorAll("[data-reverse-manual-journal]").forEach((btn) => btn.onclick = () => reverseManualJournal(btn.dataset.reverseManualJournal));
  document.querySelectorAll(".column-filter").forEach((input) => input.oninput = (event) => {
    applyColumnFilters(event);
    if (accountingTab === "ar") syncArInvoiceSelection();
  });
  if (accountingTab === "ar") syncArInvoiceSelection();
  if (accountingTab === "payments") bindPaymentRows();
  if (accountingTab === "bank") bindBankReconciliationMarks();
}

async function openAccountingSourceModal(sourceView) {
  currentCfg = tableMap[sourceView];
  if (sourceView === "accounting") {
    const [customers, vendors] = await Promise.all([
      getAll("customers"),
      getAll("vendors"),
    ]);
    productMeta.accountingCustomers = customers || [];
    productMeta.accountingVendors = vendors || [];
  }
  openModal();
}

function journalAccountOptions(coa = []) {
  return (coa || []).filter((row) => !/inactive|disabled|closed/i.test(`${row.status || ""} ${row.notes || ""}`)).map((row) => row.account).filter(Boolean).sort();
}

function journalLineRowHtml(line = {}, index = 0, accounts = []) {
  return `<tr data-journal-line data-journal-line-id="${esc(line.id || "")}">
    <td><input class="suggest-input" data-suggest-source="accounts" data-journal-line-field="account" value="${esc(line.account || "")}" placeholder="Type account name, code, type, or group" autocomplete="off" inputmode="search"></td>
    <td><input data-journal-line-field="description" value="${esc(line.description || "")}" placeholder="Line description"></td>
    <td><input type="number" min="0" step="0.01" data-journal-line-field="debit" value="${esc(line.debit || "")}"></td>
    <td><input type="number" min="0" step="0.01" data-journal-line-field="credit" value="${esc(line.credit || "")}"></td>
    <td><button type="button" class="rowbtn danger" data-remove-journal-line>Remove</button></td>
  </tr>`;
}

function updateJournalTotals() {
  const lines = readBalancedJournalLines(false);
  const debit = lines.reduce((sum, line) => sum + Number(line.debit || 0), 0);
  const credit = lines.reduce((sum, line) => sum + Number(line.credit || 0), 0);
  const difference = debit - credit;
  if ($("journalDebitTotal")) $("journalDebitTotal").textContent = money(debit);
  if ($("journalCreditTotal")) $("journalCreditTotal").textContent = money(credit);
  if ($("journalDifference")) $("journalDifference").textContent = money(difference);
}

function wireBalancedJournalLines(accounts = []) {
  document.querySelectorAll("[data-journal-line]").forEach((tr) => {
    tr.querySelectorAll("input").forEach((input) => input.oninput = updateJournalTotals);
    tr.querySelector("[data-remove-journal-line]").onclick = () => {
      if (document.querySelectorAll("[data-journal-line]").length <= 2) return alert("A balanced journal needs at least two lines.");
      tr.remove();
      updateJournalTotals();
    };
  });
  $("addJournalLineBtn").onclick = () => {
    const body = $("journalLineBody");
    body.insertAdjacentHTML("beforeend", journalLineRowHtml({}, body.querySelectorAll("tr").length, accounts));
    wireBalancedJournalLines(accounts);
  };
  updateJournalTotals();
}

function readBalancedJournalLines(clean = true) {
  const lines = [...document.querySelectorAll("[data-journal-line]")].map((tr) => {
    const read = (field) => tr.querySelector(`[data-journal-line-field="${field}"]`)?.value?.trim() || "";
    return { id: tr.dataset.journalLineId || null, account: read("account"), description: read("description"), debit: Number(read("debit") || 0), credit: Number(read("credit") || 0) };
  });
  return clean ? lines.filter((line) => line.account || line.description || line.debit || line.credit) : lines;
}

async function openBalancedJournalModal(data = null, editGroup = null, prefillGroup = null) {
  const [coaRows, customers, vendors, workOrders, assets, outsideFleet, locations] = await Promise.all([
    data?.coa?.length ? Promise.resolve(data.coa) : getAll("chart_of_accounts"),
    getAll("customers"),
    getAll("vendors"),
    getAll("work_orders").catch(() => []),
    getAll("assets").catch(() => []),
    getAll("outside_customer_fleet").catch(() => []),
    getAll("locations").catch(() => []),
  ]);
  const coa = coaRows || [];
  const journalWorkOrders = (workOrders || []).map((row) => ({
    ...row,
    wo_no: row.wo_no || row.work_order_no || row.number || "",
    asset_tag: row.asset_tag || row.asset_no || "",
    bill_to_customer: row.bill_to_customer || row.customer || "",
    jobsite_location: row.jobsite_location || row.jobsite || "",
    actual_location: row.actual_location || row.location || "",
    equipment_name: row.equipment_name || row.asset_name || row.description || "",
  }));
  productMeta.journalAccounts = coa;
  productMeta.accountingCustomers = customers || [];
  productMeta.accountingVendors = vendors || [];
  productMeta.accountingWorkOrders = journalWorkOrders;
  productMeta.workOrders = journalWorkOrders;
  productMeta.assets = assets || [];
  productMeta.outsideFleet = outsideFleet?.length ? outsideFleet : (productMeta.outsideFleet || []);
  productMeta.locations = (locations || []).map((row) => row.name || row.location || row.value).filter(Boolean);
  const accounts = journalAccountOptions(coa);
  const formGroup = editGroup || prefillGroup;
  const postingDate = editGroup?.posting_date || today();
  const reference = formGroup?.reference || await nextJournalReferencePreview(postingDate);
  const invoiceDate = formGroup?.invoice_date || postingDate || today();
  const editLines = formGroup?.lines?.length ? formGroup.lines.map((line) => prefillGroup ? { ...line, id: null } : line) : [{}, {}];
  $("modalTitle").textContent = editGroup ? `Edit balanced journal ${reference}` : prefillGroup ? `Correct and repost journal ${reference}` : "New balanced journal entry";
  $("modalBody").innerHTML = `
    <div class="form-grid">
      ${productInput("Posting date", "posting_date", postingDate, "date")}
      ${productInput("Invoice date", "invoice_date", invoiceDate, "date")}
      ${productInput("Journal reference", "reference", reference)}
      ${productInput("Bank reference", "bank_reference", formGroup?.bank_reference || "")}
      ${productSelect("Customer", "customer", (productMeta.accountingCustomers || []).map((row) => row.name).filter(Boolean), formGroup?.customer || "")}
      ${productSelect("Vendor", "vendor", (productMeta.accountingVendors || []).map((row) => row.name).filter(Boolean), formGroup?.vendor || "")}
      <div class="field"><label>Work Order #</label><input class="suggest-input" data-suggest-source="work_orders" data-product-field="work_order_no" value="${esc(formGroup?.work_order_no || "")}" placeholder="Type WO #, asset, customer, or status" autocomplete="off" inputmode="search"><small>Results appear in separate columns after you start typing.</small></div>
      <div class="field"><label>Jobsite</label><input class="suggest-input" data-suggest-source="locations" data-product-field="jobsite" value="${esc(formGroup?.jobsite || "")}" placeholder="Type jobsite, project, or equipment location" autocomplete="off" inputmode="search"><div class="actions table-actions"><button class="rowbtn" type="button" id="createJournalJobsiteBtn">+ Create new jobsite</button></div><small>Results appear in separate columns after you start typing. New jobsites are added to the shared location list.</small></div>
      <div class="field"><label>Equipment</label><input class="suggest-input" data-suggest-source="equipment" data-equipment-source="master" data-product-field="equipment" value="${esc(formGroup?.equipment || "")}" placeholder="Type asset #, equipment, plate, serial, VIN, type, or location" autocomplete="off" inputmode="search"><small>Results appear in separate columns after you start typing.</small></div>
      <div class="field wide"><label>Journal description</label><textarea data-product-field="description" required>${esc(formGroup?.description || "")}</textarea></div>
      <div class="field wide"><label>Debit and credit lines</label><div class="table-wrap"><table class="line-table"><thead><tr><th>Chart of Account</th><th>Description</th><th>Debit</th><th>Credit</th><th></th></tr></thead><tbody id="journalLineBody">${editLines.map((line, index) => journalLineRowHtml(line, index, accounts)).join("")}</tbody></table></div><div class="actions table-actions"><button type="button" id="addJournalLineBtn">Add line</button></div></div>
    </div>
    <div class="journal-total-bar"><div><span>Total Debit</span><strong id="journalDebitTotal">$0.00</strong></div><div><span>Total Credit</span><strong id="journalCreditTotal">$0.00</strong></div><div><span>Difference</span><strong id="journalDifference">$0.00</strong></div></div>
    <p class="notice">${editGroup ? "This journal remains editable only while its accounting period is open and it has not been applied to an AP check/cash payment or an AR customer payment." : prefillGroup ? "The original journal was reversed and retained for audit history. Correct these values, then save to repost the Direct AP entry." : "After posting, this journal may be edited only while its accounting period is open and it remains unsettled. Settled or closed-period journals require a reversal."}</p>`;
  $("modalSave").textContent = "Save and Close";
  $("modalSave").onclick = () => saveBalancedJournalModal(coa, { editGroup });
  document.getElementById("journalSaveOnlyBtn")?.remove();
  const saveOnlyButton = document.createElement("button");
  saveOnlyButton.id = "journalSaveOnlyBtn";
  saveOnlyButton.type = "button";
  saveOnlyButton.textContent = "Save";
  saveOnlyButton.title = "Post this balanced journal and keep Accounting open for the next entry.";
  saveOnlyButton.onclick = () => saveBalancedJournalModal(coa, { keepOpen: !editGroup, editGroup });
  $("modalSave").before(saveOnlyButton);
  $("modal").style.display = "flex";
  const postingDateInput = document.querySelector('[data-product-field="posting_date"]');
  const referenceInput = document.querySelector('[data-product-field="reference"]');
  if (referenceInput) {
    referenceInput.dataset.systemJournalReference = editGroup || prefillGroup ? "" : reference;
    if (editGroup) {
      referenceInput.readOnly = true;
      referenceInput.title = "The journal reference cannot be changed after posting.";
    }
  }
  if (!editGroup && !prefillGroup && postingDateInput && referenceInput) {
    postingDateInput.addEventListener("change", async () => {
      const priorSystemReference = referenceInput.dataset.systemJournalReference || "";
      const wasSystemGenerated = !referenceInput.value.trim() || referenceInput.value.trim() === priorSystemReference;
      if (!wasSystemGenerated) return;
      const nextReference = await nextJournalReferencePreview(postingDateInput.value || today());
      referenceInput.value = nextReference;
      referenceInput.dataset.systemJournalReference = nextReference;
    });
  }
  const workOrderInput = document.querySelector('[data-product-field="work_order_no"]');
  const jobsiteInput = document.querySelector('[data-product-field="jobsite"]');
  const equipmentInput = document.querySelector('[data-product-field="equipment"]');
  workOrderInput?.addEventListener("change", () => {
    const selected = resolveWorkOrderSuggestLookup(workOrderInput.value, workOrderInput);
    if (!selected) return;
    workOrderInput.value = selected.wo_no || workOrderInput.value;
    if (jobsiteInput && !jobsiteInput.value.trim()) {
      jobsiteInput.value = selected.jobsite_location || selected.jobsite || selected.actual_location || "";
    }
    if (equipmentInput && !equipmentInput.value.trim()) {
      equipmentInput.value = [selected.asset_tag || selected.asset_no, selected.equipment_name || selected.asset_name].filter(Boolean).join(" - ");
    }
  });
  equipmentInput?.addEventListener("change", () => {
    const selected = resolveEquipmentSuggestLookup(equipmentInput.value, equipmentInput);
    if (!selected) return;
    equipmentInput.value = [selected.assetTag, selected.name].filter(Boolean).join(" - ");
  });
  $("createJournalJobsiteBtn").onclick = quickCreateBalancedJournalJobsite;
  wireBalancedJournalLines(accounts);
}

async function quickCreateBalancedJournalJobsite() {
  const field = document.querySelector('[data-product-field="jobsite"]');
  const proposed = prompt("Enter the new jobsite name:", String(field?.value || "").trim());
  if (proposed === null) return;
  const name = String(proposed || "").trim();
  if (!name) return alert("Jobsite name is required.");
  const existing = (productMeta.locations || []).find((location) => String(location || "").trim().toLowerCase() === name.toLowerCase());
  if (existing) {
    if (field) field.value = existing;
    hideSuggestMenu();
    return;
  }
  try {
    const { error } = await supabase.from("asset_locations").upsert({ name }, { onConflict: "name" });
    if (error) throw error;
    await supabase.from("locations").upsert({ name }, { onConflict: "name" });
    productMeta.locations = [...new Set([...(productMeta.locations || []), name])]
      .sort((a, b) => String(a).localeCompare(String(b), undefined, { numeric: true, sensitivity: "base" }));
    if (field) {
      field.value = name;
      field.dispatchEvent(new Event("change", { bubbles: true }));
    }
    hideSuggestMenu();
    alert(`${name} was created and selected.`);
  } catch (error) {
    alert(error.message || error);
  }
}

function manualJournalHistoryGroups(gl = []) {
  const groups = new Map();
  (gl || []).filter((row) => /manual journal/i.test(row.source || "")).forEach((raw) => {
    const row = normalizeGlRow(raw);
    const reference = String(row.reference || "").trim();
    if (!reference) return;
    if (!groups.has(reference)) groups.set(reference, { reference, posting_date: row.posting_date, invoice_date: row.invoice_date, bank_reference: row.bank_reference, customer: row.customer, vendor: row.vendor, work_order_no: row.work_order_no, jobsite: row.jobsite, equipment: row.equipment, description: row.description, status: row.status, source: row.source, debit: 0, credit: 0, lines: [] });
    const group = groups.get(reference);
    group.posting_date = group.posting_date || row.posting_date;
    group.invoice_date = group.invoice_date || row.invoice_date;
    group.bank_reference = group.bank_reference || row.bank_reference;
    group.customer = group.customer || row.customer;
    group.vendor = group.vendor || row.vendor;
    group.work_order_no = group.work_order_no || row.work_order_no;
    group.jobsite = group.jobsite || row.jobsite;
    group.equipment = group.equipment || row.equipment;
    group.description = group.description || row.description;
    if (/reversed|void/i.test(row.status || "")) group.status = row.status;
    group.debit += Number(row.debit || 0);
    group.credit += Number(row.credit || 0);
    group.lines.push(row);
  });
  return [...groups.values()].sort((a, b) => String(b.posting_date || "").localeCompare(String(a.posting_date || "")) || b.reference.localeCompare(a.reference, undefined, { numeric: true }));
}

function journalReferenceIsListed(value, reference) {
  const wanted = String(reference || "").trim().toLowerCase();
  if (!wanted) return false;
  return String(value || "").split(/[;,|\n]+/).map((part) => part.trim().toLowerCase()).includes(wanted);
}

async function balancedJournalEditEligibility(group) {
  if (!group?.reference) return { allowed: false, reason: "Journal reference is missing." };
  if (/reversed|void|cancel/i.test(group.status || "")) return { allowed: false, reason: "Reversed or voided journals are read-only." };
  if (isLockedAccountingDate(group.posting_date) || isLockedAccountingDate(group.invoice_date)) return { allowed: false, reason: "The posting or invoice date is in a closed accounting period." };
  const reference = String(group.reference).trim();
  const [payments, checkRuns, invoices, bankTransactions] = await Promise.all([
    getAll("customer_payments").catch(() => []),
    getAll("check_runs").catch(() => []),
    getAll("invoices").catch(() => []),
    getAll("bank_transactions").catch(() => []),
  ]);
  const active = (row) => !/void|reversed|cancel/i.test(row.status || "");
  if (payments.some((row) => active(row) && journalReferenceIsListed(row.invoice_no, reference))) return { allowed: false, reason: "This journal is tied to an AR receipt or customer payment." };
  if (checkRuns.some((row) => active(row) && (journalReferenceIsListed(row.invoice_no, reference) || journalReferenceIsListed(row.reference, reference)))) return { allowed: false, reason: "This journal is tied to an AP check run or cash payment." };
  if (bankTransactions.some((row) => active(row) && (journalReferenceIsListed(row.reference, reference) || journalReferenceIsListed(row.invoice_no, reference)))) return { allowed: false, reason: "This journal is tied to a posted bank or cash transaction." };
  if (invoices.some((row) => (String(row.invoice_no || "").trim() === reference || String(row.source_ref || "").trim() === reference) && /paid|written off|settled/i.test(row.status || ""))) return { allowed: false, reason: "The AR document created by this journal is already paid or settled." };
  return { allowed: true, reason: "Open period and not tied to a payment." };
}

async function openBalancedJournalHistoryModal(data = null) {
  const gl = data?.allGl?.length ? data.allGl : data?.gl?.length ? data.gl : await getAll("general_ledger");
  const groups = manualJournalHistoryGroups(gl);
  $("modalTitle").textContent = "Balanced journal history";
  const eligibility = new Map(await Promise.all(groups.map(async (group) => [group.reference, await balancedJournalEditEligibility(group)])));
  $("modalBody").innerHTML = `<p class="notice">Posted journals remain available for audit review. Edit is allowed only while the period is open and the journal has not been applied to an AP/AR payment.</p>
    <div class="table-wrap balanced-journal-history-scroll"><table><thead><tr><th>Posting Date</th><th>Invoice Date</th><th>Reference</th><th>Customer</th><th>Vendor</th><th>WO #</th><th>Jobsite</th><th>Equipment</th><th>Description</th><th>Debit</th><th>Credit</th><th>Status</th><th>Actions</th></tr></thead><tbody>${groups.length ? groups.map((group) => { const canEdit = eligibility.get(group.reference); return `<tr><td>${esc(formatDisplayDate(group.posting_date))}</td><td>${esc(formatDisplayDate(group.invoice_date))}</td><td>${esc(group.reference)}</td><td>${esc(group.customer || "")}</td><td>${esc(group.vendor || "")}</td><td>${esc(group.work_order_no || "")}</td><td>${esc(group.jobsite || "")}</td><td>${esc(group.equipment || "")}</td><td>${esc(group.description || "")}</td><td>${money(group.debit)}</td><td>${money(group.credit)}</td><td>${badge(group.status || "Posted")}</td><td><div class="rowactions"><button type="button" class="rowbtn" data-journal-history-view="${esc(group.reference)}">View</button>${canEdit?.allowed ? `<button type="button" class="rowbtn" data-journal-history-edit="${esc(group.reference)}">Edit</button>` : `<button type="button" class="rowbtn" disabled title="${esc(canEdit?.reason || "Read-only")}">Edit</button>`}</div></td></tr>`; }).join("") : '<tr><td colspan="13" class="empty">No balanced journals yet.</td></tr>'}</tbody></table></div>`;
  $("modalSave").textContent = "Close";
  $("modalSave").onclick = closeModal;
  $("modal").style.display = "flex";
  document.querySelectorAll("[data-journal-history-view]").forEach((button) => {
    button.onclick = () => openBalancedJournalHistoryDetail(groups.find((group) => group.reference === button.dataset.journalHistoryView), groups);
  });
  document.querySelectorAll("[data-journal-history-edit]").forEach((button) => {
    button.onclick = async () => {
      const group = groups.find((item) => item.reference === button.dataset.journalHistoryEdit);
      const current = await balancedJournalEditEligibility(group);
      if (!current.allowed) return alert(current.reason);
      await openBalancedJournalModal(data, group);
    };
  });
}

function openBalancedJournalHistoryDetail(group, groups = []) {
  if (!group) return;
  $("modalTitle").textContent = `Journal ${group.reference}`;
  $("modalBody").innerHTML = `<div class="form-grid">
      <div class="field"><label>Posting date</label><input value="${esc(formatDisplayDate(group.posting_date))}" readonly></div>
      <div class="field"><label>Invoice date</label><input value="${esc(formatDisplayDate(group.invoice_date))}" readonly></div>
      <div class="field"><label>Customer</label><input value="${esc(group.customer || "")}" readonly></div>
      <div class="field"><label>Vendor</label><input value="${esc(group.vendor || "")}" readonly></div>
      <div class="field"><label>Work Order #</label><input value="${esc(group.work_order_no || "")}" readonly></div>
      <div class="field"><label>Jobsite</label><input value="${esc(group.jobsite || "")}" readonly></div>
      <div class="field"><label>Equipment</label><input value="${esc(group.equipment || "")}" readonly></div>
      <div class="field wide"><label>Description</label><textarea readonly>${esc(group.description || "")}</textarea></div>
    </div>
    <div class="table-wrap"><table><thead><tr><th>Account</th><th>Line description</th><th>Debit</th><th>Credit</th><th>Source</th><th>Status</th></tr></thead><tbody>${group.lines.map((line) => `<tr><td>${esc(line.account)}</td><td>${esc(line.description)}</td><td>${line.debit ? money(line.debit) : ""}</td><td>${line.credit ? money(line.credit) : ""}</td><td>${esc(line.source)}</td><td>${badge(line.status)}</td></tr>`).join("")}</tbody><tfoot><tr><th colspan="2">Total</th><th>${money(group.debit)}</th><th>${money(group.credit)}</th><th colspan="2"></th></tr></tfoot></table></div>`;
  $("modalSave").textContent = "Back to history";
  $("modalSave").onclick = () => {
    const data = { allGl: groups.flatMap((item) => item.lines) };
    openBalancedJournalHistoryModal(data);
  };
}

async function saveBalancedJournalModal(coa = [], { keepOpen = false, editGroup = null } = {}) {
  const header = collectProductModalFields();
  const systemJournalReference = document.querySelector('[data-product-field="reference"]')?.dataset.systemJournalReference || "";
  const lines = readBalancedJournalLines();
  if (!header.posting_date || !header.invoice_date || !header.reference || !header.description) return alert("Posting date, invoice date, journal reference, and journal description are required.");
  if (isLockedAccountingDate(header.posting_date)) return alert("This journal date is inside the closed accounting period.");
  if (isLockedAccountingDate(header.invoice_date)) return alert("This invoice date is inside the closed accounting period.");
  if (lines.length < 2) return alert("A journal must contain at least two completed lines.");
  const activeAccounts = new Set(journalAccountOptions(coa).map((account) => account.toLowerCase()));
  const invalidAccount = lines.find((line) => !activeAccounts.has(String(line.account || "").toLowerCase()));
  if (invalidAccount) return alert(`Select ${invalidAccount.account || "every account"} from the active Chart of Accounts.`);
  const invalidAmount = lines.find((line) => line.debit < 0 || line.credit < 0 || (line.debit > 0 && line.credit > 0) || (!line.debit && !line.credit));
  if (invalidAmount) return alert("Each journal line must contain either a positive debit or a positive credit, but not both.");
  const apLines = lines.filter((line) => subledgerAccountMatches(line.account, "Accounts Payable"));
  const arLines = lines.filter((line) => subledgerAccountMatches(line.account, "Accounts Receivable"));
  const apCredit = apLines.reduce((sum, line) => sum + Number(line.credit || 0) - Number(line.debit || 0), 0);
  const arDebit = arLines.reduce((sum, line) => sum + Number(line.debit || 0) - Number(line.credit || 0), 0);
  const selectedVendor = (productMeta.accountingVendors || []).find((row) => String(row.name || "").trim().toLowerCase() === String(header.vendor || "").trim().toLowerCase());
  const selectedCustomer = (productMeta.accountingCustomers || []).find((row) => String(row.name || "").trim().toLowerCase() === String(header.customer || "").trim().toLowerCase());
  if (apLines.length && !selectedVendor) return alert("Select a vendor from Vendor Master when using Accounts Payable.");
  if (arLines.length && !selectedCustomer) return alert("Select a customer from Customer Master when using Accounts Receivable.");
  if (apLines.length && apCredit <= 0) return alert("A manual Accounts Payable journal must create a positive payable credit. Use Check Run, Write Off, or a reversal to reduce an existing payable.");
  if (arLines.length && arDebit <= 0) return alert("A manual Accounts Receivable journal must create a positive receivable debit. Use Receive Payment, Write Off, or a reversal to reduce an existing receivable.");
  try { assertBalancedLedgerRows(lines, `Journal ${header.reference}`); } catch (error) { return alert(error.message); }
  if (editGroup) {
    const eligibility = await balancedJournalEditEligibility(editGroup);
    if (!eligibility.allowed) return alert(`This journal can no longer be edited. ${eligibility.reason}`);
  }
  const existing = await getAll("general_ledger");
  if (!editGroup && existing.some((row) => String(row.reference || "").trim().toLowerCase() === String(header.reference).trim().toLowerCase() && !/reversed|void/i.test(row.status || ""))) return alert(`Journal reference ${header.reference} already exists.`);
  if (header.bank_reference && existing.some((row) => String(row.bank_reference || "").trim().toLowerCase() === String(header.bank_reference).trim().toLowerCase() && String(row.reference || "").trim().toLowerCase() !== String(header.reference).trim().toLowerCase() && !/reversed|void/i.test(row.status || ""))) return alert(`Bank reference ${header.bank_reference} is already in the General Ledger.`);
  const journalAmount = Math.max(lines.reduce((sum, line) => sum + line.debit, 0), lines.reduce((sum, line) => sum + line.credit, 0));
  const rows = lines.map((line) => ({
    ...(line.id ? { id: line.id } : {}),
    entry_date: header.posting_date,
    posting_date: header.posting_date,
    account: line.account,
    customer: header.customer || null,
    vendor: header.vendor || null,
    invoice_no: subledgerAccountMatches(line.account, "Accounts Payable") || subledgerAccountMatches(line.account, "Accounts Receivable") ? header.reference : null,
    invoice_date: header.invoice_date,
    due_date: subledgerAccountMatches(line.account, "Accounts Payable") || subledgerAccountMatches(line.account, "Accounts Receivable") ? header.invoice_date : null,
    description: line.description || header.description,
    reference: header.reference,
    bank_reference: header.bank_reference || null,
    work_order_no: header.work_order_no || null,
    jobsite: header.jobsite || null,
    equipment: header.equipment || null,
    debit: line.debit,
    credit: line.credit,
    source: "Manual Journal",
    status: "Posted",
  }));
  try {
    const linkedManualArInvoices = editGroup
      ? (await getAll("invoices").catch(() => [])).filter((invoice) => String(invoice.invoice_no || "").trim() === header.reference && /manual journal ar/i.test(`${invoice.type || ""} ${invoice.notes || ""}`))
      : [];
    if (arDebit > 0) {
      const invoices = await upsertMany("invoices", [{
        invoice_no: header.reference,
        invoice_date: header.invoice_date,
        due_date: header.invoice_date,
        customer: selectedCustomer.name,
        type: "Manual Journal AR",
        source_ref: header.reference,
        status: "Open",
        notes: `Manual Journal AR | ${header.description}`,
      }], "invoice_no");
      const invoice = invoices.find((row) => row.invoice_no === header.reference) || invoices[0];
      if (!invoice?.id) throw new Error("The AR invoice document could not be created.");
      const priorInvoiceLines = editGroup ? await getAll("invoice_lines").then((all) => all.filter((line) => line.invoice_id === invoice.id)).catch(() => []) : [];
      const invoiceLine = { ...(priorInvoiceLines[0]?.id ? { id: priorInvoiceLines[0].id } : {}), invoice_id: invoice.id, description: header.description, unit: "Journal", qty: 1, rate: arDebit };
      await upsertInvoiceLines([invoiceLine], "id");
      if (priorInvoiceLines.length > 1) await deleteWhereIn("invoice_lines", "id", priorInvoiceLines.slice(1).map((line) => line.id).filter(Boolean));
    } else if (linkedManualArInvoices.length) {
      for (const invoice of linkedManualArInvoices) {
        const result = await supabase.from("invoices").update({ status: "Void", notes: `Removed from edited journal ${header.reference} | ${header.description}` }).eq("id", invoice.id);
        if (result.error) throw result.error;
      }
    }
    await upsertManyWithOptionalColumns("general_ledger", rows, "id", ["bank_reference", "work_order_no", "jobsite", "equipment"]);
    if (editGroup) {
      const keptIds = new Set(lines.map((line) => line.id).filter(Boolean));
      await deleteWhereIn("general_ledger", "id", (editGroup.lines || []).map((line) => line.id).filter((id) => id && !keptIds.has(id)));
    }
    if (!editGroup && systemJournalReference && header.reference === systemJournalReference) {
      await incrementJournalSequence(header.posting_date, header.reference);
    }
    await writeAuditLog({ tableName: "general_ledger", action: editGroup ? "Updated balanced journal" : "Posted balanced journal", beforeData: editGroup || null, afterData: { ...header, amount: journalAmount, lines } });
    if (editGroup) {
      await renderAccountingView();
      const refreshedGl = await getAll("general_ledger");
      const refreshedGroup = manualJournalHistoryGroups(refreshedGl).find((group) => String(group.reference || "") === String(header.reference || ""));
      await openBalancedJournalModal({ coa }, refreshedGroup || editGroup);
      return;
    }
    closeModal();
    await renderAccountingView();
    if (keepOpen) await openBalancedJournalModal({ coa });
  } catch (error) {
    alert(error.message || error);
  }
}

async function reverseDirectApToEdit(data, reference) {
  const gl = data?.allGl?.length ? data.allGl : await getAll("general_ledger");
  const group = manualJournalHistoryGroups(gl).find((item) => String(item.reference || "") === String(reference || ""));
  if (!group) return alert(`Direct AP journal ${reference} was not found.`);
  const eligibility = await balancedJournalEditEligibility(group);
  if (!eligibility.allowed) return alert(`This Direct AP entry cannot be reversed for editing. ${eligibility.reason}`);
  const reversed = await reverseManualJournal(reference);
  if (!reversed) return;
  const prefill = {
    ...group,
    posting_date: today(),
    bank_reference: "",
    lines: (group.lines || []).map((line) => ({ ...line, id: null, posting_date: today(), entry_date: today() })),
  };
  await openBalancedJournalModal(data, null, prefill);
}

async function reverseManualJournal(reference) {
  const reason = prompt(`Reason for reversing journal ${reference}`);
  if (reason === null || !reason.trim()) return alert("Reversal reason is required.");
  const reversalDate = today();
  if (isLockedAccountingDate(reversalDate)) return alert("The reversal date is inside the closed accounting period.");
  const { data: rows, error } = await supabase.from("general_ledger").select("*").eq("reference", reference).eq("source", "Manual Journal");
  if (error) return alert(error.message);
  const activeRows = (rows || []).filter((row) => !/reversed|void/i.test(row.status || ""));
  if (!activeRows.length) return alert(`Journal ${reference} is already reversed or was not found.`);
  if (!confirm(`Reverse all ${activeRows.length} line(s) of journal ${reference}?`)) return;
  const reversalReference = `REV-${reference}`;
  const reversalRows = activeRows.map((row) => ({
    entry_date: reversalDate,
    posting_date: reversalDate,
    account: row.account,
    customer: row.customer,
    vendor: row.vendor,
    description: `Reversal of ${reference}: ${reason.trim()}`,
    reference: reversalReference,
    bank_reference: row.bank_reference || null,
    work_order_no: row.work_order_no || null,
    jobsite: row.jobsite || null,
    equipment: row.equipment || null,
    debit: Number(row.credit || 0),
    credit: Number(row.debit || 0),
    source: "Manual Journal Reversal",
    status: "Posted",
  }));
  try {
    assertBalancedLedgerRows(reversalRows, `Reversal ${reversalReference}`);
    const existing = await getAll("general_ledger");
    if (existing.some((row) => row.reference === reversalReference && !/void/i.test(row.status || ""))) return alert(`${reversalReference} already exists.`);
    await upsertManyWithOptionalColumns("general_ledger", reversalRows, "id", ["bank_reference", "work_order_no", "jobsite", "equipment"]);
    await supabase.from("general_ledger").update({ status: "Reversed" }).eq("reference", reference).eq("source", "Manual Journal");
    await writeAuditLog({ tableName: "general_ledger", action: "Reversed manual journal", beforeData: { reference, lines: activeRows }, afterData: { reference: reversalReference, reason: reason.trim(), lines: reversalRows } });
    await renderAccountingView();
    return true;
  } catch (reverseError) {
    alert(reverseError.message || reverseError);
    return false;
  }
}

function accountingGlBalance(data, accountPattern) {
  return (data.gl || []).filter((row) => accountPattern.test(row.account || "")).reduce((sum, row) => sum + Number(row.debit || 0) - Number(row.credit || 0), 0);
}

function periodCloseChecks(data) {
  const tb = trialBalanceRows(data);
  const tbDebit = tb.reduce((sum, row) => sum + Number(row.debit || 0), 0);
  const tbCredit = tb.reduce((sum, row) => sum + Number(row.credit || 0), 0);
  const arDetail = accountsReceivableRows(data).reduce((sum, row) => sum + Number(row.balance || 0), 0);
  const arGl = accountingGlBalance(data, /accounts receivable/i);
  const apDetail = accountsPayableRows(data).filter((row) => !/paid|void|reversed/i.test(`${row.payment || ""} ${row.status || ""}`)).reduce((sum, row) => sum + Number(row.invoice_amount || row.ap || 0), 0);
  const apGl = -accountingGlBalance(data, /accounts payable|parts accrual/i);
  const inventoryGl = accountingGlBalance(data, /parts inventory/i);
  const unmatchedBank = (data.bankRows || []).filter((row) => /unmatched|review/i.test(row.status || "")).length;
  const unmatchedPo = (data.pos || []).filter((row) => /mismatch|review/i.test(`${row.match_status || ""} ${row.payment_status || ""}`)).length;
  const unposted = (data.gl || []).filter((row) => !/posted|reversed|void/i.test(row.status || "Posted")).length;
  return [
    { name: "Trial balance", ok: Math.abs(tbDebit - tbCredit) <= 0.005, detail: `Debit ${money(tbDebit)} | Credit ${money(tbCredit)} | Difference ${money(tbDebit - tbCredit)}` },
    { name: "Accounts Receivable", ok: Math.abs(arDetail - arGl) <= 0.005, detail: `Invoice detail ${money(arDetail)} | GL ${money(arGl)} | Difference ${money(arDetail - arGl)}` },
    { name: "Accounts Payable", ok: Math.abs(apDetail - apGl) <= 0.005, detail: `Vendor detail ${money(apDetail)} | GL ${money(apGl)} | Difference ${money(apDetail - apGl)}` },
    { name: "Parts Inventory", ok: Math.abs(Number(data.summary.inventory || 0) - inventoryGl) <= 0.005, detail: `Product valuation ${money(data.summary.inventory)} | GL ${money(inventoryGl)} | Difference ${money(Number(data.summary.inventory || 0) - inventoryGl)}` },
    { name: "Bank reconciliation", ok: unmatchedBank === 0, detail: `${unmatchedBank} unmatched or review item(s)` },
    { name: "PO / AP matching", ok: unmatchedPo === 0, detail: `${unmatchedPo} mismatch or review PO(s)` },
    { name: "Unposted journals", ok: unposted === 0, detail: `${unposted} ledger row(s) not posted/reversed/void` },
  ];
}

async function accountingControlData(asOf = today()) {
  const [gl, coa, invoices, invoiceLines, payments, pos, poLines, receipts, salesOrders, salesLines, bankRows, products, movements] = await Promise.all([
    getAll("general_ledger"), getAll("chart_of_accounts"), getAll("invoices"), getAll("invoice_lines"), getAll("customer_payments"), getAll("purchase_orders"), getAll("purchase_order_lines"), getAll("goods_receipts"), getAll("sales_orders"), getAll("sales_order_lines"), getAll("bank_transactions"), getAll("products"), getAll("stock_movements"),
  ]);
  return buildAccountingData({ gl, coa, invoices, invoiceLines, payments, pos, poLines, receipts, salesOrders, salesLines, bankRows, products, movements, reportFrom: "", reportTo: asOf, reportTab: "tb" });
}

async function openTransactionPostingAudit() {
  $("modalTitle").textContent = "Transaction posting audit";
  $("modalBody").innerHTML = `<div class="empty">Checking operational documents against the General Ledger...</div>`;
  $("modalSave").textContent = "Close";
  $("modalSave").onclick = () => closeModal(true);
  $("modalCancel").textContent = "Close";
  $("modal").style.display = "flex";
  try {
    const [gl, invoices, receipts, salesOrders, payments] = await Promise.all([
      getAll("general_ledger"), getAll("invoices"), getAll("goods_receipts"), getAll("sales_orders"), getAll("customer_payments"),
    ]);
    const activeGl = gl.filter((row) => !/reversed|void/i.test(row.status || ""));
    const groups = new Map();
    activeGl.forEach((row) => {
      const key = `${row.source || ""}|${row.reference || ""}`;
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push(row);
    });
    const findings = [];
    groups.forEach((rows, key) => {
      const debit = rows.reduce((sum, row) => sum + Number(row.debit || 0), 0);
      const credit = rows.reduce((sum, row) => sum + Number(row.credit || 0), 0);
      if (Math.abs(debit - credit) > 0.005) findings.push({ type: "Unbalanced GL", reference: key, detail: `Debit ${money(debit)} | Credit ${money(credit)} | Difference ${money(debit - credit)}` });
    });
    invoices.filter((row) => !/void|reversed/i.test(row.status || "")).forEach((invoice) => {
      if (!activeGl.some((row) => row.reference === invoice.invoice_no && row.source === "Invoice")) findings.push({ type: "Missing invoice posting", reference: invoice.invoice_no, detail: `${invoice.customer || ""} | ${invoice.type || "Invoice"}` });
    });
    receipts.filter((row) => !/void|reverse|cancel/i.test(row.status || "")).forEach((receipt) => {
      if (!activeGl.some((row) => row.reference === receipt.gr_no && row.source === "Goods Receipt")) findings.push({ type: "Missing goods-receipt posting", reference: receipt.gr_no, detail: `${receipt.po_no || ""} | ${receipt.sku || ""}` });
    });
    salesOrders.filter((row) => /issued|delivered|invoiced|fulfilled/i.test(`${row.status || ""} ${row.fulfillment_stage || ""}`) && !/void|reverse|cancel/i.test(row.status || "")).forEach((order) => {
      if (!activeGl.some((row) => row.reference === order.order_no && /Sales Order|Sales Fulfillment/.test(row.source || ""))) findings.push({ type: "Missing sales-order posting", reference: order.order_no, detail: `${order.customer || ""} | ${order.status || ""}` });
    });
    payments.filter((row) => !/void|reverse|cancel/i.test(row.status || "")).forEach((payment) => {
      if (!activeGl.some((row) => row.reference === payment.receipt_no && row.source === "Customer Payment")) findings.push({ type: "Missing customer-payment posting", reference: payment.receipt_no, detail: `${payment.customer || ""} | ${money(payment.amount)}` });
    });
    const summary = findings.length ? `${findings.length} possible posting exception${findings.length === 1 ? "" : "s"} found. Review the source document before posting any correction.` : "No missing or unbalanced postings were detected for invoices, goods receipts, issued sales orders, customer payments, or existing GL reference groups.";
    $("modalBody").innerHTML = `<div class="notice"><strong>${esc(summary)}</strong><br>This is a control report only. It does not create, change, or delete accounting entries.</div>${findings.length ? `<div class="table-wrap"><table><thead><tr><th>Exception</th><th>Reference</th><th>Details</th></tr></thead><tbody>${findings.map((finding) => `<tr><td>${esc(finding.type)}</td><td>${esc(finding.reference)}</td><td>${esc(finding.detail)}</td></tr>`).join("")}</tbody></table></div>` : ""}`;
  } catch (error) {
    $("modalBody").innerHTML = `<div class="notice"><strong>Audit could not finish.</strong><br>${esc(error.message || error)}</div>`;
  }
}

function openPeriodCloseChecklist(data) {
  const checks = periodCloseChecks(data);
  const ready = checks.every((check) => check.ok);
  $("modalTitle").textContent = "Accounting period-close checklist";
  $("modalBody").innerHTML = `<div class="notice"><strong>${ready ? "Ready for accounting review" : "Period close is blocked"}</strong><br>${ready ? "All automated checks passed. Accounting should still review supporting documents before closing." : "Resolve every failed control before changing the closed-through date."}</div><div class="control-checklist">${checks.map((check) => `<div class="control-check ${check.ok ? "good" : "bad"}"><strong>${check.ok ? "✓" : "!"}</strong><div><strong>${esc(check.name)}</strong><span>${esc(check.detail)}</span></div></div>`).join("")}</div>`;
  $("modalSave").textContent = ready ? "Open Period Settings" : "Close";
  $("modalSave").onclick = () => { closeModal(true); if (ready) loadView("settings"); };
  $("modalCancel").textContent = "Close";
  $("modal").style.display = "flex";
}

