async function readBeginningDetailRows(file, preferredSheet) {
  const name = file.name.toLowerCase();
  if (name.endsWith(".csv")) return rowsFromAnyDetectedHeader(parseCsvMatrix(await file.text()), beginningDetailHeaderCandidates(preferredSheet));
  if (name.endsWith(".xlsx") || name.endsWith(".xls")) {
    try {
      const XLSX = await import("https://cdn.sheetjs.com/xlsx-0.20.3/package/xlsx.mjs");
      const workbook = XLSX.read(await file.arrayBuffer(), { type: "array" });
      const sheet = workbook.Sheets[preferredSheet] || workbook.Sheets[workbook.SheetNames[0]];
      return sheetToRowsWithDetectedHeader(XLSX, sheet, beginningDetailHeaderCandidates(preferredSheet));
    } catch (error) {
      throw new Error("Excel upload needs internet access to load the Excel reader. You can also save the template as CSV and upload that file.");
    }
  }
  throw new Error("Upload the detail template as .xlsx, .xls, or .csv.");
}

function beginningDetailHeaderCandidates(preferredSheet = "") {
  const common = ["name", "payee", "invoice #", "invoice no", "invoice number", "invoice date", "due date", "amount", "invoice amount", "invoice total", "amount due", "total due", "net amount", "balance", "balance due", "open balance", "current balance", "remaining balance", "debit", "credit", "po #", "po no", "work order #", "jobsite", "equipment", "description of parts"];
  return /ar/i.test(preferredSheet)
    ? common.concat(["customer", "customer name", "customer ref", "customer reference"])
    : common.concat(["vendor", "vendor name", "supplier", "vendor ref", "vendor reference"]);
}

function beginningDetailAmount(row, side = "debit") {
  const get = (...keys) => keys.map((key) => row[key]).find((value) => String(value ?? "").trim() !== "") ?? "";
  const debit = nullableNumber(get("debit", "debit_balance"));
  const credit = nullableNumber(get("credit", "credit_balance"));
  if (debit != null || credit != null) {
    const debitValue = Math.abs(Number(debit || 0));
    const creditValue = Math.abs(Number(credit || 0));
    return side === "credit" ? creditValue - debitValue : debitValue - creditValue;
  }
  const direct = nullableNumber(get("amount", "invoice_amount", "invoice_total", "total_amount", "amount_due", "total_due", "net_amount", "balance", "open_balance", "balance_due", "remaining_balance", "open_invoice_amount", "current_balance", "unpaid_balance", "ar_balance", "ap_balance", "receivable", "payable"));
  if (direct != null) return direct;
  if (side === "credit") {
    if (credit != null) return credit;
    if (debit != null) return -Math.abs(debit);
    return 0;
  }
  if (debit != null) return debit;
  if (credit != null) return -Math.abs(credit);
  const amountKey = /(amount|balance|total|due|open|current|debit|credit|receivable|payable|unpaid|net)/i;
  const nonAmountKey = /(date|invoice_no|invoice_number|po_no|wo_no|reference|source|customer|vendor|name|terms|address|status|phone|email)/i;
  const candidates = Object.entries(row || {})
    .filter(([key]) => amountKey.test(key) && !nonAmountKey.test(key))
    .map(([, value]) => nullableNumber(value))
    .filter((value) => value != null && Number.isFinite(value) && Math.abs(value) > 0)
    .map((value) => value);
  if (candidates.length) return candidates.reduce((best, value) => Math.abs(value) > Math.abs(best) ? value : best, 0);
  return 0;
}

function beginningApRowToRecord(row) {
  const get = (...keys) => keys.map((key) => row[key]).find((value) => String(value ?? "").trim() !== "") ?? "";
  const vendor = String(get("vendor", "vendor_name", "supplier", "payee", "name")).trim();
  const invoiceNo = String(get("invoice_no", "vendor_invoice_no", "invoice")).trim();
  const invoiceDate = excelDateToIso(get("invoice_date", "vendor_invoice_date", "date")) || today();
  const amount = beginningDetailAmount(row, "credit") || 0;
  const suppliedPo = String(get("po_no", "reference", "ref")).trim();
  const poNo = suppliedPo && invoiceNo ? `${suppliedPo}-${invoiceNo}` : suppliedPo || `BBAP-${invoiceNo || vendor.replace(/\W+/g, "").slice(0, 10) || Date.now()}`;
  return {
    po_no: poNo,
    vendor,
    vendor_ref: String(get("vendor_ref", "vendor_reference")).trim() || `V-BB-${vendor.replace(/\W+/g, "").slice(0, 12) || "AP"}`,
    po_date: invoiceDate,
    expected_date: excelDateToIso(get("due_date")) || invoiceDate,
    payment_terms: String(get("terms", "payment_terms")).trim() || "Net 30",
    address: String(get("address", "vendor_address")).trim(),
    incoterm: String(get("incoterm")).trim() || null,
    vendor_invoice_no: invoiceNo || poNo,
    vendor_invoice_date: invoiceDate,
    due_date: excelDateToIso(get("due_date")) || invoiceDate,
    vendor_invoice_amount: amount,
    posting_date: invoiceDate,
    match_status: "Matched",
    payment_status: String(get("payment_status")).trim() || "Ready to Pay",
    status: "Beginning AP",
    notes: [String(get("notes", "description")).trim(), suppliedPo && suppliedPo !== poNo ? `Original PO: ${suppliedPo}` : "", "Beginning AP detail"].filter(Boolean).join("\n"),
  };
}

function consolidateBeginningApRecords(rows = []) {
  const grouped = new Map();
  rows.forEach((row, index) => {
    const conflictKey = String(row.po_no || `BBAP-ROW-${index + 1}`).trim().toLowerCase();
    if (!grouped.has(conflictKey)) {
      grouped.set(conflictKey, { ...row, vendor_invoice_amount: Number(row.vendor_invoice_amount || 0) });
      return;
    }
    const current = grouped.get(conflictKey);
    current.vendor_invoice_amount = Number(current.vendor_invoice_amount || 0) + Number(row.vendor_invoice_amount || 0);
    const notes = [...new Set(`${current.notes || ""}\n${row.notes || ""}`.split("\n").map((note) => note.trim()).filter(Boolean))];
    current.notes = notes.join("\n");
    if (!current.address && row.address) current.address = row.address;
    if (!current.vendor_ref && row.vendor_ref) current.vendor_ref = row.vendor_ref;
    if (!current.due_date && row.due_date) current.due_date = row.due_date;
  });
  return [...grouped.values()];
}

function beginningArRowToRecord(row) {
  const get = (...keys) => keys.map((key) => row[key]).find((value) => String(value ?? "").trim() !== "") ?? "";
  const customer = String(get("customer", "customer_name", "company_name", "payee", "name")).trim();
  const invoiceNo = String(get("invoice_no", "invoice", "reference")).trim() || `BBAR-${customer.replace(/\W+/g, "").slice(0, 10) || Date.now()}`;
  const invoiceDate = excelDateToIso(get("invoice_date", "date")) || today();
  return {
    invoice_no: invoiceNo,
    invoice_date: invoiceDate,
    due_date: excelDateToIso(get("due_date")) || invoiceDate,
    customer,
    customer_ref: String(get("customer_ref", "customer_reference")).trim() || `C-BB-${customer.replace(/\W+/g, "").slice(0, 12) || "AR"}`,
    terms: String(get("terms", "payment_terms")).trim() || "Net 30",
    address: String(get("address", "customer_address")).trim(),
    type: "Beginning AR",
    source_ref: String(get("source_ref", "customer_po", "po_no")).trim() || "Beginning Balance",
    status: String(get("status")).trim() || "Open",
    description: String(get("description", "notes")).trim() || "Beginning AR detail",
    amount: beginningDetailAmount(row, "debit") || 0,
    notes: "Beginning AR detail",
  };
}

async function replaceBeginningApDetail(payables, postingDate) {
  const existing = (await getAll("purchase_orders")).filter((row) => /beginning ap/i.test(row.status || ""));
  const rows = payables.map((row, index) => {
    // vendor_ref and address belong to Vendor Master, not purchase_orders.
    const { vendor_ref, address, ...purchaseOrderFields } = row;
    return {
      ...purchaseOrderFields,
      po_no: row.po_no || `BBAP-${postingDate}-${index + 1}`,
      po_date: row.po_date || postingDate,
      posting_date: row.posting_date || postingDate,
      jobsite_project: "Beginning Balance",
      currency_code: "USD",
      exchange_rate: 1,
      freight_amount: 0,
      landed_cost_enabled: false,
      landed_cost_method: "By Value",
      duty_amount: 0,
      other_landed_cost_amount: 0,
    };
  });
  await upsertManyWithOptionalColumns("purchase_orders", rows, "po_no", ["posting_date", "payment_terms", "incoterm"], "Some AP detail fields were skipped because the database schema needs the latest purchasing update.");
  const retainedPoNos = new Set(rows.map((row) => row.po_no));
  const obsoleteIds = existing.filter((row) => !retainedPoNos.has(row.po_no)).map((row) => row.id).filter(Boolean);
  if (obsoleteIds.length) {
    const { error } = await supabase.from("purchase_orders").delete().in("id", obsoleteIds);
    if (error) throw error;
  }
}

async function replaceBeginningArDetail(receivables, postingDate) {
  const existing = await getAll("invoices");
  const uploadInvoiceNos = new Set(receivables.map((row, index) => row.invoice_no || `BBAR-${postingDate}-${index + 1}`).filter(Boolean));
  const old = existing.filter((row) =>
    /beginning ar/i.test(`${row.type || ""} ${row.notes || ""}`) ||
    (uploadInvoiceNos.has(row.invoice_no) && /beginning balance/i.test(`${row.source_ref || ""} ${row.notes || ""}`))
  );
  if (old.length) {
    await supabase.from("invoice_lines").delete().in("invoice_id", old.map((row) => row.id));
    await supabase.from("invoices").delete().in("id", old.map((row) => row.id));
  }
  const invoiceRows = [];
  const seenInvoiceNos = new Set();
  receivables.forEach((row, index) => {
    const invoiceNo = row.invoice_no || `BBAR-${postingDate}-${index + 1}`;
    row.invoice_no = invoiceNo;
    if (seenInvoiceNos.has(invoiceNo)) return;
    seenInvoiceNos.add(invoiceNo);
    invoiceRows.push({
      invoice_no: invoiceNo,
      invoice_date: row.invoice_date || postingDate,
      due_date: row.due_date || row.invoice_date || postingDate,
      customer: row.customer,
      type: "Beginning AR",
      source_ref: row.source_ref || "Beginning Balance",
      status: row.status || "Open",
      notes: row.notes || "Beginning AR detail",
    });
  });
  const invoices = await upsertMany("invoices", invoiceRows, "invoice_no");
  const byNo = new Map(invoices.map((inv) => [inv.invoice_no, inv]));
  const invoiceIds = invoices.map((inv) => inv.id).filter(Boolean);
  if (invoiceIds.length) await supabase.from("invoice_lines").delete().in("invoice_id", invoiceIds);
  const lines = receivables.map((row) => {
    const invoice = byNo.get(row.invoice_no);
    return invoice ? { invoice_id: invoice.id, description: row.description || "Beginning AR detail", unit: "Balance", qty: 1, rate: Number(row.amount || 0) } : null;
  }).filter(Boolean);
  if (lines.length) await upsertInvoiceLines(lines, "id");
}

async function beginningSubledgerGlBalance(accountName, postingDate, normalSide) {
  const rows = await getAll("general_ledger");
  return rows
    .filter((row) => String(row.posting_date || row.entry_date || "").slice(0, 10) <= postingDate)
    .filter((row) => subledgerAccountMatches(row.account, accountName))
    .filter((row) => !/void|reversed/i.test(row.status || ""))
    .reduce((sum, row) => sum + (normalSide === "credit" ? Number(row.credit || 0) - Number(row.debit || 0) : Number(row.debit || 0) - Number(row.credit || 0)), 0);
}

async function readTrialBalanceRows(file) {
  const name = file.name.toLowerCase();
  if (name.endsWith(".csv")) return rowsFromDetectedHeader(parseCsvMatrix(await file.text()));
  if (name.endsWith(".xlsx") || name.endsWith(".xls")) {
    try {
      const XLSX = await import("https://cdn.sheetjs.com/xlsx-0.20.3/package/xlsx.mjs");
      const workbook = XLSX.read(await file.arrayBuffer(), { type: "array" });
      const sheet = workbook.Sheets["Trial Balance Upload"] || workbook.Sheets[workbook.SheetNames[0]];
      const matrix = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: "" });
      return rowsFromDetectedHeader(matrix);
    } catch (error) {
      throw new Error("Excel upload needs internet access to load the Excel reader. You can also save the template as CSV and upload that file.");
    }
  }
  throw new Error("Upload the Trial Balance template as .xlsx, .xls, or .csv.");
}

function rowsFromDetectedHeader(matrix) {
  return rowsFromAnyDetectedHeader(matrix, ["account", "account code", "debit", "credit", "debit balance", "credit balance"], 2);
}

function rowsFromAnyDetectedHeader(matrix, headerCandidates = [], minimumMatches = 1) {
  const rows = (matrix || []).filter((row) => Array.isArray(row) && row.some((cell) => String(cell ?? "").trim() !== ""));
  const candidates = new Set(headerCandidates.map(normalizeHeaderKey).filter(Boolean));
  const scored = rows.map((row, index) => {
    const headers = row.map(normalizeHeaderKey);
    const matches = headers.filter((header) => header && (!candidates.size || candidates.has(header))).length;
    const knownHeaders = headers.filter((header) => header && commonUploadHeaders().has(header)).length;
    return { index, score: matches || knownHeaders, knownHeaders };
  });
  const best = scored
    .filter((item) => item.score >= minimumMatches || item.knownHeaders >= Math.max(2, minimumMatches))
    .sort((a, b) => b.score - a.score || b.knownHeaders - a.knownHeaders || a.index - b.index)[0];
  if (!best) return [];
  const headers = rows[best.index].map(normalizeHeaderKey);
  return rows.slice(best.index + 1)
    .map((row) => {
      const item = {};
      headers.forEach((header, index) => {
        if (header) item[header] = row[index] ?? "";
      });
      return item;
    })
    .map(normalizeAssetTemplateRow)
    .filter((row) => Object.values(row).some((value) => String(value ?? "").trim() !== ""));
}

function commonUploadHeaders() {
  return new Set([
    "date", "posting_date", "transaction_date", "posted_date", "account_code", "account", "report_group", "type", "normal_balance", "debit", "credit",
    "vendor", "customer", "invoice_no", "invoice_date", "due_date", "amount", "po_no", "wo_no", "jobsite", "equipment", "description",
    "sku", "product_name", "category", "unit", "warehouse", "bin_shelf", "qty", "cost", "selling_price", "markup_percent", "source_vendor",
    "asset_tag", "location", "scanned_date", "last_update_date", "email", "phone", "address", "terms", "tax_id", "status",
  ]);
}

function normalizeTemplateHeader(value) {
  return String(value || "")
    .trim()
    .toLowerCase()
    .replace(/^\ufeff/, "")
    .replace(/[#/()]+/g, " ")
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");
}

function trialBalanceRowToLedger(row) {
  const get = (...keys) => keys.map((key) => row[key]).find((value) => String(value ?? "").trim() !== "") ?? "";
  const accountCode = String(get("account_code", "code", "new_code")).trim();
  const account = String(get("account", "account_name", "name")).trim() || accountCode;
  const postingDate = excelDateToIso(get("posting_date", "date", "as_of_date")) || today();
  const debit = nullableNumber(get("debit", "debit_balance")) || 0;
  const credit = nullableNumber(get("credit", "credit_balance")) || 0;
  const reference = String(get("reference", "ref")).trim() || `TB-${postingDate}-${accountCode || account}`;
  return {
    entry_date: postingDate,
    posting_date: postingDate,
    account,
    customer: String(get("customer")).trim() || null,
    vendor: String(get("vendor")).trim() || null,
    invoice_no: String(get("invoice_no", "invoice")).trim() || null,
    invoice_date: excelDateToIso(get("invoice_date")) || null,
    due_date: excelDateToIso(get("due_date")) || null,
    mechanic: String(get("mechanic")).trim() || null,
    asset: String(get("asset", "asset_tag")).trim() || null,
    description: String(get("description")).trim() || "Beginning balance from Trial Balance upload",
    reference,
    debit,
    credit,
    source: "Trial Balance Upload",
    status: "Posted",
  };
}

async function ensureTrialBalanceAccounts(entries, rawRows) {
  const existing = await getAll("chart_of_accounts");
  const existingByName = new Set(existing.map((row) => row.account));
  const accountRows = [];
  entries.forEach((entry, index) => {
    if (existingByName.has(entry.account)) return;
    const row = rawRows[index] || {};
    const code = String(row.account_code || row.code || row.new_code || "").trim();
    const type = String(row.type || "").trim() || accountType(entry.account);
    accountRows.push({
      account_code: code || null,
      account: entry.account,
      report_group: String(row.report_group || row.report || "").trim() || statementGroup(type),
      type,
      normal_balance: String(row.normal_balance || "").trim() || normalBalance(type),
      notes: "Created from Trial Balance upload",
    });
    existingByName.add(entry.account);
  });
  if (accountRows.length) await upsertManyWithOptionalColumns("chart_of_accounts", accountRows, "account", ["account_code", "report_group"], "Some optional chart fields were skipped because the database needs the latest chart update.");
}

async function openPostApFromPoModal(data, poNo = "") {
  const [assets, outsideFleet, workOrders, assetLocations, locations] = await Promise.all([
    getAll("assets").catch(() => []),
    getAll("outside_customer_fleet").catch(() => []),
    getAll("work_orders").catch(() => []),
    getAll("asset_locations").catch(() => []),
    getAll("locations").catch(() => []),
  ]);
  productMeta.assets = assets;
  productMeta.outsideFleet = outsideFleet;
  productMeta.workOrders = workOrders;
  productMeta.locations = [...new Set([...assetLocations, ...locations].map((row) => row.name || row.location || row.value).filter(Boolean))];
  data.assets = assets;
  data.workOrders = workOrders;
  const pos = data.pos.filter((po) => !/cancel/i.test(po.status || ""));
  const po = pos.find((row) => row.po_no === poNo) || pos[0];
  const ap = po ? poApSummary(po) : {};
  const support = po ? poSupportDetails(data, po) : {};
  const ref = await nextRefPreview("ap", "AP-", "general_ledger", "reference");
  $("modalTitle").textContent = po ? `Post AP from ${po.po_no}` : "Post AP from PO";
  $("modalBody").innerHTML = `
    <div class="form-grid">
      ${productSelect("Purchase order", "po_no", pos.map((row) => `${row.po_no} | ${row.vendor} | ${money(poReceivedTotal(row) || poTotal(row))}`), po ? `${po.po_no} | ${po.vendor} | ${money(poReceivedTotal(po) || poTotal(po))}` : "")}
      ${productInput("AP posting #", "reference", ref)}
      ${productInput("Posting date", "posting_date", today(), "date")}
      ${productInput("Vendor invoice #", "vendor_invoice_no", ap.invoice_no || "")}
      ${productInput("Invoice date", "vendor_invoice_date", ap.invoice_date || po?.po_date || today(), "date")}
      ${productInput("Due date", "due_date", ap.due_date || po?.expected_date || today(), "date")}
      ${productInput("Invoice amount", "vendor_invoice_amount", ap.invoice_amount || poReceivedTotal(po || {}) || poTotal(po || {}), "number")}
      <div class="field"><label>Work Order # (optional)</label><input class="suggest-input" data-suggest-source="work_orders" data-product-field="support_wo_no" value="${esc(checkRunOptionalDisplay(support.wo_no))}" placeholder="Type or select WO #, asset, customer, or status" autocomplete="off" inputmode="search"><small>Type a work order number directly or select a matching row. Jobsite and Equipment fill automatically.</small></div>
      <div class="field"><label>Jobsite</label><input class="suggest-input" data-suggest-source="locations" data-product-field="support_jobsite" value="${esc(support.jobsite || "")}" placeholder="Select or type an available jobsite" autocomplete="off" inputmode="search"><small>Choose from Location Master, work-order jobsites, or equipment locations.</small></div>
      <div class="field"><label>Equipment</label><input class="suggest-input" data-suggest-source="equipment" data-equipment-source="master" data-product-field="support_equipment" value="${esc(support.equipment || "")}" placeholder="Select or type available equipment" autocomplete="off" inputmode="search"><small>Search available fleet and outside-customer equipment by asset #, name, plate, serial, VIN, type, or location.</small></div>
      ${productSelect("Match status", "match_status", ["Matched", "Mismatch", "Pending", "Awaiting Goods"], ap.match || "Matched")}
      ${productSelect("Payment status", "payment_status", ["Not Ready", "Ready to Pay", "Hold", "Paid"], ap.payment || "Ready to Pay")}
      ${productSelect("Document status", "status", ["Draft", "Partially Received", "Goods Received", "Matched", "Paid"], ap.status || "Matched")}
      <div class="field wide"><label>PO items purchased / received</label>${apPoLineTable(po)}</div>
      <div class="field wide"><label>Description of parts / items</label><textarea data-product-field="support_parts_description">${esc(support.parts_description || "")}</textarea></div>
      <div class="field wide"><label>Notes</label><textarea data-product-field="notes">${esc(po?.notes || "")}</textarea></div>
    </div>
    <p class="notice">Posting AP updates the PO, records the invoice fields, and creates clean debit/credit lines in General Ledger.</p>`;
  $("modalSave").onclick = () => savePostApFromPo(data);
  $("modal").style.display = "flex";
  const input = document.querySelector('[data-product-field="po_no"]');
  if (input) input.onchange = () => openPostApFromPoModal(data, parsePoNo(input.value));
  const workOrderInput = document.querySelector('[data-product-field="support_wo_no"]');
  const jobsiteInput = document.querySelector('[data-product-field="support_jobsite"]');
  const equipmentInput = document.querySelector('[data-product-field="support_equipment"]');
  if (workOrderInput) {
    const fillWorkOrderSupport = () => {
      const selected = resolveWorkOrderSuggestLookup(workOrderInput.value, workOrderInput);
      if (!selected) return;
      workOrderInput.value = selected.wo_no || workOrderInput.value;
      if (jobsiteInput) jobsiteInput.value = selected.jobsite_location || selected.jobsite || selected.actual_location || selected.location || "";
      if (equipmentInput) equipmentInput.value = supportEquipmentText(selected, assets) || [selected.asset_tag, selected.equipment_name || selected.asset_name].filter(Boolean).join(" | ");
    };
    workOrderInput.addEventListener("change", fillWorkOrderSupport);
    workOrderInput.addEventListener("blur", fillWorkOrderSupport);
  }
  if (equipmentInput) equipmentInput.onchange = () => {
    const selected = resolveEquipmentSuggestLookup(equipmentInput.value, equipmentInput);
    if (selected) equipmentInput.value = [selected.assetTag, selected.name].filter(Boolean).join(" | ");
  };
}

function parsePoNo(value) {
  return String(value || "").split("|")[0].trim();
}

function poSupportDetails(data, po, fallback = {}) {
  const rows = Array.isArray(po?._lines) ? po._lines : [];
  const receipts = activeReceipts(po || {});
  const workOrders = data?.workOrders || data?.work_orders || [];
  const assets = data?.assets || [];
  const woValues = uniqueTextList([
    fallback.wo_no,
    fallback.work_order_no,
    fallback.support_wo_no,
    po?.ap_support_wo_no,
    po?.wo_no,
    ...rows.map((line) => line.wo_no),
  ]).filter((value) => !/^n\/?a$/i.test(value));
  const wo = workOrders.find((row) => woValues.includes(row.wo_no));
  const poNo = fallback.po_no || po?.po_no || fallback.reference || "";
  const jobsite = fallback.jobsite || fallback.support_jobsite || po?.ap_support_jobsite || po?.jobsite_project || wo?.jobsite_location || wo?.location || "N/A";
  const equipment = fallback.equipment || fallback.support_equipment || po?.ap_support_equipment || supportEquipmentText(wo, assets) || "N/A";
  const parts = fallback.parts_description || fallback.support_parts_description || po?.ap_support_parts_description || supportPartsDescription(rows, receipts) || "N/A";
  return {
    wo_no: woValues.join(", ") || "N/A",
    po_no: poNo,
    jobsite,
    equipment,
    parts_description: parts,
  };
}

function supportPartsDescription(lines = [], receipts = []) {
  const lineText = (lines || []).map((line) => {
    const qty = Number(line.qty || 0);
    const unit = line.unit ? ` ${line.unit}` : "";
    const name = [line.sku, line.product_name].filter(Boolean).join(" - ");
    return name ? `${name}${qty ? ` (${qty}${unit})` : ""}` : "";
  });
  const receiptText = (receipts || []).map((gr) => {
    const qty = Number(gr.received_qty || 0);
    const name = [gr.sku, gr.product_name].filter(Boolean).join(" - ");
    return name ? `${name}${qty ? ` (${qty})` : ""}` : "";
  });
  // AP support must describe the vendor invoice being posted. When a PO is
  // partially received, the invoice covers the active receipts—not the full
  // ordered quantity that remains open on the PO.
  return uniqueTextList(receiptText.length ? receiptText : lineText).join("; ");
}

function supportEquipmentText(wo, assets = []) {
  if (!wo) return "";
  const assetKey = wo.asset_tag || wo.asset || wo.asset_no || "";
  const asset = assets.find((row) => [row.asset_tag, row.asset_no, row.name].filter(Boolean).includes(assetKey));
  const parts = [
    asset?.asset_tag || assetKey,
    asset?.name || wo.asset_name,
    asset?.make,
    asset?.model,
    asset?.vin_serial || asset?.serial_no || asset?.vin,
  ].filter(Boolean);
  return uniqueTextList(parts).join(" | ");
}

function uniqueTextList(values) {
  return [...new Set((values || []).map((value) => String(value || "").trim()).filter(Boolean))];
}

function apPoLineTable(po) {
  const heads = ["SKU", "Product", "Received", "Unit Cost", "Received Amount", "WO"];
  const lines = po?._lines || [];
  const receipts = activeReceipts(po);
  const receivedRows = receipts.map((gr) => {
    const line = lines.find((row) => (gr.product_id && row.product_id === gr.product_id) || (gr.sku && row.sku === gr.sku)) || {};
    const received = Number(gr.received_qty || 0);
    const amount = Number(gr.received_amount || (received * Number(gr.unit_cost || line.unit_cost || 0)));
    const unitCost = received ? amount / received : Number(gr.unit_cost || line.unit_cost || 0);
    return `<tr><td>${esc(gr.sku || line.sku || "")}</td><td>${esc(gr.product_name || line.product_name || "")}</td><td>${esc(received)}</td><td>${money(unitCost)}</td><td>${money(amount)}</td><td>${esc(line.wo_no || "")}</td></tr>`;
  });
  const total = receipts.reduce((sum, gr) => sum + Number(gr.received_amount || (Number(gr.received_qty || 0) * Number(gr.unit_cost || 0))), 0);
  return `<div class="table-wrap"><table class="mini-table"><thead><tr>${heads.map((h) => `<th>${esc(h)}</th>`).join("")}</tr></thead><tbody>${receivedRows.length ? `${receivedRows.join("")}<tr class="summary-row"><td colspan="4"><strong>Total received</strong></td><td><strong>${money(total)}</strong></td><td></td></tr>` : `<tr><td colspan="${heads.length}" class="empty">No active goods receipts found.</td></tr>`}</tbody></table></div>`;
}

async function savePostApFromPo(data) {
  const record = collectProductModalFields();
  const poNo = parsePoNo(record.po_no);
  const po = data.pos.find((row) => row.po_no === poNo);
  if (!po) {
    alert("Choose a valid purchase order.");
    return;
  }
  const invoiceAmount = Number(record.vendor_invoice_amount || 0);
  if (!record.vendor_invoice_no || !record.vendor_invoice_date || !record.due_date || invoiceAmount <= 0) {
    alert("Vendor invoice #, invoice date, due date, and invoice amount are required.");
    return;
  }
  if (isLockedAccountingDate(record.posting_date) || isLockedAccountingDate(record.vendor_invoice_date) || isLockedAccountingDate(record.due_date)) {
    alert("This AP posting is inside the closed accounting period.");
    return;
  }
  const support = poSupportDetails(data, po, record);
  if (!support.po_no || !support.jobsite || !support.equipment || !support.parts_description) {
    alert("Invoice support details are required: PO #, jobsite, equipment, and parts/items.");
    return;
  }
  const isLandedAp = isLandedCostPayable(po);
  const receivedAmount = poReceivedTotal(po);
  if (!isLandedAp && receivedAmount <= 0) {
    alert("Receive goods before posting Accounts Payable. If the goods receipt was reversed, post a new goods receipt first.");
    return;
  }
  try {
    await supabase.from("purchase_orders").update({
      vendor_invoice_no: record.vendor_invoice_no,
      vendor_invoice_date: record.vendor_invoice_date,
      vendor_invoice_amount: invoiceAmount,
      due_date: record.due_date,
      ap_support_wo_no: support.wo_no,
      ap_support_jobsite: support.jobsite,
      ap_support_equipment: support.equipment,
      ap_support_parts_description: support.parts_description,
      match_status: record.match_status || "Matched",
      payment_status: record.payment_status || "Ready to Pay",
      status: record.status || "Matched",
      notes: record.notes || po.notes || null,
    }).eq("id", po.id);
    if (isLandedAp) {
      await postLandedCostInvoiceLedger({ ...po, ...record, po_no: po.po_no, vendor: po.vendor }, linkedLandedSourcePoNo(po) || po.po_no, "Separate AP");
    } else {
      await postPurchaseOrderLedger(po, record);
    }
    closeModal();
    accountingTab = "ap";
    renderAccountingView();
  } catch (error) {
    alert(error.message || error);
  }
}

async function openResolveApMismatchModal(data, poNo) {
  const po = data.pos.find((row) => row.po_no === poNo) || accountsPayableRows(data).find((row) => row.po_no === poNo && row.direct_ap);
  if (!po) return;
  const isDirectAp = Boolean(po.direct_ap);
  const ap = isDirectAp ? { invoice_no: po.invoice_no, invoice_date: po.invoice_date, due_date: po.due_date, invoice_amount: po.invoice_amount, match: po.match, payment: po.payment } : poApSummary(po);
  const vendors = await getAll("vendors");
  productMeta.accountingVendors = vendors;
  $("modalTitle").textContent = `${isDirectAp ? "Review Direct AP" : "Resolve AP mismatch"} ${po.po_no}`;
  $("modalBody").innerHTML = `
    <div class="form-grid">
      ${productInput(isDirectAp ? "AP reference" : "PO", "po_no", po.po_no)}
      ${productInput("Vendor", "vendor", po.vendor || "")}
      ${productInput("PO total", "po_total", poTotal(po), "number")}
      ${productInput("Received total", "received_total", poReceivedTotal(po), "number")}
      ${productInput("Vendor invoice #", "vendor_invoice_no", ap.invoice_no || "")}
      ${productInput("Invoice date", "vendor_invoice_date", ap.invoice_date || today(), "date")}
      ${productInput("Due date", "due_date", ap.due_date || po.expected_date || today(), "date")}
      ${productInput("Invoice amount", "vendor_invoice_amount", ap.invoice_amount || poReceivedTotal(po) || poTotal(po), "number")}
      ${productSelect("Resolve as", "match_status", ["Matched", "Mismatch", "Hold", "Pending"], ap.match || "Matched")}
      ${productSelect("Payment status", "payment_status", ["Ready to Pay", "Not Ready", "Hold", "Paid"], ap.payment || "Ready to Pay")}
      <div class="field wide"><label>Resolution note</label><textarea data-product-field="notes">${esc(po.notes || "")}</textarea></div>
    </div>
    <p class="notice">${isDirectAp ? "This payable comes directly from a posted balanced journal. It remains in AP without creating a Purchase Order; corrections update the journal subledger details." : "Use this to document the accounting resolution. The invoice amount and status update the PO and the GL posting can be refreshed from the AP Post action."}</p>`;
  $("modalSave").onclick = async () => {
    const record = collectProductModalFields();
    if (isLockedAccountingDate(record.vendor_invoice_date) || isLockedAccountingDate(record.due_date)) {
      alert("This AP resolution is inside the closed accounting period.");
      return;
    }
    try {
      const vendorQuery = String(record.vendor || "").trim().toLowerCase();
      const vendorMatches = vendors.filter((vendor) => [vendor.name, vendor.vendor, vendor.reference, vendor.email, vendor.phone].some((value) => String(value || "").toLowerCase().includes(vendorQuery)));
      const selectedVendor = vendors.find((vendor) => String(vendor.name || vendor.vendor || "").trim().toLowerCase() === vendorQuery) || (vendorMatches.length === 1 ? vendorMatches[0] : null);
      if (!selectedVendor) return alert("Select one vendor from Vendor Master. If several vendors match, choose the exact row from the search results.");
      const vendorName = selectedVendor.name || selectedVendor.vendor;
      if (isDirectAp) {
        if (Math.abs(Number(record.vendor_invoice_amount || 0) - Number(po.invoice_amount || 0)) > 0.005) {
          return alert("The Direct AP amount is controlled by the posted balanced journal. Reverse and repost the journal to change its amount.");
        }
        const { data: updatedLedgerRows, error: ledgerError } = await supabase.from("general_ledger").update({
          vendor: vendorName,
          invoice_no: record.vendor_invoice_no || po.po_no,
          invoice_date: record.vendor_invoice_date || null,
          due_date: record.due_date || null,
        }).eq("reference", po.po_no).eq("source", "Manual Journal").select("id");
        if (ledgerError) throw ledgerError;
        if (!(updatedLedgerRows || []).length) throw new Error(`Could not update the posted journal ${po.po_no}.`);
        await writeAuditLog({ tableName: "general_ledger", action: "Direct AP details updated", beforeData: po, afterData: { reference: po.po_no, vendor: vendorName, invoice_no: record.vendor_invoice_no, invoice_date: record.vendor_invoice_date, due_date: record.due_date, notes: record.notes || "" } });
        closeModal();
        accountingTab = "ap";
        await renderAccountingView();
        return;
      }
      const { data: updatedRows, error: updateError } = await supabase.from("purchase_orders").update({
        vendor: vendorName,
        vendor_invoice_no: record.vendor_invoice_no,
        vendor_invoice_date: record.vendor_invoice_date,
        due_date: record.due_date,
        vendor_invoice_amount: Number(record.vendor_invoice_amount || 0),
        match_status: record.match_status,
        payment_status: record.payment_status,
        notes: String(record.notes || po.notes || "").trim() || null,
      }).eq("id", po.id).select("id,po_no,vendor_invoice_no,vendor_invoice_amount,match_status,payment_status");
      if (updateError) throw updateError;
      if (!(updatedRows || []).length) throw new Error(`Could not update ${po.po_no}. Check the Purchase Orders update policy.`);

      const postedStandardAp = await hasPostedApForPurchaseOrder(po.po_no);
      if (postedStandardAp) {
        await postPurchaseOrderLedger(po, {
          ...record,
          vendor_invoice_amount: Number(record.vendor_invoice_amount || 0),
          posting_date: record.vendor_invoice_date || today(),
        });
      }
      await writeAuditLog({
        tableName: "purchase_orders",
        recordId: po.id,
        action: "AP Mismatch Resolved",
        beforeData: po,
        afterData: { ...updatedRows[0], resolution_note: record.notes || "", ledger_refreshed: postedStandardAp },
      });
      closeModal();
      accountingTab = "ap";
      await renderAccountingView();
    } catch (error) {
      alert(`Could not save the AP resolution. ${error.message || error}`);
    }
  };
  $("modal").style.display = "flex";
}

async function createCheckRunFromPo(data, poNo) {
  const po = data.pos.find((row) => row.po_no === poNo);
  if (!po) return;
  const ap = poApSummary(po);
  const amount = Number(ap.invoice_amount || poReceivedTotal(po) || poTotal(po));
  const isBeginningAp = /beginning ap/i.test(`${po.status || ""} ${po.notes || ""}`);
  const isManualJournalAp = /manual journal ap/i.test(`${po.status || ""} ${po.notes || ""}`);
  const noReceiptPayable = isBeginningAp || isManualJournalAp || isLandedCostPayable(po);
  if (!noReceiptPayable && poReceivedTotal(po) <= 0) {
    alert("This PO has no active goods receipt. Receive the goods again before creating a check run.");
    return;
  }
  if (!/ready to pay|paid/i.test(ap.payment || "")) {
    alert("This PO is not ready to pay yet. Post or resolve AP matching first.");
    return;
  }
  if (!noReceiptPayable && !await hasPostedApForPurchaseOrder(po.po_no)) {
    alert("Post this receipt to Accounts Payable first. Check run is available after AP is posted.");
    return;
  }
  if (!amount) {
    alert("This PO has no payable amount.");
    return;
  }
  if (isLockedAccountingDate(today())) {
    alert("Today's posting date is inside the closed accounting period.");
    return;
  }
  const coa = data.coa || await getAll("chart_of_accounts");
  const accounts = paymentAccountOptions(coa);
  const support = poSupportDetails(data, po);
  const checkRunNo = await nextRefPreview("check", "CHK-", "check_runs", "check_run_no");
  $("modalTitle").textContent = `Create check run for ${po.po_no}`;
  $("modalBody").innerHTML = `
    <div class="form-grid">
      ${productInput("Check run #", "check_run_no", checkRunNo)}
      ${productInput("Payment date", "payment_date", today(), "date")}
      ${productSelect("Pay from account", "payment_account", accounts, accounts[0] || "FHB Checking")}
      ${productSelect("Payment mode", "payment_mode", ["Check", "ACH", "Wire", "Cash", "Credit Card", "Intercompany"], paymentModeForAccount(accounts[0] || "FHB Checking"))}
      ${productInput("Check # / EFT reference", "check_no", "")}
      ${productInput("Vendor", "vendor", po.vendor || "")}
      ${productInput("Reference", "reference", po.po_no)}
      ${productInput("Invoice #", "invoice_no", ap.invoice_no || "")}
      ${productInput("Invoice date", "invoice_date", ap.invoice_date || "", "date")}
      ${productInput("Due date", "due_date", ap.due_date || po.expected_date || "", "date")}
      ${productInput("Amount", "amount", amount, "number")}
      ${productInput("Work Order # (optional)", "wo_no", support.wo_no || "")}
      ${productInput("PO #", "po_no", support.po_no || po.po_no)}
      ${productInput("Jobsite", "jobsite", support.jobsite || "N/A")}
      ${productInput("Equipment", "equipment", support.equipment || "N/A")}
      ${productSelect("Status", "status", ["Posted", "Draft"], "Posted")}
      <div class="field wide"><label>Description of parts / items</label><textarea data-product-field="parts_description">${esc(support.parts_description || "")}</textarea></div>
      <div class="field wide"><label>Notes</label><textarea data-product-field="notes">Created from ${esc(po.po_no)}</textarea></div>
    </div>
    <p class="notice">Choose the actual cash/checking/bank account or credit card payable account that will pay this AP item.</p>`;
  $("modalSave").onclick = async () => {
    const record = collectProductModalFields();
    if (!record.payment_account) {
      alert("Choose the payment account.");
      return;
    }
    if (isLockedAccountingDate(record.payment_date)) {
      alert("This payment date is inside the closed accounting period.");
      return;
    }
    try {
      const run = {
        check_run_no: record.check_run_no,
        payment_date: record.payment_date,
        payment_mode: record.payment_mode || paymentModeForAccount(record.payment_account),
        payment_account: record.payment_account,
        bank_account: record.payment_account,
        check_no: record.check_no || "",
        vendor: record.vendor || po.vendor,
        reference: record.reference || po.po_no,
        invoice_no: record.invoice_no || "",
        invoice_date: record.invoice_date || null,
        due_date: record.due_date || null,
        wo_no: record.wo_no || support.wo_no || "N/A",
        po_no: record.po_no || support.po_no || po.po_no,
        jobsite: record.jobsite || support.jobsite || "N/A",
        equipment: record.equipment || support.equipment || "N/A",
        parts_description: record.parts_description || support.parts_description || "N/A",
        amount: Number(record.amount || amount),
        status: record.status || "Posted",
        notes: checkRunNotesPayload(record.notes, [{
          ...po,
          ...runSupportRow(record, support, amount, po.po_no, ap),
          source: "Purchase Order",
        }]),
      };
      await upsertOne("check_runs", run, "check_run_no");
      if (/posted/i.test(run.status || "")) {
        await postCheckRunLedger(run);
        await supabase.from("purchase_orders").update({ payment_status: "Paid", status: "Paid" }).eq("id", po.id);
      } else {
        await supabase.from("purchase_orders").update({ payment_status: "Ready to Pay" }).eq("id", po.id);
      }
      await incrementSequence("check");
      closeModal();
      accountingTab = "ap";
      renderAccountingView();
    } catch (error) {
      alert(error.message || error);
    }
  };
  $("modal").style.display = "flex";
}

async function postPurchaseOrderLedger(po, record) {
  const amount = Number(record.vendor_invoice_amount || poReceivedTotal(po) || poTotal(po));
  const received = poReceivedTotal(po);
  if (received <= 0) throw new Error("Receive goods before posting AP for this PO.");
  const landedClear = landedClearAmountForInvoice(po, amount, received);
  const invoiceDifference = amount - received - landedClear;
  const freightExpense = !po.landed_cost_enabled
    ? Math.max(0, Math.min(poFreight(po), invoiceDifference))
    : 0;
  const variance = invoiceDifference - freightExpense;
  const postingDate = record.posting_date || record.vendor_invoice_date || today();
  const rows = [
    { entry_date: postingDate, posting_date: postingDate, account: "Parts Accrual", vendor: po.vendor, invoice_no: record.vendor_invoice_no, invoice_date: record.vendor_invoice_date, due_date: record.due_date, description: `Clear accrued receipt ${po.po_no}`, reference: po.po_no, debit: received, credit: 0, source: "Purchase Order", status: "Posted" },
    { entry_date: postingDate, posting_date: postingDate, account: "Accounts Payable (A/P)", vendor: po.vendor, invoice_no: record.vendor_invoice_no, invoice_date: record.vendor_invoice_date, due_date: record.due_date, description: `Payable to ${po.vendor}`, reference: po.po_no, debit: 0, credit: amount, source: "Purchase Order", status: "Posted" },
  ];
  if (landedClear > 0) rows.splice(1, 0, { entry_date: postingDate, posting_date: postingDate, account: "Landed Cost Accrual", vendor: po.vendor, invoice_no: record.vendor_invoice_no, invoice_date: record.vendor_invoice_date, due_date: record.due_date, description: `Clear landed cost on same invoice ${po.po_no}`, reference: po.po_no, debit: landedClear, credit: 0, source: "Purchase Order", status: "Posted" });
  if (freightExpense > 0) rows.splice(1, 0, { entry_date: postingDate, posting_date: postingDate, account: "Freight-In Expense", vendor: po.vendor, invoice_no: record.vendor_invoice_no, invoice_date: record.vendor_invoice_date, due_date: record.due_date, description: `Vendor freight for ${po.po_no}`, reference: po.po_no, debit: freightExpense, credit: 0, source: "Purchase Order", status: "Posted" });
  if (variance > 0) rows.push({ entry_date: postingDate, posting_date: postingDate, account: "Inventory Loss - Obsolete Part", vendor: po.vendor, invoice_no: record.vendor_invoice_no, invoice_date: record.vendor_invoice_date, due_date: record.due_date, description: `PO invoice variance ${po.vendor}`, reference: po.po_no, debit: variance, credit: 0, source: "Purchase Order", status: "Posted" });
  if (variance < 0) rows.push({ entry_date: postingDate, posting_date: postingDate, account: "Inventory Loss - Obsolete Part", vendor: po.vendor, invoice_no: record.vendor_invoice_no, invoice_date: record.vendor_invoice_date, due_date: record.due_date, description: `PO invoice variance ${po.vendor}`, reference: po.po_no, debit: 0, credit: Math.abs(variance), source: "Purchase Order", status: "Posted" });
  await supabase.from("general_ledger").delete().eq("reference", po.po_no).eq("source", "Purchase Order");
  await upsertManyWithOptionalColumns("general_ledger", rows, "id", ["bank_reference"]);
}

async function purchaseOrderForReceipt(gr) {
  const { data: poRows, error: poError } = await supabase.from("purchase_orders").select("*").eq("po_no", gr.po_no).limit(1);
  if (poError && poError.code !== "PGRST116") throw poError;
  const po = (poRows || [])[0];
  if (!po) return null;
  const { data: lines, error: lineError } = await supabase.from("purchase_order_lines").select("*").eq("po_id", po.id);
  if (lineError && lineError.code !== "PGRST116") throw lineError;
  po._lines = lines || [];
  return po;
}

async function postGoodsReceiptLedger(receipts) {
  const poCache = new Map();
  const rows = [];
  for (const gr of receipts) {
    if (!poCache.has(gr.po_no)) poCache.set(gr.po_no, await purchaseOrderForReceipt(gr));
    const po = poCache.get(gr.po_no);
    const inventoryAmount = Number(gr.received_qty || 0) * Number(gr.unit_cost || 0);
    const productVendorAmount = goodsReceiptBaseAmount(po, gr);
    const landedAccrualAmount = Math.max(0, inventoryAmount - productVendorAmount);
    if (!inventoryAmount) continue;
    rows.push(
      { entry_date: gr.gr_date, posting_date: gr.gr_date, account: "Parts Inventory", vendor: gr.vendor, invoice_no: gr.vendor_invoice_no || null, invoice_date: gr.vendor_invoice_date || null, due_date: null, description: `Goods receipt ${gr.sku}`, reference: gr.gr_no, debit: inventoryAmount, credit: 0, source: "Goods Receipt", status: "Posted" },
      { entry_date: gr.gr_date, posting_date: gr.gr_date, account: "Parts Accrual", vendor: gr.vendor, invoice_no: gr.vendor_invoice_no || null, invoice_date: gr.vendor_invoice_date || null, due_date: null, description: `Accrued product receipt ${gr.sku}`, reference: gr.gr_no, debit: 0, credit: productVendorAmount || inventoryAmount, source: "Goods Receipt", status: "Posted" },
    );
    if (landedAccrualAmount) {
      rows.push({ entry_date: gr.gr_date, posting_date: gr.gr_date, account: "Landed Cost Accrual", vendor: gr.vendor, invoice_no: gr.vendor_invoice_no || null, invoice_date: gr.vendor_invoice_date || null, due_date: null, description: `Estimated landed cost ${gr.sku}`, reference: gr.gr_no, debit: 0, credit: landedAccrualAmount, source: "Goods Receipt", status: "Posted" });
    }
  }
  for (const gr of receipts) {
    await supabase.from("general_ledger").delete().eq("reference", gr.gr_no).eq("source", "Goods Receipt");
  }
  if (rows.length) await upsertMany("general_ledger", rows, "id");
}

async function postGoodsReceiptReversalLedger(gr) {
  const po = await purchaseOrderForReceipt(gr);
  const amount = Number(gr.received_qty || 0) * Number(gr.unit_cost || 0);
  const productVendorAmount = goodsReceiptBaseAmount(po, gr);
  const landedAccrualAmount = Math.max(0, amount - productVendorAmount);
  if (!amount) return;
  const reference = `REV-${gr.gr_no}`;
  await supabase.from("general_ledger").delete().eq("reference", reference).eq("source", "Goods Receipt Reversal");
  const rows = [
    { entry_date: today(), posting_date: today(), account: "Parts Accrual", vendor: gr.vendor, invoice_no: gr.vendor_invoice_no || null, invoice_date: gr.vendor_invoice_date || null, due_date: null, description: `Reverse product accrual ${gr.gr_no}`, reference, debit: productVendorAmount || amount, credit: 0, source: "Goods Receipt Reversal", status: "Posted" },
    { entry_date: today(), posting_date: today(), account: "Parts Inventory", vendor: gr.vendor, invoice_no: gr.vendor_invoice_no || null, invoice_date: gr.vendor_invoice_date || null, due_date: null, description: `Reverse inventory ${gr.gr_no}`, reference, debit: 0, credit: amount, source: "Goods Receipt Reversal", status: "Posted" },
  ];
  if (landedAccrualAmount) rows.push({ entry_date: today(), posting_date: today(), account: "Landed Cost Accrual", vendor: gr.vendor, invoice_no: gr.vendor_invoice_no || null, invoice_date: gr.vendor_invoice_date || null, due_date: null, description: `Reverse landed cost accrual ${gr.gr_no}`, reference, debit: landedAccrualAmount, credit: 0, source: "Goods Receipt Reversal", status: "Posted" });
  await upsertManyWithOptionalColumns("general_ledger", rows, "id", ["bank_reference"]);
}

function collectProductModalFields() {
  const record = {};
  document.querySelectorAll("[data-product-field]").forEach((el) => record[el.dataset.productField] = el.value || null);
  return record;
}

function applyAccountingSearch() {
  const q = $("accountingSearch")?.value?.toLowerCase() || "";
  document.querySelectorAll("#accountingTableHost tbody tr").forEach((tr) => {
    tr.style.display = !q || tr.textContent.toLowerCase().includes(q) ? "" : "none";
  });
}

function showAccountDrill(data, account) {
  const host = $("financialDetailHost");
  if (!host) return;
  const rows = data.gl.filter((row) => row.account === account);
  host.innerHTML = `<section class="panel"><div class="panel-head"><div class="panel-title"><strong>${esc(account)} Detail</strong><span>Posting-date ledger detail for the selected account.</span></div></div>${accountingTable(rows, ["Posting Date", "Description", "Reference", "Customer", "Vendor", "Debit", "Credit", "Source"], (r) => [r.posting_date, r.description, r.reference, r.customer, r.vendor, r.debit ? money(r.debit) : "", r.credit ? money(r.credit) : "", r.source])}</section>`;
  document.querySelectorAll(".column-filter").forEach((input) => input.oninput = applyColumnFilters);
}

function exportAccountingCsv() {
  const rows = [...document.querySelectorAll("#accountingTableHost table tr")].map((tr) => [...tr.children].map((cell) => `"${String(cell.textContent || "").replace(/"/g, '""')}"`).join(","));
  const blob = new Blob([rows.join("\n")], { type: "text/csv" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = `accounting-${accountingTab}-${today()}.csv`;
  a.click();
  URL.revokeObjectURL(a.href);
}

async function renderCheckRunView() {
  currentCfg = tableMap.checkrun;
  $("viewTitle").textContent = "Check Run";
  $("viewSub").textContent = "Select approved payables, filter by vendor, issue checks, and post payments.";
  const [pos, poLines, receipts, runs, coa, gl, workOrders, assets] = await Promise.all([
    getAll("purchase_orders"),
    getAll("purchase_order_lines"),
    getAll("goods_receipts"),
    getAll("check_runs"),
    getAll("chart_of_accounts"),
    getAll("general_ledger"),
    getAll("work_orders"),
    getAll("assets"),
  ]);
  const repairedCheckReversals = await reconcileMissingVoidedCheckRunReversals(runs, gl);
  if (repairedCheckReversals) {
    const refreshedGl = await getAll("general_ledger");
    gl.splice(0, gl.length, ...refreshedGl);
  }
  await reconcilePrintedCheckRunPaymentStatuses(runs, pos);
  const data = buildAccountingData({ gl, coa, invoices: [], invoiceLines: [], payments: [], pos, poLines, receipts, salesOrders: [], salesLines: [], bankRows: [], products: [], workOrders, assets });
  data.checkRuns = runs;
  const vendorFilter = localStorage.getItem("lms.checkRunVendor") || "";
  const normalizedVendorFilter = vendorFilter.trim().toLowerCase();
  const matchesVendorFilter = (value) => !normalizedVendorFilter || String(value || "").trim().toLowerCase() === normalizedVendorFilter;
  const payables = checkRunEligiblePayables(data).filter((row) => matchesVendorFilter(row.vendor));
  const history = checkRunHistoryRows(runs).map((row) => {
    const originalRef = String(row.check_run_no || row.reference || "");
    const voidRef = `${originalRef}-VOID`;
    return {
      ...row,
      _hasOriginalLedger: gl.some((entry) => entry.reference === originalRef && /check run/i.test(entry.source || "") && !/void/i.test(entry.source || "")),
      _hasVoidLedger: gl.some((entry) => entry.reference === voidRef && /check run void/i.test(entry.source || "")),
    };
  }).filter((row) => matchesVendorFilter(row.vendor));
  currentRows = history;
  const readyTotal = payables.reduce((sum, row) => sum + Number(row.amount || 0), 0);
  $("content").innerHTML = `
    <div class="stats">
      ${stat("Ready to Pay", payables.length, "Matched payables")}
      ${stat("Open Check Amount", money(readyTotal), "Filtered payable amount")}
      ${stat("Last Check Run", history[0]?.check_run_no || "None", history[0]?.payment_date || "No payments posted")}
      ${stat("Runs Posted", runs.filter((r) => /posted|printed|cleared/i.test(r.status || "")).length, "Payment batches")}
    </div>
    <section class="panel">
      <div class="toolbar">
        <div class="check-run-vendor-filter">
          <input class="searchbox suggest-input" id="checkRunVendorFilter" data-suggest-source="vendors" value="${esc(vendorFilter)}" placeholder="Type vendor name, reference, email, or phone" autocomplete="off" inputmode="search">
          <button type="button" id="clearCheckRunVendorFilter">All vendors</button>
          <small>Vendor Master results appear in separate columns after you start typing.</small>
        </div>
        <input class="searchbox" id="checkRunSearch" placeholder="Search check runs by vendor, PO, invoice, check number, status">
      </div>
      <div class="panel-head"><div class="panel-title"><strong>Payables Ready for Check Run</strong><span>Only matched and approved payables can be selected for payment.</span></div><button class="primary" id="newCheckRunBtn">New check run</button></div>
      <div id="checkRunPayablesHost">${checkRunPayablesTable(payables)}</div>
    </section>
    <section class="panel">
      <div class="tabbar">
        <button class="tabbtn ${checkRunTab === "forprinting" ? "active" : ""}" data-check-run-tab="forprinting">For Printing ${checkRunsForTab(history, "forprinting").length}</button>
        <button class="tabbtn ${checkRunTab === "printed" ? "active" : ""}" data-check-run-tab="printed">Printed ${checkRunsForTab(history, "printed").length}</button>
        <button class="tabbtn ${checkRunTab === "void" ? "active" : ""}" data-check-run-tab="void">Void ${checkRunsForTab(history, "void").length}</button>
      </div>
      <div class="panel-head"><div class="panel-title"><strong>Check Run History</strong><span>Posted and draft payment batches with vendor-level detail.</span></div><div class="actions"><button id="checkRunCsvBtn">Excel</button><button onclick="window.print()">PDF / Print</button></div></div>
      <div id="checkRunHistoryHost">${checkRunHistoryTable(checkRunsForTab(history, checkRunTab))}</div>
    </section>`;
  $("checkRunVendorFilter").onchange = (e) => {
    const selectedVendor = String(e.target.value || "").trim();
    if (selectedVendor === vendorFilter) return;
    localStorage.setItem("lms.checkRunVendor", selectedVendor);
    renderCheckRunView();
  };
  $("clearCheckRunVendorFilter").onclick = () => {
    localStorage.removeItem("lms.checkRunVendor");
    renderCheckRunView();
  };
  $("checkRunSearch").oninput = () => filterTwoTables("checkRunSearch", ["checkRunPayablesHost", "checkRunHistoryHost"]);
  document.querySelectorAll("[data-check-run-tab]").forEach((button) => {
    button.onclick = () => {
      checkRunTab = button.dataset.checkRunTab;
      document.querySelectorAll("[data-check-run-tab]").forEach((item) => item.classList.toggle("active", item === button));
      $("checkRunHistoryHost").innerHTML = checkRunHistoryTable(checkRunsForTab(history, checkRunTab));
      bindCheckRunRows(data);
      filterTwoTables("checkRunSearch", ["checkRunPayablesHost", "checkRunHistoryHost"]);
    };
  });
  $("newCheckRunBtn").onclick = () => openCheckRunModal(data, vendorFilter);
  $("checkRunCsvBtn").onclick = () => {
    const rows = checkRunsForTab(history, checkRunTab);
    downloadCsv([["Check Run", "Date", "Mode", "Payment Account", "Check #", "Vendor", "Invoice #", "Invoice Date", "Amount", "Work Order #", "PO #", "Jobsite", "Equipment", "Description of Parts", "Status"], ...rows.map((r) => [r.check_run_no, r.payment_date, r.payment_mode, r.payment_account, r.check_no, r.vendor, r.invoice_no, r.invoice_date, r.amount, r.wo_no, r.po_no || r.reference, r.jobsite, r.equipment, r.parts_description, r.status])], `check-run-${checkRunTab}.csv`);
  };
  bindCheckRunRows(data);
}

function checkRunEligiblePayables(data) {
  const assigned = assignedCheckRunDocumentKeys(data.checkRuns || []);
  return accountsPayableRows(data).filter((row) => {
    const poKey = normalizeCheckRunDocumentKey(row.po_no || row.reference);
    const invoiceKey = normalizeCheckRunDocumentKey(row.invoice_no);
    const vendorInvoiceKey = `${normalizeCheckRunDocumentKey(row.vendor)}|${invoiceKey}`;
    const alreadyAssigned = (poKey && assigned.poNumbers.has(poKey))
      || (invoiceKey && assigned.vendorInvoices.has(vendorInvoiceKey));
    return row.ap_posted && /matched/i.test(row.match || "") && /ready/i.test(row.payment || "") && !/paid/i.test(row.payment || row.status || "") && !alreadyAssigned;
  }).map((row) => {
    const po = (data.pos || []).find((item) => item.po_no === row.po_no || item.po_no === row.reference);
    const support = poSupportDetails(data, po, row);
    return { ...row, ...support, amount: Number(row.invoice_amount || row.received || row.po_total || 0), source: "Purchase Order" };
  });
}

function normalizeCheckRunDocumentKey(value) {
  return String(value || "").trim().toLowerCase();
}

function splitCheckRunDocumentValues(value) {
  return String(value || "").split(/[,;]/).map((item) => item.trim()).filter(Boolean);
}

function assignedCheckRunDocumentKeys(runs = []) {
  const poNumbers = new Set();
  const invoiceNumbers = new Set();
  const vendorInvoices = new Set();
  // A payable belongs to only one active check run. Hide it immediately when
  // the run is saved (For Printing), not only after Final Print. Voiding the
  // run releases the payable and makes it eligible again.
  (runs || []).filter((run) => !/void|revers|cancel/i.test(String(run.status || ""))).forEach((run) => {
    const vendorKey = normalizeCheckRunDocumentKey(run.vendor);
    splitCheckRunDocumentValues(run.reference || run.po_no).forEach((value) => poNumbers.add(normalizeCheckRunDocumentKey(value)));
    splitCheckRunDocumentValues(run.po_no).forEach((value) => poNumbers.add(normalizeCheckRunDocumentKey(value)));
    splitCheckRunDocumentValues(run.invoice_no).forEach((value) => {
      const invoiceKey = normalizeCheckRunDocumentKey(value);
      invoiceNumbers.add(invoiceKey);
      vendorInvoices.add(`${vendorKey}|${invoiceKey}`);
    });
    const detail = parseCheckRunNotes(run.notes);
    (detail.invoices || []).forEach((invoice) => {
      const poKey = normalizeCheckRunDocumentKey(invoice.po_no || invoice.reference);
      const invoiceKey = normalizeCheckRunDocumentKey(invoice.invoice_no);
      const invoiceVendorKey = normalizeCheckRunDocumentKey(invoice.vendor || run.vendor);
      if (poKey) poNumbers.add(poKey);
      if (invoiceKey) {
        invoiceNumbers.add(invoiceKey);
        vendorInvoices.add(`${invoiceVendorKey}|${invoiceKey}`);
      }
    });
  });
  return { poNumbers, invoiceNumbers, vendorInvoices };
}

function settledCheckRunDocumentKeys(runs = []) {
  const poNumbers = new Set();
  const invoiceNumbers = new Set();
  const vendorInvoices = new Set();
  (runs || []).filter((run) => /printed|cleared/i.test(String(run.status || "")) && !/void|revers|cancel/i.test(String(run.status || ""))).forEach((run) => {
    const vendorKey = normalizeCheckRunDocumentKey(run.vendor);
    splitCheckRunDocumentValues(run.reference || run.po_no).forEach((value) => poNumbers.add(normalizeCheckRunDocumentKey(value)));
    splitCheckRunDocumentValues(run.po_no).forEach((value) => poNumbers.add(normalizeCheckRunDocumentKey(value)));
    splitCheckRunDocumentValues(run.invoice_no).forEach((value) => {
      const invoiceKey = normalizeCheckRunDocumentKey(value);
      invoiceNumbers.add(invoiceKey);
      vendorInvoices.add(`${vendorKey}|${invoiceKey}`);
    });
    const detail = parseCheckRunNotes(run.notes);
    (detail.invoices || []).forEach((invoice) => {
      const poKey = normalizeCheckRunDocumentKey(invoice.po_no || invoice.reference);
      const invoiceKey = normalizeCheckRunDocumentKey(invoice.invoice_no);
      const invoiceVendorKey = normalizeCheckRunDocumentKey(invoice.vendor || run.vendor);
      if (poKey) poNumbers.add(poKey);
      if (invoiceKey) {
        invoiceNumbers.add(invoiceKey);
        vendorInvoices.add(`${invoiceVendorKey}|${invoiceKey}`);
      }
    });
  });
  return { poNumbers, invoiceNumbers, vendorInvoices };
}

async function reconcilePrintedCheckRunPaymentStatuses(runs = [], purchaseOrders = []) {
  const settled = settledCheckRunDocumentKeys(runs);
  const stale = (purchaseOrders || []).filter((po) => settled.poNumbers.has(normalizeCheckRunDocumentKey(po.po_no)) && !/paid/i.test(String(po.payment_status || "")));
  if (!stale.length) return;
  const results = await Promise.all(stale.map(async (po) => {
    const { data, error } = await supabase.from("purchase_orders").update({ payment_status: "Paid" }).eq("id", po.id).select("id,payment_status");
    if (!error && data?.length) po.payment_status = "Paid";
    return { po, error, updated: Boolean(data?.length) };
  }));
  const failed = results.filter((result) => result.error || !result.updated);
  if (failed.length) console.warn("Some Purchase Orders referenced by printed Check Runs could not be reconciled to Paid.", failed);
}

function checkRunHistoryRows(runs) {
  return [...runs].sort((a, b) => String(b.payment_date || "").localeCompare(String(a.payment_date || "")));
}

function checkRunsForTab(rows, tab = checkRunTab) {
  return (rows || []).filter((row) => {
    const status = String(row.status || "Posted").toLowerCase();
    if (tab === "void") return /void/.test(status);
    if (tab === "printed") return /printed|cleared/.test(status);
    return !/void|printed|cleared/.test(status);
  });
}

function checkRunOptionalDisplay(value) {
  const text = String(value || "").trim();
  return /^(?:n\/?a|not applicable|none|null)$/i.test(text) ? "" : text;
}

function checkRunPayablesTable(rows) {
  const heads = ["Include", "Vendor", "Invoice #", "Invoice Date", "Amount", "Work Order #", "PO #", "Jobsite", "Equipment", "Description of Parts", "Match", "Payment"];
  return `<div class="table-wrap"><table class="check-run-payables-table"><thead><tr>${heads.map((h, index) => `<th>${index === 0 ? '<label class="select-all-label"><input type="checkbox" data-check-payable-all checked title="Select or clear all visible payables"> <span>Include</span></label>' : esc(h)}</th>`).join("")}</tr><tr>${heads.map((h, i) => i ? `<th><input class="column-filter" data-col="${i}" placeholder="Filter ${esc(h)}"></th>` : "<th></th>").join("")}</tr></thead><tbody>${rows.length ? rows.map((r) => `<tr><td><input type="checkbox" data-check-payable="${esc(r.po_no)}" checked></td><td>${esc(r.vendor)}</td><td>${esc(r.invoice_no)}</td><td>${esc(formatDisplayDate(r.invoice_date))}</td><td>${money(r.amount)}</td><td>${esc(checkRunOptionalDisplay(r.wo_no))}</td><td>${esc(r.po_no)}</td><td>${esc(checkRunOptionalDisplay(r.jobsite))}</td><td>${esc(checkRunOptionalDisplay(r.equipment))}</td><td>${esc(checkRunOptionalDisplay(r.parts_description))}</td><td>${badge(r.match)}</td><td>${badge(r.payment)}</td></tr>`).join("") : `<tr><td colspan="${heads.length}" class="empty">No matched payables ready for check run.</td></tr>`}</tbody></table></div>`;
}

function bindCheckRunPayableSelectAll(root = document) {
  root.querySelectorAll(".check-run-payables-table").forEach((table) => {
    const selectAll = table.querySelector("[data-check-payable-all]");
    const rowChecks = [...table.querySelectorAll("[data-check-payable]")];
    if (!selectAll) return;
    const visibleChecks = () => rowChecks.filter((checkbox) => checkbox.closest("tr")?.style.display !== "none");
    const refresh = () => {
      const visible = visibleChecks();
      const checked = visible.filter((checkbox) => checkbox.checked).length;
      selectAll.checked = visible.length > 0 && checked === visible.length;
      selectAll.indeterminate = checked > 0 && checked < visible.length;
    };
    selectAll.onchange = () => {
      visibleChecks().forEach((checkbox) => { checkbox.checked = selectAll.checked; });
      refresh();
    };
    rowChecks.forEach((checkbox) => checkbox.onchange = refresh);
    table.querySelectorAll(".column-filter").forEach((input) => input.addEventListener("input", () => setTimeout(refresh, 0)));
    refresh();
  });
}

function checkRunHistoryTable(rows) {
  const heads = ["Check Run", "Date", "Payment Account", "Check #", "Vendor", "Invoice #", "Amount", "Work Order #", "PO #", "Jobsite", "Equipment", "Description of Parts", "Status", ""];
  return `<div class="table-wrap"><table><thead><tr>${heads.map((h) => `<th>${esc(h)}</th>`).join("")}</tr><tr>${heads.map((h, i) => h ? `<th><input class="column-filter" data-col="${i}" placeholder="Filter ${esc(h)}"></th>` : "<th></th>").join("")}</tr></thead><tbody>${rows.length ? rows.map((r) => {
    const editable = !/printed|cleared|void/i.test(r.status || "");
    const missingReversal = /void/i.test(r.status || "") && r._hasOriginalLedger && !r._hasVoidLedger;
    return `<tr><td>${esc(r.check_run_no)}</td><td>${esc(formatDisplayDate(r.payment_date))}</td><td>${esc(r.payment_account)}</td><td>${esc(r.check_no || "")}</td><td>${esc(r.vendor)}</td><td>${esc(r.invoice_no || "")}</td><td>${money(r.amount)}</td><td>${esc(checkRunOptionalDisplay(r.wo_no))}</td><td>${esc(r.po_no || r.reference || "")}</td><td>${esc(checkRunOptionalDisplay(r.jobsite))}</td><td>${esc(checkRunOptionalDisplay(r.equipment))}</td><td>${esc(checkRunOptionalDisplay(r.parts_description))}</td><td>${badge(r.status)}${missingReversal ? '<br><span class="badge bad">Missing reversal</span>' : ""}</td><td><div class="rowactions">${editable ? `<button class="rowbtn" data-check-edit="${esc(r.check_run_no)}">Edit</button><button class="rowbtn" data-check-add="${esc(r.check_run_no)}">Add Payables</button>` : ""}<button class="rowbtn" data-check-draft="${esc(r.check_run_no)}">Draft Print</button><button class="rowbtn" data-check-print="${esc(r.check_run_no)}">Final Print</button>${!/void/i.test(r.status || "") ? `<button class="rowbtn danger" data-check-void="${esc(r.check_run_no)}">Void</button>` : missingReversal ? `<button class="rowbtn danger" data-check-post-missing-reversal="${esc(r.check_run_no)}">Post Missing Reversal</button>` : ""}</div></td></tr>`;
  }).join("") : `<tr><td colspan="${heads.length}" class="empty">No check runs yet.</td></tr>`}</tbody></table></div>`;
}

function bindCheckRunRows(data = {}) {
  document.querySelectorAll("[data-check-edit]").forEach((btn) => btn.onclick = () => openEditCheckRunModal(data, btn.dataset.checkEdit));
  document.querySelectorAll("[data-check-add]").forEach((btn) => btn.onclick = () => openAddToCheckRunModal(data, btn.dataset.checkAdd));
  document.querySelectorAll("[data-check-draft]").forEach((btn) => btn.onclick = () => printCheckRun(btn.dataset.checkDraft, true));
  document.querySelectorAll("[data-check-print]").forEach((btn) => btn.onclick = () => printCheckRun(btn.dataset.checkPrint));
  document.querySelectorAll("[data-check-post]").forEach((btn) => btn.onclick = () => postCheckRun(btn.dataset.checkPost));
  document.querySelectorAll("[data-check-void]").forEach((btn) => btn.onclick = () => voidCheckRun(btn.dataset.checkVoid));
  document.querySelectorAll("[data-check-post-missing-reversal]").forEach((btn) => btn.onclick = () => postMissingCheckRunReversal(btn.dataset.checkPostMissingReversal));
  document.querySelectorAll(".column-filter").forEach((input) => input.oninput = applyColumnFilters);
  bindCheckRunPayableSelectAll();
}

async function openAddToCheckRunModal(data, checkRunNo) {
  const run = (data.checkRuns || []).find((row) => row.check_run_no === checkRunNo);
  if (!run || /printed|cleared|void/i.test(run.status || "")) return alert("This check run is already printed or locked.");
  const existing = parseCheckRunNotes(run.notes).invoices || [];
  const existingKeys = new Set(existing.map((row) => `${row.po_no || row.reference}|${row.invoice_no || ""}`));
  const payables = checkRunEligiblePayables(data).filter((row) => String(row.vendor || "").trim().toLowerCase() === String(run.vendor || "").trim().toLowerCase() && !existingKeys.has(`${row.po_no}|${row.invoice_no || ""}`));
  $("modalTitle").textContent = `Add payables to ${run.check_run_no}`;
  $("modalBody").innerHTML = `<p class="notice">Additional payables may be added until Final Print. Draft Print does not post accounting or lock the check run.</p>${checkRunPayablesTable(payables)}`;
  $("modalSave").textContent = "Add selected";
  $("modalSave").onclick = () => saveAdditionalCheckRunPayables(data, run, payables);
  $("modal").style.display = "flex";
  bindCheckRunPayableSelectAll($("modal"));
}

async function saveAdditionalCheckRunPayables(data, run, payables) {
  const selected = payables.filter((row) => $("modal").querySelector(`[data-check-payable="${CSS.escape(row.po_no)}"]`)?.checked);
  if (!selected.length) return alert("Select at least one payable.");
  const { data: current, error } = await supabase.from("check_runs").select("*").eq("check_run_no", run.check_run_no).maybeSingle();
  if (error) return alert(error.message);
  if (!current || /printed|cleared|void/i.test(current.status || "")) return alert("This check run has already been printed or locked.");
  const detail = parseCheckRunNotes(current.notes);
  const fallback = runSupportRow(current, current, current.amount, current.po_no || current.reference);
  const merged = [...(detail.invoices.length ? detail.invoices : [fallback]), ...selected];
  const unique = [...new Map(merged.map((row) => [`${row.po_no || row.reference}|${row.invoice_no || ""}`, row])).values()];
  const support = summarizeCheckSupport(unique);
  const amount = unique.reduce((sum, row) => sum + Number(row.amount || 0), 0);
  const patch = { reference: uniqueTextList(unique.map((row) => row.po_no || row.reference)).join(", "), invoice_no: uniqueTextList(unique.map((row) => row.invoice_no)).join(", "), amount, wo_no: support.wo_no, po_no: support.po_no, jobsite: support.jobsite, equipment: support.equipment, parts_description: support.parts_description, notes: checkRunNotesPayload(detail.userNotes, unique) };
  const { error: updateError } = await supabase.from("check_runs").update(patch).eq("check_run_no", current.check_run_no);
  if (updateError) return alert(updateError.message);
  for (const row of selected) await supabase.from("purchase_orders").update({ payment_status: "For Check Run" }).eq("po_no", row.po_no);
  closeModal();
  renderCheckRunView();
}

async function openEditCheckRunModal(data, checkRunNo) {
  let row = (data.checkRuns || []).find((item) => String(item.check_run_no || "") === String(checkRunNo || ""));
  if (!row) {
    const result = await supabase.from("check_runs").select("*").eq("check_run_no", checkRunNo).maybeSingle();
    if (result.error || !result.data) return alert(result.error?.message || "Check run was not found.");
    row = result.data;
  }
  if (/printed|cleared|void/i.test(row.status || "")) return alert(`${checkRunNo} is locked after printing, clearing, or voiding.`);
  const accounts = paymentAccountOptions(data.coa || []);
  $("modalTitle").textContent = `Edit check run ${checkRunNo}`;
  $("modalBody").innerHTML = `
    <div class="form-grid">
      ${productInput("Check run #", "check_run_no", row.check_run_no || checkRunNo)}
      ${productInput("Payment date", "payment_date", row.payment_date || today(), "date")}
      ${productSelect("Pay from account", "payment_account", accounts, row.payment_account || "FHB Checking")}
      ${productSelect("Payment mode", "payment_mode", ["Check", "ACH", "Wire", "Cash", "Credit Card", "Intercompany"], row.payment_mode || "Check")}
      ${productInput("Starting check # / EFT batch", "check_no", row.check_no || "")}
    </div>
    <p class="notice">You can edit this check run until Final Print. Draft Print does not post accounting; Final Print creates the accounting entry and locks editing.</p>`;
  const numberField = $("modalBody").querySelector('[data-product-field="check_run_no"]');
  if (numberField) numberField.disabled = true;
  $("modalSave").onclick = async () => {
    const read = (name) => $("modalBody").querySelector(`[data-product-field="${name}"]`)?.value?.trim() || "";
    const payload = {
      payment_date: read("payment_date"),
      payment_account: read("payment_account"),
      payment_mode: read("payment_mode"),
      check_no: read("check_no"),
    };
    if (/^check$/i.test(payload.payment_mode) && !isFhbCheckingAccount(payload.payment_account)) return alert("Only FHB Checking can use Check payment mode.");
    if (!checkRunUsesPrintedCheck(payload.payment_account, payload.payment_mode)) payload.check_no = "";
    const { error } = await supabase.from("check_runs").update(payload).eq("check_run_no", checkRunNo);
    if (error) return alert(error.message);
    $("modal").style.display = "none";
    await renderCheckRunView();
  };
  $("modal").style.display = "flex";
  bindCheckRunPaymentFields($("modal"));
}

async function openCheckRunModal(data, vendorFilter = "") {
  const payables = checkRunEligiblePayables(data).filter((row) => !vendorFilter || row.vendor === vendorFilter);
  const number = await nextRefPreview("check", "CHK-", "check_runs", "check_run_no");
  const startingCheckNo = nextAvailableCheckNumber(data.checkRuns || []);
  const accounts = paymentAccountOptions(data.coa || []);
  const defaultPaymentAccount = accounts.find((account) => String(account).trim().toLowerCase() === "fhb checking") || "FHB Checking";
  $("modalTitle").textContent = "New check run";
  $("modalBody").innerHTML = `
    <div class="form-grid">
      ${productInput("Check run #", "check_run_no", number)}
      ${productInput("Payment date", "payment_date", today(), "date")}
      ${productSelect("Pay from account", "payment_account", accounts, defaultPaymentAccount)}
      ${productSelect("Payment mode", "payment_mode", ["Check", "ACH", "Wire", "Cash", "Credit Card", "Intercompany"], "Check")}
      ${productInput("Starting check # / EFT batch", "check_no", startingCheckNo)}
      <div class="field wide"><label>Payables to include</label>${checkRunPayablesTable(payables)}</div>
      <div class="field wide"><label>Notes</label><textarea data-product-field="notes"></textarea></div>
    </div>
    <p class="notice">${vendorFilter ? `Filtered to ${esc(vendorFilter)}. ` : ""}Saving assembles the check run only. The Accounts Payable and payment-account entry is created once, when the check is printed.</p>`;
  $("modalSave").onclick = () => saveCheckRunModal(data, payables);
  $("modal").style.display = "flex";
  bindCheckRunPayableSelectAll($("modal"));
  bindCheckRunPaymentFields($("modal"));
}

function paymentAccountOptions(coa = []) {
  const names = (coa || [])
    .map((a) => a.account)
    .filter((account) => {
      const text = String(account || "");
      const isCash = /cash|bank|checking|savings|petty cash/i.test(text) && !/receivable|payable|deposit/i.test(text);
      const isCreditCardPayable = /credit card payable|card payable/i.test(text);
      const isIntercompany = /intercompany/i.test(text);
      return isCash || isCreditCardPayable || isIntercompany;
    });
  return [...new Set([...(names.length ? names : []), "FHB Checking", "Credit Card Payable - LMS Impo", "Intercompany - LMS Main"])];
}

async function saveCheckRunModal(data, payables) {
  const record = collectProductModalFields();
  const usesPrintedCheck = checkRunUsesPrintedCheck(record.payment_account, record.payment_mode);
  if (/^check$/i.test(String(record.payment_mode || "")) && !isFhbCheckingAccount(record.payment_account)) {
    alert("Only FHB Checking can use Check payment mode. Choose another payment mode for this account.");
    return;
  }
  if (usesPrintedCheck && (!String(record.check_no || "").trim() || String(record.check_no || "").trim() === "0")) {
    alert("Check # is required. Enter the actual check number before saving the check run.");
    return;
  }
  if (!usesPrintedCheck) record.check_no = "";
  const selected = payables.filter((row) => $("modal").querySelector(`[data-check-payable="${CSS.escape(row.po_no)}"]`)?.checked);
  if (!selected.length) {
    alert("Select at least one payable.");
    return;
  }
  if (isLockedAccountingDate(record.payment_date)) {
    alert("This payment date is inside the closed accounting period.");
    return;
  }
  try {
    const groups = groupPayablesByVendor(selected);
    if (usesPrintedCheck) {
      const startingCheckNo = Number(String(record.check_no || "").trim());
      if (!Number.isInteger(startingCheckNo) || startingCheckNo < 6816) {
        alert("Check numbers must be whole numbers beginning at 6816.");
        return;
      }
      const currentRuns = await getAll("check_runs");
      const usedCheckNumbers = new Set(currentRuns.filter(checkRunNumberIsUnavailable).map((run) => String(run.check_no || "").trim()).filter(Boolean));
      const requestedCheckNumbers = groups.map((_, index) => sequentialCheckNo(record.check_no, index));
      const duplicateCheckNo = requestedCheckNumbers.find((checkNo) => usedCheckNumbers.has(checkNo));
      if (duplicateCheckNo) {
        const nextCheckNo = nextAvailableCheckNumber(currentRuns);
        const checkField = $("modal")?.querySelector('[data-product-field="check_no"]');
        if (checkField) checkField.value = nextCheckNo;
        alert(`Check # ${duplicateCheckNo} is already used. The next available check number is ${nextCheckNo}.`);
        return;
      }
    }
    for (const [index, group] of groups.entries()) {
      const checkNo = sequentialCheckNo(record.check_no, index);
      const refs = group.rows.map((row) => row.po_no).filter(Boolean);
      const invoiceNos = group.rows.map((row) => row.invoice_no).filter(Boolean);
      const detailNotes = checkRunNotesPayload(record.notes, group.rows);
      const support = summarizeCheckSupport(group.rows);
      await upsertOne("check_runs", {
        check_run_no: index ? `${record.check_run_no}-${index + 1}` : record.check_run_no,
        payment_date: record.payment_date,
        payment_mode: record.payment_mode || paymentModeForAccount(record.payment_account),
        payment_account: record.payment_account,
        bank_account: record.payment_account,
        check_no: checkNo,
        vendor: group.vendor,
        reference: refs.join(", "),
        invoice_no: invoiceNos.join(", "),
        invoice_date: group.rows[0]?.invoice_date || null,
        due_date: group.rows.map((row) => row.due_date).filter(Boolean).sort()[0] || null,
        wo_no: support.wo_no,
        po_no: support.po_no,
        jobsite: support.jobsite,
        equipment: support.equipment,
        parts_description: support.parts_description,
        amount: group.amount,
        status: "For Printing",
        notes: detailNotes,
      }, "check_run_no");
      for (const row of group.rows) {
        await supabase.from("purchase_orders").update({ payment_status: "For Check Run" }).eq("po_no", row.po_no);
      }
    }
    await incrementSequence("check");
    closeModal();
    renderCheckRunView();
  } catch (error) {
    alert(error.message || error);
  }
}

function groupPayablesByVendor(rows) {
  const map = new Map();
  rows.forEach((row) => {
    const vendor = row.vendor || "Unknown Vendor";
    if (!map.has(vendor)) map.set(vendor, { vendor, rows: [], amount: 0 });
    const group = map.get(vendor);
    group.rows.push(row);
    group.amount += Number(row.amount || 0);
  });
  return [...map.values()];
}

function summarizeCheckSupport(rows) {
  return {
    wo_no: combineSupportField(rows, "wo_no"),
    po_no: combineSupportField(rows, "po_no"),
    jobsite: combineSupportField(rows, "jobsite"),
    equipment: combineSupportField(rows, "equipment"),
    parts_description: combineSupportField(rows, "parts_description"),
  };
}

function combineSupportField(rows, key) {
  return uniqueTextList((rows || []).map((row) => row[key])).join("; ");
}

function runSupportRow(record, support, amount, poNo, ap = {}) {
  return {
    vendor: record.vendor || "",
    po_no: record.po_no || support.po_no || poNo || "",
    invoice_no: record.invoice_no || ap.invoice_no || "",
    invoice_date: record.invoice_date || ap.invoice_date || "",
    due_date: record.due_date || ap.due_date || "",
    amount: Number(record.amount || amount || 0),
    wo_no: record.wo_no || support.wo_no || "N/A",
    jobsite: record.jobsite || support.jobsite || "N/A",
    equipment: record.equipment || support.equipment || "N/A",
    parts_description: record.parts_description || support.parts_description || "N/A",
  };
}

function checkRunNotesPayload(userNotes, rows) {
  const payload = {
    userNotes: userNotes || "",
    invoices: rows.map((row) => ({
      vendor: row.vendor || "",
      reference: row.po_no || "",
      invoice_no: row.invoice_no || "",
      invoice_date: row.invoice_date || "",
      due_date: row.due_date || "",
      amount: Number(row.amount || 0),
      wo_no: row.wo_no || "N/A",
      po_no: row.po_no || row.reference || "",
      jobsite: row.jobsite || "N/A",
      equipment: row.equipment || "N/A",
      parts_description: row.parts_description || "N/A",
      source: row.source || "Purchase Order",
    })),
  };
  return `CHECK_RUN_DETAIL:${JSON.stringify(payload)}`;
}

function parseCheckRunNotes(notes) {
  const text = String(notes || "");
  if (!text.startsWith("CHECK_RUN_DETAIL:")) return { userNotes: text, invoices: [] };
  try {
    return JSON.parse(text.replace("CHECK_RUN_DETAIL:", ""));
  } catch {
    return { userNotes: text, invoices: [] };
  }
}

function sequentialCheckNo(start, index) {
  const n = Number(start);
  return Number.isFinite(n) && start !== "" ? String(n + index) : start || "";
}

function checkRunNumberIsUnavailable(run = {}) {
  const inactive = /void|cancel|reversed/i.test(String(run.status || ""));
  if (!inactive) return true;
  return /\bunusable\b/i.test(String(run.notes || ""));
}

function nextAvailableCheckNumber(runs = []) {
  const used = (runs || [])
    .filter(checkRunNumberIsUnavailable)
    .map((run) => String(run.check_no || "").trim())
    .filter((checkNo) => /^\d+$/.test(checkNo))
    .map(Number)
    .filter(Number.isSafeInteger);
  return String(Math.max(6815, ...used) + 1);
}

function paymentModeForAccount(account) {
  if (/intercompany/i.test(account || "")) return "Intercompany";
  if (/credit card|card payable/i.test(account || "")) return "Credit Card";
  if (/cash|petty cash/i.test(account || "")) return "Cash";
  if (/wire/i.test(account || "")) return "Wire";
  return "Check";
}

function isFhbCheckingAccount(account) {
  return /^fhb checking$/i.test(String(account || "").trim());
}

function checkRunModeForAccount(account) {
  if (isFhbCheckingAccount(account)) return "Check";
  const mode = paymentModeForAccount(account);
  return /^check$/i.test(mode) ? "ACH" : mode;
}

function checkRunUsesPrintedCheck(account, mode) {
  return isFhbCheckingAccount(account) && /^check$/i.test(String(mode || "").trim());
}

function bindCheckRunPaymentFields(root = document) {
  const account = root.querySelector('[data-product-field="payment_account"]');
  const mode = root.querySelector('[data-product-field="payment_mode"]');
  const checkNo = root.querySelector('[data-product-field="check_no"]');
  if (!account || !mode || !checkNo) return;
  const sync = () => {
    const usesCheckAccount = isFhbCheckingAccount(account.value);
    if (usesCheckAccount) {
      mode.value = "Check";
    } else if (/^check$/i.test(mode.value || "")) {
      mode.value = checkRunModeForAccount(account.value);
    }
    checkNo.disabled = !usesCheckAccount;
    checkNo.required = usesCheckAccount;
    checkNo.closest(".field")?.toggleAttribute("hidden", !usesCheckAccount);
    if (!usesCheckAccount) checkNo.value = "";
  };
  account.addEventListener("change", sync);
  mode.addEventListener("change", () => {
    if (!isFhbCheckingAccount(account.value) && /^check$/i.test(mode.value || "")) mode.value = checkRunModeForAccount(account.value);
    sync();
  });
  sync();
}

async function postCheckRun(checkRunNo) {
  const rows = await getAll("check_runs");
  const run = rows.find((r) => r.check_run_no === checkRunNo);
  if (!run) return;
  if (isLockedAccountingDate(run.payment_date)) {
    alert("This check run is inside the closed accounting period.");
    return;
  }
  await supabase.from("check_runs").update({ status: "For Printing" }).eq("check_run_no", checkRunNo);
  renderCheckRunView();
}

function splitCheckRunReferences(reference) {
  return String(reference || "").split(",").map((ref) => ref.trim()).filter(Boolean);
}

async function postCheckRunLedger(run) {
  const amount = Number(run.amount || 0);
  if (!amount) return;
  const bankReference = run.check_run_no || run.reference;
  const bankPayload = {
    tx_date: run.payment_date,
    bank_account: run.bank_account || run.payment_account || "FHB Checking",
    description: `Check run ${bankReference}`,
    reference: bankReference,
    amount: -Math.abs(amount),
    status: "Matched",
    matched_reference: run.reference,
    notes: `Account: ${run.bank_account || run.payment_account || "FHB Checking"}`,
  };
  const { data: existingBankRows, error: bankLookupError } = await supabase.from("bank_transactions").select("id").eq("reference", bankReference).limit(1);
  if (bankLookupError) throw bankLookupError;
  if (existingBankRows?.length) {
    await updateOneWithOptionalColumns("bank_transactions", bankPayload, "id", existingBankRows[0].id, ["bank_account"], "Payment posted. Run the bank account SQL update when you want the bank account stored in a separate bank transaction column.");
  } else {
    await upsertOneWithOptionalColumns("bank_transactions", bankPayload, "id", ["bank_account"], "Payment posted. Run the bank account SQL update when you want the bank account stored in a separate bank transaction column.");
  }
  await supabase.from("general_ledger").delete().eq("reference", run.check_run_no || run.reference).eq("source", "Check Run");
  await upsertMany("general_ledger", [
    { entry_date: run.payment_date, posting_date: run.payment_date, account: "Accounts Payable (A/P)", vendor: run.vendor, invoice_no: run.invoice_no || null, invoice_date: run.invoice_date || null, due_date: run.due_date || null, description: `Payment to ${run.vendor}`, reference: run.check_run_no || run.reference, debit: amount, credit: 0, source: "Check Run", status: run.status || "Posted" },
    { entry_date: run.payment_date, posting_date: run.payment_date, account: run.payment_account || "FHB Checking", vendor: run.vendor, invoice_no: run.invoice_no || null, invoice_date: run.invoice_date || null, due_date: run.due_date || null, description: `Check run ${run.check_no || run.check_run_no || ""}`, reference: run.check_run_no || run.reference, debit: 0, credit: amount, source: "Check Run", status: run.status || "Posted" },
  ], "id");
}

async function postCheckRunVoidLedger(run, voidDate, reason) {
  const voidRef = `${run.check_run_no || run.reference}-VOID`;
  const amount = Number(run.amount || 0);
  if (!(amount > 0)) throw new Error("The check run amount must be greater than zero before its reversal can be posted.");
  await supabase.from("general_ledger").delete().eq("reference", voidRef).eq("source", "Check Run Void");
  await upsertMany("general_ledger", [
    { entry_date: voidDate, posting_date: voidDate, account: run.payment_account || run.bank_account || "FHB Checking", vendor: run.vendor, invoice_no: run.invoice_no || null, invoice_date: run.invoice_date || null, due_date: run.due_date || null, description: `Void check ${run.check_no || run.check_run_no}: ${reason}`, reference: voidRef, debit: amount, credit: 0, source: "Check Run Void", status: "Posted" },
    { entry_date: voidDate, posting_date: voidDate, account: "Accounts Payable (A/P)", vendor: run.vendor, invoice_no: run.invoice_no || null, invoice_date: run.invoice_date || null, due_date: run.due_date || null, description: `Restore payable from voided check ${run.check_no || run.check_run_no}: ${reason}`, reference: voidRef, debit: 0, credit: amount, source: "Check Run Void", status: "Posted" },
  ], "id");
  const bankPayload = {
    tx_date: voidDate,
    bank_account: run.bank_account || run.payment_account || "FHB Checking",
    description: `Void check ${run.check_no || run.check_run_no}`,
    reference: voidRef,
    amount: Math.abs(amount),
    status: "Matched",
    matched_reference: run.reference,
    notes: `Void reason: ${reason}`,
  };
  const { data: existingBank, error: bankLookupError } = await supabase.from("bank_transactions").select("id").eq("reference", voidRef).limit(1);
  if (bankLookupError) throw bankLookupError;
  if (existingBank?.[0]?.id) {
    const { error } = await supabase.from("bank_transactions").update(bankPayload).eq("id", existingBank[0].id);
    if (error) throw error;
  } else {
    await insertOneWithOptionalColumns("bank_transactions", bankPayload, ["bank_account"], "Void posted. Run the bank account SQL update when you want the bank account stored separately.");
  }
}

function savedCheckRunVoidDetails(run = {}) {
  const match = String(run.notes || "").match(/\[VOID\s+([^\]]+)\]\s*([^\r\n]*)/i);
  const voidDate = match?.[1] ? parseFlexibleDate(match[1]) : "";
  return { voidDate, reason: String(match?.[2] || "Reprint").trim() || "Reprint" };
}

async function reconcileMissingVoidedCheckRunReversals(runs = [], ledgerRows = []) {
  const ledger = ledgerRows || [];
  const repairs = [];
  for (const run of runs || []) {
    if (!/void/i.test(String(run.status || ""))) continue;
    const originalRef = String(run.check_run_no || run.reference || "").trim();
    if (!originalRef) continue;
    const voidRef = `${originalRef}-VOID`;
    const hasOriginal = ledger.some((entry) => entry.reference === originalRef && /check run/i.test(entry.source || "") && !/void/i.test(entry.source || ""));
    const hasReversal = ledger.some((entry) => entry.reference === voidRef && /check run void/i.test(entry.source || ""));
    if (!hasOriginal || hasReversal) continue;
    const details = savedCheckRunVoidDetails(run);
    let postingDate = details.voidDate || today();
    if (isLockedAccountingDate(postingDate)) postingDate = today();
    if (isLockedAccountingDate(postingDate)) continue;
    const reason = postingDate !== details.voidDate
      ? `${details.reason} (missing prior-period reversal posted in the current open period)`
      : details.reason;
    repairs.push({ run, voidDate: postingDate, reason });
  }
  if (!repairs.length) return 0;
  let repaired = 0;
  for (const item of repairs) {
    try {
      await postCheckRunVoidLedger(item.run, item.voidDate, item.reason);
      repaired += 1;
    } catch (error) {
      console.error(`Could not automatically post missing reversal for ${item.run.check_run_no || item.run.reference}.`, error);
    }
  }
  return repaired;
}

async function postMissingCheckRunReversal(checkRunNo) {
  const [{ data: run, error: runError }, { data: originalLedger, error: ledgerError }] = await Promise.all([
    supabase.from("check_runs").select("*").eq("check_run_no", checkRunNo).maybeSingle(),
    supabase.from("general_ledger").select("id").eq("reference", checkRunNo).eq("source", "Check Run"),
  ]);
  if (runError || !run) return alert(runError?.message || "Check run was not found.");
  if (ledgerError) return alert(ledgerError.message);
  if (!/void/i.test(run.status || "")) return alert("Only a voided check run can receive a missing reversal.");
  if (!originalLedger?.length) return alert("No original Check Run ledger posting was found, so there is nothing to reverse.");
  await loadAccountingCloseDate();
  const saved = savedCheckRunVoidDetails(run);
  const enteredDate = prompt(`Reversal posting date for voided check ${run.check_no || run.check_run_no}\n\nEnter as mm/dd/yyyy.`, formatDisplayDate(saved.voidDate || today()));
  if (enteredDate === null) return;
  const postingDate = parseFlexibleDate(enteredDate);
  if (!postingDate) return alert("Enter a valid reversal posting date as mm/dd/yyyy.");
  if (postingDate > today()) return alert("Reversal posting date cannot be in the future.");
  if (isLockedAccountingDate(postingDate)) return alert(`Reversal date ${formatDisplayDate(postingDate)} is inside a closed accounting period. Choose a date after ${formatDisplayDate(getAccountingCloseDate())}.`);
  if (!confirm(`Post the missing reversal for ${run.check_run_no}?\n\nCheck: ${run.check_no || ""}\nVendor: ${run.vendor || ""}\nAmount: ${money(run.amount)}\nPosting date: ${formatDisplayDate(postingDate)}\n\nThis restores Accounts Payable and posts the Cash reversal without deleting the original audit entry.`)) return;
  try {
    await postCheckRunVoidLedger(run, postingDate, saved.reason);
    for (const ref of splitCheckRunReferences(run.reference)) {
      await supabase.from("purchase_orders").update({ payment_status: "Ready to Pay" }).eq("po_no", ref);
    }
    alert(`The missing reversal for ${run.check_run_no} was posted. Cash and Accounts Payable now include the correcting entry.`);
    await renderCheckRunView();
  } catch (error) {
    alert(error.message || "Could not post the missing check reversal.");
  }
}

async function voidCheckRun(checkRunNo) {
  const rows = await getAll("check_runs");
  const run = rows.find((r) => r.check_run_no === checkRunNo);
  if (!run) return alert("Check run was not found.");
  if (/void/i.test(run.status || "")) return alert("This check run is already voided.");
  await loadAccountingCloseDate();
  const details = promptCheckVoidDetails(`check ${run.check_no || run.check_run_no}`);
  if (!details) return;
  if (!confirm(`Void check ${run.check_no || run.check_run_no} for ${run.vendor} on ${formatDisplayDate(details.voidDate)}?\n\nThe payable documents will return to the check run list.`)) return;
  try {
    const [{ data: originalLedger, error: originalLedgerError }, { data: originalBank, error: originalBankError }] = await Promise.all([
      supabase.from("general_ledger").select("id").eq("reference", run.check_run_no || run.reference).eq("source", "Check Run"),
      supabase.from("bank_transactions").select("id").eq("reference", run.check_run_no || run.reference).limit(1),
    ]);
    if (originalLedgerError) throw originalLedgerError;
    if (originalBankError) throw originalBankError;
    const wasPosted = /printed|cleared|posted/i.test(run.status || "") || originalLedger?.length || originalBank?.length;
    if (wasPosted) await postCheckRunVoidLedger(run, details.voidDate, details.reason);
    const notes = `${run.notes || ""}\n[VOID ${formatDisplayDate(details.voidDate)}] ${details.reason}`.trim();
    await supabase.from("check_runs").update({ status: "Void", notes }).eq("check_run_no", checkRunNo);
    for (const ref of splitCheckRunReferences(run.reference)) {
      await supabase.from("purchase_orders").update({ payment_status: "Ready to Pay" }).eq("po_no", ref);
    }
    alert("Check was voided. The related payable documents are back in Payables Ready for Check Run.");
    renderCheckRunView();
  } catch (error) {
    alert(error.message || error);
  }
}

function promptCheckVoidDetails(documentLabel) {
  const enteredDate = prompt(`Voiding date for ${documentLabel}\n\nEnter as mm/dd/yyyy. This date controls the accounting posting period.`, formatDisplayDate(today()));
  if (enteredDate === null) return null;
  const voidDate = parseFlexibleDate(enteredDate);
  if (!voidDate) {
    alert("Enter a valid voiding date as mm/dd/yyyy.");
    return null;
  }
  if (voidDate > today()) {
    alert("Voiding date cannot be in the future.");
    return null;
  }
  if (isLockedAccountingDate(voidDate)) {
    alert(`Voiding date ${formatDisplayDate(voidDate)} is inside a closed accounting period. Choose a date in an open period.`);
    return null;
  }
  const enteredReason = prompt(`Reason for voiding ${documentLabel}\n\nEnter Reprint or Unusable.`, "Reprint");
  if (enteredReason === null) return null;
  const reason = enteredReason.trim().toLowerCase();
  if (!new Set(["reprint", "unusable"]).has(reason)) {
    alert('The void reason must be either "Reprint" or "Unusable".');
    return null;
  }
  return { voidDate, reason: reason === "reprint" ? "Reprint" : "Unusable" };
}

async function printCheckRun(checkRunNo, draftOnly = false) {
  const { data: row, error: rowError } = await supabase.from("check_runs").select("*").eq("check_run_no", checkRunNo).maybeSingle();
  if (rowError || !row) return alert(rowError?.message || "Check run was not found.");
  const vendors = await getAll("vendors").catch(() => []);
  const vendor = vendors.find((v) => String(v.name || "").trim().toLowerCase() === String(row.vendor || "").trim().toLowerCase());
  const detail = parseCheckRunNotes(row.notes);
  const invoices = detail.invoices.length ? detail.invoices : [{
    reference: row.reference || "",
    invoice_no: row.invoice_no || "",
    invoice_date: row.invoice_date || "",
    due_date: row.due_date || "",
    amount: Number(row.amount || 0),
    wo_no: row.wo_no || "N/A",
    po_no: row.po_no || row.reference || "",
    jobsite: row.jobsite || "N/A",
    equipment: row.equipment || "N/A",
    parts_description: row.parts_description || "N/A",
  }];
  const amount = Number(row.amount || 0);
  const html = checkPrintHtml(row, vendor, invoices, amount, detail.userNotes, draftOnly);
  const win = openInAppDocumentWindow(draftOnly ? "Check Draft" : "Check");
  if (!win) return alert("Allow popups to print checks.");
  win.document.write(partNumberWording(html));
  win.document.close();
  if (draftOnly) return;
  if (row.check_run_no && !/printed|cleared|void/i.test(row.status || "")) {
    try {
      await postCheckRunLedger({ ...row, status: "Posted" });
      const payableRefs = [...new Set([
        ...splitCheckRunDocumentValues(row.reference),
        ...splitCheckRunDocumentValues(row.po_no),
        ...(detail.invoices || []).map((invoice) => invoice.po_no || invoice.reference),
      ].map((value) => String(value || "").trim()).filter(Boolean))];
      for (const ref of payableRefs) {
        const { data: paidRows, error: paidError } = await supabase.from("purchase_orders").update({ payment_status: "Paid" }).eq("po_no", ref).select("id,po_no,payment_status");
        if (paidError) throw new Error(`Could not mark PO ${ref} Paid: ${paidError.message || paidError}`);
        // Direct/manual AP invoices use their invoice reference in the PO column
        // even though no purchase_orders row exists. Their paid state is derived
        // from the printed Check Run and its AP ledger debit, so they must not
        // block Final Print.
        if (!(paidRows || []).length) console.info(`Check Run payable ${ref} is not a Purchase Order; paid status will be derived from the posted payment.`);
      }
    } catch (postingError) {
      return alert(`The check opened, but accounting was not posted: ${postingError.message || postingError}`);
    }
    const { error } = await supabase.from("check_runs").update({ status: "Printed" }).eq("check_run_no", row.check_run_no);
    if (error) return alert(`The check opened for printing, but its status could not be changed to Printed: ${error.message}`);
    row.status = "Printed";
    await renderCheckRunView();
  }
}

