function openInventoryCountSheet() {
  if (!canApproveInventoryControl()) {
    alert("Only an Administrator or Manager can post physical inventory count corrections.");
    return;
  }
  const matchingRows = inventoryCountSourceRows();
  const rows = matchingRows.slice(0, PRODUCT_RENDER_LIMIT);
  const draft = loadInventoryCountDraft();
  inventoryCountSessionRows = matchingRows;
  inventoryCountSessionItems = { ...(draft?.items || {}) };
  if (!rows.length) return alert("No products match the current Product Master filters.");
  $("modalTitle").textContent = "Inventory count sheet";
  $("modalBody").innerHTML = `
    <div class="form-grid">
      ${productInput("Count date", "count_date", draft?.count_date || today(), "date")}
      <div class="field wide"><label>Count reason / approval note</label><textarea data-product-field="count_reason" required placeholder="Example: Monthly physical count - Mall Lot Parts Shop">${esc(draft?.reason || "")}</textarea></div>
      <div class="field wide"><label>Search parts</label><input id="inventoryCountSearch" placeholder="Search SKU, product, warehouse, bin, category" autocomplete="off"><small>Search only changes what is visible; entered counts remain saved on the sheet.</small></div>
    </div>
    <div class="actions table-actions"><button type="button" class="rowbtn" id="downloadInventoryCountSheetBtn">Download blank count sheet</button><button type="button" class="rowbtn" id="saveInventoryCountDraftBtn">Save &amp; Continue Later</button><button type="button" class="primary" id="implementInventoryCountBtn">Save &amp; Implement Inventory Adjustment</button></div>
    <p class="notice" id="inventoryCountResultNotice">${matchingRows.length > PRODUCT_RENDER_LIMIT ? `${matchingRows.length.toLocaleString()} products match the current filters. The first ${PRODUCT_RENDER_LIMIT.toLocaleString()} are shown initially; Search Parts searches all ${matchingRows.length.toLocaleString()} products.` : `${matchingRows.length.toLocaleString()} products available for this count.`}</p>
    <div class="table-wrap"><table class="line-table"><thead><tr><th>SKU</th><th>Product</th><th>Warehouse</th><th>Bin / Shelf</th><th>Unit</th><th>System Qty</th><th>Counted Qty</th><th>Variance</th><th>Unit Cost</th><th>Value Variance</th></tr></thead><tbody id="inventoryCountBody">
      ${rows.map((product) => inventoryCountRowHtml(product, draft?.items?.[product.sku])).join("")}
    </tbody></table></div>
    <p class="notice">All matching active products are included, including products with zero quantity or Out status. Enter only products physically counted. If Product Master cost is zero, enter the verified unit cost here. Save &amp; Continue Later stores a draft on this device without changing inventory. Save &amp; Implement posts the approved quantity adjustments, eligible missing costs, stock movements, accounting entries, and audit history.</p>`;
  $("modalSave").style.display = "none";
  $("modalCancel").textContent = "Cancel";
  document.querySelector(".modalbox")?.classList.add("wide-modal");
  $("modal").style.display = "flex";
  bindInventoryCountRows();
  $("downloadInventoryCountSheetBtn").onclick = () => downloadInventoryCountSheet(rows);
  $("saveInventoryCountDraftBtn").onclick = saveInventoryCountDraft;
  $("implementInventoryCountBtn").onclick = saveInventoryCountSheet;
  $("inventoryCountSearch").oninput = filterInventoryCountRows;
}

function inventoryCountSourceRows() {
  const query = String($("productSearch")?.value || "").trim().toLowerCase();
  const category = $("productCategoryFilter")?.value || "";
  const warehouse = $("productWarehouseFilter")?.value || "";
  return (currentRows || []).filter((product) => {
    const searchOk = !query || [product.sku, product.name, product.source_vendor, product.category, product.warehouse, product.bin_shelf, product.compatible_with].join(" ").toLowerCase().includes(query);
    const active = !/inactive|deactivated/i.test(String(product.status || ""));
    return active && searchOk && (!category || product.category === category) && (!warehouse || product.warehouse === warehouse);
  });
}

function inventoryCountRowHtml(product, draftItem = null) {
  const searchText = inventoryCountProductSearchText(product);
  const cost = draftItem?.cost ?? product.cost ?? 0;
  return `<tr data-inventory-count-row="${esc(product.sku)}" data-count-search="${esc(searchText)}">
    <td>${esc(product.sku)}</td><td>${esc(product.name || "")}</td><td>${esc(product.warehouse || "")}</td><td>${esc(product.bin_shelf || "")}</td><td>${esc(product.unit || "")}</td>
    <td data-system-qty>${esc(Number(product.qty || 0))}</td>
    <td><input type="number" min="0" step="0.01" data-inventory-count="${esc(product.sku)}" value="${esc(draftItem?.counted_qty ?? "")}" placeholder="Enter count"></td>
    <td data-count-variance></td><td><input type="number" min="0" step="0.0001" data-inventory-count-cost="${esc(product.sku)}" value="${esc(cost)}" ${Number(product.cost || 0) > 0 ? "readonly" : ""} placeholder="Enter verified cost"></td><td data-count-value></td>
  </tr>`;
}

function filterInventoryCountRows() {
  captureInventoryCountVisibleRows();
  const query = String($("inventoryCountSearch")?.value || "").trim().toLowerCase();
  const matches = inventoryCountSessionRows.filter((product) => !query || inventoryCountProductSearchText(product).includes(query));
  const visible = matches.slice(0, PRODUCT_RENDER_LIMIT);
  $("inventoryCountBody").innerHTML = visible.map((product) => inventoryCountRowHtml(product, inventoryCountSessionItems[product.sku])).join("");
  const notice = $("inventoryCountResultNotice");
  if (notice) notice.textContent = query
    ? `${matches.length.toLocaleString()} product${matches.length === 1 ? "" : "s"} match “${query}”.${matches.length > PRODUCT_RENDER_LIMIT ? ` Showing the first ${PRODUCT_RENDER_LIMIT.toLocaleString()}.` : ""}`
    : `${inventoryCountSessionRows.length.toLocaleString()} products are available. Showing the first ${Math.min(PRODUCT_RENDER_LIMIT, inventoryCountSessionRows.length).toLocaleString()}; Search Parts searches the full list.`;
  bindInventoryCountRows();
}

function inventoryCountProductSearchText(product) {
  return [product.sku, product.name, product.source_vendor, product.warehouse, product.bin_shelf, product.category, product.barcode].filter(Boolean).join(" ").toLowerCase();
}

function bindInventoryCountRows() {
  document.querySelectorAll("[data-inventory-count], [data-inventory-count-cost]").forEach((input) => input.oninput = () => {
    refreshInventoryCountRow(input.closest("tr"));
    captureInventoryCountVisibleRows();
  });
  document.querySelectorAll("[data-inventory-count-row]").forEach(refreshInventoryCountRow);
}

function captureInventoryCountVisibleRows() {
  document.querySelectorAll("[data-inventory-count-row]").forEach((row) => {
    const sku = row.dataset.inventoryCountRow;
    const qty = row.querySelector("[data-inventory-count]");
    const cost = row.querySelector("[data-inventory-count-cost]");
    if (!sku) return;
    if (qty?.value !== "" || cost?.value !== "") inventoryCountSessionItems[sku] = { counted_qty: qty?.value || "", cost: cost?.value || "" };
    else delete inventoryCountSessionItems[sku];
  });
}

function refreshInventoryCountRow(row) {
  if (!row) return;
  const input = row.querySelector("[data-inventory-count]");
  const costInput = row.querySelector("[data-inventory-count-cost]");
  const product = (currentRows || []).find((item) => item.sku === input?.dataset.inventoryCount);
  if (!input || !product || input.value === "") {
    if (row.querySelector("[data-count-variance]")) row.querySelector("[data-count-variance]").textContent = "";
    if (row.querySelector("[data-count-value]")) row.querySelector("[data-count-value]").textContent = "";
    return;
  }
  const variance = Number(input.value || 0) - Number(product.qty || 0);
  row.querySelector("[data-count-variance]").textContent = Number(variance.toFixed(4));
  row.querySelector("[data-count-value]").textContent = money(variance * Number(costInput?.value || product.cost || 0));
}

function downloadInventoryCountSheet(rows) {
  downloadCsv([
    ["SKU", "Product", "Warehouse", "Bin / Shelf", "Unit", "System Qty", "Counted Qty", "Variance", "Unit Cost", "Notes"],
    ...rows.map((product) => [product.sku, product.name, product.warehouse, product.bin_shelf, product.unit, Number(product.qty || 0), "", "", Number(product.cost || 0), ""]),
  ], `inventory-count-sheet-${today()}.csv`);
}

const INVENTORY_COUNT_DRAFT_KEY = "lms_inventory_count_draft_v1";
let inventoryCountSessionRows = [];
let inventoryCountSessionItems = {};

function loadInventoryCountDraft() {
  try { return JSON.parse(localStorage.getItem(INVENTORY_COUNT_DRAFT_KEY) || "null"); } catch { return null; }
}

function inventoryCountFormState() {
  captureInventoryCountVisibleRows();
  return {
    count_date: document.querySelector('[data-product-field="count_date"]')?.value || today(),
    reason: String(document.querySelector('[data-product-field="count_reason"]')?.value || "").trim(),
    items: { ...inventoryCountSessionItems },
    saved_at: new Date().toISOString(),
  };
}

function saveInventoryCountDraft() {
  localStorage.setItem(INVENTORY_COUNT_DRAFT_KEY, JSON.stringify(inventoryCountFormState()));
  alert("Inventory count draft saved on this device. You can close the window and continue later.");
}

async function saveInventoryCountSheet() {
  const countDate = document.querySelector('[data-product-field="count_date"]')?.value || today();
  const reason = String(document.querySelector('[data-product-field="count_reason"]')?.value || "").trim();
  if (!reason) return alert("Count reason / approval note is required.");
  if (isLockedAccountingDate(countDate)) return alert("This count date is inside the closed accounting period.");
  captureInventoryCountVisibleRows();
  const counted = Object.entries(inventoryCountSessionItems).filter(([, item]) => item?.counted_qty !== "").map(([sku, item]) => {
    const product = (currentRows || []).find((row) => row.sku === sku);
    const countedQty = Number(item.counted_qty);
    const unitCost = Number(item.cost || product?.cost || 0);
    return { product, countedQty, unitCost, variance: countedQty - Number(product?.qty || 0) };
  });
  if (!counted.length) return alert("Enter at least one physical Counted Qty.");
  if (counted.some((row) => !row.product || !Number.isFinite(row.countedQty) || row.countedQty < 0)) return alert("Every counted quantity must be a valid number of zero or more.");
  if (counted.some((row) => !Number.isFinite(row.unitCost) || row.unitCost < 0)) return alert("Every unit cost must be a valid number of zero or more.");
  const missingCost = counted.find((row) => Math.abs(row.variance) > 0.000001 && Number(row.product.cost || 0) <= 0 && row.unitCost <= 0);
  if (missingCost) return alert(`Enter the verified unit cost for ${missingCost.product.sku} before implementing its inventory variance.`);
  const corrections = counted.filter((row) => Math.abs(row.variance) > 0.000001);
  const costUpdates = counted.filter((row) => Number(row.product.cost || 0) <= 0 && row.unitCost > 0);
  const totalVariance = corrections.reduce((sum, row) => sum + row.variance, 0);
  const valueVariance = corrections.reduce((sum, row) => sum + row.variance * row.unitCost, 0);
  if (!corrections.length && !costUpdates.length) {
    alert(`${counted.length} product${counted.length === 1 ? " was" : "s were"} counted with no variance. No correction was posted.`);
    return;
  }
  if (!confirm(`Implement this inventory count?\n\nQuantity corrections: ${corrections.length}\nMissing costs to update: ${costUpdates.length}\nNet quantity variance: ${Number(totalVariance.toFixed(4))}\nNet value variance: ${money(valueVariance)}\n\nThis creates stock movement, accounting, and audit entries.`)) return;
  const batch = Date.now().toString();
  try {
    for (let index = 0; index < corrections.length; index += 1) {
      const { product, countedQty, variance, unitCost } = corrections[index];
      const reference = `COUNT-${batch}-${index + 1}`;
      const record = { reference_no: reference, movement_date: countDate, type: "Physical Count" };
      await upsertOneWithOptionalColumns("stock_movements", {
        ...record,
        product_id: product.id,
        sku: product.sku,
        product_name: product.name,
        qty: variance,
        from_warehouse: variance < 0 ? product.warehouse || null : null,
        from_bin_shelf: variance < 0 ? product.bin_shelf || null : null,
        to_warehouse: variance > 0 ? product.warehouse || null : null,
        to_bin_shelf: variance > 0 ? product.bin_shelf || null : null,
        unit_fifo_cost: unitCost,
        total_fifo_cost: Math.abs(variance) * unitCost,
        document_no: `COUNT-${countDate}`,
        entered_by: profile?.full_name || profile?.username || session?.user?.email || "Manager",
        reason: `${reason} | System ${Number(product.qty || 0)}, counted ${countedQty}`,
      }, "reference_no", ["from_bin_shelf", "to_bin_shelf"], "Count correction saved. Run the multi-location SQL update so bin/shelf details can be stored.");
      const productUpdate = { qty: countedQty };
      if (Number(product.cost || 0) <= 0 && unitCost > 0) productUpdate.cost = unitCost;
      const { error } = await supabase.from("products").update(productUpdate).eq("id", product.id);
      if (error) throw error;
      await postStockCorrectionLedger(record, product, variance, unitCost);
    }
    for (const row of costUpdates.filter((item) => !corrections.includes(item))) {
      const { error } = await supabase.from("products").update({ cost: row.unitCost }).eq("id", row.product.id);
      if (error) throw error;
    }
    await writeAuditLog({ tableName: "products", action: "Physical Count", beforeData: null, afterData: { count_date: countDate, reason, corrections: corrections.map(({ product, countedQty, variance, unitCost }) => ({ sku: product.sku, system_qty: Number(product.qty || 0), counted_qty: countedQty, variance, unit_cost: unitCost })), cost_updates: costUpdates.map(({ product, unitCost }) => ({ sku: product.sku, previous_cost: Number(product.cost || 0), unit_cost: unitCost })) } });
    localStorage.removeItem(INVENTORY_COUNT_DRAFT_KEY);
    closeModal();
    await renderProductsView();
    alert(`Inventory count implemented successfully: ${corrections.length} quantity correction${corrections.length === 1 ? "" : "s"} and ${costUpdates.length} missing-cost update${costUpdates.length === 1 ? "" : "s"}.`);
  } catch (error) {
    alert(error.message || error);
  }
}

async function renderStockMovementView() {
  currentCfg = tableMap.movements;
  $("viewTitle").textContent = "Stock Movement";
  $("viewSub").textContent = "Receive, sell, adjust, transfer, reserve, and audit stock.";
  const [movements, products, receipts, salesOrders, salesLines, workOrders, workOrderParts, warehouses, assets, outsideFleet] = await Promise.all([
    getAll("stock_movements"),
    getAll("products"),
    getAll("goods_receipts"),
    getAll("sales_orders"),
    getAll("sales_order_lines"),
    getAll("work_orders"),
    getAll("work_order_parts"),
    getAll("warehouses"),
    getAll("assets"),
    getAll("outside_customer_fleet"),
  ]);
  currentRows = buildLinkedStockMovements({ movements, products, receipts, salesOrders, salesLines, workOrders, workOrderParts, assets, outsideFleet });
  productMeta.products = products.sort((a, b) => String(a.sku).localeCompare(String(b.sku)));
  productMeta.purchaseCostHistory = buildPurchaseCostHistory(pos, lines, receipts);
  productMeta.warehouses = warehouses.map((v) => v.name).filter(Boolean).sort();
  $("content").innerHTML = `
    <div class="toolbar">
      <input class="searchbox" id="movementSearch" placeholder="Search stock ledger by product, SKU, type, reference, location">
    </div>
    <section class="panel">
      <div class="panel-head"><div class="panel-title"><strong>Stock Ledger</strong><span>Read-only movement history. Sales, work orders, and goods receipts post here automatically.</span></div><div class="actions">${dateRangeControls("movement")}<button id="movementApplyDates">Apply dates</button><button id="movementCsvBtn">Excel</button><button onclick="window.print()">PDF / Print</button><button id="physicalCountBtn">Physical count variance</button><button class="primary" id="correctionBtn">Approved correction</button></div></div>
      <div id="movementTableHost">${stockMovementTableHtml(currentRows)}</div>
    </section>`;
  $("movementSearch").oninput = renderFilteredStockMovements;
  $("movementApplyDates").onclick = renderFilteredStockMovements;
  $("movementCsvBtn").onclick = exportCurrentCsv;
  $("correctionBtn").onclick = () => openStockCorrectionModal("Adjustment");
  $("physicalCountBtn").onclick = () => openStockCorrectionModal("Count");
  document.querySelectorAll(".column-filter").forEach((input) => input.oninput = applyColumnFilters);
  bindStockMovementRows();
}

function renderFilteredStockMovements() {
  const q = ($("movementSearch")?.value || "").toLowerCase();
  const from = $("movementFrom")?.value || "";
  const to = $("movementTo")?.value || "";
  const rows = currentRows.filter((row) => {
    const date = String(row.movement_date || "");
    return (!q || Object.values(row).join(" ").toLowerCase().includes(q)) && (!from || date >= from) && (!to || date <= to);
  });
  $("movementTableHost").innerHTML = stockMovementTableHtml(rows);
  document.querySelectorAll(".column-filter").forEach((input) => input.oninput = applyColumnFilters);
  bindStockMovementRows();
}

function stockMovementTableHtml(rows) {
  const heads = ["Date", "Reference #", "Type", "Product", "Vendor", "Sold To", "Sold Date", "Asset #", "Equipment Name", "Qty", "From Warehouse", "From Bin", "To Warehouse", "To Bin", "Unit FIFO Cost", "Total FIFO Cost", "Document", "Entered By", "Reason"];
  const fields = ["movement_date", "reference_no", "type", "product_name", "vendor", "sold_to", "sold_date", "asset_tag", "equipment_name", "qty", "from_warehouse", "from_bin_shelf", "to_warehouse", "to_bin_shelf", "unit_fifo_cost", "total_fifo_cost", "document_no", "entered_by", "reason"];
  return `<div class="table-wrap"><table><thead><tr>${heads.map((h) => `<th>${esc(h)}</th>`).join("")}</tr><tr>${heads.map((h, i) => `<th><input class="column-filter" data-col="${i}" placeholder="Filter ${esc(h)}"></th>`).join("")}</tr></thead><tbody>${rows.length ? rows.map((row) => `<tr>${fields.map((h) => `<td>${stockMovementCell(h, row)}</td>`).join("")}</tr>`).join("") : `<tr><td colspan="${heads.length}" class="empty">No stock movement yet.</td></tr>`}</tbody></table></div>`;
}

function stockMovementCell(field, row) {
  if (field === "product_name") return `${esc(row.product_name || "")}${row.sku ? `<br><span class="muted">${esc(row.sku)}</span>` : ""}`;
  if (field === "document_no") return row.document_no ? `<button class="linkbtn" type="button" data-doc-link="${esc(row.document_no)}">${esc(row.document_no)}</button>` : "";
  if (/cost/.test(field)) return money(row[field]);
  return esc(row[field] ?? "");
}

function dateRangeControls(prefix) {
  return `<label class="mini-filter">From <input type="date" id="${prefix}From"></label><label class="mini-filter">To <input type="date" id="${prefix}To"></label>`;
}

function bindStockMovementRows() {
  document.querySelectorAll("[data-doc-link]").forEach((b) => b.onclick = async () => {
    const ref = b.dataset.docLink || "";
    const purchaseOrder = (await getAll("purchase_orders")).find((po) => String(po.po_no || "").trim().toLowerCase() === ref.trim().toLowerCase());
    if (purchaseOrder) {
      await loadView("purchasing");
      return openPurchaseOrderRecord(currentRows.find((po) => String(po.po_no || "").trim().toLowerCase() === ref.trim().toLowerCase()));
    }
    if (/^PO-/i.test(ref)) loadView("purchasing");
    else if (/^SO-/i.test(ref)) loadView("orders");
    else if (/^(?:WO-|W\d)/i.test(ref)) loadView("repairs");
    else if (/^GR-/i.test(ref)) loadView("receipts");
  });
}

function buildLinkedStockMovements({ movements = [], products = [], receipts = [], salesOrders = [], salesLines = [], workOrders = [], workOrderParts = [], assets = [], outsideFleet = [] }) {
  const productById = new Map(products.map((p) => [p.id, p]));
  const productBySku = new Map(products.map((p) => [p.sku, p]));
  const workOrdersByNumber = new Map(workOrders.map((wo) => [String(wo.wo_no || "").trim().toLowerCase(), wo]).filter(([number]) => number));
  const workOrderNumbers = [...workOrdersByNumber.keys()].sort((a, b) => b.length - a.length);
  const workOrderForMovement = (row = {}) => {
    const explicit = [row.wo_no, row.work_order_no, row.source_wo_no, row.document_no]
      .map((value) => String(value || "").trim().toLowerCase())
      .find((value) => workOrdersByNumber.has(value));
    if (explicit) return workOrdersByNumber.get(explicit);
    const searchable = [row.reference_no, row.document_no, row.reason].filter(Boolean).join(" ").toLowerCase();
    const number = workOrderNumbers.find((candidate) => {
      const start = searchable.indexOf(candidate);
      if (start < 0) return false;
      const before = searchable[start - 1] || " ";
      const after = searchable[start + candidate.length] || " ";
      return !/[a-z0-9]/i.test(before) && !/[a-z0-9]/i.test(after);
    });
    return number ? workOrdersByNumber.get(number) : null;
  };
  const equipmentForWorkOrder = (wo = {}) => {
    if (!wo) return { asset_tag: "", equipment_name: "" };
    const details = workOrderAssetDetailsFromLists(wo, assets, outsideFleet);
    return { asset_tag: wo.asset_tag || "", equipment_name: details.name || "" };
  };
  const seen = new Set();
  const rows = [];
  const push = (row) => {
    if (!row.reference_no || seen.has(row.reference_no)) return;
    seen.add(row.reference_no);
    const p = productById.get(row.product_id) || productBySku.get(row.sku) || {};
    const relatedWorkOrder = workOrderForMovement(row);
    const equipment = equipmentForWorkOrder(relatedWorkOrder);
    rows.push({
      ...row,
      product_id: row.product_id || p.id || null,
      sku: row.sku || p.sku || "",
      product_name: row.product_name || p.name || "Deleted item",
      vendor: row.vendor || p.source_vendor || "",
      unit_fifo_cost: Number(row.unit_fifo_cost ?? p.cost ?? 0),
      total_fifo_cost: Number(row.total_fifo_cost ?? Math.abs(Number(row.qty || 0)) * Number(row.unit_fifo_cost ?? p.cost ?? 0)),
      entered_by: row.entered_by || "System",
      asset_tag: row.asset_tag || equipment.asset_tag,
      equipment_name: row.equipment_name || equipment.equipment_name,
    });
  };

  movements.forEach((m) => push(m));

  receipts.forEach((gr) => push({
    reference_no: `SM-${gr.gr_no}`,
    movement_date: gr.gr_date,
    type: "Goods Receipt",
    product_id: gr.product_id,
    sku: gr.sku,
    product_name: gr.product_name,
    vendor: gr.vendor,
    qty: Number(gr.received_qty || 0),
    to_warehouse: gr.receipt_warehouse || productById.get(gr.product_id)?.warehouse || "",
    to_bin_shelf: gr.receipt_bin_shelf || productById.get(gr.product_id)?.bin_shelf || "",
    unit_fifo_cost: Number(gr.unit_cost || 0),
    total_fifo_cost: Number(gr.received_qty || 0) * Number(gr.unit_cost || 0),
    document_no: gr.po_no || gr.gr_no,
    reason: `${gr.gr_no} received from ${gr.po_no || "purchase"}`,
    entered_by: gr.received_by || "System",
  }));

  const orderById = new Map(salesOrders.map((o) => [o.id, o]));
  salesLines.forEach((line) => {
    const order = orderById.get(line.order_id);
    if (!order || !/fulfilled|posted|paid/i.test(order.status || "")) return;
    const p = productById.get(line.product_id) || productBySku.get(line.sku) || {};
    push({
      reference_no: `SM-${order.order_no}-${line.sku}`,
      movement_date: order.order_date,
      type: "Sale Issue",
      product_id: line.product_id || p.id,
      sku: line.sku,
      product_name: line.product_name,
      vendor: p.source_vendor || "",
      sold_to: order.customer,
      sold_date: order.order_date,
      qty: -Math.abs(Number(line.qty || 0)),
      from_warehouse: p.warehouse || "",
      from_bin_shelf: p.bin_shelf || "",
      unit_fifo_cost: Number(p.cost || 0),
      total_fifo_cost: Math.abs(Number(line.qty || 0)) * Number(p.cost || 0),
      document_no: order.order_no,
      wo_no: line.wo_no || order.wo_no || order.work_order_no || order.source_wo_no || "",
      reason: `Order ${order.order_no}`,
      entered_by: "System",
    });
  });

  const woById = new Map(workOrders.map((wo) => [wo.id, wo]));
  workOrderParts.forEach((part, index) => {
    const acceptedQty = Number(part.accepted_qty || 0);
    if (!acceptedQty || !/accepted|used|issued|complete/i.test(effectivePartStatus(part))) return;
    const wo = woById.get(part.wo_id) || {};
    const p = productById.get(part.product_id) || productBySku.get(part.sku) || {};
    push({
      reference_no: `SM-${wo.wo_no || "WO"}-${part.sku}-${index + 1}`,
      movement_date: wo.wo_date || today(),
      type: "Repair",
      product_id: part.product_id || p.id,
      sku: part.sku,
      product_name: part.product_name,
      vendor: p.source_vendor || "",
      qty: -Math.abs(acceptedQty),
      from_warehouse: p.warehouse || "",
      from_bin_shelf: p.bin_shelf || "",
      unit_fifo_cost: Number(part.unit_cost || p.cost || 0),
      total_fifo_cost: Math.abs(acceptedQty) * Number(part.unit_cost || p.cost || 0),
      document_no: wo.wo_no || "",
      wo_no: wo.wo_no || "",
      asset_tag: wo.asset_tag || "",
      equipment_name: workOrderAssetDetailsFromLists(wo, assets, outsideFleet).name || "",
      reason: part.issue || "Work order part",
      entered_by: "System",
    });
  });

  return rows.sort((a, b) => String(b.movement_date || "").localeCompare(String(a.movement_date || "")));
}

function openStockCorrectionModal(defaultType = "Adjustment") {
  if (!canApproveInventoryControl()) {
    alert("Only an Administrator or Manager can post inventory corrections or physical-count variances.");
    return;
  }
  const reference = `SM-${Date.now().toString().slice(-6)}`;
  $("modalTitle").textContent = "Approved stock correction";
  $("modalBody").innerHTML = `
    <div class="form-grid">
      ${productInput("Reference #", "reference_no", reference)}
      ${productInput("Date", "movement_date", today(), "date")}
      ${productSelect("Type", "type", ["Adjustment", "Count", "Transfer"], defaultType)}
      <div class="field"><label>Product</label><input class="suggest-input" list="poProductOptions" data-product-field="product_lookup" placeholder="Search SKU, name, vendor" autocomplete="off">${productOptionsDatalist()}</div>
      ${productInput("Qty change", "qty", "", "number")}
      <div class="field"><label>From warehouse</label>${suggestInput("stockFromWarehouse", productMeta.warehouses || [], "", "From warehouse").replace(">", ' data-product-field="from_warehouse">')}</div>
      ${productInput("From bin / shelf", "from_bin_shelf", "")}
      <div class="field"><label>To warehouse</label>${suggestInput("stockToWarehouse", productMeta.warehouses || [], "", "To warehouse").replace(">", ' data-product-field="to_warehouse">')}</div>
      ${productInput("To bin / shelf", "to_bin_shelf", "")}
      ${productInput("Unit FIFO cost", "unit_fifo_cost", "", "number")}
      ${productInput("Document", "document_no", "")}
      <div class="field wide"><label>Reason / approval note</label><textarea data-product-field="reason"></textarea></div>
    </div>
    <p class="notice">Use this only for approved corrections. For a physical count, enter the variance—not the final counted balance. Positive quantity adds stock; negative quantity removes stock. The expected quantity is not displayed in this entry popup.</p>`;
  $("modalSave").onclick = saveStockCorrectionModal;
  $("modal").style.display = "flex";
}

async function saveStockCorrectionModal() {
  const record = {};
  document.querySelectorAll("[data-product-field]").forEach((el) => record[el.dataset.productField] = el.value || null);
  const product = resolveProductLookup(record.product_lookup);
  if (!product) {
    alert("Choose a valid product before posting the correction.");
    return;
  }
  if (!record.reason) {
    alert("Reason / approval note is required.");
    return;
  }
  const qty = Number(record.qty || 0);
  if (!qty) {
    alert("Qty change cannot be zero.");
    return;
  }
  if (isLockedAccountingDate(record.movement_date)) {
    alert("This inventory correction date is inside the closed accounting period.");
    return;
  }
  if (qty < 0 && Math.abs(qty) > Number(product.qty || 0)) {
    alert(`This correction would create negative inventory. ${product.sku} has only ${product.qty || 0} available.`);
    return;
  }
  const isTransfer = /transfer/i.test(record.type || "");
  if (isTransfer && (!record.from_warehouse || !record.from_bin_shelf || !record.to_warehouse || !record.to_bin_shelf)) {
    alert("Transfers require From Warehouse, From Bin/Shelf, To Warehouse, and To Bin/Shelf.");
    return;
  }
  if (!isTransfer && qty > 0 && (!record.to_warehouse || !record.to_bin_shelf)) {
    alert("Positive inventory corrections require the destination warehouse and bin/shelf.");
    return;
  }
  if (!isTransfer && qty < 0 && (!record.from_warehouse || !record.from_bin_shelf)) {
    alert("Negative inventory corrections require the source warehouse and bin/shelf.");
    return;
  }
  const unitCost = Number(record.unit_fifo_cost || product.cost || 0);
  try {
    await upsertOneWithOptionalColumns("stock_movements", {
      reference_no: record.reference_no,
      movement_date: record.movement_date || today(),
      type: record.type || "Adjustment",
      product_id: product.id,
      sku: product.sku,
      product_name: product.name,
      qty,
      from_warehouse: record.from_warehouse,
      from_bin_shelf: record.from_bin_shelf,
      to_warehouse: record.to_warehouse || product.warehouse,
      to_bin_shelf: record.to_bin_shelf || product.bin_shelf,
      unit_fifo_cost: unitCost,
      total_fifo_cost: Math.abs(qty) * unitCost,
      document_no: record.document_no,
      entered_by: profile?.full_name || profile?.username || "Owner",
      reason: record.reason,
    }, "reference_no", ["from_bin_shelf", "to_bin_shelf"], "Stock correction saved. Run the multi-location SQL update so bin/shelf details can be stored.");
    const productQtyChange = /transfer/i.test(record.type || "") ? 0 : qty;
    await supabase.from("products").update({ qty: Number(product.qty || 0) + productQtyChange }).eq("id", product.id);
    if (productQtyChange) await postStockCorrectionLedger(record, product, qty, unitCost);
    closeModal();
    renderStockMovementView();
  } catch (error) {
    alert(error.message || error);
  }
}

async function postStockCorrectionLedger(record, product, qty, unitCost) {
  const total = Math.abs(Number(qty || 0) * Number(unitCost || 0));
  if (!total) return;
  const date = record.movement_date || today();
  const reference = record.reference_no;
  const description = `${record.type || "Stock correction"} ${product.sku} - ${product.name || ""}`;
  await supabase.from("general_ledger").delete().eq("reference", reference).eq("source", "Stock Correction");
  const rows = Number(qty || 0) > 0
    ? [
        { entry_date: date, posting_date: date, account: "Parts Inventory", description, reference, debit: total, credit: 0, source: "Stock Correction", status: "Posted" },
        { entry_date: date, posting_date: date, account: "Inventory Count Gain/Loss", description, reference, debit: 0, credit: total, source: "Stock Correction", status: "Posted" },
      ]
    : [
        { entry_date: date, posting_date: date, account: "Inventory Count Gain/Loss", description, reference, debit: total, credit: 0, source: "Stock Correction", status: "Posted" },
        { entry_date: date, posting_date: date, account: "Parts Inventory", description, reference, debit: 0, credit: total, source: "Stock Correction", status: "Posted" },
      ];
  await upsertMany("general_ledger", rows, "id");
}

async function renderPurchasingView() {
  currentCfg = tableMap.purchasing;
  $("viewTitle").textContent = "Purchasing";
  $("viewSub").textContent = "Issue POs, receive goods, match invoices, and release payments.";
  const [pos, lines, receipts, vendors, customers, products, workOrders, terms, incoterms, standardNotes, warehouses, fleet, locations, assetLocations, stockMovements] = await Promise.all([
    getAll("purchase_orders"),
    getAll("purchase_order_lines"),
    getAll("goods_receipts"),
    getAll("vendors"),
    getAll("customers"),
    getAll("products"),
    getAll("work_orders"),
    getAll("master_terms"),
    getAll("incoterms"),
    getAll("standard_po_notes"),
    getAll("warehouses"),
    getAll("assets").catch(() => []),
    getAll("locations").catch(() => []),
    getAll("asset_locations").catch(() => []),
    getAll("stock_movements").catch(() => []),
  ]);
  const reversedReceiptRefs = new Set((stockMovements || []).filter((row) => /goods receipt reversal/i.test(row.type || "") || /^REV-GR-/i.test(row.reference_no || "")).map((row) => String(row.reference_no || "").replace(/^REV-/, "")));
  receipts.forEach((gr) => { gr._has_reversal_movement = reversedReceiptRefs.has(String(gr.gr_no || "")); });
  currentRows = pos.filter((po) => !/manual journal ap/i.test(`${po.status || ""} ${po.notes || ""}`) && !isBeginningBalanceApRecord(po)).sort((a, b) => String(b.po_date || "").localeCompare(String(a.po_date || "")));
  const statusCorrections = [];
  currentRows.forEach((po) => {
    po._lines = lines.filter((line) => String(line.po_id || "") === String(po.id || "") || String(line.po_no || "") === String(po.po_no || ""));
    po._receipts = receipts.filter((gr) => String(gr.po_id || "") === String(po.id || "") || String(gr.po_no || "") === String(po.po_no || ""));
    const calculatedStatus = poReceiptStatus(po);
    const hasReceiptReversal = po._receipts.some((receipt) => isReversedGoodsReceipt(receipt));
    const receiptManagedStatus = /draft|issued|partially received|goods received/i.test(po.status || "");
    // A GR reversal must reopen a previously auto-closed PO so the remaining
    // quantity can be received again. Preserve manually closed POs only when
    // there is no receipt-reversal history driving the recalculation.
    const receiptReopenedClosedPo = /closed po/i.test(po.status || "") && hasReceiptReversal && calculatedStatus !== "Goods Received";
    const protectedStatus = /paid|cancel|void|reversed/i.test(`${po.status || ""} ${po.payment_status || ""}`)
      || (/closed po/i.test(po.status || "") && !receiptReopenedClosedPo);
    if ((receiptManagedStatus || receiptReopenedClosedPo) && !protectedStatus && String(po.status || "") !== calculatedStatus) {
      po.status = calculatedStatus;
      statusCorrections.push({ id: po.id, status: calculatedStatus });
      if (!activeReceipts(po).length) {
        po.vendor_invoice_no = null;
        po.vendor_invoice_date = null;
        po.vendor_invoice_amount = 0;
        po.match_status = "Awaiting Goods";
        po.payment_status = "Not Ready";
      }
    }
  });
  if (statusCorrections.length) {
    await Promise.allSettled(statusCorrections.map((row) => supabase.from("purchase_orders").update({ status: row.status }).eq("id", row.id)));
  }
  productMeta.vendors = vendors.map((v) => v.name).filter(Boolean).sort();
  productMeta.customers = customers.map((v) => v.name).filter(Boolean).sort();
  productMeta.products = products.sort((a, b) => String(a.sku).localeCompare(String(b.sku)));
  productMeta.warehouses = warehouses.map((v) => v.name).filter(Boolean).sort();
  productMeta.workOrders = (workOrders || []).sort((a, b) => String(a.wo_no || "").localeCompare(String(b.wo_no || "")));
  productMeta.openWorkOrders = (workOrders || []).filter(isOpenWorkOrder).sort((a, b) => String(a.wo_no || "").localeCompare(String(b.wo_no || "")));
  productMeta.terms = terms.map((t) => t.name).filter(Boolean).sort();
  productMeta.incoterms = incoterms.map((t) => t.name).filter(Boolean).sort();
  productMeta.standardPoNotes = standardNotes.sort((a, b) => String(a.title || "").localeCompare(String(b.title || "")));
  const jobsiteMap = new Map();
  const addJobsite = (value, source) => {
    const name = String(value || "").trim();
    if (!name || /^general$/i.test(name)) return;
    const key = name.toLowerCase();
    if (!jobsiteMap.has(key)) jobsiteMap.set(key, { name, source });
  };
  (fleet || []).forEach((asset) => [asset.location, asset.jobsite, asset.project, asset.jobsite_project].forEach((value) => addJobsite(value, "Fleet & Equipment")));
  (assetLocations || []).forEach((row) => addJobsite(row.name || row.location || row.value, "Fleet & Equipment Location"));
  (locations || []).forEach((row) => addJobsite(row.name || row.location || row.jobsite, "Saved Location"));
  (pos || []).forEach((row) => addJobsite(row.jobsite_project, "Purchase Order"));
  productMeta.purchaseJobsiteRows = [...jobsiteMap.values()]
    .sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true, sensitivity: "base" }));
  productMeta.purchaseJobsites = productMeta.purchaseJobsiteRows.map((row) => row.name);
  purchaseContext = { products: productMeta.products, vendors: productMeta.vendors, vendorRows: vendors, customers: productMeta.customers, openWorkOrders: productMeta.openWorkOrders, terms: productMeta.terms, incoterms: productMeta.incoterms, standardPoNotes: productMeta.standardPoNotes };
  $("content").innerHTML = `
    <div class="toolbar">
      <input class="searchbox" id="poSearch" placeholder="Search purchase orders by PO, vendor, invoice, product, match status">
    </div>
    <section class="panel">
      <div class="panel-head"><div class="panel-title"><strong>Purchase Orders</strong><span>PO issued, goods receipt, invoice matching, and accounting payment readiness</span></div><div class="actions"><button id="poCsvBtn">Excel</button><button onclick="window.print()">PDF / Print</button><button id="newLandedPoBtn">New landed cost PO</button><button class="primary" id="newPoBtn">New PO</button></div></div>
      <div class="tabs">
        <button class="${purchasingTab === "open" ? "active" : ""}" data-po-tab="open">Open PO ${purchaseRowsForTab(currentRows, "open").length}</button>
        <button class="${purchasingTab === "closed" ? "active" : ""}" data-po-tab="closed">Closed PO ${purchaseRowsForTab(currentRows, "closed").length}</button>
      </div>
      <div id="poTableHost">${purchaseOrderTableHtml(purchaseRowsForTab(currentRows, purchasingTab))}</div>
    </section>`;
  $("poSearch").oninput = renderFilteredPurchaseOrders;
  $("poCsvBtn").onclick = exportPurchaseOrdersCsv;
  $("newPoBtn").onclick = () => openPurchaseOrderModal();
  $("newLandedPoBtn").onclick = () => openLandedCostInvoiceModal();
  document.querySelectorAll("[data-po-tab]").forEach((btn) => btn.onclick = () => {
    purchasingTab = btn.dataset.poTab;
    document.querySelectorAll("[data-po-tab]").forEach((tab) => tab.classList.toggle("active", tab.dataset.poTab === purchasingTab));
    renderFilteredPurchaseOrders();
  });
  bindPurchaseRows();
}

function renderFilteredPurchaseOrders() {
  const q = $("poSearch").value.toLowerCase();
  const rows = purchaseRowsForTab(currentRows, purchasingTab).filter((po) => !q || [
    po.po_no, po.po_date, po.vendor, po.jobsite_project, po.purchase_purpose, po.linked_customer, po.ap_support_wo_no, po.linked_sales_order_no, po.vendor_invoice_no, po.match_status, po.payment_status, po.status,
    ...(po._lines || []).map((line) => `${line.sku} ${line.product_name}`)
  ].join(" ").toLowerCase().includes(q));
  $("poTableHost").innerHTML = purchaseOrderTableHtml(rows);
  bindPurchaseRows();
}

function purchaseRowsForTab(rows, tab = "open") {
  return (rows || []).filter((po) => tab === "closed" ? isClosedPurchaseOrder(po) : !isClosedPurchaseOrder(po));
}

function isClosedPurchaseOrder(po) {
  const text = `${po?.status || ""} ${po?.payment_status || ""}`.toLowerCase();
  return /paid|closed|cancel|void|reversed|goods received/.test(text) || poReceiptStatus(po) === "Goods Received";
}

function purchaseOrderPurpose(po = {}) {
  if (po.purchase_purpose) return po.purchase_purpose;
  if (po.linked_customer) return "Customer Order";
  if (po.ap_support_wo_no) return "Work Order";
  return "Inventory Stock";
}

function isCustomerPurchaseOrder(po = {}) {
  return purchaseOrderPurpose(po) === "Customer Order";
}

function isWorkOrderPurchaseOrder(po = {}) {
  return purchaseOrderPurpose(po) === "Work Order";
}

function isShopIssuancePurchaseOrder(po = {}) {
  return purchaseOrderPurpose(po) === "Shop Issuance";
}

function purchaseOrderShopIssuanceDetail(po = {}) {
  const text = String(po.notes || "");
  const match = text.match(/SHOP_ISSUANCE_DETAIL:(\{[^\n]*\})/);
  if (!match) return { charge_mode: "general_shop", issued_to: "General Shop", wo_no: po.ap_support_wo_no || "", issue: "Shop supplies issuance" };
  try {
    return { charge_mode: "general_shop", issued_to: "General Shop", wo_no: "", issue: "Shop supplies issuance", ...JSON.parse(match[1]) };
  } catch {
    return { charge_mode: "general_shop", issued_to: "General Shop", wo_no: po.ap_support_wo_no || "", issue: "Shop supplies issuance" };
  }
}

function purchaseOrderVisibleNotes(notes = "") {
  return String(notes || "").replace(/\n?SHOP_ISSUANCE_DETAIL:\{[^\n]*\}/g, "").trim();
}

function shopIssuancePoFields(detail = {}) {
  const mechanic = detail.charge_mode === "mechanic";
  const wo = detail.wo_no ? workOrderOptionLabel((productMeta.workOrders || []).find((row) => row.wo_no === detail.wo_no) || { wo_no: detail.wo_no }) : "";
  return `<div class="field wide" id="purchaseShopIssuanceFields"><label>Shop issuance destination</label><div class="supply-mode-picker">
    <label><input type="radio" name="poShopChargeMode" value="general_shop" ${mechanic ? "" : "checked"}><span><b>General Shop</b><small>Shared shop supplies and consumables</small></span></label>
    <label><input type="radio" name="poShopChargeMode" value="mechanic" ${mechanic ? "checked" : ""}><span><b>Mechanic Issuance</b><small>Assign received supplies directly to a mechanic</small></span></label>
  </div><div class="form-grid">
    <div class="field" id="purchaseShopMechanicField"><label>Mechanic</label><select id="purchaseShopMechanic"><option value="">Select mechanic</option>${(productMeta.mechanics || []).map((name) => `<option value="${esc(name)}" ${name === detail.issued_to ? "selected" : ""}>${esc(name)}</option>`).join("")}</select></div>
    <div class="field"><label>Work order (optional)</label><input class="suggest-input" data-suggest-source="work_orders" id="purchaseShopWorkOrder" value="${esc(wo)}" placeholder="Type WO, asset, customer, or status" autocomplete="off"><small>Results appear after typing.</small></div>
    <div class="field"><label>Issue / use</label><input id="purchaseShopIssue" value="${esc(detail.issue || "Shop supplies issuance")}"></div>
  </div><small>Each Goods Receipt automatically creates a linked issuance for the quantity received.</small></div>`;
}

function purchaseOrderTableHtml(rows) {
  const heads = ["Actions", "PO", "Status", "Date", "Vendor", "Jobsite / Project", "Work Order", "Purpose / Customer", "Terms", "Incoterm", "Currency", "Parts", "Freight", "Landed Add", "PO Total", "Received", "Invoice", "Match", "Payment"];
  return `<div class="table-wrap purchase-order-table-wrap"><table class="purchase-order-table"><thead><tr>${heads.map((h, i) => `<th class="${i === 0 ? "purchase-order-action-cell" : ""}">${esc(h)}</th>`).join("")}</tr><tr>${heads.map((h, i) => i === 0 ? `<th class="purchase-order-action-cell"></th>` : `<th><input class="column-filter" data-col="${i}" placeholder="Filter ${esc(h)}"></th>`).join("")}</tr></thead><tbody>${rows.length ? rows.map(purchaseOrderRowHtml).join("") : `<tr><td colspan="${heads.length}" class="empty">No purchase orders yet.</td></tr>`}</tbody></table></div>`;
}

function purchaseOrderRowHtml(po) {
  const invoice = po.vendor_invoice_no ? `${esc(po.vendor_invoice_no)}<br>${money(po.vendor_invoice_amount)}` : "";
  const closed = isClosedPurchaseOrder(po);
  const terminal = /paid|cancel|void|reversed/i.test(`${po.status || ""} ${po.payment_status || ""}`);
  const fullyReceived = poReceiptStatus(po) === "Goods Received";
  const canPay = !terminal && String(po.match_status || "").toLowerCase() === "matched" && String(po.payment_status || "").toLowerCase() !== "paid";
  const landedAp = isLandedCostPayable(po);
  const canClose = !closed && (landedAp || /matched|goods received/i.test(`${po.match_status || ""} ${po.status || ""}`));
  const documentActions = `<button class="rowbtn" type="button" data-po-pdf="${esc(po.po_no)}">PDF</button><button class="rowbtn" type="button" data-po-email="${esc(po.po_no)}">Email</button>`;
  const workflowActions = closed || terminal || landedAp ? "" : `${fullyReceived ? "" : `<button class="rowbtn" type="button" data-po-gr="${esc(po.po_no)}">GR</button>`}<button class="rowbtn" type="button" data-po-landed="${esc(po.po_no)}">Landed AP</button><button class="rowbtn" type="button" data-po-match="${esc(po.po_no)}">=</button>`;
  const editAction = closed ? "" : `<button class="rowbtn" type="button" data-po-edit="${esc(po.po_no)}">Edit</button>`;
  const reverseReceiptAction = activeReceipts(po).length ? `<button class="rowbtn danger" type="button" data-po-reverse-gr="${esc(po.po_no)}">Reverse GR</button>` : "";
  const salesOrderAction = isCustomerPurchaseOrder(po) && activeReceipts(po).length
    ? `<button class="rowbtn" type="button" data-po-sales="${esc(po.po_no)}">${po.linked_sales_order_no ? "Open SO" : "Create SO"}</button>`
    : "";
  return `<tr>
    <td class="purchase-order-action-cell"><div class="rowactions"><button class="rowbtn" type="button" data-po-sign="${esc(po.po_no)}">Sign</button>${documentActions}${workflowActions}${salesOrderAction}${canClose ? `<button class="rowbtn" type="button" data-po-close="${esc(po.po_no)}">Close PO</button>` : ""}${canPay ? `<button class="rowbtn" type="button" data-po-pay="${esc(po.po_no)}">$</button>` : ""}${editAction}${reverseReceiptAction}<button class="rowbtn danger" type="button" data-po-reverse="${esc(po.po_no)}">Reverse PO</button></div></td>
    <td><button class="linkbtn" type="button" data-po-open="${esc(po.po_no)}">${esc(po.po_no)}</button></td>
    <td>${badge(po.status || "Draft")}</td>
    <td>${esc(formatDisplayDate(po.po_date))}</td>
    <td>${esc(po.vendor || "")}</td>
    <td>${esc(/^general$/i.test(po.jobsite_project || "") ? "" : po.jobsite_project || "")}</td>
    <td>${esc(po.ap_support_wo_no || "")}</td>
    <td>${esc(purchaseOrderPurpose(po))}${po.linked_customer ? `<br><small>${esc(po.linked_customer)}</small>` : ""}${po.linked_sales_order_no ? `<br><small>${esc(po.linked_sales_order_no)}</small>` : ""}</td>
    <td>${esc(po.payment_terms || "")}</td>
    <td>${esc(po.incoterm || "")}</td>
    <td>${po.foreign_order ? `${esc(po.currency_code || "")}<br><small>${esc(po.foreign_country || "")}</small>` : "USD"}</td>
    <td>${money(poPartsSubtotal(po))}</td>
    <td>${money(poFreight(po))}</td>
    <td>${po.landed_cost_enabled ? `${money(effectivePoLandedAddOn(po))}<br><small>${esc(po.landed_cost_method || "By Value")}</small>` : "Off"}</td>
    <td>${landedAp ? money(Number(po.vendor_invoice_amount || 0)) : money(poTotal(po))}<br>${po.landed_cost_enabled ? `<small>Inventory ${money(poInventoryCostTotal(po))}</small>` : ""}</td>
    <td>${landedAp ? "Separate AP" : money(poReceivedTotal(po))}</td>
    <td>${invoice}</td>
    <td>${badge(po.match_status || "Pending")}</td>
    <td>${badge(po.payment_status || "Not Ready")}</td>
  </tr>`;
}

function poTotal(po) {
  return roundCurrency(poPartsSubtotal(po));
}

function poDocumentTotal(po) {
  return roundCurrency(poPartsSubtotal(po) + poFreight(po));
}

function poInventoryCostTotal(po) {
  return poPartsSubtotal(po) + effectivePoLandedAddOn(po);
}

function poPartsSubtotal(po) {
  const subtotal = (po._lines || []).reduce((sum, line) => sum + Number(line.qty || 0) * poLineVendorUnitCost(line), 0);
  return roundCurrency(subtotal);
}

function poLineVendorUnitCost(line) {
  const explicitBase = Number(line?.base_unit_cost || 0);
  if (explicitBase > 0) return explicitBase;
  const unitCost = Number(line?.unit_cost || 0);
  const landedUnitCost = Number(line?.landed_unit_cost || 0);
  const qty = Number(line?.qty || 0);
  const allocated = Number(line?.allocated_landed_cost || 0);
  if (qty > 0 && allocated > 0 && landedUnitCost > 0 && Math.abs(unitCost - landedUnitCost) < 0.005) {
    return Math.max(0, landedUnitCost - allocated / qty);
  }
  return unitCost;
}

function roundCurrency(value) {
  return Math.round((Number(value || 0) + Number.EPSILON) * 100) / 100;
}

function poFreight(po) {
  return Number(po?.freight_amount || 0);
}

function poLandedAddOn(po) {
  return roundCurrency(Number(po?.freight_amount || 0) + Number(po?.duty_amount || 0) + Number(po?.other_landed_cost_amount || 0));
}

function poLineLandedAddOnTotal(po) {
  return roundCurrency((po?._lines || []).reduce((sum, line) => {
    const qty = Number(line.qty || 0);
    const baseUnit = Number(line.unit_cost || 0);
    const landedUnit = Number(line.landed_unit_cost || baseUnit);
    return sum + Math.max(0, qty * (landedUnit - baseUnit));
  }, 0));
}

function effectivePoLandedAddOn(po) {
  const separateApAllocation = po?.po_no ? landedCostApTotalForSource(po.po_no) : 0;
  const allocatedAcrossLines = poLineLandedAddOnTotal(po);
  if (separateApAllocation > 0.005) return roundCurrency(separateApAllocation);
  if (allocatedAcrossLines > 0.005) return allocatedAcrossLines;
  return Math.max(0, poLandedAddOn(po));
}

function poReceivedTotal(po) {
  return activeReceipts(po).reduce((sum, line) => sum + goodsReceiptBaseAmount(po, line), 0);
}

function poReceivedInventoryTotal(po) {
  return activeReceipts(po).reduce((sum, line) => sum + Number(line.received_qty || 0) * Number(line.unit_cost || 0), 0);
}

function poReceivedLandedAccrualTotal(po) {
  return Math.max(0, poReceivedInventoryTotal(po) - poReceivedTotal(po));
}

function landedClearAmountForInvoice(po, invoiceAmount, receivedAmount = poReceivedTotal(po)) {
  const landedReceived = poReceivedLandedAccrualTotal(po);
  if (landedReceived <= 0) return 0;
  const invoiceExtra = Number(invoiceAmount || 0) - Number(receivedAmount || 0);
  return Math.max(0, Math.min(landedReceived, invoiceExtra));
}

function goodsReceiptBaseAmount(po, gr) {
  const receiptKey = purchaseOrderReceiptKey(po, gr);
  const line = (po?._lines || []).find((row) => purchaseOrderLineReceiptKey(row) === receiptKey);
  const baseUnit = line ? poLineVendorUnitCost(line) : Number(gr.base_unit_cost || gr.unit_cost || 0);
  return Number(gr.received_qty || 0) * baseUnit;
}

function isLandedCostPayable(po) {
  return /landed cost ap/i.test(`${po?.status || ""} ${po?.notes || ""}`);
}

function linkedLandedSourcePoNo(po) {
  return linkedLandedSourcePoNos(po)[0] || "";
}

function linkedLandedSourcePoNos(po) {
  const notes = String(po?.notes || "");
  const plural = notes.match(/Linked landed cost POs:\s*([^\n]+)/i);
  if (plural) return plural[1].split(",").map((value) => value.trim()).filter(Boolean);
  const single = notes.match(/Linked landed cost PO:\s*([^\n]+)/i);
  return single ? [single[1].trim()].filter(Boolean) : [];
}

function landedCostVisibleNotes(notes = "") {
  return String(notes || "")
    .split(/\r?\n/)
    .filter((line) => !/^(Linked landed cost POs?|Cost type|Allocation method|Allocation):/i.test(line.trim()))
    .join("\n")
    .trim();
}

function landedAllocationMap(po) {
  const map = new Map();
  String(po?.notes || "").split(/\r?\n/).forEach((line) => {
    const match = line.match(/^Allocation:\s*([^|]+)\|\s*([0-9.,-]+)\s*\|\s*(.+)$/i);
    if (!match) return;
    const poNo = match[1].trim();
    const amount = Number(String(match[2]).replace(/,/g, ""));
    if (poNo && Number.isFinite(amount)) map.set(poNo, amount);
  });
  return map;
}

function landedAllocationAmountForSource(landedPo, sourcePoNo) {
  const allocations = landedAllocationMap(landedPo);
  if (allocations.has(sourcePoNo)) return Number(allocations.get(sourcePoNo) || 0);
  const linked = linkedLandedSourcePoNos(landedPo);
  if (linked.length === 1 && linked[0] === sourcePoNo) return Number(landedPo.vendor_invoice_amount || 0);
  return 0;
}

function normalizedPurchaseLink(value) {
  return String(value || "").trim().toLowerCase();
}

function purchaseOrderLineReceiptKey(line = {}) {
  const productId = normalizedPurchaseLink(line.product_id);
  const sku = normalizedPurchaseLink(line.sku);
  const productName = normalizedPurchaseLink(line.product_name);
  const lineId = normalizedPurchaseLink(line.id);
  if (productId) return `product:${productId}`;
  if (sku) return `sku:${sku}`;
  if (productName) return `name:${productName}`;
  return lineId ? `line:${lineId}` : "";
}

function purchaseOrderReceiptKey(po, receipt = {}) {
  const lines = po?._lines || [];
  const receiptLineId = normalizedPurchaseLink(receipt.po_line_id);
  const receiptProductId = normalizedPurchaseLink(receipt.product_id);
  const receiptSku = normalizedPurchaseLink(receipt.sku);
  const receiptName = normalizedPurchaseLink(receipt.product_name);
  const matchedLine = lines.find((line) => receiptLineId && normalizedPurchaseLink(line.id) === receiptLineId)
    || lines.find((line) => receiptProductId && normalizedPurchaseLink(line.product_id) === receiptProductId)
    || lines.find((line) => receiptSku && normalizedPurchaseLink(line.sku) === receiptSku)
    || lines.find((line) => receiptName && normalizedPurchaseLink(line.product_name) === receiptName);
  if (matchedLine) return purchaseOrderLineReceiptKey(matchedLine);
  if (receiptProductId) return `product:${receiptProductId}`;
  if (receiptSku) return `sku:${receiptSku}`;
  if (receiptName) return `name:${receiptName}`;
  return receiptLineId ? `line:${receiptLineId}` : "";
}

function poReceivedQuantityByLine(po, line) {
  const key = purchaseOrderLineReceiptKey(line);
  if (!key) return 0;
  return activeReceipts(po)
    .filter((receipt) => purchaseOrderReceiptKey(po, receipt) === key)
    .reduce((sum, receipt) => sum + Number(receipt.received_qty || 0), 0);
}

function isReversedGoodsReceipt(line) {
  return Boolean(line?._has_reversal_movement) || /reversed|void|cancel/i.test(`${line?.status || ""} ${line?.notes || ""}`);
}

function activeReceipts(po) {
  return (po?._receipts || []).filter((line) => !isReversedGoodsReceipt(line));
}

function goodsReceiptBatchKey(receipts, receipt) {
  const grNo = String(receipt?.gr_no || "").trim();
  if (!grNo) return "";
  const candidate = grNo.replace(/-\d+$/, "");
  const siblings = (receipts || []).filter((row) => {
    const other = String(row?.gr_no || "").trim();
    return other !== grNo && other.replace(/-\d+$/, "") === candidate;
  });
  return siblings.length ? candidate : grNo;
}

function groupedGoodsReceiptBatches(receipts = []) {
  const groups = new Map();
  receipts.forEach((receipt) => {
    const key = goodsReceiptBatchKey(receipts, receipt);
    if (!key) return;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(receipt);
  });
  return [...groups.entries()].map(([key, rows]) => ({ key, rows }));
}

function poReceiptStatus(po) {
  const lines = po?._lines || [];
  if (isBlanketPurchaseOrder(po)) return activeReceipts(po).length ? "Partially Received" : "Issued";
  if (!lines.length) return "Draft";
  const receipts = activeReceipts(po);
  const receivedTotal = receipts.reduce((sum, row) => sum + Number(row.received_qty || 0), 0);
  if (receivedTotal <= 0) return "Issued";
  const orderedByItem = new Map();
  lines.forEach((line) => {
    const key = purchaseOrderLineReceiptKey(line);
    if (key) orderedByItem.set(key, Number(orderedByItem.get(key) || 0) + Number(line.qty || 0));
  });
  const receivedByItem = new Map();
  receipts.forEach((receipt) => {
    const key = purchaseOrderReceiptKey(po, receipt);
    if (key) receivedByItem.set(key, Number(receivedByItem.get(key) || 0) + Number(receipt.received_qty || 0));
  });
  const allReceived = orderedByItem.size > 0 && [...orderedByItem.entries()]
    .every(([key, orderedQty]) => Number(receivedByItem.get(key) || 0) + 0.000001 >= orderedQty);
  return allReceived ? "Goods Received" : "Partially Received";
}

function isBlanketPurchaseOrder(po) {
  return String(po?.po_type || "Standard").toLowerCase() === "blanket";
}

function poMatchStatusFromAmounts(po) {
  const received = poReceivedTotal(po);
  const receiptInvoiceAmount = activeReceipts(po).reduce((sum, gr) => sum + Number(gr.vendor_invoice_amount || gr.received_amount || goodsReceiptBaseAmount(po, gr)), 0);
  const invoice = Number(po.vendor_invoice_amount || receiptInvoiceAmount || 0);
  const landedClear = landedClearAmountForInvoice(po, invoice, received);
  const expectedInvoice = received + landedClear;
  if (!received) return "Awaiting Goods";
  if (!invoice) return "Pending";
  return Math.abs(invoice - expectedInvoice) <= 0.005 ? "Matched" : "Mismatch";
}

function landedCostAllocationBase(po, method = "By Value") {
  if (String(method || "").toLowerCase().includes("qty")) {
    return (po?._lines || []).reduce((sum, line) => sum + Number(line.qty || 0), 0);
  }
  return poPartsSubtotal(po);
}

function calculateMultiPoLandedAllocations(pos, amount, method = "By Value", selectedPoNos = null) {
  const selected = (pos || []).filter((po) => !selectedPoNos || selectedPoNos.has(po.po_no));
  if (!selected.length || !Number(amount || 0)) return selected.map((po) => ({ po_no: po.po_no, amount: 0 }));
  const baseTotal = selected.reduce((sum, po) => sum + landedCostAllocationBase(po, method), 0);
  if (!baseTotal) return selected.map((po) => ({ po_no: po.po_no, amount: 0 }));
  let allocatedSoFar = 0;
  return selected.map((po, index) => {
    const allocation = index === selected.length - 1
      ? Number(amount || 0) - allocatedSoFar
      : Math.round((Number(amount || 0) * (landedCostAllocationBase(po, method) / baseTotal)) * 100) / 100;
    allocatedSoFar += allocation;
    return { po_no: po.po_no, amount: Math.round(allocation * 100) / 100 };
  });
}

function receiptInvoiceSummary(rows, fallbackDate = today()) {
  const invoiceRows = rows.filter((row) => row.vendor_invoice_no || row.vendor_invoice_date || Number(row.vendor_invoice_amount || 0));
  if (!invoiceRows.length) return null;
  const invoiceNos = [...new Set(invoiceRows.map((row) => row.vendor_invoice_no).filter(Boolean))];
  const invoiceDates = invoiceRows.map((row) => row.vendor_invoice_date).filter(Boolean).sort();
  const amount = invoiceRows.reduce((sum, row) => sum + Number(row.vendor_invoice_amount || row.received_qty * (row.base_unit_cost || row.unit_cost) || 0), 0);
  return {
    vendor_invoice_no: invoiceNos.join(", "),
    vendor_invoice_date: invoiceDates[0] || fallbackDate,
    vendor_invoice_amount: amount,
  };
}

async function refreshPurchaseOrderFlow(poNo, { keepPaid = false, reopenAfterReceiptReversal = false } = {}) {
  const [poRows, lines, receipts, stockMovements] = await Promise.all([getAll("purchase_orders"), getAll("purchase_order_lines"), getAll("goods_receipts"), getAll("stock_movements").catch(() => [])]);
  const po = poRows.find((row) => row.po_no === poNo);
  if (!po) return null;
  po._lines = lines.filter((line) => String(line.po_id || "") === String(po.id || "") || String(line.po_no || "") === String(po.po_no || ""));
  const reversedReceiptRefs = new Set((stockMovements || []).filter((row) => /goods receipt reversal/i.test(row.type || "") || /^REV-GR-/i.test(row.reference_no || "")).map((row) => String(row.reference_no || "").replace(/^REV-/, "")));
  po._receipts = receipts.filter((row) => String(row.po_id || "") === String(po.id || "") || String(row.po_no || "") === String(po.po_no || "")).map((row) => ({ ...row, _has_reversal_movement: reversedReceiptRefs.has(String(row.gr_no || "")) }));
  const status = poReceiptStatus(po);
  const match = poMatchStatusFromAmounts(po);
  const apPosted = await hasPostedApForPurchaseOrder(po.po_no);
  const paymentStatus = keepPaid && /paid/i.test(po.payment_status || "") ? "Paid" : apPosted && match === "Matched" ? "Ready to Pay" : "Not Ready";
  const finalStatus = !reopenAfterReceiptReversal && /closed po/i.test(po.status || "")
    ? "Closed PO"
    : !isBlanketPurchaseOrder(po) && status === "Goods Received" ? "Closed PO" : status;
  const active = activeReceipts(po);
  const updates = { status: finalStatus, match_status: match, payment_status: paymentStatus };
  if (!active.length) {
    updates.vendor_invoice_no = null;
    updates.vendor_invoice_date = null;
    updates.vendor_invoice_amount = 0;
  }
  const { data: updatedRows, error: updateError } = await supabase.from("purchase_orders").update(updates).eq("id", po.id).select("id,status,match_status,payment_status");
  if (updateError) throw updateError;
  if (!(updatedRows || []).length) throw new Error(`Could not update ${po.po_no}. Check the Purchase Orders update policy.`);
  if (!active.length) {
    await supabase.from("general_ledger").delete().eq("reference", po.po_no).eq("source", "Purchase Order");
  }
  return { ...po, status: finalStatus, match_status: match, payment_status: paymentStatus };
}

async function promptCloseCompletedLandedCostPos(receivedPoNo = "") {
  const normalizedPoNo = String(receivedPoNo || "").trim();
  if (!normalizedPoNo) return 0;
  const [poRows, lines, receipts, stockMovements] = await Promise.all([
    getAll("purchase_orders"),
    getAll("purchase_order_lines"),
    getAll("goods_receipts"),
    getAll("stock_movements").catch(() => []),
  ]);
  const reversedReceiptRefs = new Set((stockMovements || [])
    .filter((row) => /goods receipt reversal/i.test(row.type || "") || /^REV-GR-/i.test(row.reference_no || ""))
    .map((row) => String(row.reference_no || "").replace(/^REV-/, "")));
  const preparedPos = (poRows || []).map((po) => ({
    ...po,
    _lines: (lines || []).filter((line) => String(line.po_id || "") === String(po.id || "") || String(line.po_no || "") === String(po.po_no || "")),
    _receipts: (receipts || [])
      .filter((row) => String(row.po_id || "") === String(po.id || "") || String(row.po_no || "") === String(po.po_no || ""))
      .map((row) => ({ ...row, _has_reversal_movement: reversedReceiptRefs.has(String(row.gr_no || "")) })),
  }));
  const poByNo = new Map(preparedPos.map((po) => [String(po.po_no || "").trim(), po]));
  const candidates = preparedPos.filter((po) => {
    const linked = linkedLandedSourcePoNos(po);
    return isLandedCostPayable(po) && !isClosedPurchaseOrder(po) && linked.includes(normalizedPoNo);
  });
  let closedCount = 0;
  for (const landedPo of candidates) {
    const linkedNos = linkedLandedSourcePoNos(landedPo);
    const sourcePos = linkedNos.map((poNo) => poByNo.get(poNo)).filter(Boolean);
    if (!linkedNos.length || sourcePos.length !== linkedNos.length) continue;
    if (!sourcePos.every((sourcePo) => poReceiptStatus(sourcePo) === "Goods Received")) continue;
    const grNos = [...new Set(sourcePos.flatMap((sourcePo) => activeReceipts(sourcePo).map((receipt) => receipt.gr_no)).filter(Boolean))];
    const closeNow = confirm(
      `All product POs linked to landed cost PO ${landedPo.po_no} are fully received.\n\n`
      + `Related POs: ${linkedNos.join(", ")}\n`
      + `${grNos.length ? `Goods Receipts: ${grNos.join(", ")}\n\n` : "\n"}`
      + `Close ${landedPo.po_no} now as GR complete?\n\n`
      + "This only closes the landed-cost purchasing workflow. It does not create another accounting entry."
    );
    if (!closeNow) continue;
    const closedStatus = "Closed PO - Landed Cost AP";
    const { data: updatedRows, error } = await supabase.from("purchase_orders")
      .update({ status: closedStatus })
      .eq("id", landedPo.id)
      .select("id,status");
    if (error) throw error;
    if (!(updatedRows || []).length) throw new Error(`Could not close ${landedPo.po_no}. Check the Purchase Orders update policy.`);
    await writeAuditLog({
      tableName: "purchase_orders",
      action: "Closed",
      beforeData: landedPo,
      afterData: { ...landedPo, status: closedStatus },
      reason: `All linked POs fully received: ${linkedNos.join(", ")}`,
    });
    closedCount += 1;
  }
  return closedCount;
}

async function hasPurchaseOrderPayments(poNo) {
  const [checks, ledger] = await Promise.all([
    supabase.from("check_runs").select("id,status,reference").eq("reference", poNo).limit(1),
    supabase.from("general_ledger").select("id,source,reference,account").eq("reference", poNo).eq("source", "Check Run").limit(1),
  ]);
  if (checks.error && checks.error.code !== "PGRST116") throw checks.error;
  if (ledger.error && ledger.error.code !== "PGRST116") throw ledger.error;
  return Boolean((checks.data || []).length || (ledger.data || []).length);
}

async function hasPostedApForPurchaseOrder(poNo) {
  const { data, error } = await supabase.from("general_ledger").select("id").eq("reference", poNo).eq("source", "Purchase Order").limit(1);
  if (error && error.code !== "PGRST116") throw error;
  return Boolean((data || []).length);
}

function bindPurchaseRows() {
  document.querySelectorAll("[data-po-open]").forEach((b) => b.onclick = () => openPurchaseOrderRecord(currentRows.find((po) => po.po_no === b.dataset.poOpen)));
  document.querySelectorAll("[data-po-edit]").forEach((b) => b.onclick = () => {
    const po = currentRows.find((row) => row.po_no === b.dataset.poEdit);
    return openPurchaseOrderRecord(po);
  });
  document.querySelectorAll("[data-po-reverse]").forEach((b) => b.onclick = () => reversePurchaseOrder(b.dataset.poReverse));
  document.querySelectorAll("[data-po-reverse-gr]").forEach((b) => b.onclick = () => reverseLinkedGoodsReceiptsOnly(b.dataset.poReverseGr));
  document.querySelectorAll("[data-po-pdf]").forEach((b) => b.onclick = () => printPurchaseOrder(b.dataset.poPdf));
  document.querySelectorAll("[data-po-email]").forEach((b) => b.onclick = () => emailPurchaseOrder(b.dataset.poEmail));
  document.querySelectorAll("[data-po-gr]").forEach((b) => b.onclick = () => openGoodsReceiptModal(currentRows.find((po) => po.po_no === b.dataset.poGr)));
  document.querySelectorAll("[data-po-landed]").forEach((b) => b.onclick = () => openLandedCostInvoiceModal(currentRows.find((po) => po.po_no === b.dataset.poLanded)));
  document.querySelectorAll("[data-po-match]").forEach((b) => b.onclick = () => openPostApFromPoModal({ pos: currentRows }, b.dataset.poMatch));
  document.querySelectorAll("[data-po-pay]").forEach((b) => b.onclick = () => createCheckRunFromPo({ pos: currentRows }, b.dataset.poPay));
  document.querySelectorAll("[data-po-sales]").forEach((b) => b.onclick = () => openSalesOrderFromPurchaseOrder(b.dataset.poSales));
  document.querySelectorAll("[data-po-close]").forEach((b) => b.onclick = () => closePurchaseOrder(b.dataset.poClose));
  document.querySelectorAll("[data-po-sign]").forEach((b) => b.onclick = () => openSavedSignatureModal("purchase_orders", "po_no", b.dataset.poSign, `Save signature for ${b.dataset.poSign}`, () => renderPurchasingView()));
  document.querySelectorAll(".column-filter").forEach((input) => input.oninput = applyColumnFilters);
  enhanceRowHistoryButtons();
  enhanceRowActionMenus();
}

function openPurchaseOrderRecord(po) {
  if (!po) return alert("That purchase order could not be found.");
  return isLandedCostPayable(po) ? openLandedCostInvoiceModal(po) : openPurchaseOrderModal(po);
}

async function closePurchaseOrder(poNo) {
  const po = currentRows.find((row) => row.po_no === poNo);
  if (!po) return;
  const ok = confirm(`Move ${poNo} to Closed PO?\n\nThis does not post accounting. It only closes the purchasing workflow view.`);
  if (!ok) return;
  try {
    const closedStatus = isLandedCostPayable(po) ? "Closed PO - Landed Cost AP" : "Closed PO";
    const { error } = await supabase.from("purchase_orders").update({ status: closedStatus }).eq("id", po.id);
    if (error) throw error;
    await writeAuditLog({ tableName: "purchase_orders", action: "Closed", beforeData: po, afterData: { ...po, status: closedStatus }, reason: "Purchasing workflow closed" });
    purchasingTab = "closed";
    await renderPurchasingView();
  } catch (error) {
    alert(`Could not close ${poNo}.\n\n${error.message || error}`);
  }
}

