window.savePdfSignatures = async function savePdfSignatures(request) {
  const table = request?.table;
  const keyField = request?.keyField;
  const keyValue = request?.keyValue;
  const values = request?.values || {};
  if (table !== "purchase_orders" || keyField !== "po_no" || !keyValue) {
    return { ok: false, message: "This PDF signature can only be saved against a purchase order." };
  }
  const allowedColumns = [
    "signature_data_url",
    "signature_printed_name",
    "signature_signed_date",
    "internal_signature_data_url",
    "internal_signature_name",
    "internal_signature_remarks",
  ];
  const optionalColumns = [
    "signature_printed_name",
    "signature_signed_date",
    "internal_signature_data_url",
    "internal_signature_name",
    "internal_signature_remarks",
  ];
  let row = Object.fromEntries(Object.entries(values)
    .filter(([key, value]) => allowedColumns.includes(key) && value !== undefined)
    .map(([key, value]) => [key, value === "" ? null : value]));
  if (!Object.keys(row).length) return { ok: false, message: "There is no signature or signature detail to save yet." };
  const skipped = [];
  for (let attempt = 0; attempt <= optionalColumns.length; attempt += 1) {
    try {
      const { error } = await supabase.from("purchase_orders").update(row).eq("po_no", keyValue);
      if (error) throw error;
      currentRows = currentRows.map((record) => record.po_no === keyValue ? { ...record, ...row } : record);
      if (skipped.length) {
        return {
          ok: true,
          message: `Signature saved. Some extra signature fields were skipped because the database is missing: ${skipped.join(", ")}. Run the PO signature SQL update when ready.`,
        };
      }
      return { ok: true, message: "Signature saved on this purchase order." };
    } catch (error) {
      const missing = optionalColumns.find((column) => column in row && isMissingSchemaColumn(error, column));
      if (!missing) return { ok: false, message: error.message || String(error) };
      const { [missing]: _removed, ...nextRow } = row;
      row = nextRow;
      skipped.push(missing);
      if (!Object.keys(row).length) {
        return { ok: false, message: `The database is missing the signature storage fields: ${skipped.join(", ")}. Run the PO signature SQL update first.` };
      }
    }
  }
  return { ok: false, message: "Could not save the signature." };
};

async function emailPurchaseOrder(poNo) {
  const po = resolvePreparedPurchaseOrder(poNo);
  if (!po) return;
  const vendor = (purchaseContext.vendorRows || []).find((row) => String(row.name || "").toLowerCase() === String(po.vendor || "").toLowerCase()) || {};
  if (!vendor.email) {
    const email = prompt(`No email is saved for ${po.vendor || "this vendor"}.\n\nEnter the vendor email to save in Vendor Master:`, "");
    if (!email) return;
    if (!areValidEmailRecipients(email)) {
      alert("Please enter valid email addresses separated by commas, semicolons, or new lines.");
      return;
    }
    const normalizedEmail = normalizeEmailRecipients(email);
    const update = { email: normalizedEmail };
    const query = vendor.id
      ? supabase.from("vendors").update(update).eq("id", vendor.id)
      : supabase.from("vendors").update(update).ilike("name", po.vendor || "");
    const { error } = await query;
    if (error) {
      alert(`Could not save vendor email: ${error.message || error}`);
      return;
    }
    vendor.email = normalizedEmail;
    purchaseContext.vendorRows = (purchaseContext.vendorRows || []).map((row) => String(row.name || "").toLowerCase() === String(po.vendor || "").toLowerCase() ? { ...row, email: normalizedEmail } : row);
  }
  if (!areValidEmailRecipients(vendor.email)) return alert(`Vendor ${po.vendor || ""} does not have valid email recipients in Vendor Master.`);
  const subject = `Purchase Order ${po.po_no} — LMS Imports`;
  const body = [
    `Dear ${po.vendor || "Vendor"} Sales / Accounts Receivable Team,`,
    "",
    `Please accept this formal submission of Purchase Order ${po.po_no}.`,
    "",
    "Please confirm receipt and advise us promptly of any availability, pricing, or delivery concerns.",
    "",
    "Sincerely,",
    "LMS Imports",
  ].filter((line) => line !== null).join("\n");
  openEmailDraftDirect({ email: vendor.email, subject, body });
}

function isValidEmail(value) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(value || "").trim());
}

function emailRecipients(value) {
  const seen = new Set();
  return String(value || "").split(/[,;\n\r]+/).map((item) => item.trim()).filter(Boolean).filter((item) => {
    const key = item.toLowerCase();
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function areValidEmailRecipients(value) {
  const recipients = emailRecipients(value);
  return recipients.length > 0 && recipients.every(isValidEmail);
}

function normalizeEmailRecipients(value) {
  return emailRecipients(value).join("; ");
}

function emailRecipientCount(value) {
  return emailRecipients(value).length;
}

function mailtoRecipients(value) {
  return emailRecipients(value).map((recipient) => encodeURIComponent(recipient)).join(",");
}

function sharedDocumentLink(documentType, reference) {
  const url = new URL(window.location.href);
  url.hash = new URLSearchParams({ document: documentType, reference: String(reference || "") }).toString();
  return url.toString();
}

async function printableHtmlToPdfBlob(html, fileName = "document.pdf") {
  if (!window.html2pdf) throw new Error("The PDF generator is not available. Refresh the page and try again.");
  const frame = document.createElement("iframe");
  frame.setAttribute("aria-hidden", "true");
  frame.style.cssText = "position:fixed;left:-10000px;top:0;width:816px;height:1056px;border:0;opacity:0;pointer-events:none;";
  document.body.appendChild(frame);
  try {
    const frameDocument = frame.contentDocument;
    frameDocument.open();
    frameDocument.write(html);
    frameDocument.close();
    await new Promise((resolve) => setTimeout(resolve, 150));
    await frameDocument.fonts?.ready?.catch(() => {});
    const images = [...frameDocument.images];
    await Promise.all(images.map((image) => image.complete ? Promise.resolve() : new Promise((resolve) => {
      image.addEventListener("load", resolve, { once: true });
      image.addEventListener("error", resolve, { once: true });
    })));
    frameDocument.querySelectorAll(".print-btn,.sig-actions,.sig-save-actions").forEach((element) => element.remove());
    const element = frameDocument.querySelector(".pdf-export-root") || frameDocument.querySelector(".sheet") || frameDocument.body;
    return await window.html2pdf().set({
      margin: 0,
      filename: fileName,
      image: { type: "jpeg", quality: 0.98 },
      html2canvas: { scale: 2, useCORS: true, logging: false, windowWidth: 816 },
      jsPDF: { unit: "in", format: "letter", orientation: "portrait" },
      pagebreak: { mode: ["css", "legacy"] },
    }).from(element).outputPdf("blob");
  } finally {
    frame.remove();
  }
}

function bytesToBase64(bytes) {
  const chunkSize = 0x8000;
  let binary = "";
  for (let index = 0; index < bytes.length; index += chunkSize) {
    binary += String.fromCharCode(...bytes.subarray(index, index + chunkSize));
  }
  return btoa(binary);
}

async function createPublicPdfDownloadLink({ documentType, reference, fileName, html, promptLabel }) {
  if (!html) throw new Error("The printable document could not be generated.");
  const { data: { session } } = await supabase.auth.getSession();
  if (!session?.access_token) throw new Error("Your login session expired. Please log in again.");
  const blob = await printableHtmlToPdfBlob(html, fileName);
  const fileBase64 = bytesToBase64(new Uint8Array(await blob.arrayBuffer()));
  const response = await fetch("/api/share-document", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${session.access_token}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ documentType, reference, fileName, fileBase64 }),
  });
  const result = await response.json().catch(() => ({}));
  if (!response.ok || !result.signedUrl) throw new Error(result.error || "The secure PDF link could not be created.");
  const page = new URL("download.html", window.location.href);
  page.hash = new URLSearchParams({
    url: result.signedUrl,
    label: promptLabel || `Download ${reference}`,
    file: fileName,
  }).toString();
  return page.toString();
}

function exportPurchaseOrdersCsv() {
  currentCfg = { labels: ["PO", "Date", "Vendor", "Jobsite / Project", "Work Order", "Terms", "Incoterm", "Foreign Order", "Country", "Currency", "Exchange Rate", "Landed Cost Enabled", "Allocation Method", "Parts Subtotal", "Freight", "Duty", "Other Landed", "Vendor PO Total", "Inventory Cost Total", "Received Vendor Cost", "Received Inventory Cost", "Invoice", "Invoice Amount", "Match", "Payment", "Status"], heads: [] };
  currentRows = currentRows.map((po) => ({ PO: po.po_no, Date: po.po_date, Vendor: po.vendor, "Purchase Purpose": purchaseOrderPurpose(po), Customer: po.linked_customer, "Linked Sales Order": po.linked_sales_order_no, "Jobsite / Project": /^general$/i.test(po.jobsite_project || "") ? "" : po.jobsite_project, "Work Order": po.ap_support_wo_no, Terms: po.payment_terms, Incoterm: po.incoterm, "Foreign Order": po.foreign_order ? "Yes" : "No", Country: po.foreign_country, Currency: po.currency_code, "Exchange Rate": po.exchange_rate, "Landed Cost Enabled": po.landed_cost_enabled ? "Yes" : "No", "Allocation Method": po.landed_cost_method, "Parts Subtotal": poPartsSubtotal(po), Freight: poFreight(po), Duty: po.duty_amount, "Other Landed": po.other_landed_cost_amount, "Vendor PO Total": poDocumentTotal(po), "Inventory Cost Total": poInventoryCostTotal(po), "Received Vendor Cost": poReceivedTotal(po), "Received Inventory Cost": poReceivedInventoryTotal(po), Invoice: po.vendor_invoice_no, "Invoice Amount": po.vendor_invoice_amount, Match: po.match_status, Payment: po.payment_status, Status: po.status }));
  const rows = [currentCfg.labels, ...currentRows.map((r) => currentCfg.labels.map((h) => r[h] ?? ""))];
  const csv = rows.map((r) => r.map((v) => `"${String(v ?? "").replace(/"/g, '""')}"`).join(",")).join("\n");
  const url = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
  const a = document.createElement("a");
  a.href = url;
  a.download = "purchase-orders.csv";
  a.click();
  URL.revokeObjectURL(url);
  renderPurchasingView();
}

async function renderGoodsReceiptsView() {
  currentCfg = tableMap.receipts;
  $("viewTitle").textContent = "Goods Receipts";
  $("viewSub").textContent = "Receive ordered goods only and track partial/full receipt.";
  const [receipts, products, stockMovements] = await Promise.all([getAll("goods_receipts"), getAll("products"), getAll("stock_movements").catch(() => [])]);
  const reversedReceiptRefs = new Set((stockMovements || []).filter((row) => /goods receipt reversal/i.test(row.type || "") || /^REV-GR-/i.test(row.reference_no || "")).map((row) => String(row.reference_no || "").replace(/^REV-/, "")));
  receipts.forEach((gr) => { gr._has_reversal_movement = reversedReceiptRefs.has(String(gr.gr_no || "")); });
  productMeta.products = products;
  currentRows = receipts.sort((a, b) => String(b.gr_date || "").localeCompare(String(a.gr_date || "")));
  $("content").innerHTML = `
    <div class="toolbar">
      <input class="searchbox" id="receiptSearch" placeholder="Search receipts by GR, PO, vendor, invoice, product, status">
    </div>
    <section class="panel">
      <div class="panel-head"><div class="panel-title"><strong>Goods Receipts</strong><span>Receipt history with invoice references and reversal controls.</span></div><div class="actions">${dateRangeControls("receipt")}<button id="receiptApplyDates">Apply dates</button><button id="receiptCsvBtn">Excel</button><button onclick="window.print()">PDF / Print</button></div></div>
      <div id="receiptTableHost">${goodsReceiptsTableHtml(currentRows)}</div>
    </section>`;
  $("receiptSearch").oninput = renderFilteredGoodsReceipts;
  $("receiptApplyDates").onclick = renderFilteredGoodsReceipts;
  $("receiptCsvBtn").onclick = exportCurrentCsv;
  bindGoodsReceiptRows();
}

function renderFilteredGoodsReceipts() {
  const q = ($("receiptSearch")?.value || "").toLowerCase();
  const from = $("receiptFrom")?.value || "";
  const to = $("receiptTo")?.value || "";
  const rows = currentRows.filter((row) => {
    const date = String(row.gr_date || "");
    return (!q || Object.values(row).join(" ").toLowerCase().includes(q)) && (!from || date >= from) && (!to || date <= to);
  });
  $("receiptTableHost").innerHTML = goodsReceiptsTableHtml(rows);
  bindGoodsReceiptRows();
}

function goodsReceiptsTableHtml(rows) {
  const heads = [...currentCfg.labels, ""];
  return `<div class="table-wrap"><table><thead><tr>${heads.map((h) => `<th>${esc(h)}</th>`).join("")}</tr><tr>${heads.map((h, i) => h ? `<th><input class="column-filter" data-col="${i}" placeholder="Filter ${esc(h)}"></th>` : "<th></th>").join("")}</tr></thead><tbody>${rows.length ? rows.map(goodsReceiptRowHtml).join("") : `<tr><td colspan="${heads.length}" class="empty">No goods receipts yet.</td></tr>`}</tbody></table></div>`;
}

function goodsReceiptRowHtml(row) {
  const reversed = isReversedGoodsReceipt(row);
  return `<tr>${currentCfg.heads.map((h) => `<td>${cell(h, row[h], row)}</td>`).join("")}<td><div class="rowactions">${reversed ? badge("Reversed") : `<button class="rowbtn primary" type="button" data-review-gr-ap="${esc(row.po_no || "")}">AP Review</button><button class="rowbtn danger" type="button" data-reverse-gr="${esc(row.gr_no)}">Reverse</button>`}</div></td></tr>`;
}

function openGoodsReceiptRecord(rows, requestedReference = "") {
  const receiptRows = (Array.isArray(rows) ? rows : [rows]).filter(Boolean);
  if (!receiptRows.length) return alert("Goods Receipt could not be found.");
  const first = receiptRows[0];
  const baseReference = requestedReference || String(first.gr_no || "").replace(/-\d+$/, "");
  const totalQty = receiptRows.reduce((sum, row) => sum + Number(row.received_qty || 0), 0);
  const totalAmount = receiptRows.reduce((sum, row) => sum + Number(row.received_amount || Number(row.received_qty || 0) * Number(row.unit_cost || 0)), 0);
  $("modalTitle").textContent = `Goods Receipt ${baseReference}`;
  $("modalBody").innerHTML = `<div class="summary-strip">
      <strong>${esc(first.vendor || "")}</strong>
      <span>${esc(formatDisplayDate(first.gr_date))}</span>
      ${first.po_no ? `<button type="button" class="document-reference-link" data-document-reference="${esc(first.po_no)}" data-document-view="purchasing" title="Open Purchase Order ${esc(first.po_no)}">PO ${esc(first.po_no)}</button>` : ""}
    </div>
    <div class="form-grid read-only-record-grid">
      <div class="field"><label>GR #</label><input value="${esc(baseReference)}" readonly></div>
      <div class="field"><label>Date</label><input value="${esc(formatDisplayDate(first.gr_date))}" readonly></div>
      <div class="field"><label>Vendor</label><input value="${esc(first.vendor || "")}" readonly></div>
      <div class="field"><label>Vendor Invoice #</label><input value="${esc(first.vendor_invoice_no || "")}" readonly></div>
      <div class="field"><label>Invoice Date</label><input value="${esc(formatDisplayDate(first.vendor_invoice_date))}" readonly></div>
      <div class="field"><label>Status</label><input value="${esc(first.status || "Received")}" readonly></div>
    </div>
    <div class="table-wrap"><table class="line-table"><thead><tr><th>SKU</th><th>Product</th><th>Warehouse</th><th>Bin / Shelf</th><th>Qty Received</th><th>Unit Cost</th><th>Amount</th><th>Receipt Type</th></tr></thead><tbody>
      ${receiptRows.map((row) => `<tr><td>${esc(row.sku || "")}</td><td>${esc(row.product_name || "")}</td><td>${esc(row.receipt_warehouse || "")}</td><td>${esc(row.receipt_bin_shelf || "")}</td><td>${esc(row.received_qty || 0)}</td><td>${money(row.unit_cost)}</td><td>${money(row.received_amount || Number(row.received_qty || 0) * Number(row.unit_cost || 0))}</td><td>${esc(row.receipt_type || "")}</td></tr>`).join("")}
    </tbody><tfoot><tr><th colspan="4">Totals</th><th>${esc(totalQty)}</th><th></th><th>${money(totalAmount)}</th><th></th></tr></tfoot></table></div>
    ${first.notes ? `<p class="notice preserve-lines">${esc(first.notes)}</p>` : ""}`;
  $("modalSave").style.display = "none";
  $("modalDraft").hidden = true;
  $("modalCancel").textContent = "Close";
  $("modalCancel").onclick = closeModal;
  document.querySelector(".modalbox")?.classList.add("wide-modal");
  $("modal").style.display = "flex";
  modalDirty = false;
}

function bindGoodsReceiptRows() {
  document.querySelectorAll("[data-review-gr-ap]").forEach((b) => b.onclick = () => openApReviewForGoodsReceipt(b.dataset.reviewGrAp));
  document.querySelectorAll("[data-reverse-gr]").forEach((b) => b.onclick = () => reverseGoodsReceipt(b.dataset.reverseGr));
  document.querySelectorAll(".column-filter").forEach((input) => input.oninput = applyColumnFilters);
}

async function reverseGoodsReceipt(grNo) {
  const gr = currentRows.find((row) => row.gr_no === grNo);
  if (!gr || isReversedGoodsReceipt(gr)) return;
  if (!confirm(`Reverse ${gr.gr_no}? This will subtract the received quantity from stock and post a reversal movement.`)) return;
  try {
    if (gr.po_no && await hasPurchaseOrderPayments(gr.po_no)) {
      alert("This PO already has a payment/check run. Reverse the payment first, then reverse the goods receipt.");
      return;
    }
    if (gr.po_no && await hasPostedApForPurchaseOrder(gr.po_no)) {
      alert("This PO is already posted to Accounts Payable. Reverse or clear the AP posting first, then reverse the goods receipt.");
      return;
    }
    await reverseGoodsReceiptRecord(gr);
    if (gr.po_no) await refreshPurchaseOrderFlow(gr.po_no, { reopenAfterReceiptReversal: true });
    await renderPurchasingView();
  } catch (error) {
    alert(error.message || error);
  }
}

async function reverseGoodsReceiptRecord(gr, { reason = "" } = {}) {
  if (!gr?.gr_no) throw new Error("The linked Goods Receipt number is missing.");
  const product = (productMeta.products || []).find((p) => p.id === gr.product_id || p.sku === gr.sku);
  const qty = Number(gr.received_qty || 0);
  const unitCost = Number(gr.unit_cost || product?.cost || 0);
  const { data: existingReversalRows, error: existingReversalError } = await supabase.from("stock_movements").select("reference_no").eq("reference_no", `REV-${gr.gr_no}`).limit(1);
  if (existingReversalError) throw existingReversalError;
  const reversalAlreadyPosted = Boolean((existingReversalRows || []).length);
  if (!reversalAlreadyPosted && qty && !product?.id) {
    throw new Error(`Cannot safely reverse ${gr.gr_no}: Product Master item ${gr.sku || gr.product_name || "Unknown"} was not found. Restore or link the product first so inventory can be corrected.`);
  }
  const reversedBy = profile?.full_name || profile?.username || profile?.email || "Owner";
  const reversalNote = `Reversed ${today()} by ${reversedBy}${reason ? `. Reason: ${reason}` : ""}`;
  const { data: reversedRows, error: reverseError } = await supabase.from("goods_receipts").update({
    status: "Reversed",
    notes: [gr.notes, reversalNote].filter(Boolean).join(" | "),
  }).eq("gr_no", gr.gr_no).select("gr_no,status");
  if (reverseError) throw reverseError;
  if (!(reversedRows || []).length || !reversedRows.every((row) => /reversed/i.test(row.status || ""))) {
    throw new Error(`Could not reverse ${gr.gr_no}. Check the Goods Receipts update policy.`);
  }
  if (reversalAlreadyPosted) {
    await writeAuditLog({ tableName: "goods_receipts", action: "Reversal Status Repaired", beforeData: gr, afterData: reversedRows[0], reason: reason || "Existing inventory reversal found" });
    return { repaired: true, gr_no: gr.gr_no };
  }
  await upsertOneWithOptionalColumns("stock_movements", {
    reference_no: `REV-${gr.gr_no}`,
    movement_date: today(),
    type: "Goods Receipt Reversal",
    product_id: gr.product_id || product?.id || null,
    sku: gr.sku,
    product_name: gr.product_name,
    vendor: gr.vendor,
    qty: -Math.abs(qty),
    from_warehouse: gr.receipt_warehouse || product?.warehouse || "",
    from_bin_shelf: gr.receipt_bin_shelf || product?.bin_shelf || "",
    unit_fifo_cost: unitCost,
    total_fifo_cost: Math.abs(qty) * unitCost,
    document_no: gr.po_no || gr.gr_no,
    entered_by: reversedBy,
    reason: `Reversal of ${gr.gr_no}${gr.vendor_invoice_no ? ` / invoice ${gr.vendor_invoice_no}` : ""}${reason ? ` / ${reason}` : ""}`,
  }, "reference_no", ["from_bin_shelf"], "Receipt reversed. Run the multi-location SQL update so bin/shelf details can be stored.");
  if (product?.id) {
    const nextQty = Number(product.qty || 0) - qty;
    const { data: productRows, error: productError } = await supabase.from("products").update({ qty: nextQty }).eq("id", product.id).select("id,qty");
    if (productError) throw productError;
    if (!(productRows || []).length) throw new Error(`Receipt ${gr.gr_no} was reversed, but inventory for ${gr.sku || gr.product_name} could not be updated.`);
    product.qty = nextQty;
  }
  await postGoodsReceiptReversalLedger(gr);
  await writeAuditLog({ tableName: "goods_receipts", action: "Reversed", beforeData: gr, afterData: reversedRows[0], reason: reason || "Goods Receipt reversal" });
  return { repaired: false, gr_no: gr.gr_no, qty_reversed: qty };
}

async function renderQuotationsView() {
  currentCfg = tableMap.quotes;
  $("viewTitle").textContent = "Quotations";
  $("viewSub").textContent = "Create customer quotes and convert accepted quotes to sales orders.";
  const [quotes, lines, customers, products, salesOrders] = await Promise.all([
    getAll("quotations"),
    getAll("quotation_lines"),
    getAll("customers"),
    getAll("products"),
    getAll("sales_orders").catch(() => []),
  ]);
  const inactiveSalesOrders = new Set(salesOrders.filter((order) => /void|reversed|cancel/i.test(String(order.status || ""))).map((order) => order.order_no));
  const staleLinks = [...new Set(quotes.map((quote) => quote.sales_order_no).filter((orderNo) => orderNo && inactiveSalesOrders.has(orderNo)))];
  for (const orderNo of staleLinks) await releaseQuotationFromSalesOrder(orderNo, `Linked Sales Order ${orderNo} is cancelled, void, or reversed`);
  quotes.forEach((quote) => {
    if (!quote.sales_order_no || !inactiveSalesOrders.has(quote.sales_order_no)) return;
    quote.status = "Draft";
    quote.sales_order_no = null;
    quote.accepted_date = null;
  });
  currentRows = quotes.sort((a, b) => String(b.quote_date || "").localeCompare(String(a.quote_date || "")));
  currentRows.forEach((quote) => quote._lines = lines.filter((line) => line.quote_id === quote.id));
  productMeta.customers = customers.map((c) => c.name).filter(Boolean).sort();
  productMeta.customerRows = customers;
  productMeta.products = products.sort((a, b) => String(a.sku || "").localeCompare(String(b.sku || "")));
  $("content").innerHTML = `
    <div class="toolbar">
      <input class="searchbox" id="quoteSearch" placeholder="Search quotations by quote, customer, product, status">
    </div>
    <div class="tabbar">
      <button class="tabbtn ${quotationTab === "active" ? "active" : ""}" data-quotation-tab="active">Current Quotations ${currentRows.filter((quote) => !quotationIsExpired(quote)).length}</button>
      <button class="tabbtn ${quotationTab === "expired" ? "active" : ""}" data-quotation-tab="expired">Expired Quotations ${currentRows.filter(quotationIsExpired).length}</button>
    </div>
    <section class="panel">
      <div class="panel-head"><div class="panel-title"><strong>Quotations</strong><span>Unconverted quotations with no activity for more than 30 days move to Expired Quotations. They are never deleted automatically.</span></div><div class="actions"><button id="quoteCsvBtn">Excel</button><button onclick="window.print()">PDF / Print</button><button class="primary" id="newQuoteBtn">New quote</button></div></div>
      <div id="quoteTableHost"></div>
    </section>`;
  $("quoteSearch").oninput = renderFilteredQuotations;
  $("quoteCsvBtn").onclick = exportQuotationsCsv;
  $("newQuoteBtn").onclick = () => openQuotationModal();
  document.querySelectorAll("[data-quotation-tab]").forEach((button) => {
    button.onclick = () => {
      quotationTab = button.dataset.quotationTab;
      document.querySelectorAll("[data-quotation-tab]").forEach((item) => item.classList.toggle("active", item === button));
      renderFilteredQuotations();
    };
  });
  renderFilteredQuotations();
}

function renderFilteredQuotations() {
  const q = $("quoteSearch").value.toLowerCase();
  const rows = currentRows.filter((quote) => (quotationTab === "expired" ? quotationIsExpired(quote) : !quotationIsExpired(quote))).filter((quote) => !q || [
    quote.quote_no, quote.customer, quote.status, quote.sales_order_no,
    ...(quote._lines || []).map((line) => `${line.sku} ${line.product_name}`)
  ].join(" ").toLowerCase().includes(q));
  $("quoteTableHost").innerHTML = quotationTableHtml(rows);
  bindQuotationRows();
}

function quotationIsExpired(quote) {
  if (quote?.sales_order_no || /converted|accepted/i.test(String(quote?.status || ""))) return false;
  const activityValue = quote?.last_activity_at || quote?.updated_at || quote?.created_at || quote?.quote_date;
  const activityTime = new Date(activityValue || "").getTime();
  return Number.isFinite(activityTime) && activityTime < Date.now() - 30 * 24 * 60 * 60 * 1000;
}

function quotationTableHtml(rows) {
  const heads = ["Quote", "Date", "Customer", "Valid Until", "Status", "Lines", "Total", "Sales Order", ""];
  return `<div class="table-wrap"><table><thead><tr>${heads.map((h) => `<th>${esc(h)}</th>`).join("")}</tr><tr>${heads.map((h, i) => h ? `<th><input class="column-filter" data-col="${i}" placeholder="Filter ${esc(h)}"></th>` : "<th></th>").join("")}</tr></thead><tbody>${rows.length ? rows.map(quotationRowHtml).join("") : `<tr><td colspan="${heads.length}" class="empty">No quotations yet.</td></tr>`}</tbody></table></div>`;
}

function quotationRowHtml(quote) {
  const status = String(quote.status || "Draft");
  const converted = Boolean(quote.sales_order_no) || /converted/i.test(status);
  return `<tr>
    <td>${esc(quote.quote_no)}</td>
    <td>${esc(formatDisplayDate(quote.quote_date))}</td>
    <td>${esc(quote.customer || "")}</td>
    <td>${esc(formatDisplayDate(quote.valid_until))}</td>
    <td>${badge(status)}</td>
    <td>${esc((quote._lines || []).length)}</td>
    <td>${money(quotationTotal(quote))}</td>
    <td>${esc(quote.sales_order_no || "")}</td>
    <td><div class="rowactions"><button class="rowbtn" type="button" data-quote-pdf="${esc(quote.quote_no)}">PDF</button>${converted ? "" : `<button class="rowbtn primary" type="button" data-quote-accept="${esc(quote.quote_no)}">Convert to Sales Order</button>`}<button class="rowbtn" type="button" data-quote-edit="${esc(quote.quote_no)}">Edit</button>${converted ? "" : `<button class="rowbtn danger" type="button" data-quote-void="${esc(quote.quote_no)}">Void</button>`}</div></td>
  </tr>`;
}

function quotationTotal(quote) {
  return (quote._lines || []).reduce((sum, line) => sum + Number(line.qty || 0) * Number(line.price || 0), 0);
}

function bindQuotationRows() {
  document.querySelectorAll("[data-quote-edit]").forEach((b) => b.onclick = () => openQuotationModal(currentRows.find((quote) => quote.quote_no === b.dataset.quoteEdit)));
  document.querySelectorAll("[data-quote-void]").forEach((b) => b.onclick = () => voidQuotation(b.dataset.quoteVoid));
  document.querySelectorAll("[data-quote-pdf]").forEach((b) => b.onclick = () => printQuotation(b.dataset.quotePdf));
  document.querySelectorAll("[data-quote-accept]").forEach((b) => b.onclick = () => acceptQuotation(b.dataset.quoteAccept));
  document.querySelectorAll(".column-filter").forEach((input) => input.oninput = applyColumnFilters);
}

async function openQuotationModal(quote = null) {
  if (quote && (quote.sales_order_no || /converted|cancelled/i.test(quote.status || ""))) {
    alert(`${quote.quote_no} is ${quote.status || "converted"} and is locked. Use the linked Sales Order or preserve it as quotation history.`);
    return;
  }
  editing = quote;
  if (!productMeta.products?.length) productMeta.products = await getAll("products");
  if (!productMeta.customers?.length) productMeta.customers = (await getAll("customers")).map((c) => c.name).filter(Boolean).sort();
  const quoteNo = quote?.quote_no || await nextRefPreview("quote", "QT-", "quotations", "quote_no");
  const lines = quote?._lines?.length ? quote._lines : [{ sku: "", product_name: "", unit: "", qty: 1, price: 0 }];
  $("modalTitle").textContent = quote ? "Edit quotation" : "New quotation";
  $("modalBody").innerHTML = `
    <div class="form-grid">
      ${productInput("Quote #", "quote_no", quoteNo)}
      ${productSelect("Customer", "customer", productMeta.customers || [], quote?.customer || "", "New customer")}
      ${productInput("Date", "quote_date", quote?.quote_date || today(), "date")}
      ${productInput("Valid until", "valid_until", quote?.valid_until || "", "date")}
      ${productInput("Customer PO #", "customer_po", quote?.customer_po || "")}
      ${productSelect("Status", "status", ["Draft", "Sent", "Accepted", "Converted", "Cancelled"], quote?.status || "Draft")}
      <div class="field wide"><label>Line items</label>${quotationLineRows(lines)}</div>
      <div class="field wide"><label>Notes</label><textarea data-product-field="notes">${esc(quote?.notes || "")}</textarea></div>
    </div>
    <p class="notice">Quote pricing follows the product sales price from inventory. Change a line price only when you intentionally override the quoted price.</p>`;
  $("modalSave").onclick = saveQuotationModal;
  $("modal").style.display = "flex";
  document.querySelectorAll("[data-product-quick]").forEach((b) => b.onclick = () => quickCreateQuotationCustomer(quote));
  const addLineBtn = $("addQuoteLineBtn");
  if (addLineBtn) addLineBtn.onclick = addQuotationLineRow;
  const quickPartBtn = $("quickCreateQuotePartBtn");
  if (quickPartBtn) quickPartBtn.onclick = () => quickCreateQuotationPart();
  wireQuotationLinePricing();
}

function quotationLineRows(lines) {
  return `<div class="table-wrap"><table class="line-table"><thead><tr><th>Product</th><th>On Hand</th><th>Unit</th><th>Qty</th><th>Sales Price</th><th>Amount</th></tr></thead><tbody id="quoteLineBody">${lines.map((line, i) => quotationLineRowHtml(line, i)).join("")}</tbody></table></div><div class="actions table-actions"><button class="rowbtn" type="button" id="addQuoteLineBtn">Add row</button>${createPartButtonMarkup()}</div>`;
}

function quotationLineRowHtml(line = {}, index = 0) {
  const sku = line.sku || "";
  const product = productMeta.products?.find((p) => p.sku === sku) || {};
  const label = sku ? `${sku} - ${line.product_name || product.name || ""}` : "";
  const price = line.price ?? product.selling_price ?? 0;
  const unit = line.unit || product.unit || "";
  return `<tr>
    <td><input class="suggest-input" list="poProductOptions" data-quote-line="sku" data-line-index="${index}" value="${esc(label)}" placeholder="Search SKU, name, vendor" autocomplete="off">${productOptionsDatalist()}</td>
    <td data-quote-onhand>${esc(product.qty ?? "")}</td>
    <td data-quote-unit>${esc(unit)}</td>
    <td><input type="number" step="0.01" data-quote-line="qty" data-line-index="${index}" value="${esc(line.qty || "")}"></td>
    <td><input type="number" step="0.01" data-quote-line="price" data-line-index="${index}" value="${esc(price)}"></td>
    <td data-quote-amount>${money(Number(line.qty || 0) * Number(price || 0))}</td>
  </tr>`;
}

function addQuotationLineRow() {
  const body = $("quoteLineBody");
  if (!body) return;
  const index = body.querySelectorAll("tr").length;
  body.insertAdjacentHTML("beforeend", quotationLineRowHtml({}, index));
  wireQuotationLinePricing();
}

function wireQuotationLinePricing() {
  document.querySelectorAll("#quoteLineBody tr").forEach((tr) => {
    const skuInput = tr.querySelector('[data-quote-line="sku"]');
    const qtyInput = tr.querySelector('[data-quote-line="qty"]');
    const priceInput = tr.querySelector('[data-quote-line="price"]');
    const refreshAmount = () => {
      const qty = Number(qtyInput?.value || 0);
      const price = Number(priceInput?.value || 0);
      const amountCell = tr.querySelector("[data-quote-amount]");
      if (amountCell) amountCell.textContent = money(qty * price);
    };
    const applySelectedProduct = () => {
      if (!consumeExplicitProductSuggestion(skuInput)) return;
      const product = resolveProductLookup(skuInput.value);
      if (!product) return;
      skuInput.value = `${product.sku} - ${product.name || ""}`;
      const onHandCell = tr.querySelector("[data-quote-onhand]");
      const unitCell = tr.querySelector("[data-quote-unit]");
      if (onHandCell) onHandCell.textContent = product.qty ?? "";
      if (unitCell) unitCell.textContent = product.unit || "";
      if (priceInput) priceInput.value = product.selling_price ?? 0;
      refreshAmount();
    };
    if (skuInput) {
      skuInput.onchange = applySelectedProduct;
      skuInput.oninput = (event) => {
        if (event.isTrusted) clearPendingProductSuggestion(skuInput);
        if (!skuInput.value.trim()) {
          if (qtyInput) qtyInput.value = "";
          if (priceInput) priceInput.value = "";
          const onHandCell = tr.querySelector("[data-quote-onhand]");
          const unitCell = tr.querySelector("[data-quote-unit]");
          if (onHandCell) onHandCell.textContent = "";
          if (unitCell) unitCell.textContent = "";
          refreshAmount();
          return;
        }
      };
    }
    if (qtyInput) qtyInput.oninput = refreshAmount;
    if (priceInput) priceInput.oninput = refreshAmount;
  });
}

function parseQuotationLineRows() {
  return [...document.querySelectorAll("#quoteLineBody tr")].map((tr) => {
    const get = (field) => tr.querySelector(`[data-quote-line="${field}"]`)?.value || "";
    const product = resolveProductLookup(get("sku"));
    if (!product) return null;
    const qty = Number(get("qty") || 0);
    const price = Number(get("price") || product.selling_price || 0);
    return { product_id: product.id, sku: product.sku, product_name: product.name, unit: product.unit || "", qty, price };
  }).filter((line) => line && line.qty > 0);
}

function parseTypedQuotePart(text) {
  const raw = String(text || "").trim();
  if (!raw) return null;
  const existing = resolveProductLookup(raw);
  if (existing) return { existing };
  const clean = raw.split("|")[0].trim();
  const parts = clean.split(" - ").map((part) => part.trim()).filter(Boolean);
  const sku = (parts[0] || clean.split(/\s+/)[0] || "").trim();
  const name = (parts.slice(1).join(" - ") || clean.replace(sku, "").trim() || sku).trim();
  if (!sku) return null;
  return { sku, name };
}

function refreshProductDatalistOptions() {
  const datalist = $("poProductOptions");
  if (!datalist) return;
  datalist.innerHTML = "";
}

async function quickCreateQuotationPartFromRow(tr, { ask = true } = {}) {
  const skuInput = tr?.querySelector('[data-quote-line="sku"]');
  const qtyInput = tr?.querySelector('[data-quote-line="qty"]');
  const priceInput = tr?.querySelector('[data-quote-line="price"]');
  const typed = parseTypedQuotePart(skuInput?.value);
  if (!typed || typed.existing) return typed?.existing || null;
  const sku = typed.sku;
  let name = typed.name;
  const qty = Number(qtyInput?.value || 0);
  const price = Number(priceInput?.value || 0);
  if (ask) {
    if (!confirm(`${sku} is not in Product Master. Create it now so it can be used on this quotation?`)) return null;
    const enteredName = prompt("Product name", name === sku ? "" : name);
    if (enteredName === null) return null;
    name = enteredName.trim() || name || sku;
  }
  const unit = prompt("Unit of measurement", "Each");
  if (unit === null) return null;
  const firstProduct = productMeta.products?.[0] || {};
  const row = {
    sku,
    name,
    category: firstProduct.category || "Service Parts",
    unit: unit.trim() || "Each",
    warehouse: firstProduct.warehouse || "Main",
    bin_shelf: "",
    qty: 0,
    reorder_point: 0,
    cost: 0,
    selling_price: price || 0,
    markup_percent: null,
    source_vendor: null,
    barcode: "",
    batch: "",
    expiry: null,
    status: "Active",
    alternate_skus: "",
    compatible_with: "",
    notes: "Quick-created from quotation",
    photo_url: ""
  };
  const saved = await upsertOne("products", row, "sku");
  productMeta.products = await getAll("products");
  refreshProductDatalistOptions();
  if (skuInput) skuInput.value = `${saved.sku} - ${saved.name}`;
  const onHandCell = tr.querySelector("[data-quote-onhand]");
  const unitCell = tr.querySelector("[data-quote-unit]");
  const amountCell = tr.querySelector("[data-quote-amount]");
  if (onHandCell) onHandCell.textContent = saved.qty ?? 0;
  if (unitCell) unitCell.textContent = saved.unit || "";
  if (priceInput && !Number(priceInput.value || 0)) priceInput.value = saved.selling_price || 0;
  if (qtyInput && amountCell) amountCell.textContent = money(Number(qtyInput.value || qty || 0) * Number(priceInput?.value || saved.selling_price || 0));
  return saved;
}

async function quickCreateQuotationPart() {
  try {
    const rows = [...document.querySelectorAll("#quoteLineBody tr")];
    const focused = document.activeElement?.closest?.("#quoteLineBody tr");
    const target = focused || rows.find((tr) => {
      const typed = tr.querySelector('[data-quote-line="sku"]')?.value;
      return typed && !resolveProductLookup(typed);
    }) || rows[0];
    if (!target) {
      alert("Add a quote line first.");
      return;
    }
    await quickCreateQuotationPartFromRow(target);
  } catch (error) {
    alert(error.message || error);
  }
}

async function parseQuotationLineRowsForSave() {
  const lines = [];
  for (const tr of [...document.querySelectorAll("#quoteLineBody tr")]) {
    const get = (field) => tr.querySelector(`[data-quote-line="${field}"]`)?.value || "";
    let product = resolveProductLookup(get("sku"));
    const qty = Number(get("qty") || 0);
    const price = Number(get("price") || product?.selling_price || 0);
    if (!product && get("sku") && qty > 0) product = await quickCreateQuotationPartFromRow(tr);
    if (!product || qty <= 0) continue;
    lines.push({ product_id: product.id, sku: product.sku, product_name: product.name, unit: product.unit || "", qty, price });
  }
  return lines;
}

async function quickCreateQuotationCustomer(quote) {
  const name = prompt("Customer name to create");
  if (!name) return;
  try {
    if (!await approveMasterNameCreation("customers", name)) return;
    await upsertOne("customers", { reference: await nextRefPreview("customer", "C-", "customers", "reference"), name: name.trim(), terms: "30 days" }, "name");
    await ensurePartyMasterSuggestRows(true);
    await renderQuotationsView();
    await openQuotationModal(quote);
    const customerField = document.querySelector('[data-product-field="customer"]');
    if (customerField) customerField.value = name.trim();
  } catch (error) {
    alert(error.message || error);
  }
}

async function saveQuotationModal() {
  const record = {};
  document.querySelectorAll("[data-product-field]").forEach((el) => record[el.dataset.productField] = el.value || null);
  if (!record.customer) {
    alert("Customer is required for a quotation.");
    return;
  }
  const selectedCustomerMaster = await requirePartyMasterSelection("customers", record.customer, "a customer");
  if (!selectedCustomerMaster) return;
  record.customer = selectedCustomerMaster.name;
  const duplicateQuote = (currentRows || []).find((row) => row.quote_no === record.quote_no && row.id !== editing?.id);
  if (duplicateQuote) return alert(`Quotation ${record.quote_no} already exists.`);
  if (record.valid_until && record.quote_date && record.valid_until < record.quote_date) return alert("Quotation expiration cannot be earlier than the quotation date.");
  if (isLockedAccountingDate(record.quote_date)) return alert("This quotation date is inside the closed accounting period.");
    const lineRows = await parseQuotationLineRowsForSave();
  if (!lineRows.length) {
    alert("Add at least one quote line.");
    return;
  }
  try {
    const wasNew = !editing;
    record.last_activity_at = new Date().toISOString();
    const saved = await upsertOneWithOptionalColumns("quotations", record, "quote_no", ["last_activity_at"]);
    await supabase.from("quotation_lines").delete().eq("quote_id", saved.id);
    const { error } = await supabase.from("quotation_lines").insert(lineRows.map((line) => ({ ...line, quote_id: saved.id })));
    if (error) throw error;
    await writeAuditLog({ tableName: "quotations", action: wasNew ? "Created" : "Updated", beforeData: editing, afterData: { ...saved, lines: lineRows } });
    if (wasNew) await incrementSequence("quote");
    closeModal();
    renderQuotationsView();
  } catch (error) {
    alert(error.message || error);
  }
}

async function voidQuotation(quoteNo) {
  const quote = currentRows.find((row) => row.quote_no === quoteNo);
  if (!quote || quote.sales_order_no) return alert("A converted quotation cannot be voided. Reverse the related sales order first.");
  await loadAccountingCloseDate();
  const details = promptVoidDetails(`quotation ${quoteNo}`, "Customer declined / entered in error");
  if (!details) return;
  const { error } = await supabase.from("quotations").update({ status: "Cancelled", notes: [quote.notes, `Voided ${formatDisplayDate(details.voidDate)}: ${details.reason}`].filter(Boolean).join("\n") }).eq("quote_no", quoteNo);
  if (error) alert(error.message);
  renderQuotationsView();
}

async function acceptQuotation(quoteNo) {
  const quote = currentRows.find((row) => row.quote_no === quoteNo);
  if (!quote) return;
  if (quote.sales_order_no) {
    alert(`This quote is already converted to ${quote.sales_order_no}.`);
    return;
  }
  if (!confirm(`Accept ${quoteNo} and convert it to a sales order?`)) return;
  const lines = quote._lines || [];
  if (!lines.length) {
    alert("Cannot convert. Add at least one quotation line first.");
    return;
  }
  try {
    const orderNo = await nextRefPreview("so", "SO-", "sales_orders", "order_no");
    const hasShortage = hasSalesLineShortage(lines);
    const order = await upsertOneWithOptionalColumns("sales_orders", {
      order_no: orderNo,
      customer: quote.customer,
      customer_po: quote.customer_po || null,
      payment_mode: "PO",
      manager_override: quote.customer_po ? false : true,
      override_by: quote.customer_po ? null : (profile?.full_name || profile?.username || "Manager"),
      override_reason: quote.customer_po ? null : `Converted from accepted quotation ${quote.quote_no} without customer PO.`,
      order_date: today(),
      order_type: hasShortage ? "Backorder" : "Stock Order",
      special_order_status: hasShortage ? "Awaiting Stock" : "Unfulfilled",
      status: hasShortage ? "Backordered" : "Open",
      notes: `Converted from quotation ${quote.quote_no}${quote.notes ? `\n${quote.notes}` : ""}`,
    }, "order_no", ["payment_mode", "order_type", "special_order_status"], "Sales order created, but run the Special Order SQL update so shortage stages can be stored.");
    const orderLines = lines.map((line) => ({
      order_id: order.id,
      product_id: line.product_id,
      sku: line.sku,
      product_name: line.product_name,
      qty: Number(line.qty || 0),
      price: Number(line.price || 0),
    }));
    if (orderLines.length) {
      const { error } = await supabase.from("sales_order_lines").insert(orderLines);
      if (error) throw error;
    }
    await supabase.from("quotations").update({ status: "Converted", accepted_date: today(), sales_order_no: orderNo }).eq("id", quote.id);
    await incrementSequence("so");
    alert(`Sales Order ${orderNo} was created from quotation ${quoteNo}.`);
    await loadView("orders");
    await openSalesReorderPoPrompt({ sourceNo: orderNo, sourceLabel: `Quote ${quoteNo} / Sales Order ${orderNo}`, lines: orderLines });
  } catch (error) {
    alert(error.message || error);
  }
}

function printQuotation(quoteNo) {
  const quote = currentRows.find((row) => row.quote_no === quoteNo);
  if (!quote) return;
  const html = printableDocumentHtml({
    title: "Quotation",
    number: quote.quote_no,
    date: quote.quote_date,
    partyLabel: "Customer",
    partyName: quote.customer,
    meta: [["Valid Until", quote.valid_until || ""], ["Status", quote.status || "Draft"], ["Customer PO #", quote.customer_po || ""], ["Sales Order", quote.sales_order_no || ""]],
    heads: ["SKU", "Item", "Unit", "Qty", "Sales Price", "Amount"],
    lines: (quote._lines || []).map((line) => [line.sku, line.product_name || "", line.unit || "", line.qty, money(line.price), money(Number(line.qty || 0) * Number(line.price || 0))]),
    total: quotationTotal(quote),
    notes: quote.notes || "",
  });
  openPrintWindow(html, quote.quote_no);
}

function exportQuotationsCsv() {
  const heads = ["Quote", "Date", "Customer", "Valid Until", "Status", "Lines", "Total", "Sales Order"];
  const rows = [heads, ...currentRows.map((quote) => [quote.quote_no, quote.quote_date, quote.customer, quote.valid_until, quote.status, (quote._lines || []).length, quotationTotal(quote), quote.sales_order_no || ""])];
  downloadCsv(rows, "quotations.csv");
}

function salesPricingRateLabel(rate = {}) {
  const name = String(rate.rate_name || rate.rate_type || "").trim();
  const type = String(rate.rate_type || "").trim();
  return type === "Special Markup" && name && name !== type ? `${type} - ${name}` : name || type;
}

function salesPricingRatePrice(product = {}, rate = null) {
  if (!rate) return Number(product.selling_price || 0);
  const cost = salesInventoryUnitCost(product);
  if (!(cost > 0)) return 0;
  const multiplierPercent = Number(rate.markup_percent || 0);
  return Math.max(0, Math.round((cost * multiplierPercent / 100 + Number.EPSILON) * 100) / 100);
}

async function renderSalesPricingRatesView() {
  currentCfg = tableMap.salesrates;
  $("viewTitle").textContent = "Pricing Rates";
  $("viewSub").textContent = "Maintain optional cost-multiplier selling-price rules for Sales Orders.";
  currentRows = (await getAll("sales_pricing_rates")).sort((a, b) => String(a.rate_type || "").localeCompare(String(b.rate_type || "")) || String(a.rate_name || "").localeCompare(String(b.rate_name || "")));
  productMeta.salesPricingRates = currentRows;
  $("content").innerHTML = `
    <div class="toolbar"><input class="searchbox" id="salesRateSearch" placeholder="Search rate type, name, multiplier, description, or status"></div>
    <section class="panel">
      <div class="panel-head"><div class="panel-title"><strong>Sales Pricing Rates</strong><span>Selling price = Inventory / FIFO Cost multiplied by Rate Multiplier %. Leaving the Sales Order rate blank keeps Product Master or manual pricing.</span></div><div class="actions"><button id="salesRatesCsvBtn">Excel</button><button class="primary" id="newSalesRateBtn">Add pricing rate</button></div></div>
      <div id="salesRatesHost">${salesPricingRatesTableHtml(currentRows)}</div>
    </section>`;
  $("salesRateSearch").oninput = renderFilteredSalesPricingRates;
  $("salesRatesCsvBtn").onclick = () => exportRowsCsv(currentRows, "sales-pricing-rates.csv");
  $("newSalesRateBtn").onclick = () => openSalesPricingRateModal();
  bindSalesPricingRateRows();
}

function salesPricingRatesTableHtml(rows = []) {
  return `<div class="table-wrap"><table><thead><tr><th>Rate Type</th><th>Rate Name</th><th>Rate Multiplier %</th><th>Description / Reminder</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.length ? rows.map((rate) => `<tr><td>${esc(rate.rate_type || "")}</td><td><strong>${esc(rate.rate_name || "")}</strong></td><td>${Number(rate.markup_percent || 0).toFixed(2)}%</td><td class="preserve-lines">${esc(rate.description || "")}</td><td>${badge(rate.status || "Active")}</td><td><div class="rowactions"><button class="rowbtn" data-edit-sales-rate="${esc(rate.id)}">Edit</button>${rate.status !== "Inactive" ? `<button class="rowbtn danger" data-deactivate-sales-rate="${esc(rate.id)}">Deactivate</button>` : ""}</div></td></tr>`).join("") : `<tr><td colspan="6" class="empty">No pricing rates yet. Run the Sales Pricing Rates SQL update, then add a rate.</td></tr>`}</tbody></table></div>`;
}

function renderFilteredSalesPricingRates() {
  const q = String($("salesRateSearch")?.value || "").trim().toLowerCase();
  const rows = (currentRows || []).filter((rate) => !q || [rate.rate_type, rate.rate_name, rate.markup_percent, rate.description, rate.status].join(" ").toLowerCase().includes(q));
  $("salesRatesHost").innerHTML = salesPricingRatesTableHtml(rows);
  bindSalesPricingRateRows();
}

function bindSalesPricingRateRows() {
  document.querySelectorAll("[data-edit-sales-rate]").forEach((button) => button.onclick = () => openSalesPricingRateModal((currentRows || []).find((rate) => String(rate.id) === button.dataset.editSalesRate)));
  document.querySelectorAll("[data-deactivate-sales-rate]").forEach((button) => button.onclick = () => deactivateSalesPricingRate(button.dataset.deactivateSalesRate));
}

function openSalesPricingRateModal(rate = null) {
  editing = rate;
  $("modalTitle").textContent = rate ? `Edit pricing rate - ${salesPricingRateLabel(rate)}` : "New sales pricing rate";
  $("modalBody").innerHTML = `<div class="form-grid">
    ${productSelect("Rate type", "rate_type", ["Internal", "External Customer", "Special Markup"], rate?.rate_type || "Special Markup")}
    ${productInput("Rate name", "rate_name", rate?.rate_name || "")}
    ${productInput("Rate multiplier %", "markup_percent", rate?.markup_percent ?? 100, "number")}
    <div class="field wide"><label>Description / reminder</label><textarea data-product-field="description" placeholder="Explain when or why this rate should be used">${esc(rate?.description || "")}</textarea></div>
    ${productSelect("Status", "status", ["Active", "Inactive"], rate?.status || "Active")}
  </div><p class="notice">The Sales Order multiplies current Inventory / FIFO Cost by this percentage. Example: $100 cost at 140% becomes $140; 300% becomes $300. Existing saved orders keep their recorded line prices unless the rate is applied again.</p>`;
  const typeInput = document.querySelector('[data-product-field="rate_type"]');
  const nameInput = document.querySelector('[data-product-field="rate_name"]');
  const syncBuiltInName = () => {
    if (!nameInput || !typeInput) return;
    if (["Internal", "External Customer"].includes(typeInput.value)) {
      nameInput.value = typeInput.value;
      nameInput.readOnly = true;
    } else {
      nameInput.readOnly = false;
      if (["Internal", "External Customer"].includes(nameInput.value)) nameInput.value = "";
    }
  };
  typeInput.onchange = syncBuiltInName;
  syncBuiltInName();
  $("modalSave").textContent = "Save";
  $("modalSave").onclick = saveSalesPricingRate;
  $("modal").style.display = "flex";
}

async function saveSalesPricingRate() {
  const record = {};
  document.querySelectorAll("[data-product-field]").forEach((input) => record[input.dataset.productField] = input.value || null);
  record.rate_name = String(record.rate_name || "").trim();
  record.description = String(record.description || "").trim() || null;
  record.markup_percent = Number(record.markup_percent || 0);
  record.updated_at = new Date().toISOString();
  if (!record.rate_name) return alert("Rate name is required.");
  if (!Number.isFinite(record.markup_percent) || record.markup_percent < 0) return alert("Rate multiplier must be zero or greater.");
  if (["Internal", "External Customer"].includes(record.rate_type)) record.rate_name = record.rate_type;
  const duplicate = (currentRows || []).find((rate) => rate.id !== editing?.id && String(rate.rate_type).toLowerCase() === String(record.rate_type).toLowerCase() && String(rate.rate_name).toLowerCase() === record.rate_name.toLowerCase());
  if (duplicate) return alert(`${record.rate_name} already exists. Edit the existing rate instead.`);
  try {
    const saved = editing?.id
      ? await upsertOne("sales_pricing_rates", { id: editing.id, ...record }, "id")
      : await insertOne("sales_pricing_rates", record);
    await writeAuditLog({ tableName: "sales_pricing_rates", action: editing ? "Updated" : "Created", beforeData: editing, afterData: saved });
    closeModal();
    await renderSalesPricingRatesView();
  } catch (error) {
    alert(error.message || "Could not save the pricing rate. Run the Sales Pricing Rates SQL update first.");
  }
}

async function deactivateSalesPricingRate(id) {
  const rate = (currentRows || []).find((item) => String(item.id) === String(id));
  if (!rate || !confirm(`Deactivate ${salesPricingRateLabel(rate)}?\n\nExisting Sales Orders keep their saved prices.`)) return;
  const { error } = await supabase.from("sales_pricing_rates").update({ status: "Inactive", updated_at: new Date().toISOString() }).eq("id", rate.id);
  if (error) return alert(error.message || "Could not deactivate the pricing rate.");
  await renderSalesPricingRatesView();
}

