async function renderSalesOrdersView() {
  currentCfg = tableMap.orders;
  $("viewTitle").textContent = "Sales Orders";
  $("viewSub").textContent = "Track customer demand and committed inventory.";
  const [orders, lines, customers, products, productAlternates, salesPricingRates] = await Promise.all([
    getAll("sales_orders"),
    getAll("sales_order_lines"),
    getAll("customers"),
    getAll("products"),
    getAll("product_alternates").catch(() => []),
    getAll("sales_pricing_rates").catch(() => []),
  ]);
  currentRows = orders.sort((a, b) => String(b.order_date || "").localeCompare(String(a.order_date || "")));
  currentRows.forEach((order) => order._lines = lines.filter((line) => line.order_id === order.id));
  const activeOrderIds = new Set(orders.filter((order) => !/fulfilled|delivered|paid|void|reversed|cancel/i.test(String(order.status || ""))).map((order) => String(order.id || "")));
  const reservedBySku = lines.reduce((map, line) => {
    if (!activeOrderIds.has(String(line.order_id || ""))) return map;
    const sku = String(line.sku || "").trim().toLowerCase();
    if (!sku) return map;
    map.set(sku, Number(map.get(sku) || 0) + Math.max(0, Number(line.issued_qty || 0) - Number(line.shipped_qty || 0)));
    return map;
  }, new Map());
  productMeta.customers = customers.map((c) => c.name).filter(Boolean).sort();
  productMeta.products = products.map((product) => {
    const reservedQty = Number(reservedBySku.get(String(product.sku || "").trim().toLowerCase()) || 0);
    return { ...product, reserved_qty: reservedQty, available_qty: Math.max(0, Number(product.qty || 0) - reservedQty) };
  }).sort((a, b) => String(a.sku).localeCompare(String(b.sku)));
  productMeta.productAlternates = productAlternates;
  productMeta.salesPricingRates = salesPricingRates;
  $("content").innerHTML = `
    <div class="toolbar">
      <input class="searchbox" id="salesSearch" placeholder="Search sales orders by order, customer, PO, product, status">
    </div>
    <div class="tabbar">
      <button class="tabbtn ${salesOrderTab === "current" ? "active" : ""}" data-sales-order-tab="current">Current / Unfulfilled ${salesOrdersForTab(currentRows, "current").length}</button>
      <button class="tabbtn ${salesOrderTab === "special" ? "active" : ""}" data-sales-order-tab="special">Special Order / Backordered ${salesOrdersForTab(currentRows, "special").length}</button>
      <button class="tabbtn ${salesOrderTab === "issued" ? "active" : ""}" data-sales-order-tab="issued">Delivered / Issued ${salesOrdersForTab(currentRows, "issued").length}</button>
      <button class="tabbtn ${salesOrderTab === "all" ? "active" : ""}" data-sales-order-tab="all">All Sales Orders ${salesOrdersForTab(currentRows, "all").length}</button>
    </div>
    <section class="panel">
      <div class="panel-head"><div class="panel-title"><strong>Sales Orders</strong><span>Customer requests and fulfillment status</span></div><div class="actions"><button id="salesCsvBtn">Excel</button><button onclick="window.print()">PDF / Print</button><button id="newSpecialSalesBtn">New special order</button><button class="primary" id="newSalesBtn">New order</button></div></div>
      <div id="salesTableHost">${salesOrderTableHtml(salesOrdersForTab(currentRows, salesOrderTab))}</div>
    </section>`;
  $("salesSearch").oninput = renderFilteredSalesOrders;
  $("salesCsvBtn").onclick = exportSalesOrdersCsv;
  $("newSalesBtn").onclick = () => openSalesOrderModal();
  $("newSpecialSalesBtn").onclick = () => openSalesOrderModal(null, { orderType: "Special Order" });
  document.querySelectorAll("[data-sales-order-tab]").forEach((button) => {
    button.onclick = () => {
      salesOrderTab = button.dataset.salesOrderTab;
      document.querySelectorAll("[data-sales-order-tab]").forEach((item) => item.classList.toggle("active", item === button));
      renderFilteredSalesOrders();
    };
  });
  bindSalesRows();
}

function salesOrdersForTab(rows, tab = salesOrderTab) {
  const issuedStatuses = ["fulfilled", "issued", "delivered", "invoiced", "posted", "paid"];
  if (tab === "all") return [...(rows || [])];
  return (rows || []).filter((order) => {
    const issued = salesOrderFullyShipped(order) || issuedStatuses.includes(String(order.status || "").toLowerCase());
    const special = /special order|backorder/i.test(order.order_type || "") && !issued;
    if (tab === "issued") return issued;
    if (tab === "special") return special;
    return !issued && !special;
  });
}

function salesOrderFullyShipped(order = {}) {
  return Boolean((order._lines || []).length) && (order._lines || []).every((line) => Number(line.shipped_qty || 0) >= Number(line.qty || 0));
}

function renderFilteredSalesOrders() {
  const q = $("salesSearch").value.toLowerCase();
  const rows = salesOrdersForTab(currentRows, salesOrderTab).filter((order) => !q || [
    order.order_no, order.customer, order.customer_po, order.order_date, order.status, salesOrderDisplayStatus(order), order.invoice_no,
    ...(order._lines || []).map((line) => `${line.sku} ${line.product_name}`)
  ].join(" ").toLowerCase().includes(q));
  $("salesTableHost").innerHTML = salesOrderTableHtml(rows);
  bindSalesRows();
}

function salesOrderTableHtml(rows) {
  const heads = ["Order", "Type", "Customer", "PO / Reference", "Payment Mode", "Pricing Rate", "Date", "Stage", "Status", "ORD", "ISS", "SHP", "To Order", "Deposit", "Total", ""];
  return `<div class="table-wrap"><table><thead><tr>${heads.map((h) => `<th>${esc(h)}</th>`).join("")}</tr><tr>${heads.map((h, i) => h ? `<th><input class="column-filter" data-col="${i}" placeholder="Filter ${esc(h)}"></th>` : "<th></th>").join("")}</tr></thead><tbody>${rows.length ? rows.map(salesOrderRowHtml).join("") : `<tr><td colspan="${heads.length}" class="empty">No sales orders yet.</td></tr>`}</tbody></table></div>`;
}

function salesOrderRowHtml(order) {
  const poBadge = order.customer_po ? badge(order.customer_po) : String(order.payment_mode || "PO").toLowerCase() === "po" ? badge("Missing PO") : badge("Optional");
  const toOrderQty = salesOrderShortageQty(order);
  const issued = salesOrderFullyShipped(order) || ["fulfilled", "issued", "delivered", "posted", "paid"].includes(String(order.status || "").toLowerCase());
  const inactive = /void|reversed|cancelled/i.test(order.status || "");
  const quantities = salesOrderQuantitySummary(order);
  const canInvoice = salesOrderUnbilledShippedQty(order) > 0;
  const displayStatus = salesOrderDisplayStatus(order);
  const canEdit = !inactive && !order.invoice_no && !/paid/i.test(order.status || "");
  return `<tr>
    <td>${esc(order.order_no)}</td>
    <td>${badge(order.order_type || "Stock Order")}</td>
    <td>${esc(order.customer || "")}</td>
    <td>${poBadge}</td>
    <td>${badge(order.payment_mode || "PO")}</td>
    <td>${order.pricing_rate_name ? `${badge(order.pricing_rate_name)}<br><small>${Number(order.pricing_markup_percent || 0).toFixed(2)}%</small>` : ""}</td>
    <td>${esc(formatDisplayDate(order.order_date))}</td>
    <td>${badge(order.special_order_status || "")}</td>
    <td>${badge(displayStatus)}</td>
    <td>${esc(quantities.ordered)}</td>
    <td>${esc(quantities.issued)}</td>
    <td title="Quantity shipped/released to the customer and deducted from inventory">${esc(quantities.shipped)}</td>
    <td>${toOrderQty ? badge(`${toOrderQty} to order`) : ""}</td>
    <td>${Number(order.deposit_amount || 0) ? `${money(order.deposit_amount)}<br><small>${esc(order.deposit_invoice_no || "")}</small>` : ""}</td>
    <td>${money(salesOrderTotal(order))}</td>
    <td><div class="rowactions"><button class="rowbtn" type="button" data-sales-sign="${esc(order.order_no)}">Sign</button><button class="rowbtn" type="button" data-sales-pdf="${esc(order.order_no)}">PDF</button>${order.invoice_no ? `<button class="rowbtn" type="button" data-sales-invoice-history="${esc(order.order_no)}">PDF Invoice History</button>` : ""}${!inactive && salesOrderAtOrBelowReorder(order) ? `<button class="rowbtn" type="button" data-sales-create-po="${esc(order.order_no)}">Create PO</button>` : ""}${!inactive && /special order|backorder/i.test(order.order_type || "") && !order.deposit_invoice_no && !issued ? `<button class="rowbtn" type="button" data-sales-deposit="${esc(order.order_no)}">Deposit invoice</button>` : ""}${!inactive && canInvoice ? `<button class="rowbtn" type="button" data-sales-invoice="${esc(order.order_no)}">Inv</button>` : ""}${!inactive && !issued ? `<button class="rowbtn" type="button" data-sales-issue="${esc(order.order_no)}">Deliver / Issue</button>` : ""}${canEdit ? `<button class="rowbtn" type="button" data-sales-edit="${esc(order.order_no)}">Edit</button>` : ""}${!inactive && issued ? `<button class="rowbtn danger" type="button" data-sales-reverse="${esc(order.order_no)}">Reverse</button>` : ""}${!inactive && !issued ? `<button class="rowbtn danger" type="button" data-sales-void="${esc(order.order_no)}">Void</button>` : ""}</div></td>
  </tr>`;
}

function salesOrderDisplayStatus(order = {}) {
  const status = String(order.status || "Open");
  if (/paid/i.test(status)) return "Paid";
  if (String(order.invoice_no || "").trim()) return "Invoiced";
  return status;
}

function salesOrderQuantitySummary(order = {}) {
  return (order._lines || []).reduce((totals, line) => {
    totals.ordered += Number(line.qty || 0);
    totals.issued += Number(line.issued_qty || 0);
    totals.shipped += Number(line.shipped_qty || 0);
    totals.invoiced += Number(line.invoiced_qty || 0);
    return totals;
  }, { ordered: 0, issued: 0, shipped: 0, invoiced: 0 });
}

function salesOrderUnbilledShippedQty(order = {}) {
  // ISS is reserved stock. Confirming an invoice is the customer release, so
  // the invoice may consume any reserved quantity that has not been invoiced.
  return (order._lines || []).reduce((sum, line) => sum + Math.max(0, Number(line.issued_qty || 0) - Number(line.invoiced_qty || 0)), 0);
}

function salesOrderTotal(order) {
  const partsSubtotal = (order._lines || []).reduce((sum, line) => sum + Number(line.qty || 0) * Number(line.price || 0), 0);
  return partsSubtotal + Math.max(0, Number(order.freight_amount || 0));
}

function salesOrderShortageQty(order) {
  if (["quotation", "fulfilled", "paid", "cancelled"].includes(String(order.status || "").toLowerCase())) return 0;
  return (order._lines || []).reduce((sum, line) => {
    const product = (productMeta.products || []).find((p) => p.sku === line.sku);
    return sum + Math.max(0, Number(line.qty || 0) - Number(product?.qty || 0));
  }, 0);
}

function salesOrderAtOrBelowReorder(order = {}) {
  return (order._lines || []).some((line) => {
    const product = (productMeta.products || []).find((item) => item.id === line.product_id || String(item.sku || "").toLowerCase() === String(line.sku || "").toLowerCase());
    if (!product) return false;
    return Number(product.qty || 0) - Number(line.qty || 0) <= Math.max(0, Number(product.reorder_point || 0));
  });
}

function bindSalesRows() {
  document.querySelectorAll("[data-sales-edit]").forEach((b) => b.onclick = () => openSalesOrderModal(currentRows.find((order) => order.order_no === b.dataset.salesEdit)));
  document.querySelectorAll("[data-sales-void]").forEach((b) => b.onclick = () => voidSalesOrder(b.dataset.salesVoid));
  document.querySelectorAll("[data-sales-reverse]").forEach((b) => b.onclick = () => reverseSalesOrder(b.dataset.salesReverse));
  document.querySelectorAll("[data-sales-pdf]").forEach((b) => b.onclick = () => printSalesOrder(b.dataset.salesPdf));
  document.querySelectorAll("[data-sales-sign]").forEach((b) => b.onclick = () => openSavedSignatureModal("sales_orders", "order_no", b.dataset.salesSign, `Save signature for ${b.dataset.salesSign}`, () => renderSalesOrdersView()));
  document.querySelectorAll("[data-sales-issue]").forEach((b) => b.onclick = () => issueSalesOrder(b.dataset.salesIssue));
  document.querySelectorAll("[data-sales-invoice]").forEach((b) => b.onclick = () => invoiceSalesOrder(b.dataset.salesInvoice));
  document.querySelectorAll("[data-sales-invoice-history]").forEach((b) => b.onclick = () => printSalesOrderInvoiceHistory(b.dataset.salesInvoiceHistory));
  document.querySelectorAll("[data-sales-deposit]").forEach((b) => b.onclick = () => createSalesOrderDepositInvoice(b.dataset.salesDeposit));
  document.querySelectorAll("[data-sales-create-po]").forEach((b) => b.onclick = () => openSalesOrderReorderPrompt(b.dataset.salesCreatePo));
  document.querySelectorAll(".column-filter").forEach((input) => input.oninput = applyColumnFilters);
}

async function openSalesOrderReorderPrompt(orderNo) {
  const order = (currentRows || []).find((row) => row.order_no === orderNo);
  if (!order) return;
  const opened = await openSalesReorderPoPrompt({ sourceNo: order.order_no, sourceLabel: `Sales Order ${order.order_no}`, lines: order._lines || [] });
  if (!opened) alert(`${order.order_no} has no new reorder quantity to purchase. An existing linked reorder PO may already cover the requirement.`);
}

async function salesOrderLinkedPurchaseOrdersHtml(orderNo) {
  const [purchaseOrders, purchaseLines, receipts] = await Promise.all([
    getAll("purchase_orders").catch(() => []),
    getAll("purchase_order_lines").catch(() => []),
    getAll("goods_receipts").catch(() => []),
  ]);
  const marker = `[Reorder Source: ${orderNo}]`;
  const linked = purchaseOrders.filter((po) => String(po.linked_sales_order_no || "") === String(orderNo)
    || String(po.notes || "").includes(marker));
  if (!linked.length) return `<div class="field wide"><label>Linked vendor POs</label><p class="notice">No vendor POs are linked yet. Save this Sales Order, then use <strong>Create Vendor PO</strong>. You may create multiple POs without losing this Sales Order.</p></div>`;
  linked.forEach((po) => {
    po._lines = purchaseLines.filter((line) => String(line.po_id || "") === String(po.id || "") || String(line.po_no || "") === String(po.po_no || ""));
    po._receipts = receipts.filter((receipt) => String(receipt.po_id || "") === String(po.id || "") || String(receipt.po_no || "") === String(po.po_no || ""));
  });
  const rows = linked.sort((a, b) => String(a.po_date || "").localeCompare(String(b.po_date || "")) || String(a.po_no || "").localeCompare(String(b.po_no || ""))).map((po) => {
    const ordered = (po._lines || []).reduce((sum, line) => sum + Number(line.qty || 0), 0);
    const received = activeReceipts(po).reduce((sum, receipt) => sum + Number(receipt.received_qty || 0), 0);
    const remaining = Math.max(0, ordered - received);
    const lines = (po._lines || []).map((line) => {
      const lineReceived = poReceivedQuantityByLine(po, line);
      return `${line.sku || line.product_name || "Item"}: ${Number(line.qty || 0)} ordered / ${lineReceived} received / ${Math.max(0, Number(line.qty || 0) - lineReceived)} remaining`;
    }).join("\n");
    return `<tr><td><button type="button" class="rowbtn" data-linked-sales-po="${esc(po.po_no)}">${esc(po.po_no)}</button></td><td>${esc(po.vendor || "")}</td><td class="numcell">${esc(ordered)}</td><td class="numcell">${esc(received)}</td><td class="numcell">${esc(remaining)}</td><td>${esc(po.status || "Draft")}</td><td class="preserve-lines">${esc(lines)}</td></tr>`;
  }).join("");
  return `<div class="field wide"><label>Linked vendor POs (${linked.length})</label><div class="table-wrap"><table class="line-table"><thead><tr><th>PO #</th><th>Vendor</th><th>Ordered</th><th>Received</th><th>Remaining</th><th>Status</th><th>Line progress</th></tr></thead><tbody>${rows}</tbody></table></div><small>Create as many vendor POs as needed. Goods Receipts update this progress automatically.</small></div>`;
}

async function salesOrderLinkedPurchaseOrderMap(orderNo) {
  if (!orderNo) return {};
  const [purchaseOrders, purchaseLines] = await Promise.all([
    getAll("purchase_orders").catch(() => []),
    getAll("purchase_order_lines").catch(() => []),
  ]);
  const marker = `[Reorder Source: ${orderNo}]`;
  const linked = purchaseOrders.filter((po) => String(po.linked_sales_order_no || "") === String(orderNo)
    || String(po.notes || "").includes(marker));
  const linkedIds = new Set(linked.map((po) => String(po.id || "")));
  const poById = new Map(linked.map((po) => [String(po.id || ""), po]));
  return purchaseLines.reduce((map, line) => {
    if (!linkedIds.has(String(line.po_id || ""))) return map;
    const sku = String(line.sku || "").trim().toLowerCase();
    const po = poById.get(String(line.po_id || ""));
    if (!sku || !po?.po_no) return map;
    if (!map[sku]) map[sku] = [];
    if (!map[sku].some((item) => item.po_no === po.po_no)) map[sku].push({ po_no: po.po_no, status: po.status || "Draft" });
    return map;
  }, {});
}

async function openSalesOrderModal(order = null, options = {}) {
  const readOnly = Boolean(order && (String(order.invoice_no || "").trim() || /^(invoiced|paid|void|reversed|cancelled)$/i.test(order.status || "")));
  editing = order;
  if (!Array.isArray(productMeta.salesPricingRates)) productMeta.salesPricingRates = await getAll("sales_pricing_rates").catch(() => []);
  const prefill = options.prefill || {};
  productMeta.pendingSalesPoSource = options.sourcePo || (order?.source_po_no ? { po_no: order.source_po_no } : null);
  const orderNo = order?.order_no || await nextRefPreview("so", "SO-", "sales_orders", "order_no");
  const lines = order?._lines?.length ? order._lines : prefill.lines?.length ? prefill.lines : [{ sku: "", product_name: "", qty: 1, price: 0 }];
  const sourcePoNo = order?.source_po_no || options.sourcePo?.po_no || "";
  const initialPaymentMode = order?.payment_mode || prefill.payment_mode || "PO";
  const initialReferenceLabel = paymentReferencePrintLabel(initialPaymentMode);
  const initialReferenceIsPo = initialReferenceLabel === "Customer PO #";
  const linkedPoSummary = order?.order_no ? await salesOrderLinkedPurchaseOrdersHtml(order.order_no) : "";
  const linkedPoMap = order?.order_no ? await salesOrderLinkedPurchaseOrderMap(order.order_no) : {};
  $("modalTitle").textContent = readOnly ? `View sales order ${order.order_no}` : order ? "Edit sales order" : "New sales order";
  $("modalBody").innerHTML = `
    <div class="form-grid">
      ${productInput("Number", "order_no", orderNo)}
      ${productSelect("Customer", "customer", productMeta.customers || [], order?.customer || prefill.customer || "", "New customer")}
      ${productInput("Date", "order_date", order?.order_date || prefill.order_date || today(), "date")}
      ${sourcePoNo ? `<div class="field"><label>Source Purchase Order</label><input value="${esc(sourcePoNo)}" disabled><small>Traceable to the customer-designated PO and Goods Receipt.</small></div>` : ""}
      <div class="field ${initialReferenceIsPo ? "required-field" : ""}" id="salesPaymentReferenceField"><label id="salesPaymentReferenceLabel">${esc(initialReferenceLabel)}</label><input data-product-field="customer_po" value="${esc(order?.customer_po || prefill.customer_po || "")}" placeholder="${initialReferenceIsPo ? "Required customer PO number" : "Optional cash / credit card reference"}" ${initialReferenceIsPo ? "required" : ""}><small id="salesPaymentReferenceHelp">${initialReferenceIsPo ? "Required when payment mode is PO." : "Optional reference for the cash or credit card payment."}</small></div>
      ${productInput("Requested by", "requested_by", order?.requested_by || prefill.requested_by || "")}
      ${productSelect("Mode of payment", "payment_mode", ["Cash", "Credit Card", "PO"], initialPaymentMode)}
      ${salesOrderPricingRateField(order?.pricing_rate_id || prefill.pricing_rate_id || "")}
      ${productInput("Freight billed to customer", "freight_amount", order?.freight_amount ?? prefill.freight_amount ?? 0, "number")}
      ${productSelect("Order type", "order_type", ["Stock Order", "Special Order", "Backorder"], order?.order_type || prefill.order_type || options.orderType || "Stock Order")}
      ${linkedPoSummary}
       <div class="field wide"><label>Line items</label>${salesLineRows(lines, linkedPoMap, Boolean(order?.order_no))}</div>
      <div class="field wide"><label>Notes</label><textarea data-product-field="notes">${esc(order?.notes || prefill.notes || "")}</textarea></div>
    </div>
    <p class="notice">${sourcePoNo ? `This Sales Order is prefilled from received items on ${esc(sourcePoNo)}. Review the PO or payment reference, payment mode, quantities, and selling prices before saving. ` : ""}The optional pricing rate calculates Selling Price from Inventory / FIFO Cost. Leave it blank to keep Product Master or manually entered prices. Manager or Administrator approval is still required below Product Master selling price. For an out-of-stock line, use Check alternate to select and remember a replacement part. Goods issue and invoicing stay blocked until enough stock is available.</p>`;
  $("modalSave").textContent = "Save and Close";
  $("modalSave").onclick = saveSalesOrderModal;
  setupSalesOrderModalFooter(order);
  $("modal").style.display = "flex";
  bindPaymentReferenceField({ paymentSelector: '[data-product-field="payment_mode"]', referenceSelector: '[data-product-field="customer_po"]', labelId: "salesPaymentReferenceLabel", helpId: "salesPaymentReferenceHelp" });
  document.querySelectorAll("[data-product-quick]").forEach((b) => b.onclick = () => quickCreateSalesCustomer(order));
  const addLineBtn = $("addSalesLineBtn");
  if (addLineBtn) addLineBtn.onclick = addSalesLineRow;
  const selectedPoBtn = $("createSelectedSalesPoBtn");
  if (selectedPoBtn) selectedPoBtn.onclick = async () => {
    if (!order?.order_no) return alert("Save the Sales Order before creating a linked vendor PO.");
    if (modalDirty) return alert("Save the Sales Order first so the vendor PO uses the latest quantities.");
    const selectedLines = [...document.querySelectorAll("#salesLineBody tr")].filter((row) => row.querySelector("[data-sales-po-select]")?.checked).map((row) => {
      const product = resolveProductLookup(row.querySelector('[data-sales-line="sku"]')?.value || "");
      if (!product) return null;
      return {
        product_id: product.id,
        sku: product.sku,
        product_name: product.name || product.sku,
        unit: row.querySelector('[data-sales-line="unit"]')?.value || product.unit || "Each",
        qty: Number(row.querySelector('[data-sales-line="qty"]')?.value || 0),
      };
    }).filter(Boolean);
    if (!selectedLines.length) return alert("Tick at least one out-of-stock line first.");
    productMeta.salesPoReturnOrderNo = order.order_no;
    const opened = await openSalesReorderPoPrompt({ sourceNo: order.order_no, sourceLabel: `Sales Order ${order.order_no}`, lines: selectedLines, includeAllLines: true });
    if (!opened) alert("The selected quantities are already covered by linked open vendor POs.");
  };
  document.querySelectorAll("[data-linked-sales-po]").forEach((button) => button.onclick = async () => {
    const pos = await getAll("purchase_orders");
    const lines = await getAll("purchase_order_lines");
    const receipts = await getAll("goods_receipts");
    const po = pos.find((row) => row.po_no === button.dataset.linkedSalesPo);
    if (!po) return alert("That linked purchase order could not be loaded.");
    po._lines = lines.filter((line) => String(line.po_id || "") === String(po.id || "") || String(line.po_no || "") === String(po.po_no || ""));
    po._receipts = receipts.filter((receipt) => String(receipt.po_id || "") === String(po.id || "") || String(receipt.po_no || "") === String(po.po_no || ""));
    productMeta.salesPoReturnOrderNo = order?.order_no || null;
    openPurchaseOrderRecord(po);
  });
  wireSalesOrderLinePricing();
  if (readOnly) setSalesOrderModalReadOnly(order);
}

function setSalesOrderModalReadOnly(order) {
  const body = $("modalBody");
  if (!body) return;
  body.querySelectorAll("input, select, textarea").forEach((field) => {
    field.disabled = true;
    field.setAttribute("aria-readonly", "true");
  });
  body.querySelectorAll("button").forEach((button) => {
    // Reference links remain available so the completed order can still be
    // traced to its related vendor purchase orders.
    if (!button.matches("[data-linked-sales-po]")) button.disabled = true;
  });
  ["salesOrderInvoiceModalBtn", "salesOrderCreatePoModalBtn", "salesOrderSaveOnlyBtn", "modalSave"].forEach((id) => {
    const button = document.getElementById(id);
    if (button) button.disabled = true;
  });
  const save = $("modalSave");
  if (save) {
    save.textContent = "Close";
    save.disabled = false;
    save.onclick = () => closeModal();
  }
  const cancel = $("modalCancel");
  if (cancel) cancel.textContent = "Close";
  const notice = document.createElement("p");
  notice.className = "notice";
  notice.innerHTML = `<strong>Read-only completed order.</strong> ${esc(order.order_no)} is ${esc(order.status || "completed")}. Details cannot be changed. Use Reverse or Void from the Sales Orders action menu when a controlled correction is required.`;
  body.prepend(notice);
}

function paymentReferencePrintLabel(paymentMode = "PO") {
  return String(paymentMode || "PO").toLowerCase() === "po" ? "Customer PO #" : "Reference #";
}

function bindPaymentReferenceField({ paymentSelector, referenceSelector, labelId, helpId }) {
  const root = document.getElementById(labelId)?.closest(".modal-body") || $("modalBody") || document;
  const payment = root.querySelector(paymentSelector);
  const reference = root.querySelector(referenceSelector);
  const label = document.getElementById(labelId);
  const help = document.getElementById(helpId);
  if (!payment || !reference || !label) return;
  const sync = () => {
    const isPo = String(payment.value || "PO").toLowerCase() === "po";
    label.textContent = isPo ? "Customer PO #" : "Reference #";
    reference.placeholder = isPo ? "Required customer PO number" : "Optional cash / credit card reference";
    reference.required = isPo;
    reference.closest(".field")?.classList.toggle("required-field", isPo);
    if (help) help.textContent = isPo ? "Required when payment mode is PO." : "Optional reference for the cash or credit card payment.";
  };
  payment.addEventListener("input", sync);
  payment.addEventListener("change", sync);
  payment.addEventListener("blur", sync);
  sync();
}

function salesOrderPricingRateField(selectedId = "") {
  const rates = (productMeta.salesPricingRates || []).filter((rate) => rate.status !== "Inactive" || String(rate.id) === String(selectedId));
  return `<div class="field"><label>Selling price rate (optional)</label><div class="sales-rate-selector"><select data-product-field="pricing_rate_id" id="salesPricingRateSelect"><option value="">Blank - Product Master / manual price</option>${rates.map((rate) => `<option value="${esc(rate.id)}" ${String(rate.id) === String(selectedId) ? "selected" : ""}>${esc(salesPricingRateLabel(rate))} (${Number(rate.markup_percent || 0).toFixed(2)}% of cost)</option>`).join("")}</select><button type="button" class="rowbtn" id="applySalesPricingRateBtn">Apply rate to all lines</button></div><small id="salesPricingRateHelp">${selectedId ? esc((rates.find((rate) => String(rate.id) === String(selectedId)) || {}).description || "Rate multiplies Inventory / FIFO Cost.") : "Optional. Blank leaves the line selling prices unchanged."}</small></div>`;
}

function selectedSalesPricingRate() {
  const id = document.getElementById("salesPricingRateSelect")?.value || "";
  return (productMeta.salesPricingRates || []).find((rate) => String(rate.id) === String(id)) || null;
}

function applySelectedSalesPricingRate({ notify = true } = {}) {
  const rate = selectedSalesPricingRate();
  if (!rate) {
    if (notify) alert("Choose Internal, External Customer, or a Special Markup rate first. Leaving it blank keeps the existing prices.");
    return false;
  }
  let applied = 0;
  const missingCost = [];
  document.querySelectorAll("#salesLineBody tr").forEach((row) => {
    const product = resolveProductLookup(row.querySelector('[data-sales-line="sku"]')?.value || "");
    const priceInput = row.querySelector('[data-sales-line="price"]');
    if (!product || !priceInput) return;
    const price = salesPricingRatePrice(product, rate);
    if (!(price > 0)) {
      missingCost.push(product.sku || product.name || "Product");
      return;
    }
    priceInput.value = String(price);
    priceInput.dispatchEvent(new Event("input", { bubbles: true }));
    applied += 1;
  });
  const help = document.getElementById("salesPricingRateHelp");
  if (help) help.textContent = `${salesPricingRateLabel(rate)}: Inventory / FIFO Cost × ${Number(rate.markup_percent || 0).toFixed(2)}%. ${rate.description || ""}`.trim();
  if (notify) {
    if (applied) alert(`${salesPricingRateLabel(rate)} was applied to ${applied} line${applied === 1 ? "" : "s"}.${missingCost.length ? `\n\nNot changed because inventory cost is zero: ${missingCost.join(", ")}` : ""}`);
    else alert(missingCost.length ? `The rate could not be applied because inventory cost is zero for: ${missingCost.join(", ")}` : "Add or select a Product Master item first.");
  }
  return applied > 0;
}

function setupSalesOrderModalFooter(order = null) {
  document.getElementById("salesOrderSaveOnlyBtn")?.remove();
  document.getElementById("salesOrderPdfModalBtn")?.remove();
  document.getElementById("salesOrderInvoiceModalBtn")?.remove();
  document.getElementById("salesOrderInvoiceHistoryModalBtn")?.remove();
  document.getElementById("salesOrderCreatePoModalBtn")?.remove();
  const footer = $("modalSave")?.parentElement;
  if (!footer) return;
  const saveOnlyButton = document.createElement("button");
  saveOnlyButton.id = "salesOrderSaveOnlyBtn";
  saveOnlyButton.type = "button";
  saveOnlyButton.textContent = "Save";
  saveOnlyButton.title = "Save changes and keep this Sales Order open.";
  saveOnlyButton.onclick = () => saveSalesOrderModal({ keepOpen: true });
  const pdfButton = document.createElement("button");
  pdfButton.id = "salesOrderPdfModalBtn";
  pdfButton.type = "button";
  pdfButton.textContent = "PDF";
  pdfButton.disabled = !order?.order_no;
  pdfButton.title = order?.order_no ? `Open PDF for ${order.order_no}` : "Save the Sales Order before opening its PDF.";
  pdfButton.onclick = () => {
    if (!order?.order_no) return;
    printSalesOrder(order.order_no);
  };

  const invoiceButton = document.createElement("button");
  invoiceButton.id = "salesOrderInvoiceModalBtn";
  invoiceButton.type = "button";
  const unbilledShipped = salesOrderUnbilledShippedQty(order || {});
  invoiceButton.textContent = unbilledShipped > 0 ? (order?.invoice_no ? "Create Next Invoice" : "Invoice") : (order?.invoice_no ? "Fully Invoiced" : "Invoice");
  invoiceButton.disabled = !order?.order_no || !(unbilledShipped > 0);
  invoiceButton.title = !order?.order_no
    ? "Save the Sales Order before invoicing."
    : unbilledShipped > 0
      ? `Review a draft invoice for ${unbilledShipped} reserved, uninvoiced unit(s). Confirming updates SHP and inventory.`
      : "Reserve stock (ISS) before creating an invoice.";
  invoiceButton.onclick = async () => {
    if (!order?.order_no || !(unbilledShipped > 0)) return;
    if (modalDirty) {
      alert("Save and Close the Sales Order first so the invoice uses the latest customer, quantity, freight, and price details.");
      return;
    }
    closeModal(true);
    await invoiceSalesOrder(order.order_no);
  };

  const invoiceHistoryButton = document.createElement("button");
  invoiceHistoryButton.id = "salesOrderInvoiceHistoryModalBtn";
  invoiceHistoryButton.type = "button";
  invoiceHistoryButton.textContent = "PDF Invoice History";
  invoiceHistoryButton.disabled = !order?.order_no || !order?.invoice_no;
  invoiceHistoryButton.title = order?.invoice_no ? `Open every invoice linked to ${order.order_no}` : "No invoices have been created for this Sales Order.";
  invoiceHistoryButton.onclick = () => {
    if (order?.order_no && order?.invoice_no) printSalesOrderInvoiceHistory(order.order_no);
  };

  const createPoButton = document.createElement("button");
  createPoButton.id = "salesOrderCreatePoModalBtn";
  createPoButton.type = "button";
  createPoButton.textContent = "Create Vendor PO";
  createPoButton.disabled = !order?.order_no;
  createPoButton.title = order?.order_no ? `Create one or more vendor POs linked to ${order.order_no}` : "Save the Sales Order before creating vendor POs.";
  createPoButton.onclick = async () => {
    if (!order?.order_no) return;
    if (modalDirty) {
      alert("Save the Sales Order first so the vendor PO uses the latest customer and line quantities.");
      return;
    }
    productMeta.salesPoReturnOrderNo = order.order_no;
    const opened = await openSalesReorderPoPrompt({ sourceNo: order.order_no, sourceLabel: `Sales Order ${order.order_no}`, lines: order._lines || [], includeAllLines: true });
    if (!opened) alert("All quantities on this Sales Order are already covered by linked open vendor POs.");
  };

  footer.insertBefore(createPoButton, $("modalSave"));
  footer.insertBefore(pdfButton, $("modalSave"));
  footer.insertBefore(invoiceHistoryButton, $("modalSave"));
  footer.insertBefore(invoiceButton, $("modalSave"));
  footer.insertBefore(saveOnlyButton, $("modalSave"));
}

function salesLineRows(lines, linkedPoMap = {}, savedOrder = false) {
  return `<div class="table-wrap sales-line-wrap"><table class="line-table sales-line-table"><thead><tr><th class="sales-po-select-col">PO</th><th>SKU</th><th>Product Name / Description</th><th>UOM</th><th>On Hand</th><th>Inventory / FIFO Cost</th><th title="Quantity ordered by the customer">ORD</th><th title="Quantity automatically reserved when the Sales Order is saved">ISS</th><th title="Quantity shipped/released to the customer and deducted from inventory">SHP</th><th>Adjustable Selling Price</th><th>Amount</th><th>Alternate Part</th><th>Vendor PO Ref.</th></tr></thead><tbody id="salesLineBody">${lines.map((line, i) => salesLineRowHtml(line, i, linkedPoMap)).join("")}</tbody><tfoot><tr><th colspan="10">Parts subtotal</th><th id="salesOrderPartsSubtotal">$0.00</th><th colspan="2"></th></tr><tr><th colspan="10">Customer-billed freight</th><th id="salesOrderFreightTotal">$0.00</th><th colspan="2"></th></tr><tr><th colspan="10">Sales order total</th><th id="salesOrderGrandTotal">$0.00</th><th colspan="2"></th></tr></tfoot></table></div><div class="actions table-actions"><button class="rowbtn" type="button" id="addSalesLineBtn">Add row</button>${createPartButtonMarkup()}<button class="rowbtn primary" type="button" id="createSelectedSalesPoBtn" ${savedOrder ? "" : "disabled"}>Create Vendor PO from Selected</button></div>`;
}

function salesLineRowHtml(line = {}, index = 0, linkedPoMap = {}) {
  const sku = line.sku || "";
  const product = productMeta.products?.find((p) => p.sku === sku) || {};
  const label = sku ? `${sku} - ${line.product_name || product.name || ""}` : "";
  const canCreateVendorPo = Boolean(product.id);
  const linkedPos = linkedPoMap[String(sku).trim().toLowerCase()] || [];
  const linkedPoHtml = linkedPos.length ? linkedPos.map((po) => `<button type="button" class="rowbtn sales-line-po-link" data-linked-sales-po="${esc(po.po_no)}" title="Open ${esc(po.po_no)} (${esc(po.status)})">${esc(po.po_no)}</button>`).join(" ") : `<span class="muted">None</span>`;
  return `<tr data-issued-qty="${esc(line.issued_qty || 0)}" data-shipped-qty="${esc(line.shipped_qty || 0)}" data-invoiced-qty="${esc(line.invoiced_qty || 0)}">
    <td data-label="Select for vendor PO" class="sales-po-select-col"><input type="checkbox" data-sales-po-select ${canCreateVendorPo ? "" : "disabled"} title="${canCreateVendorPo ? "Include this line in a linked vendor PO" : "Select a Product Master item first"}"></td>
    <td data-label="SKU"><input class="suggest-input compact-line-text" list="poProductOptions" data-suggest-source="products" data-sales-line="sku" data-line-index="${index}" value="${esc(label)}" placeholder="Search SKU" autocomplete="off" inputmode="search">${productOptionsDatalist()}</td>
    <td data-label="Product Name / Description"><textarea class="line-description compact-line-text" data-sales-line="description" data-line-index="${index}" rows="2" placeholder="Product name or description">${esc(line.description || line.product_name || product.name || "")}</textarea></td>
    <td data-label="UOM"><input class="line-uom compact-line-text" data-sales-line="unit" data-line-index="${index}" value="${esc(line.unit || product.unit || "")}" placeholder="EA"></td>
    <td data-label="On Hand" data-sales-onhand>${esc(product.qty ?? "")}</td>
    <td data-label="Inventory / FIFO Cost" data-sales-cost title="Current inventory unit cost from Product Master">${product.id ? money(salesInventoryUnitCost(product)) : ""}</td>
    <td data-label="ORD"><input type="number" min="0" step="0.01" data-sales-line="qty" data-line-index="${index}" value="${esc(line.qty || "")}" ${Number(line.issued_qty || 0) > 0 ? `min="${esc(line.issued_qty)}"` : ""}></td>
    <td data-label="ISS" class="num" data-sales-issued>${esc(Number(line.issued_qty || 0))}</td>
    <td data-label="SHP" class="num" title="Quantity shipped/released to the customer and deducted from inventory">${esc(Number(line.shipped_qty || 0))}</td>
    <td data-label="Adjustable Selling Price"><input type="number" min="0" step="0.01" data-sales-line="price" data-line-index="${index}" value="${esc(line.price ?? product.selling_price ?? "")}"></td>
    <td data-label="Amount" data-sales-amount>${money(Number(line.qty || 0) * Number(line.price ?? product.selling_price ?? 0))}</td>
    <td data-label="Alternate Part" data-sales-availability>${salesAlternateAvailabilityHtml(product)}</td>
    <td data-label="Vendor PO Ref." class="sales-line-po-refs">${linkedPoHtml}</td>
  </tr>`;
}

function salesInventoryUnitCost(product) {
  return Number(product?.cost || 0);
}

function savedSalesAlternateProducts(product) {
  if (!product?.id) return [];
  const seen = new Set();
  return (productMeta.productAlternates || [])
    .filter((row) => String(row.product_id || "") === String(product.id))
    .map((row) => (productMeta.products || []).find((candidate) => String(candidate.sku || "").trim().toLowerCase() === String(row.alternate_sku || "").trim().toLowerCase()))
    .filter((candidate) => candidate && candidate.id !== product.id)
    .filter((candidate) => {
      const key = String(candidate.sku || "").trim().toLowerCase();
      if (!key || seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .sort((a, b) => Number(Number(b.qty || 0) > 0) - Number(Number(a.qty || 0) > 0) || String(a.sku || "").localeCompare(String(b.sku || ""), undefined, { numeric: true, sensitivity: "base" }));
}

function salesAlternateAvailabilityHtml(product) {
  if (!product?.id) return "";
  const savedCount = savedSalesAlternateProducts(product).length;
  return `<div class="sales-alternate-cell"><input type="checkbox" data-sales-alternate aria-label="Assign alternate part" title="Assign or review alternate parts">${savedCount ? `<small title="${savedCount} saved alternate part${savedCount === 1 ? "" : "s"}">${savedCount}</small>` : ""}</div>`;
}

function addSalesLineRow() {
  const body = $("salesLineBody");
  if (!body) return;
  const index = body.querySelectorAll("tr").length;
  body.insertAdjacentHTML("beforeend", salesLineRowHtml({}, index, {}));
  wireSalesOrderLinePricing();
}

function requireTransactionSellingPrice(product, priceInput, transactionLabel = "transaction") {
  if (!product || !priceInput) return true;
  const currentPrice = Number(priceInput.value || product.selling_price || 0);
  if (currentPrice > 0) {
    priceInput.classList.remove("field-error");
    return true;
  }
  const typed = prompt(`${product.sku || "Product"} - ${product.name || "Unnamed product"} has no Product Master selling price.\n\nEnter the selling price for this ${transactionLabel}:`, "");
  if (typed === null) {
    priceInput.value = "";
    priceInput.classList.add("field-error");
    return false;
  }
  const price = Number(String(typed).replace(/[$,]/g, "").trim());
  if (!Number.isFinite(price) || price <= 0) {
    priceInput.value = "";
    priceInput.classList.add("field-error");
    alert("Enter a selling price greater than zero.");
    return false;
  }
  priceInput.value = String(price);
  priceInput.classList.remove("field-error");
  return true;
}

function wireSalesOrderLinePricing() {
  const refreshSalesOrderTotals = () => {
    const partsSubtotal = Array.from(document.querySelectorAll("#salesLineBody tr")).reduce((sum, row) => {
      const qty = Number(row.querySelector('[data-sales-line="qty"]')?.value || 0);
      const price = Number(row.querySelector('[data-sales-line="price"]')?.value || 0);
      return sum + qty * price;
    }, 0);
    const freight = Math.max(0, Number(document.querySelector('[data-product-field="freight_amount"]')?.value || 0));
    const partsHost = $("salesOrderPartsSubtotal");
    const freightHost = $("salesOrderFreightTotal");
    const totalHost = $("salesOrderGrandTotal");
    if (partsHost) partsHost.textContent = money(partsSubtotal);
    if (freightHost) freightHost.textContent = money(freight);
    if (totalHost) totalHost.textContent = money(partsSubtotal + freight);
  };
  document.querySelectorAll("#salesLineBody tr").forEach((tr) => {
    const skuInput = tr.querySelector('[data-sales-line="sku"]');
    const descriptionInput = tr.querySelector('[data-sales-line="description"]');
    const unitInput = tr.querySelector('[data-sales-line="unit"]');
    const qtyInput = tr.querySelector('[data-sales-line="qty"]');
    const priceInput = tr.querySelector('[data-sales-line="price"]');
    const refreshPoSelection = (product = resolveProductLookup(skuInput?.value)) => {
      const checkbox = tr.querySelector("[data-sales-po-select]");
      if (!checkbox) return;
      const selectable = Boolean(product?.id);
      checkbox.disabled = !selectable;
      if (!selectable) checkbox.checked = false;
      checkbox.title = selectable ? "Include this line in a linked vendor PO" : "Select a Product Master item first";
    };
    const refreshReservedPreview = (product = resolveProductLookup(skuInput?.value)) => {
      const issuedCell = tr.querySelector("[data-sales-issued]");
      if (!issuedCell) return;
      if (!product?.id) {
        issuedCell.textContent = "0";
        tr.dataset.issuedQty = "0";
        return;
      }
      const ordered = Math.max(0, Number(qtyInput?.value || 0));
      const shipped = Math.max(0, Number(tr.dataset.shippedQty || 0));
      const existingIssued = Math.max(shipped, Number(tr.dataset.issuedQty || 0));
      const existingOutstanding = Math.max(0, existingIssued - shipped);
      const availableForThisOrder = Math.max(0, Number(product.available_qty ?? product.qty ?? 0) + existingOutstanding);
      const previewIssued = shipped + Math.min(Math.max(0, ordered - shipped), availableForThisOrder);
      issuedCell.textContent = String(previewIssued);
      tr.dataset.issuedQty = String(previewIssued);
    };
    const refreshAmount = () => {
      const amountCell = tr.querySelector("[data-sales-amount]");
      if (amountCell) amountCell.textContent = money(Number(qtyInput?.value || 0) * Number(priceInput?.value || 0));
      refreshSalesOrderTotals();
    };
    const bindAlternateButton = (product) => {
      const checkbox = tr.querySelector("[data-sales-alternate]");
      if (checkbox) checkbox.onchange = () => {
        if (!checkbox.checked) return;
        checkbox.checked = false;
        openSalesAlternatePicker(tr, product);
      };
    };
    const applySelectedProduct = () => {
      if (!consumeExplicitProductSuggestion(skuInput)) return;
      const product = resolveProductLookup(skuInput?.value);
      if (!product) return;
      skuInput.value = `${product.sku} - ${product.name || ""}`;
      if (descriptionInput) descriptionInput.value = product.name || product.sku || "";
      if (unitInput) unitInput.value = product.unit || "Each";
      const onHandCell = tr.querySelector("[data-sales-onhand]");
      const costCell = tr.querySelector("[data-sales-cost]");
      const availabilityCell = tr.querySelector("[data-sales-availability]");
      if (onHandCell) onHandCell.textContent = product.qty ?? "";
      if (costCell) costCell.textContent = money(salesInventoryUnitCost(product));
      if (availabilityCell) availabilityCell.innerHTML = salesAlternateAvailabilityHtml(product);
      const selectedRate = selectedSalesPricingRate();
      const ratePrice = salesPricingRatePrice(product, selectedRate);
      if (priceInput) priceInput.value = Number(ratePrice || 0) > 0 ? ratePrice : Number(product.selling_price || 0) > 0 ? product.selling_price : "";
      requireTransactionSellingPrice(product, priceInput, "sales order");
      bindAlternateButton(product);
      refreshPoSelection(product);
      refreshReservedPreview(product);
      fitTransactionLineText(tr);
      refreshAmount();
    };
    if (skuInput) {
      skuInput.onchange = applySelectedProduct;
      skuInput.oninput = (event) => {
        if (event.isTrusted) clearPendingProductSuggestion(skuInput);
        if (!skuInput.value.trim()) {
          if (qtyInput) qtyInput.value = "";
          if (priceInput) priceInput.value = "";
          if (descriptionInput) descriptionInput.value = "";
          if (unitInput) unitInput.value = "";
          const onHandCell = tr.querySelector("[data-sales-onhand]");
          const costCell = tr.querySelector("[data-sales-cost]");
          const availabilityCell = tr.querySelector("[data-sales-availability]");
          if (onHandCell) onHandCell.textContent = "";
          if (costCell) costCell.textContent = "";
          if (availabilityCell) availabilityCell.textContent = "";
          refreshPoSelection(null);
          refreshReservedPreview(null);
          refreshAmount();
          return;
        }
      };
    }
    if (qtyInput) qtyInput.oninput = () => {
      refreshPoSelection();
      refreshReservedPreview();
      refreshAmount();
    };
    if (priceInput) priceInput.oninput = refreshAmount;
    if (descriptionInput) descriptionInput.oninput = () => fitTransactionLineText(tr);
    if (unitInput) unitInput.oninput = () => fitTransactionLineText(tr);
    bindAlternateButton(resolveProductLookup(skuInput?.value));
    refreshPoSelection();
    refreshReservedPreview();
    fitTransactionLineText(tr);
  });
  const freightInput = document.querySelector('[data-product-field="freight_amount"]');
  if (freightInput) freightInput.oninput = refreshSalesOrderTotals;
  const rateSelect = document.getElementById("salesPricingRateSelect");
  const applyRateButton = document.getElementById("applySalesPricingRateBtn");
  if (rateSelect) rateSelect.onchange = () => {
    const rate = selectedSalesPricingRate();
    const help = document.getElementById("salesPricingRateHelp");
    if (help) help.textContent = rate ? `${salesPricingRateLabel(rate)}: Inventory / FIFO Cost × ${Number(rate.markup_percent || 0).toFixed(2)}%. ${rate.description || ""}`.trim() : "Optional. Blank leaves the line selling prices unchanged.";
    if (rate) applySelectedSalesPricingRate({ notify: true });
  };
  if (applyRateButton) applyRateButton.onclick = () => applySelectedSalesPricingRate({ notify: true });
  refreshSalesOrderTotals();
}

function closeSalesAlternatePicker() {
  hideSuggestMenu();
  document.getElementById("salesAlternateOverlay")?.remove();
}

function salesAlternateTableHtml(sourceProduct) {
  const alternates = savedSalesAlternateProducts(sourceProduct);
  if (!alternates.length) return `<div class="empty sales-alternate-empty">No separate Product Master alternatives are linked. You may continue using the original part.</div>`;
  return `<div class="table-wrap"><table class="line-table sales-alternate-table"><thead><tr><th>SKU</th><th>Product</th><th>On Hand</th><th>Inventory Cost</th><th>Selling Price</th><th></th></tr></thead><tbody>${alternates.map((product) => `<tr><td>${esc(product.sku)}</td><td>${esc(product.name || "")}</td><td>${esc(product.qty ?? 0)}</td><td>${money(salesInventoryUnitCost(product))}</td><td>${money(product.selling_price || 0)}</td><td><button class="rowbtn ${Number(product.qty || 0) > 0 ? "primary" : ""}" type="button" data-use-sales-alternate="${esc(product.sku)}">Use${Number(product.qty || 0) > 0 ? "" : " (out of stock)"}</button></td></tr>`).join("")}</tbody></table></div>`;
}

function openSalesAlternatePicker(lineRow, sourceProduct) {
  if (!lineRow || !sourceProduct?.id) {
    alert("Select a Product Master item before checking alternates.");
    return;
  }
  closeSalesAlternatePicker();
  const alternateNumbers = sourceProduct._alternate_part_numbers || [];
  const crossReferences = sourceProduct._cross_reference_numbers || [];
  document.body.insertAdjacentHTML("beforeend", `<div class="sales-alternate-overlay" id="salesAlternateOverlay" role="presentation">
    <section class="sales-alternate-picker" role="dialog" aria-modal="false" aria-labelledby="salesAlternateTitle">
      <div class="sales-alternate-head"><div><h3 id="salesAlternateTitle">Part reference view</h3><p>${esc(sourceProduct.sku)} - ${esc(sourceProduct.name || "")} | On hand ${esc(sourceProduct.qty ?? 0)} | Cost ${money(salesInventoryUnitCost(sourceProduct))}</p></div><button type="button" data-close-sales-alternate aria-label="Close part reference view">x</button></div>
      <div class="sales-alternate-body">
        <section class="subpanel"><div class="panel-title"><strong>Reference numbers</strong><span>For identification only; these numbers point back to the primary Product Master part.</span></div><div class="summary-strip"><span><strong>Primary Part #:</strong> ${esc(sourceProduct.sku || "-")}</span><span><strong>Alternate Part Numbers:</strong> ${esc(alternateNumbers.join(", ") || "None")}</span><span><strong>Cross References:</strong> ${esc(crossReferences.join(", ") || "None")}</span></div></section>
        <div><strong>Available Product Master alternatives</strong><p class="muted">Selecting an available alternative is optional. You may continue with the original part and proceed to the next action.</p></div>
        <div id="salesAlternateSaved">${salesAlternateTableHtml(sourceProduct)}</div>
        <div class="sales-alternate-search">
          <label for="salesAlternateSearch"><strong>Optional: search another Product Master part</strong></label>
          <input class="suggest-input" id="salesAlternateSearch" data-suggest-source="products" placeholder="Type SKU, product name, or vendor" autocomplete="off" inputmode="search">
          <small>Results appear only after typing. Choosing a part saves it as an alternate; leaving this blank keeps the original Part #.</small>
        </div>
        <div id="salesAlternateCandidate" aria-live="polite"></div>
      </div>
      <div class="sales-alternate-foot"><button class="primary" type="button" data-close-sales-alternate>Continue with original Part #</button><button type="button" data-close-sales-alternate>Close reference view</button></div>
    </section>
  </div>`);
  const overlay = document.getElementById("salesAlternateOverlay");
  const search = document.getElementById("salesAlternateSearch");
  const candidateHost = document.getElementById("salesAlternateCandidate");
  const renderCandidate = () => {
    const alternate = resolveProductLookup(search?.value);
    if (!alternate || !isCommittedProductLookup(search?.value)) {
      candidateHost.innerHTML = search?.value?.trim() ? `<div class="notice">Select a matching Product Master row from the search results.</div>` : "";
      return;
    }
    if (alternate.id === sourceProduct.id) {
      candidateHost.innerHTML = `<div class="notice">Choose a different part. ${esc(sourceProduct.sku)} is the original item.</div>`;
      return;
    }
    candidateHost.innerHTML = `<div class="sales-alternate-candidate"><div><strong>${esc(alternate.sku)} - ${esc(alternate.name || "")}</strong><span>On hand ${esc(alternate.qty ?? 0)} | Inventory cost ${money(salesInventoryUnitCost(alternate))} | Selling price ${money(alternate.selling_price || 0)}</span></div><button class="primary" type="button" data-confirm-sales-alternate>Use and remember alternate</button></div>`;
    candidateHost.querySelector("[data-confirm-sales-alternate]").onclick = () => useSalesAlternate(lineRow, sourceProduct, alternate);
  };
  overlay.querySelectorAll("[data-close-sales-alternate]").forEach((button) => button.onclick = closeSalesAlternatePicker);
  overlay.onclick = (event) => {
    if (event.target === overlay) closeSalesAlternatePicker();
  };
  overlay.querySelectorAll("[data-use-sales-alternate]").forEach((button) => {
    button.onclick = () => {
      const alternate = (productMeta.products || []).find((product) => String(product.sku || "").toLowerCase() === String(button.dataset.useSalesAlternate || "").toLowerCase());
      if (alternate) useSalesAlternate(lineRow, sourceProduct, alternate);
    };
  });
  if (search) {
    search.oninput = renderCandidate;
    search.onchange = renderCandidate;
    setTimeout(() => search.focus(), 0);
  }
}

async function rememberSalesAlternate(sourceProduct, alternateProduct) {
  const existing = (productMeta.productAlternates || []).find((row) => String(row.product_id || "") === String(sourceProduct.id) && String(row.alternate_sku || "").trim().toLowerCase() === String(alternateProduct.sku || "").trim().toLowerCase());
  if (existing) return existing;
  const { data, error } = await supabase.from("product_alternates").insert({ product_id: sourceProduct.id, alternate_sku: alternateProduct.sku }).select("*").single();
  if (error) throw error;
  productMeta.productAlternates = [...(productMeta.productAlternates || []), data];
  return data;
}

async function useSalesAlternate(lineRow, sourceProduct, alternateProduct) {
  if (!lineRow || !sourceProduct?.id || !alternateProduct?.id) return;
  const qty = Number(lineRow.querySelector('[data-sales-line="qty"]')?.value || 0);
  if (qty > Number(alternateProduct.qty || 0) && !confirm(`${alternateProduct.sku} has ${alternateProduct.qty || 0} on hand, which is less than the requested quantity ${qty}. Use it anyway and keep the order backordered?`)) return;
  try {
    await rememberSalesAlternate(sourceProduct, alternateProduct);
    const skuInput = lineRow.querySelector('[data-sales-line="sku"]');
    if (skuInput) {
      skuInput.value = `${alternateProduct.sku} - ${alternateProduct.name || ""}`;
      skuInput.dispatchEvent(new Event("input", { bubbles: true }));
      skuInput.dispatchEvent(new Event("change", { bubbles: true }));
    }
    closeSalesAlternatePicker();
  } catch (error) {
    alert(error.message || "Could not save this alternate part.");
  }
}

async function renderSalesPartsToOrderView() {
  currentCfg = tableMap.salestopurchase;
  $("viewTitle").textContent = "Parts to Order";
  $("viewSub").textContent = "Reserved customer demand that cannot be fulfilled until inventory is received.";
  const [orders, lines, products] = await Promise.all([
    getAll("sales_orders"),
    getAll("sales_order_lines"),
    getAll("products"),
  ]);
  currentRows = buildSalesPartsToOrderRows(orders, lines, products);
  $("content").innerHTML = `
    <div class="toolbar">
      <input class="searchbox" id="partsToOrderSearch" placeholder="Search by customer, order, SKU, product, status">
    </div>
    <section class="panel">
      <div class="panel-head"><div class="panel-title"><strong>Parts to Order</strong><span>Sales orders are allowed, but issue and invoice stay blocked until these shortages are received.</span></div><div class="actions"><button id="partsToOrderCsvBtn">Excel</button><button onclick="window.print()">PDF / Print</button><button class="primary" id="partsToOrderPoBtn">New PO</button></div></div>
      <div id="partsToOrderHost">${salesPartsToOrderTableHtml(currentRows)}</div>
    </section>`;
  $("partsToOrderSearch").oninput = renderFilteredSalesPartsToOrder;
  $("partsToOrderCsvBtn").onclick = exportSalesPartsToOrderCsv;
  $("partsToOrderPoBtn").onclick = () => loadView("purchasing");
  bindPartsToOrderRows();
}

function buildSalesPartsToOrderRows(orders, lines, products) {
  const productById = Object.fromEntries(products.map((p) => [p.id, p]));
  const availableBySku = Object.fromEntries(products.map((p) => [p.sku, Number(p.qty || 0)]));
  const orderById = Object.fromEntries(orders.map((o) => [o.id, o]));
  return lines
    .map((line) => ({ line, order: orderById[line.order_id], product: productById[line.product_id] || products.find((p) => p.sku === line.sku) }))
    .filter(({ order }) => order && !["quotation", "fulfilled", "paid", "cancelled"].includes(String(order.status || "").toLowerCase()))
    .sort((a, b) => String(a.order.order_date || "").localeCompare(String(b.order.order_date || "")) || String(a.order.order_no || "").localeCompare(String(b.order.order_no || "")))
    .map(({ line, order, product }) => {
      const sku = line.sku || product?.sku || "";
      const ordered = Number(line.qty || 0);
      const availableBefore = Number(availableBySku[sku] || 0);
      const reservedQty = Math.min(ordered, Math.max(0, availableBefore));
      const shortage = Math.max(0, ordered - reservedQty);
      availableBySku[sku] = availableBefore - ordered;
      return {
        order_no: order.order_no,
        order_date: order.order_date,
        customer: order.customer,
        customer_po: order.customer_po,
        sku,
        product_name: line.product_name || product?.name || "",
        ordered_qty: ordered,
        reserved_qty: reservedQty,
        to_order_qty: shortage,
        on_hand_at_review: Math.max(0, availableBefore),
        source_vendor: product?.source_vendor || "",
        unit_cost: Number(product?.cost || 0),
        estimated_cost: shortage * Number(product?.cost || 0),
        status: shortage > 0 ? "To Order" : "Reserved",
      };
    })
    .filter((row) => row.to_order_qty > 0);
}

function renderFilteredSalesPartsToOrder() {
  const q = $("partsToOrderSearch").value.toLowerCase();
  const rows = currentRows.filter((row) => !q || Object.values(row).join(" ").toLowerCase().includes(q));
  $("partsToOrderHost").innerHTML = salesPartsToOrderTableHtml(rows);
  bindPartsToOrderRows();
}

function salesPartsToOrderTableHtml(rows) {
  const heads = ["Order", "Date", "Customer", "PO / Reference", "SKU", "Product", "Ordered", "Reserved", "To Order", "On Hand", "Preferred Vendor", "Est. Cost", "Status", ""];
  return `<div class="table-wrap"><table><thead><tr>${heads.map((h) => `<th>${esc(h)}</th>`).join("")}</tr><tr>${heads.map((h, i) => h ? `<th><input class="column-filter" data-col="${i}" placeholder="Filter ${esc(h)}"></th>` : "<th></th>").join("")}</tr></thead><tbody>${rows.length ? rows.map(salesPartsToOrderRowHtml).join("") : `<tr><td colspan="${heads.length}" class="empty">No sales parts need ordering right now.</td></tr>`}</tbody></table></div>`;
}

function salesPartsToOrderRowHtml(row) {
  return `<tr>
    <td>${esc(row.order_no)}</td>
    <td>${esc(formatDisplayDate(row.order_date))}</td>
    <td>${esc(row.customer || "")}</td>
    <td>${esc(row.customer_po || "")}</td>
    <td>${esc(row.sku)}</td>
    <td>${esc(row.product_name)}</td>
    <td>${esc(row.ordered_qty)}</td>
    <td>${esc(row.reserved_qty)}</td>
    <td><strong>${esc(row.to_order_qty)}</strong></td>
    <td>${esc(row.on_hand_at_review)}</td>
    <td>${esc(row.source_vendor || "")}</td>
    <td>${money(row.estimated_cost)}</td>
    <td>${badge(row.status)}</td>
    <td><button class="rowbtn" type="button" data-open-sales="${esc(row.order_no)}">Open SO</button></td>
  </tr>`;
}

function bindPartsToOrderRows() {
  document.querySelectorAll("[data-open-sales]").forEach((b) => b.onclick = async () => {
    await renderSalesOrdersView();
    const order = currentRows.find((row) => row.order_no === b.dataset.openSales);
    if (order) openSalesOrderModal(order);
  });
  document.querySelectorAll(".column-filter").forEach((input) => input.oninput = applyColumnFilters);
}

function exportSalesPartsToOrderCsv() {
  const heads = ["Order", "Date", "Customer", "PO / Reference", "SKU", "Product", "Ordered", "Reserved", "To Order", "On Hand", "Preferred Vendor", "Estimated Cost", "Status"];
  const rows = [heads, ...currentRows.map((row) => [row.order_no, row.order_date, row.customer, row.customer_po, row.sku, row.product_name, row.ordered_qty, row.reserved_qty, row.to_order_qty, row.on_hand_at_review, row.source_vendor, row.estimated_cost, row.status])];
  downloadCsv(rows, "sales-parts-to-order.csv");
}

async function quickCreateSalesCustomer(order) {
  const name = prompt("Customer name to create");
  if (!name) return;
  try {
    if (!await approveMasterNameCreation("customers", name)) return;
    await upsertOne("customers", { reference: await nextRefPreview("customer", "C-", "customers", "reference"), name: name.trim(), terms: "30 days" }, "name");
    await ensurePartyMasterSuggestRows(true);
    await renderSalesOrdersView();
    await openSalesOrderModal(order);
    const customerField = document.querySelector('[data-product-field="customer"]');
    if (customerField) customerField.value = name.trim();
  } catch (error) {
    alert(error.message || error);
  }
}

async function saveSalesOrderModal({ keepOpen = false } = {}) {
  const record = {};
  document.querySelectorAll("[data-product-field]").forEach((el) => record[el.dataset.productField] = el.value || null);
  // Status and fulfillment stage are workflow outputs, not user-entered fields.
  // Preserve an existing workflow state until the reservation/delivery logic below advances it.
  record.status = editing?.status || "Open";
  record.special_order_status = editing?.special_order_status || "Unfulfilled";
  const sourcePo = productMeta.pendingSalesPoSource || null;
  record.source_po_no = editing?.source_po_no || sourcePo?.po_no || null;
  record.payment_mode = record.payment_mode || "PO";
  const selectedCustomerMaster = await requirePartyMasterSelection("customers", record.customer, "a customer");
  if (!selectedCustomerMaster) return;
  record.customer = selectedCustomerMaster.name;
  record.freight_amount = Math.max(0, Number(record.freight_amount || 0));
  const selectedPricingRate = (productMeta.salesPricingRates || []).find((rate) => String(rate.id) === String(record.pricing_rate_id || "")) || null;
  record.pricing_rate_id = selectedPricingRate?.id || null;
  record.pricing_rate_name = selectedPricingRate ? salesPricingRateLabel(selectedPricingRate) : null;
  record.pricing_markup_percent = selectedPricingRate ? Number(selectedPricingRate.markup_percent || 0) : null;
  if (record.payment_mode === "PO" && !String(record.customer_po || "").trim()) {
    alert("Customer PO # is required when the mode of payment is PO.");
    return;
  }
  record.manager_override = false;
  record.override_by = null;
  record.override_reason = null;
  const lineRows = parseSalesLineRows();
  if (!lineRows.length) {
    alert("Add at least one sales order line.");
    return;
  }
  const missingSellingPrice = lineRows.filter((line) => !(Number(line.price || 0) > 0));
  if (missingSellingPrice.length) {
    alert(`Selling price is required for: ${missingSellingPrice.map((line) => `${line.sku} - ${line.product_name || "Product"}`).join(", ")}.\n\nEnter a price greater than zero before saving the sales order.`);
    document.querySelectorAll('#salesLineBody [data-sales-line="price"]').forEach((input) => { if (!(Number(input.value || 0) > 0)) input.classList.add("field-error"); });
    return;
  }
  const reservationAvailability = await salesReservationAvailability(record.order_no, lineRows);
  const reservationShortages = reservationAvailability.filter((line) => Math.max(0, Number(line.qty || 0) - Number(line.shipped_qty || 0)) > Number(line.available || 0));
  const availabilityBySku = new Map(reservationAvailability.map((line) => [String(line.sku || "").trim().toLowerCase(), Number(line.available || 0)]));
  lineRows.forEach((line) => {
    const shipped = Number(line.shipped_qty || 0);
    const remainingOrder = Math.max(0, Number(line.qty || 0) - shipped);
    const available = Math.max(0, Number(availabilityBySku.get(String(line.sku || "").trim().toLowerCase()) || 0));
    line.issued_qty = shipped + Math.min(remainingOrder, available);
  });
  if (isLockedAccountingDate(record.order_date)) return alert("This sales-order date is inside the closed accounting period.");
  const duplicateOrder = (currentRows || []).find((row) => row.order_no === record.order_no && row.id !== editing?.id);
  if (duplicateOrder) return alert(`Sales order ${record.order_no} already exists.`);
  const duplicateCustomerPo = record.customer_po && (currentRows || []).find((row) => row.id !== editing?.id
    && String(row.customer || "").trim().toLowerCase() === String(record.customer || "").trim().toLowerCase()
    && String(row.customer_po || "").trim().toLowerCase() === String(record.customer_po || "").trim().toLowerCase()
    && !/void|reversed|cancel/i.test(row.status || ""));
  if (duplicateCustomerPo) return alert(`${paymentReferencePrintLabel(record.payment_mode)} ${record.customer_po} is already used on ${duplicateCustomerPo.order_no}.`);
  const belowMasterPrice = lineRows.filter((line) => {
    const product = (productMeta.products || []).find((row) => row.sku === line.sku);
    return product && Number(product.selling_price || 0) > 0 && Number(line.price || 0) < Number(product.selling_price || 0);
  });
  if (belowMasterPrice.length && !canApproveInventoryControl()) {
    return alert(`Price override requires Manager or Administrator approval: ${belowMasterPrice.map((line) => line.sku).join(", ")}.`);
  }
  if (belowMasterPrice.length && !confirm(`The following lines are below Product Master selling price: ${belowMasterPrice.map((line) => line.sku).join(", ")}. Approve this price override?`)) return;
  if (record.payment_mode === "PO" && !await enforceCustomerCreditControl(record.customer, lineRows.reduce((sum, line) => sum + Number(line.qty || 0) * Number(line.price || 0), record.freight_amount), "sales order")) return;
  if (["open", "reserved", "backordered"].includes(String(record.status || "").toLowerCase()) && (hasSalesLineShortage(lineRows) || reservationShortages.length)) {
    record.order_type = record.order_type === "Special Order" ? "Special Order" : "Backorder";
    record.special_order_status = "Awaiting Stock";
    record.status = "Backordered";
  } else if (/special order|backorder/i.test(record.order_type || "") && !/fulfilled|cancelled/i.test(record.status || "")) {
    record.special_order_status = "Ready for Delivery";
    if (record.status === "Backordered") record.status = "Reserved";
  } else if (/^open$/i.test(String(record.status || "")) && lineRows.every((line) => Number(line.issued_qty || 0) >= Number(line.qty || 0))) {
    record.status = "Reserved";
    record.special_order_status = "Ready for Delivery";
  } else if (/^open$/i.test(String(record.status || ""))) {
    record.special_order_status = "Unfulfilled";
  }
  try {
    const wasNew = !editing;
    let saved;
    try {
      saved = await upsertOneWithOptionalColumns("sales_orders", record, "order_no", ["payment_mode", "order_type", "special_order_status", "source_po_no", "freight_amount", "pricing_rate_id", "pricing_rate_name", "pricing_markup_percent", "requested_by"], "Saved the sales order, but run the current Sales Order update SQL so all pricing, workflow, and Requested By fields are stored.");
    } catch (saveError) {
      const oldPoConstraint = record.payment_mode !== "PO" && /customer_po_or_override|check constraint/i.test(String(saveError?.message || saveError));
      if (!oldPoConstraint) throw saveError;
      saved = await upsertOneWithOptionalColumns("sales_orders", {
        ...record,
        manager_override: true,
        override_by: "System payment-mode exemption",
        override_reason: `${record.payment_mode} sale does not require a Customer PO. Compatibility entry until the cash-payment constraint migration is applied.`,
      }, "order_no", ["payment_mode", "order_type", "special_order_status", "source_po_no", "freight_amount", "pricing_rate_id", "pricing_rate_name", "pricing_markup_percent", "requested_by"], "Sales Order saved using the Cash/Credit Card compatibility rule. Apply the latest sales-order cash PO exemption migration.");
    }
    await supabase.from("sales_order_lines").delete().eq("order_id", saved.id);
    await upsertManyWithOptionalColumns("sales_order_lines", lineRows.map((line) => ({ ...line, order_id: saved.id })), "id", ["description", "unit", "issued_qty", "shipped_qty", "invoiced_qty"], "Sales Order saved. Run the Sales Order Partial Issue/Invoice SQL update so ORD, ISS, and SHP quantities are stored on each line.");
    await syncSalesOrderInitialAccounting({ ...saved, payment_mode: record.payment_mode, freight_amount: record.freight_amount }, lineRows, productMeta.products || [], { forceAvailable: /fulfilled|posted|paid/i.test(saved.status || "") });
    if (record.source_po_no) {
      await updateOneWithOptionalColumns("purchase_orders", { linked_sales_order_no: saved.order_no }, "po_no", record.source_po_no, ["linked_sales_order_no"], "Sales Order saved. Run the Purchase Order Destination SQL update so its link appears on the PO.");
    }
    await writeAuditLog({ tableName: "sales_orders", action: wasNew ? "Created" : "Updated", beforeData: editing, afterData: { ...saved, lines: lineRows } });
    if (/void|reversed|cancel/i.test(String(saved.status || ""))) await releaseQuotationFromSalesOrder(saved.order_no, `Sales Order saved as ${saved.status}`);
    if (wasNew) await incrementSequence("so");
    productMeta.pendingSalesPoSource = null;
    closeModal(true);
    await renderSalesOrdersView();
    if (keepOpen) {
      const refreshed = currentRows.find((row) => row.order_no === saved.order_no) || { ...saved, _lines: lineRows };
      await openSalesOrderModal(refreshed);
      return;
    }
    await openSalesReorderPoPrompt({ sourceNo: saved.order_no, sourceLabel: `Sales Order ${saved.order_no}`, lines: lineRows });
  } catch (error) {
    alert(error.message || error);
  }
}

async function salesReservationShortages(orderNo, lines = []) {
  const availability = await salesReservationAvailability(orderNo, lines);
  return availability.filter((line) => Math.max(0, Number(line.qty || 0) - Number(line.shipped_qty || 0)) > Number(line.available || 0));
}

async function salesReservationAvailability(orderNo, lines = []) {
  const [orders, savedLines] = await Promise.all([getAll("sales_orders"), getAll("sales_order_lines")]);
  const activeOrderIds = new Set(orders.filter((order) => order.order_no !== orderNo && !/fulfilled|delivered|paid|void|reversed|cancel/i.test(order.status || "")).map((order) => String(order.id || "")));
  return (lines || []).map((line) => {
    const product = (productMeta.products || []).find((row) => row.sku === line.sku);
    const reservedElsewhere = savedLines.filter((saved) => activeOrderIds.has(String(saved.order_id || "")) && String(saved.sku || "").trim().toLowerCase() === String(line.sku || "").trim().toLowerCase()).reduce((sum, saved) => sum + Math.max(0, Number(saved.issued_qty || 0) - Number(saved.shipped_qty || 0)), 0);
    const available = Math.max(0, Number(product?.qty || 0) - reservedElsewhere);
    return { ...line, available, reservedElsewhere };
  });
}

async function salesReorderCandidates(sourceNo, lines = [], { includeAllLines = false } = {}) {
  const products = (productMeta.products || []).length ? productMeta.products : await getAll("products");
  productMeta.products = products;
  const [purchaseOrders, purchaseLines] = await Promise.all([
    getAll("purchase_orders").catch(() => []),
    getAll("purchase_order_lines").catch(() => []),
  ]);
  const sourceTag = `[Reorder Source: ${sourceNo}]`;
  const sourcePoIds = new Set(purchaseOrders
    .filter((po) => String(po.notes || "").includes(sourceTag) && !/cancel|closed/i.test(String(po.status || "")))
    .map((po) => po.id));
  const alreadyOrdered = {};
  purchaseLines.filter((line) => sourcePoIds.has(line.po_id)).forEach((line) => {
    alreadyOrdered[line.sku] = Number(alreadyOrdered[line.sku] || 0) + Number(line.qty || 0);
  });
  return (lines || []).map((line) => {
    const product = products.find((item) => item.id === line.product_id || String(item.sku || "").toLowerCase() === String(line.sku || "").toLowerCase());
    if (!product) return null;
    const orderedQty = Number(line.qty || 0);
    const onHand = Number(product.qty || 0);
    const reorderPoint = Math.max(0, Number(product.reorder_point || 0));
    const projected = onHand - orderedQty;
    if (!includeAllLines && projected > reorderPoint) return null;
    const requestedPurchase = includeAllLines
      ? orderedQty
      : Math.max(1, Number((reorderPoint - projected).toFixed(2)));
    const suggestedQty = Math.max(0, Number((requestedPurchase - Number(alreadyOrdered[product.sku] || 0)).toFixed(2)));
    if (!(suggestedQty > 0)) return null;
    return {
      product_id: product.id,
      sku: product.sku,
      product_name: product.name || line.product_name || "",
      unit: product.unit || "Each",
      ordered_qty: orderedQty,
      on_hand: onHand,
      reorder_point: reorderPoint,
      projected_qty: projected,
      po_qty: suggestedQty,
      vendor: product.source_vendor || "",
      unit_cost: Number(product.cost || 0),
    };
  }).filter(Boolean);
}

async function openSalesReorderPoPrompt({ sourceNo, sourceLabel, lines = [], includeAllLines = false } = {}) {
  if (!sourceNo || !lines.length) return false;
  const candidates = await salesReorderCandidates(sourceNo, lines, { includeAllLines });
  if (!candidates.length) return false;
  const vendorRows = await getAll("vendors").catch(() => []);
  const vendorNames = [...new Set(vendorRows.map((vendor) => String(vendor.name || "").trim()).filter(Boolean))].sort((a, b) => a.localeCompare(b));
  modalTitle.textContent = "Parts Below Reorder Point";
  modalBody.innerHTML = `
    <div class="notice"><strong>${esc(sourceLabel || sourceNo)}</strong> has ${candidates.length} part${candidates.length === 1 ? "" : "s"} available for a linked vendor PO. Select the parts, adjust the PO quantities, and confirm their vendors. You may repeat this process for additional vendors.</div>
    <div class="field reorder-po-mode"><label>Create purchase orders</label><select id="salesReorderPoMode"><option value="vendor">Group selected parts by vendor</option><option value="part">Create a separate PO for each part</option></select></div>
    <div class="table-wrap"><table class="line-table"><thead><tr><th>Include</th><th>SKU</th><th>Part</th><th>On Hand</th><th>SO Qty</th><th>Reorder Point</th><th>Projected</th><th>PO Qty</th><th>Vendor</th><th>Est. Cost</th></tr></thead><tbody>
      ${candidates.map((item, index) => `<tr data-sales-reorder-row data-index="${index}" data-product-id="${esc(item.product_id || "")}" data-sku="${esc(item.sku)}" data-product-name="${esc(item.product_name)}" data-unit="${esc(item.unit)}" data-unit-cost="${esc(item.unit_cost)}">
        <td><input type="checkbox" data-sales-reorder-include checked></td><td>${esc(item.sku)}</td><td>${esc(item.product_name)}</td><td>${esc(item.on_hand)}</td><td>${esc(item.ordered_qty)}</td><td>${esc(item.reorder_point)}</td><td>${esc(item.projected_qty)}</td>
        <td><input type="number" min="0.01" step="0.01" data-sales-reorder-qty value="${esc(item.po_qty)}"></td>
        <td><input class="suggest-input" data-suggest-source="vendors" data-sales-reorder-vendor value="${esc(item.vendor)}" placeholder="Type vendor name, reference, email, or phone" autocomplete="off" inputmode="search"></td>
        <td data-sales-reorder-cost>${money(item.po_qty * item.unit_cost)}</td>
      </tr>`).join("")}
    </tbody></table></div>
    <p class="notice">Draft purchase orders only—no receipt, payable, inventory, or accounting entry is created until the normal purchasing steps are completed.</p>`;
  modalBody.querySelectorAll("[data-sales-reorder-qty]").forEach((input) => {
    input.oninput = () => {
      const row = input.closest("[data-sales-reorder-row]");
      const amount = Number(input.value || 0) * Number(row.dataset.unitCost || 0);
      row.querySelector("[data-sales-reorder-cost]").textContent = money(amount);
    };
  });
  modalSave.textContent = "Create Purchase Order(s)";
  modalSave.onclick = () => createSalesReorderPurchaseOrders(sourceNo, sourceLabel || sourceNo, vendorRows);
  modalCancel.textContent = "Skip for now";
  modalCancel.onclick = async () => {
    const returnNo = productMeta.salesPoReturnOrderNo;
    closeModal(true);
    if (returnNo && currentView === "orders") {
      await renderSalesOrdersView();
      const returnOrder = currentRows.find((order) => order.order_no === returnNo);
      productMeta.salesPoReturnOrderNo = null;
      if (returnOrder) await openSalesOrderModal(returnOrder);
    }
  };
  document.querySelector(".modalbox")?.classList.add("wide-modal");
  $("modal").style.display = "flex";
  return true;
}

async function createSalesReorderPurchaseOrders(sourceNo, sourceLabel, vendorRows = []) {
  const selected = [...modalBody.querySelectorAll("[data-sales-reorder-row]")].filter((row) => row.querySelector("[data-sales-reorder-include]")?.checked).map((row) => ({
    product_id: row.dataset.productId || null,
    sku: row.dataset.sku || "",
    product_name: row.dataset.productName || "",
    unit: row.dataset.unit || "Each",
    qty: Number(row.querySelector("[data-sales-reorder-qty]")?.value || 0),
    vendor: String(row.querySelector("[data-sales-reorder-vendor]")?.value || "").trim(),
    unit_cost: Number(row.dataset.unitCost || 0),
  })).filter((item) => item.sku && item.qty > 0);
  if (!selected.length) return alert("Select at least one part and enter a PO quantity.");
  const missingVendor = selected.find((item) => !item.vendor);
  if (missingVendor) return alert(`Select or enter a vendor for ${missingVendor.sku}.`);
  const mode = $("salesReorderPoMode")?.value || "vendor";
  const groups = mode === "part"
    ? selected.map((item) => ({ vendor: item.vendor, items: [item] }))
    : [...selected.reduce((map, item) => {
      const key = item.vendor.toLowerCase();
      if (!map.has(key)) map.set(key, { vendor: item.vendor, items: [] });
      map.get(key).items.push(item);
      return map;
    }, new Map()).values()];
  try {
    const salesOrders = await getAll("sales_orders").catch(() => []);
    const sourceOrder = salesOrders.find((order) => String(order.order_no || "") === String(sourceNo));
    const created = [];
    for (const group of groups) {
      const vendor = vendorRows.find((row) => String(row.name || "").trim().toLowerCase() === group.vendor.toLowerCase());
      const poNo = await nextRefPreview("po", "PO-", "purchase_orders", "po_no");
      const po = await upsertOneWithOptionalColumns("purchase_orders", {
        po_no: poNo,
        vendor: group.vendor,
        po_date: today(),
        jobsite_project: sourceLabel,
        expected_date: null,
        payment_terms: vendor?.terms || "Net 30",
        incoterm: "FOB",
        foreign_order: false,
        currency_code: "USD",
        exchange_rate: 1,
        freight_amount: 0,
        landed_cost_enabled: false,
        landed_cost_method: "By Value",
        duty_amount: 0,
        other_landed_cost_amount: 0,
        vendor_invoice_amount: 0,
        posting_date: today(),
        match_status: "Pending",
        payment_status: "Not Ready",
        status: "Draft",
        purchase_purpose: "Customer Order",
        linked_customer: sourceOrder?.customer || null,
        linked_sales_order_no: sourceNo,
        notes: `[Reorder Source: ${sourceNo}] Vendor PO linked to ${sourceLabel}.`,
      }, "po_no", ["purchase_purpose", "linked_customer", "linked_sales_order_no"], "PO created. Run the Purchase Order Destination SQL update so the Sales Order link is stored.");
      await upsertMany("purchase_order_lines", group.items.map((item) => ({
        po_id: po.id,
        wo_no: null,
        product_id: item.product_id,
        sku: item.sku,
        product_name: item.product_name,
        unit: item.unit,
        qty: item.qty,
        foreign_unit_cost: 0,
        unit_cost: item.unit_cost,
        allocated_landed_cost: 0,
        landed_unit_cost: item.unit_cost,
      })), "id");
      await incrementSequence("po");
      created.push(poNo);
    }
    closeModal(true);
    alert(`Created ${created.length} draft purchase order${created.length === 1 ? "" : "s"}:\n${created.join("\n")}`);
    if (currentView === "orders") {
      await renderSalesOrdersView();
      const returnNo = productMeta.salesPoReturnOrderNo || sourceNo;
      const returnOrder = currentRows.find((order) => order.order_no === returnNo);
      productMeta.salesPoReturnOrderNo = null;
      if (returnOrder) await openSalesOrderModal(returnOrder);
    }
  } catch (error) {
    alert(error.message || "Could not create the purchase order(s).");
  }
}

function parseSalesLineRows() {
  return [...document.querySelectorAll("#salesLineBody tr")].map((tr) => {
    const get = (field) => tr.querySelector(`[data-sales-line="${field}"]`)?.value || "";
    const product = resolveProductLookup(get("sku"));
    if (!product) return null;
    const sku = product.sku;
    const issuedQty = Number(tr.dataset.issuedQty || 0);
    const shippedQty = Number(tr.dataset.shippedQty || 0);
    const invoicedQty = Number(tr.dataset.invoicedQty || 0);
    return { product_id: product.id, sku, product_name: product.name, description: get("description") || product.name || sku, unit: get("unit") || product.unit || "Each", qty: Number(get("qty") || 0), price: Number(get("price") || 0), issued_qty: issuedQty, shipped_qty: shippedQty, invoiced_qty: invoicedQty };
  }).filter((line) => line && line.qty > 0);
}

function hasSalesLineShortage(lines) {
  return lines.some((line) => {
    const product = (productMeta.products || []).find((p) => p.sku === line.sku);
    return !product || Number(line.qty || 0) > Number(product.available_qty ?? product.qty ?? 0);
  });
}

function reversalLedgerRows(rows, reference, source, descriptionPrefix) {
  return (rows || []).filter((row) => row.status !== "Reversed").map((row) => ({
    entry_date: today(),
    posting_date: today(),
    account: row.account,
    customer: row.customer,
    vendor: row.vendor,
    invoice_no: row.invoice_no,
    invoice_date: row.invoice_date,
    due_date: row.due_date,
    bank_reference: row.bank_reference || null,
    description: `${descriptionPrefix} ${row.description || reference}`,
    reference,
    debit: Number(row.credit || 0),
    credit: Number(row.debit || 0),
    source,
    status: "Posted",
  })).filter((row) => row.debit || row.credit);
}

async function voidSalesOrder(orderNo) {
  const order = currentRows.find((row) => row.order_no === orderNo);
  if (!order || /void|reversed|cancelled/i.test(order.status || "")) return;
  if (/fulfilled|issued|delivered|posted|paid/i.test(order.status || "")) {
    alert("This order was already issued. Use Reverse instead.");
    return;
  }
  await loadAccountingCloseDate();
  const details = promptVoidDetails(`sales order ${orderNo}`);
  if (!details) return;
  if (!confirm(`Void ${orderNo} on ${formatDisplayDate(details.voidDate)}? The order will remain in the system for audit history.`)) return;
  try {
    if (order.deposit_invoice_no) {
      const { data: depositRows, error } = await supabase.from("general_ledger").select("*").eq("reference", order.deposit_invoice_no).eq("source", "Sales Order Deposit");
      if (error) throw error;
      const reversals = reversalLedgerRows(depositRows, order.deposit_invoice_no, "Sales Order Void", `Void ${orderNo}: ${details.reason}.`).map((row) => ({ ...row, entry_date: details.voidDate, posting_date: details.voidDate }));
      if (reversals.length) await upsertManyWithOptionalColumns("general_ledger", reversals, "id", ["bank_reference"]);
      await supabase.from("invoices").update({ status: "Reversed", notes: `Deposit invoice voided with ${orderNo} on ${formatDisplayDate(details.voidDate)}: ${details.reason}` }).eq("invoice_no", order.deposit_invoice_no);
    }
    await updateOneWithOptionalColumns("sales_orders", {
      status: "Void",
      special_order_status: "Cancelled",
      notes: [order.notes, `Voided ${formatDisplayDate(details.voidDate)} by ${profile?.full_name || profile?.username || "Owner"}: ${details.reason}`].filter(Boolean).join("\n"),
    }, "id", order.id, ["special_order_status"]);
    await releaseQuotationFromSalesOrder(orderNo, `Sales Order voided on ${formatDisplayDate(details.voidDate)}: ${details.reason}`);
    renderSalesOrdersView();
  } catch (error) {
    alert(error.message || error);
  }
}

async function reverseSalesOrder(orderNo) {
  const order = currentRows.find((row) => row.order_no === orderNo);
  if (!order || /void|reversed|cancelled/i.test(order.status || "")) return;
  const reason = prompt(`Reason for reversing ${orderNo}:`);
  if (!reason?.trim()) return;
  if (!confirm(`Reverse ${orderNo}? Inventory will be restored and reversing accounting entries will be posted. The original records will remain for audit history.`)) return;
  try {
    if (isLockedAccountingDate(today())) throw new Error("Today's posting date is inside the closed accounting period.");
    for (const line of order._lines || []) {
      const product = (productMeta.products || []).find((p) => p.id === line.product_id || p.sku === line.sku);
      if (!product) throw new Error(`Cannot restore ${line.sku}; the product is missing from Product Master.`);
      const qty = Number(line.qty || 0);
      const unitCost = Number(product.cost || 0);
      await supabase.from("products").update({ qty: Number(product.qty || 0) + qty }).eq("id", product.id);
      await upsertOneWithOptionalColumns("stock_movements", {
        reference_no: `REV-${order.order_no}-${line.sku}`,
        movement_date: today(),
        type: "Sales Order Reversal",
        product_id: product.id,
        sku: product.sku,
        product_name: product.name,
        vendor: product.source_vendor,
        sold_to: order.customer,
        sold_date: order.order_date,
        qty,
        to_warehouse: product.warehouse,
        to_bin_shelf: product.bin_shelf || "",
        unit_fifo_cost: unitCost,
        total_fifo_cost: qty * unitCost,
        document_no: order.order_no,
        entered_by: profile?.full_name || profile?.username || "Owner",
        reason: `Reversal of ${order.order_no}: ${reason.trim()}`,
      }, "reference_no", ["to_bin_shelf"]);
    }
    const { data: ledgerRows, error } = await supabase.from("general_ledger").select("*").eq("reference", order.order_no).in("source", ["Sales Order", "Sales Fulfillment"]);
    if (error) throw error;
    const reversals = reversalLedgerRows(ledgerRows, order.order_no, "Sales Order Reversal", `Reverse ${orderNo}:`);
    if (reversals.length) await upsertManyWithOptionalColumns("general_ledger", reversals, "id", ["bank_reference"]);
    if (order.invoice_no) {
      await supabase.from("invoices").update({ status: "Reversed", notes: `Reversed with sales order ${orderNo}: ${reason.trim()}` }).eq("invoice_no", order.invoice_no);
      await supabase.from("customer_payments").update({ status: "Reversed" }).eq("invoice_no", order.invoice_no).neq("status", "Void");
    }
    await updateOneWithOptionalColumns("sales_orders", {
      status: "Reversed",
      special_order_status: /special order|backorder/i.test(order.order_type || "") ? "Ready for Delivery" : "Unfulfilled",
      notes: [order.notes, `Reversed ${today()} by ${profile?.full_name || profile?.username || "Owner"}: ${reason.trim()}`].filter(Boolean).join("\n"),
    }, "id", order.id, ["special_order_status"]);
    await releaseQuotationFromSalesOrder(orderNo, `Sales Order reversed on ${formatDisplayDate(today())}: ${reason.trim()}`);
    renderSalesOrdersView();
  } catch (error) {
    alert(error.message || error);
  }
}

async function releaseQuotationFromSalesOrder(orderNo, reason = "Related Sales Order cancelled") {
  if (!orderNo) return 0;
  const { data: quotations, error } = await supabase.from("quotations").select("*").eq("sales_order_no", orderNo);
  if (error) throw error;
  let released = 0;
  for (const quote of quotations || []) {
    const after = {
      status: "Draft",
      sales_order_no: null,
      accepted_date: null,
      last_activity_at: new Date().toISOString(),
      notes: [quote.notes, `Returned to Draft: ${reason}. Previous linked Sales Order: ${orderNo}.`].filter(Boolean).join("\n"),
    };
    await updateOneWithOptionalColumns("quotations", after, "id", quote.id, ["last_activity_at"]);
    await writeAuditLog({ tableName: "quotations", action: "Released from cancelled Sales Order", beforeData: quote, afterData: { ...quote, ...after } });
    released += 1;
  }
  return released;
}

function salesOrderAccountingReady(order) {
  return ["fulfilled", "issued", "delivered", "posted", "paid"].includes(String(order?.status || "").toLowerCase());
}

async function requireSalesAccountingAccounts() {
  const chart = await getAll("chart_of_accounts");
  const required = ["FHB Checking", "Accounts Receivable (A/R)", "Customer Deposit", "Parts Sales", "COGS - Parts", "Parts Inventory"];
  const missing = required.filter((name) => !chart.some((row) => String(row.account || "").trim().toLowerCase() === name.toLowerCase() || String(row.report_group || "").trim().toLowerCase() === name.toLowerCase()));
  if (missing.length) throw new Error(`Accounting cannot post because these accounts are missing from Chart of Accounts: ${missing.join(", ")}.`);
}

async function syncSalesOrderInitialAccounting(order, lines, products = [], options = {}) {
  if (!order?.order_no) return;
  await supabase.from("general_ledger").delete().eq("reference", order.order_no).eq("source", "Sales Order");
  if (!salesOrderAccountingReady(order) || !lines?.length) {
    await supabase.from("general_ledger").delete().eq("reference", order.order_no).eq("source", "Sales Fulfillment");
    return;
  }
  if (isLockedAccountingDate(order.order_date)) throw new Error("This sales order date is inside the closed accounting period.");
  await requireSalesAccountingAccounts();

  const productBySku = Object.fromEntries((products || []).map((p) => [p.sku, p]));
  const stockBySku = Object.fromEntries((products || []).map((p) => [p.sku, Number(p.qty || 0)]));
  const freightAmount = Math.max(0, Number(order.freight_amount || 0));
  const total = lines.reduce((sum, line) => sum + Number(line.qty || 0) * Number(line.price || 0), freightAmount);
  if (!total) return;

  const paymentMode = String(order.payment_mode || "PO").trim().toLowerCase();
  const debitAccount = paymentMode === "po" ? "Accounts Receivable (A/R)" : "FHB Checking";
  const isSpecial = /special order|backorder/i.test(order.order_type || "");
  const depositApplied = isSpecial ? Math.min(total, Math.max(0, Number(order.deposit_amount || 0))) : 0;
  const balanceDue = Math.max(0, total - depositApplied);
  const invoiceFields = {
    invoice_no: order.invoice_no || null,
    invoice_date: order.invoice_no ? today() : null,
    bank_reference: paymentMode === "po" ? null : (order.bank_reference || order.invoice_no || order.order_no),
  };
  const rows = [];
  if (depositApplied > 0) rows.push({
    entry_date: order.order_date, posting_date: order.order_date, account: "Customer Deposit", customer: order.customer,
    ...invoiceFields, description: `Apply customer deposit to ${order.order_no}`, reference: order.order_no,
    debit: depositApplied, credit: 0, source: "Sales Order", status: "Posted",
  });
  if (balanceDue > 0) rows.push({
    entry_date: order.order_date, posting_date: order.order_date, account: debitAccount, customer: order.customer,
    ...invoiceFields, description: `Balance due for ${order.order_no} (${order.payment_mode || "PO"})`, reference: order.order_no,
    debit: balanceDue, credit: 0, source: "Sales Order", status: "Posted",
  });

  for (const line of lines) {
    const qty = Number(line.qty || 0);
    if (!qty) continue;
    const product = productBySku[line.sku] || {};
    const price = Number(line.price || 0);
    const cost = Number(product.cost || 0);
    const availableQty = options.forceAvailable ? qty : Math.min(qty, Math.max(0, Number(stockBySku[line.sku] || 0)));
    const transitQty = Math.max(0, qty - availableQty);
    stockBySku[line.sku] = Number(stockBySku[line.sku] || 0) - qty;

    if (availableQty > 0 && price > 0) {
      rows.push({ entry_date: order.order_date, posting_date: order.order_date, account: "Parts Sales", customer: order.customer, ...invoiceFields, description: `Available parts sale ${line.sku} ${line.product_name || ""}`, reference: order.order_no, debit: 0, credit: availableQty * price, source: "Sales Order", status: "Posted" });
    }
    if (transitQty > 0 && price > 0) {
      rows.push({ entry_date: order.order_date, posting_date: order.order_date, account: "Parts in Transit", customer: order.customer, ...invoiceFields, description: `Backordered parts sale ${line.sku} ${line.product_name || ""}`, reference: order.order_no, debit: 0, credit: transitQty * price, source: "Sales Order", status: "Posted" });
    }
    if (availableQty > 0 && cost > 0) {
      rows.push({ entry_date: order.order_date, posting_date: order.order_date, account: "COGS - Parts", customer: order.customer, ...invoiceFields, description: `Cost of goods sold ${line.sku} ${line.product_name || ""}`, reference: order.order_no, debit: availableQty * cost, credit: 0, source: "Sales Order", status: "Posted" });
      rows.push({ entry_date: order.order_date, posting_date: order.order_date, account: "Parts Inventory", customer: order.customer, ...invoiceFields, description: `Inventory relief ${line.sku} ${line.product_name || ""}`, reference: order.order_no, debit: 0, credit: availableQty * cost, source: "Sales Order", status: "Posted" });
    }
  }
  if (freightAmount > 0) {
    rows.push({ entry_date: order.order_date, posting_date: order.order_date, account: "Parts Sales", customer: order.customer, ...invoiceFields, description: `Customer-billed freight ${order.order_no}`, reference: order.order_no, debit: 0, credit: freightAmount, source: "Sales Order", status: "Posted" });
  }
  await upsertManyWithOptionalColumns("general_ledger", rows, "id", ["bank_reference"]);
}

async function postSalesOrderFulfillmentAccounting(order, lines, products = []) {
  if (!order?.order_no || !lines?.length) return;
  if (isLockedAccountingDate(today())) throw new Error("Today's posting date is inside the closed accounting period.");
  const { data: initialRows, error } = await supabase.from("general_ledger").select("*").eq("reference", order.order_no).eq("source", "Sales Order");
  if (error) throw error;
  const existing = initialRows || [];
  const transitAmount = existing.filter((row) => row.account === "Parts in Transit").reduce((sum, row) => sum + Number(row.credit || 0) - Number(row.debit || 0), 0);
  const initialInventoryCredit = existing.filter((row) => row.account === "Parts Inventory").reduce((sum, row) => sum + Number(row.credit || 0) - Number(row.debit || 0), 0);
  const productBySku = Object.fromEntries((products || []).map((p) => [p.sku, p]));
  const totalCost = (lines || []).reduce((sum, line) => sum + Number(line.qty || 0) * Number(productBySku[line.sku]?.cost || 0), 0);
  const remainingCost = Math.max(0, totalCost - Math.max(0, initialInventoryCredit));
  const rows = [];

  if (transitAmount > 0) {
    rows.push({ entry_date: today(), posting_date: today(), account: "Parts in Transit", customer: order.customer, description: `Backordered parts arrived ${order.order_no}`, reference: order.order_no, debit: transitAmount, credit: 0, source: "Sales Fulfillment", status: "Posted" });
    rows.push({ entry_date: today(), posting_date: today(), account: "Parts Sales", customer: order.customer, description: `Recognize sales after parts arrived ${order.order_no}`, reference: order.order_no, debit: 0, credit: transitAmount, source: "Sales Fulfillment", status: "Posted" });
  }
  if (remainingCost > 0) {
    rows.push({ entry_date: today(), posting_date: today(), account: "COGS - Parts", customer: order.customer, description: `Cost of goods sold on fulfillment ${order.order_no}`, reference: order.order_no, debit: remainingCost, credit: 0, source: "Sales Fulfillment", status: "Posted" });
    rows.push({ entry_date: today(), posting_date: today(), account: "Parts Inventory", customer: order.customer, description: `Inventory relief on fulfillment ${order.order_no}`, reference: order.order_no, debit: 0, credit: remainingCost, source: "Sales Fulfillment", status: "Posted" });
  }
  await supabase.from("general_ledger").delete().eq("reference", order.order_no).eq("source", "Sales Fulfillment");
  if (rows.length) await upsertMany("general_ledger", rows, "id");
}

async function issueSalesOrderLegacy(orderNo) {
  const order = currentRows.find((row) => row.order_no === orderNo);
  if (!order) return;
  if (String(order.status || "").toLowerCase() === "quotation") {
    alert("Quotation cannot be issued. Change the status first.");
    return;
  }
  const reservationShortage = (await salesReservationShortages(orderNo, order._lines || []))[0];
  if (reservationShortage) {
    alert(`Cannot issue sale. ${reservationShortage.product_name || reservationShortage.sku} has only ${reservationShortage.available} available after other open sales reservations (${reservationShortage.reservedElsewhere} reserved elsewhere).`);
    return;
  }
  const shortage = (order._lines || []).find((line) => {
    const product = (productMeta.products || []).find((p) => p.sku === line.sku);
    return !product || Number(line.qty || 0) > Number(product.qty || 0);
  });
  if (shortage) {
    const product = (productMeta.products || []).find((p) => p.sku === shortage.sku);
    alert(`Cannot issue sale. ${shortage.product_name || shortage.sku} has only ${product?.qty || 0} received units available.`);
    return;
  }
  try {
    const { data: existingSalesEntries, error: existingSalesError } = await supabase.from("general_ledger").select("id").eq("reference", order.order_no).eq("source", "Sales Order");
    if (existingSalesError) throw existingSalesError;
    if (!(existingSalesEntries || []).length) {
      await syncSalesOrderInitialAccounting({ ...order, status: "Fulfilled", payment_mode: order.payment_mode || "PO" }, order._lines || [], productMeta.products || [], { forceAvailable: true });
    }
    for (const line of order._lines || []) {
      const product = (productMeta.products || []).find((p) => p.sku === line.sku);
      const qty = Number(line.qty || 0);
      const unitCost = Number(product?.cost || 0);
      await supabase.from("products").update({ qty: Number(product.qty || 0) - qty }).eq("id", product.id);
      await upsertOneWithOptionalColumns("stock_movements", {
        reference_no: `SM-${order.order_no}-${line.sku}`,
        movement_date: today(),
        type: "Sale Issue",
        product_id: product.id,
        sku: product.sku,
        product_name: product.name,
        vendor: product.source_vendor,
        sold_to: order.customer,
        sold_date: order.order_date,
        qty: -qty,
        from_warehouse: product.warehouse,
        from_bin_shelf: product.bin_shelf || "",
        unit_fifo_cost: unitCost,
        total_fifo_cost: qty * unitCost,
        document_no: order.order_no,
        entered_by: profile?.full_name || profile?.username || "Owner",
        reason: `Order ${order.order_no}`,
      }, "reference_no", ["from_bin_shelf"], "Sale issued. Run the multi-location SQL update so bin/shelf details can be stored.");
    }
    await updateOneWithOptionalColumns("sales_orders", { status: "Fulfilled", special_order_status: "Delivered", delivered_at: new Date().toISOString() }, "id", order.id, ["special_order_status", "delivered_at"]);
    await postSalesOrderFulfillmentAccounting({ ...order, status: "Fulfilled" }, order._lines || [], productMeta.products || []);
    await invoiceSalesOrder(orderNo, true);
    renderSalesOrdersView();
  } catch (error) {
    alert(error.message || error);
  }
}

async function issueSalesOrder(orderNo) {
  const order = currentRows.find((row) => row.order_no === orderNo);
  if (!order || /void|reversed|cancelled/i.test(order.status || "")) return;
  if (String(order.status || "").toLowerCase() === "quotation") return alert("Quotation cannot be issued. Convert or approve it first.");
  const products = await getAll("products");
  productMeta.products = products;
  const reservationAvailability = await salesReservationAvailability(orderNo, order._lines || []);
  const availabilityBySku = new Map(reservationAvailability.map((line) => [String(line.sku || "").trim().toLowerCase(), line]));
  const rows = (order._lines || []).map((line, index) => {
    const product = products.find((item) => item.id === line.product_id || String(item.sku || "").toLowerCase() === String(line.sku || "").toLowerCase()) || {};
    const ordered = Number(line.qty || 0);
    const issued = Number(line.issued_qty || 0);
    const shipped = Number(line.shipped_qty || 0);
    const issueRemaining = Math.max(0, ordered - issued);
    const shipAvailable = Math.max(0, issued - shipped);
    const availability = availabilityBySku.get(String(line.sku || "").trim().toLowerCase()) || {};
    const currentReservation = Math.max(0, issued - shipped);
    const freeAvailable = Math.max(0, Number(availability.available || 0) - currentReservation);
    const reserveNow = Math.min(issueRemaining, freeAvailable);
    return `<tr data-partial-line="${index}" data-free-available="${esc(freeAvailable)}"><td>${esc(line.sku)}</td><td>${esc(line.product_name || line.description || "")}</td><td class="num">${ordered}</td><td class="num">${issued}</td><td class="num">${shipped}</td><td class="num">${Number(product.qty || 0)}</td><td class="num">${freeAvailable}</td><td><input type="number" min="0" max="${reserveNow}" step="0.01" data-issue-now value="${reserveNow}"></td><td><input type="number" min="0" max="${shipAvailable + reserveNow}" step="0.01" data-ship-now value="0"></td></tr>`;
  }).join("");
  $("modalTitle").textContent = `Reserve / Ship to Customer ${order.order_no}`;
  $("modalBody").innerHTML = `<p class="notice"><strong>ORD</strong> = quantity ordered by the customer. <strong>ISS</strong> = quantity reserved automatically from available stock when the Sales Order is saved; it remains physically on hand but cannot be used by another order. <strong>SHP</strong> = quantity shipped/released to the customer; it reduces physical inventory. Invoice tracking remains separate so one Sales Order can have multiple invoices.</p><div class="table-wrap"><table class="line-table"><thead><tr><th>SKU</th><th>Product</th><th>ORD</th><th>ISS</th><th>SHP</th><th>On Hand</th><th>Available</th><th>Additional Reserve</th><th>Ship to Customer</th></tr></thead><tbody id="partialSalesIssueBody">${rows}</tbody></table></div>`;
  $("modalSave").textContent = "Save Reservation / Customer Shipment";
  $("modalSave").onclick = () => savePartialSalesOrderIssue(order, products);
  $("modal").style.display = "flex";
}

async function savePartialSalesOrderIssue(order, products = []) {
  const actions = [...document.querySelectorAll("#partialSalesIssueBody tr")].map((row, index) => {
    const line = (order._lines || [])[index];
    const product = products.find((item) => item.id === line?.product_id || String(item.sku || "").toLowerCase() === String(line?.sku || "").toLowerCase());
    return { line, product, issueNow: Number(row.querySelector("[data-issue-now]")?.value || 0), shipNow: Number(row.querySelector("[data-ship-now]")?.value || 0) };
  }).filter((item) => item.line && (item.issueNow > 0 || item.shipNow > 0));
  if (!actions.length) return alert("Enter an Additional Reserve or Ship to Customer quantity.");
  for (const action of actions) {
    const ordered = Number(action.line.qty || 0);
    const issued = Number(action.line.issued_qty || 0);
    const shipped = Number(action.line.shipped_qty || 0);
    if (!action.product) return alert(`Product ${action.line.sku} is missing from Product Master.`);
    if (action.issueNow < 0 || action.issueNow > ordered - issued) return alert(`Issue Now for ${action.line.sku} cannot exceed the remaining ORD quantity.`);
    const row = document.querySelector(`[data-partial-line="${(order._lines || []).indexOf(action.line)}"]`);
    const freeAvailable = Number(row?.dataset.freeAvailable || 0);
    if (action.issueNow > freeAvailable) return alert(`${action.line.sku} has only ${freeAvailable} units available after other Sales Order reservations.`);
    if (action.shipNow < 0 || action.shipNow > issued + action.issueNow - shipped) return alert(`Ship to Customer for ${action.line.sku} cannot exceed cumulative ISS less cumulative SHP.`);
    if (action.shipNow > Number(action.product.qty || 0)) return alert(`${action.line.sku} has only ${Number(action.product.qty || 0)} units physically on hand to ship.`);
  }
  if (!confirm(`Save this reservation/customer shipment for ${order.order_no}?\n\nISS reserves stock without reducing physical inventory. SHP releases stock to the customer and reduces physical inventory. Invoicing is tracked separately.`)) return;
  try {
    for (const action of actions) {
      const nextIssued = Number(action.line.issued_qty || 0) + action.issueNow;
      const nextShipped = Number(action.line.shipped_qty || 0) + action.shipNow;
      if (action.shipNow > 0) {
        const deductions = await deductProductWithMotherComponents(action.product, action.shipNow);
        for (const deduction of deductions) {
          const deductedProduct = deduction.product;
          const deductedQty = Number(deduction.quantity_deducted || 0);
          const deductedCost = Number(deductedProduct.cost || 0);
          const movementKey = crypto.randomUUID();
          await upsertOneWithOptionalColumns("stock_movements", {
            reference_no: `SM-${order.order_no}-${deductedProduct.sku}-${movementKey.slice(0, 8)}`,
            movement_date: today(), type: deduction.is_component ? "Sale Issue - Mother Component" : "Sale Issue", product_id: deductedProduct.id, sku: deductedProduct.sku,
            product_name: deductedProduct.name, vendor: deductedProduct.source_vendor, sold_to: order.customer,
            sold_date: today(), qty: -deductedQty, from_warehouse: deductedProduct.warehouse,
            from_bin_shelf: deductedProduct.bin_shelf || "", unit_fifo_cost: deductedCost,
            total_fifo_cost: deductedQty * deductedCost, document_no: order.order_no,
            entered_by: profile?.full_name || profile?.username || "Owner", reason: deduction.is_component ? `Automatically shipped with mother part ${deduction.mother_sku} for ${order.order_no}` : `Customer shipment for ${order.order_no}`,
          }, "reference_no", ["from_bin_shelf"]);
        }
      }
      const { error: lineError } = await supabase.from("sales_order_lines").update({ issued_qty: nextIssued, shipped_qty: nextShipped }).eq("id", action.line.id);
      if (lineError) throw lineError;
      action.line.issued_qty = nextIssued;
      action.line.shipped_qty = nextShipped;
    }
    const allIssued = (order._lines || []).every((line) => Number(line.issued_qty || 0) >= Number(line.qty || 0));
    const allShipped = (order._lines || []).every((line) => Number(line.shipped_qty || 0) >= Number(line.qty || 0));
    const anyShipped = (order._lines || []).some((line) => Number(line.shipped_qty || 0) > 0);
    const nextStatus = allShipped ? "Fulfilled" : anyShipped ? "Partially Shipped" : allIssued ? "Ready to Ship" : "Partially Issued";
    const nextStage = allShipped ? "Delivered" : anyShipped ? "Partially Delivered" : allIssued ? "Ready for Delivery" : "Awaiting Stock";
    await updateOneWithOptionalColumns("sales_orders", { status: nextStatus, special_order_status: nextStage, delivered_at: allShipped ? new Date().toISOString() : null }, "id", order.id, ["special_order_status", "delivered_at"]);
    closeModal();
    alert(`${order.order_no} updated.\n\nSHP and inventory were updated for the customer release. Use Invoice to bill the shipped quantity.`);
    await renderSalesOrdersView();
  } catch (error) {
    alert(error.message || error);
  }
}

function confirmSalesOrderInvoiceDraft(order, billableLines = [], previousInvoices = []) {
  return new Promise((resolve) => {
    const freight = previousInvoices.length ? 0 : Math.max(0, Number(order.freight_amount || 0));
    const lineSubtotal = billableLines.reduce((sum, line) => sum + Number(line.billQty || 0) * Number(line.price || 0), 0);
    const depositApplied = previousInvoices.length ? 0 : Math.min(lineSubtotal + freight, Math.max(0, Number(order.deposit_amount || 0)));
    const total = lineSubtotal + freight - depositApplied;
    const rows = billableLines.map((line) => `<tr><td>${esc(line.sku || "")}</td><td>${esc(line.description || line.product_name || "")}</td><td class="num">${esc(line.billQty)}</td><td class="num">${money(line.price)}</td><td class="num">${money(Number(line.billQty || 0) * Number(line.price || 0))}</td></tr>`).join("");
    const adjustments = `${freight > 0 ? `<tr><td></td><td>Freight</td><td class="num">1</td><td class="num">${money(freight)}</td><td class="num">${money(freight)}</td></tr>` : ""}${depositApplied > 0 ? `<tr><td></td><td>Less customer deposit ${esc(order.deposit_invoice_no || "")}</td><td class="num">1</td><td class="num">${money(-depositApplied)}</td><td class="num">${money(-depositApplied)}</td></tr>` : ""}`;
    $("modalTitle").textContent = `Draft invoice — ${order.order_no}`;
    $("modalBody").innerHTML = `
      <section class="subpanel">
        <div class="panel-title"><strong>Review before creating</strong><span>No invoice or accounting entry has been created yet.</span></div>
        <div class="form-grid compact-grid">
          ${productInput("Customer", "draft_invoice_customer", order.customer || "")}
          ${productInput("Sales Order", "draft_invoice_order", order.order_no || "")}
          ${productInput(paymentReferencePrintLabel(order.payment_mode), "draft_invoice_po", salesOrderInvoicePoReference(order))}
          ${productInput("Invoice date", "draft_invoice_date", today())}
        </div>
        <div class="table-wrap"><table class="line-table"><thead><tr><th>SKU</th><th>Product / Description</th><th class="num">SHP to Invoice</th><th class="num">Rate</th><th class="num">Amount</th></tr></thead><tbody>${rows}${adjustments}<tr class="total-row"><td colspan="4" class="num"><strong>Draft Invoice Total</strong></td><td class="num"><strong>${money(total)}</strong></td></tr></tbody></table></div>
        <p class="notice"><strong>Control:</strong> Only shipped quantities not previously invoiced are included. Confirming will not deduct inventory or SHP again.</p>
      </section>`;
    $("modalSave").style.display = "";
    $("modalSave").textContent = "Confirm & Create Invoice";
    $("modalCancel").textContent = "Cancel";
    modalDirty = false;
    $("modal").style.display = "flex";
    $("modalSave").onclick = () => {
      const invoiceWindow = openInAppDocumentWindow("Creating Invoice");
      if (!invoiceWindow) {
        alert("Please allow popups for this site, then click Confirm & Create Invoice again. The invoice has not been created.");
        return;
      }
      if (invoiceWindow) {
        invoiceWindow.document.write("<!doctype html><title>Creating invoice...</title><body style='font-family:Arial;padding:32px'>Creating invoice and preparing the PDF...</body>");
        invoiceWindow.document.close();
      }
      $("modalClose").onclick = closeModal;
      closeModal(true);
      resolve(invoiceWindow);
    };
    const cancelDraft = () => {
      $("modalClose").onclick = closeModal;
      closeModal(true);
      resolve(null);
    };
    $("modalCancel").onclick = cancelDraft;
    $("modalClose").onclick = cancelDraft;
  });
}

function salesOrderInvoicePoReference(order = {}) {
  return String(order.customer_po || order.source_po_no || "").trim();
}

async function invoiceSalesOrder(orderNo, silent = false) {
  const order = currentRows.find((row) => row.order_no === orderNo);
  if (!order) return;
  const billableLines = (order._lines || []).map((line) => {
    const issued = Number(line.issued_qty || 0);
    const shipped = Number(line.shipped_qty || 0);
    const invoiced = Number(line.invoiced_qty || 0);
    const billQty = Math.max(0, issued - invoiced);
    const alreadyShippedNotInvoiced = Math.max(0, shipped - invoiced);
    return { ...line, billQty, shipQty: Math.max(0, billQty - alreadyShippedNotInvoiced) };
  }).filter((line) => line.billQty > 0);
  if (!billableLines.length) return alert(`There is no reserved, uninvoiced quantity on ${orderNo}. Save the Sales Order with available stock so ISS is reserved first.`);
  let previousInvoices = [];
  try {
    previousInvoices = (await getAll("invoices")).filter((row) => row.source_ref === order.order_no && !/void|reversed/i.test(row.status || ""));
  } catch (error) {
    alert(error.message || error);
    return;
  }
  const invoiceWindow = silent ? null : await confirmSalesOrderInvoiceDraft(order, billableLines, previousInvoices);
  if (!silent && !invoiceWindow) return;
  try {
    const invoiceNo = await nextInvoiceNoByType("Parts Sales");
    const invoice = await upsertOneWithOptionalColumns("invoices", {
      invoice_no: invoiceNo,
      invoice_date: today(),
      due_date: today(),
      customer: order.customer,
      customer_po: salesOrderInvoicePoReference(order) || null,
      payment_mode: order.payment_mode || "PO",
      type: "Parts Sales",
      source_ref: order.order_no,
      status: "Open",
      notes: `Partial shipment invoice for Sales Order ${order.order_no}`,
    }, "invoice_no", ["customer_po", "payment_mode"], "Invoice created, but the database needs the invoice Customer PO update before the Sales Order PO can be stored on the invoice header.");
    const invoiceLines = billableLines.map((line) => ({
      invoice_id: invoice.id,
      product_id: line.product_id || null,
      sku: line.sku || null,
      product_name: line.product_name || null,
      description: `${line.sku} - ${line.description || line.product_name || ""}`,
      unit: line.unit || "Each",
      qty: line.billQty,
      rate: Number(line.price || 0),
      ordered_qty: Number(line.qty || 0),
      issued_qty: Number(line.issued_qty || 0),
      shipped_qty: line.billQty,
    }));
    if (!previousInvoices.length && Number(order.freight_amount || 0) > 0) invoiceLines.push({ invoice_id: invoice.id, description: "Freight", qty: 1, rate: Number(order.freight_amount || 0), ordered_qty: 1, issued_qty: 1, shipped_qty: 1 });
    const depositApplied = previousInvoices.length ? 0 : Math.min(invoiceLines.reduce((sum, line) => sum + Number(line.qty || 0) * Number(line.rate || 0), 0), Math.max(0, Number(order.deposit_amount || 0)));
    if (depositApplied > 0) invoiceLines.push({ invoice_id: invoice.id, description: `Less customer deposit ${order.deposit_invoice_no || ""}`.trim(), qty: 1, rate: -depositApplied });
    await upsertInvoiceLines(invoiceLines, "id");
    const products = productMeta.products?.length ? productMeta.products : await getAll("products");
    for (const line of billableLines) {
      if (!(Number(line.shipQty || 0) > 0)) continue;
      const product = products.find((item) => item.id === line.product_id || String(item.sku || "").toLowerCase() === String(line.sku || "").toLowerCase());
      if (!product) throw new Error(`Product ${line.sku} is missing from Product Master.`);
      if (Number(product.qty || 0) < Number(line.shipQty || 0)) throw new Error(`${line.sku} has only ${Number(product.qty || 0)} physically on hand. The invoice was not finalized.`);
      const nextOnHand = Number(product.qty || 0) - Number(line.shipQty || 0);
      const { error: productError } = await supabase.from("products").update({ qty: nextOnHand }).eq("id", product.id);
      if (productError) throw productError;
      product.qty = nextOnHand;
      await upsertOneWithOptionalColumns("stock_movements", {
        reference_no: `SM-${invoiceNo}-${line.sku}`,
        movement_date: today(), type: "Invoice Issue", product_id: product.id, sku: product.sku,
        product_name: product.name, vendor: product.source_vendor, sold_to: order.customer,
        sold_date: today(), qty: -Number(line.shipQty || 0), from_warehouse: product.warehouse,
        from_bin_shelf: product.bin_shelf || "", unit_fifo_cost: Number(product.cost || 0),
        total_fifo_cost: Number(line.shipQty || 0) * Number(product.cost || 0), document_no: invoiceNo,
        entered_by: profile?.full_name || profile?.username || "Owner",
        reason: `Customer invoice ${invoiceNo} for ${order.order_no}`,
      }, "reference_no", ["from_bin_shelf"]);
    }
    await postPartialSalesOrderInvoiceAccounting(order, invoice, billableLines, { freight: !previousInvoices.length ? Number(order.freight_amount || 0) : 0, depositApplied });
    for (const line of billableLines) {
      const nextInvoiced = Number(line.invoiced_qty || 0) + line.billQty;
      const nextShipped = Number(line.shipped_qty || 0) + Number(line.shipQty || 0);
      const { error } = await supabase.from("sales_order_lines").update({ invoiced_qty: nextInvoiced, shipped_qty: nextShipped }).eq("id", line.id);
      if (error) throw error;
      line.invoiced_qty = nextInvoiced;
      line.shipped_qty = nextShipped;
      const sourceLine = (order._lines || []).find((item) => item.id === line.id);
      if (sourceLine) {
        sourceLine.invoiced_qty = nextInvoiced;
        sourceLine.shipped_qty = nextShipped;
      }
    }
    const invoiceList = [...new Set(String(order.invoice_no || "").split(",").map((value) => value.trim()).filter(Boolean).concat(invoiceNo))].join(", ");
    const allShipped = salesOrderFullyShipped(order);
    const allInvoiced = (order._lines || []).every((line) => Number(line.invoiced_qty || 0) >= Number(line.shipped_qty || 0));
    await updateOneWithOptionalColumns("sales_orders", { invoice_no: invoiceList, status: allShipped && allInvoiced ? "Invoiced" : "Partially Invoiced", special_order_status: allShipped ? "Delivered" : "Partially Delivered", delivered_at: allShipped ? new Date().toISOString() : null }, "id", order.id, ["special_order_status", "delivered_at"]);
    if (!silent) {
      await printCustomerInvoice(invoiceNo, { targetWindow: invoiceWindow });
      alert(`Invoice ${invoiceNo} created and opened.`);
      await renderSalesOrdersView();
    }
  } catch (error) {
    if (invoiceWindow && !invoiceWindow.closed) invoiceWindow.close();
    alert(error.message || error);
  }
}

async function postPartialSalesOrderInvoiceAccounting(order, invoice, lines = [], options = {}) {
  if (isLockedAccountingDate(invoice.invoice_date)) throw new Error("This invoice date is inside the closed accounting period.");
  await requireSalesAccountingAccounts();
  const paymentMode = String(order.payment_mode || "PO").toLowerCase();
  const debitAccount = paymentMode === "po" ? "Accounts Receivable (A/R)" : "FHB Checking";
  const salesAmount = lines.reduce((sum, line) => sum + Number(line.billQty || 0) * Number(line.price || 0), 0) + Math.max(0, Number(options.freight || 0));
  const netReceivable = Math.max(0, salesAmount - Math.max(0, Number(options.depositApplied || 0)));
  const rows = [];
  if (netReceivable > 0) rows.push({ entry_date: invoice.invoice_date, posting_date: invoice.invoice_date, account: debitAccount, customer: order.customer, invoice_no: invoice.invoice_no, invoice_date: invoice.invoice_date, due_date: invoice.due_date, bank_reference: paymentMode === "po" ? null : invoice.invoice_no, description: `Partial shipment invoice ${order.order_no}`, reference: invoice.invoice_no, debit: netReceivable, credit: 0, source: "Sales Order Invoice", status: "Posted" });
  if (Number(options.depositApplied || 0) > 0) rows.push({ entry_date: invoice.invoice_date, posting_date: invoice.invoice_date, account: "Customer Deposit", customer: order.customer, invoice_no: invoice.invoice_no, invoice_date: invoice.invoice_date, due_date: invoice.due_date, description: `Apply deposit to ${order.order_no}`, reference: invoice.invoice_no, debit: Number(options.depositApplied), credit: 0, source: "Sales Order Invoice", status: "Posted" });
  if (salesAmount > 0) rows.push({ entry_date: invoice.invoice_date, posting_date: invoice.invoice_date, account: "Parts Sales", customer: order.customer, invoice_no: invoice.invoice_no, invoice_date: invoice.invoice_date, due_date: invoice.due_date, description: `Parts shipped for ${order.order_no}`, reference: invoice.invoice_no, debit: 0, credit: salesAmount, source: "Sales Order Invoice", status: "Posted" });
  const products = productMeta.products?.length ? productMeta.products : await getAll("products");
  lines.forEach((line) => {
    const product = products.find((item) => item.id === line.product_id || item.sku === line.sku) || {};
    const costAmount = Number(line.billQty || 0) * Number(product.cost || 0);
    if (!(costAmount > 0)) return;
    rows.push({ entry_date: invoice.invoice_date, posting_date: invoice.invoice_date, account: "COGS - Parts", customer: order.customer, invoice_no: invoice.invoice_no, invoice_date: invoice.invoice_date, due_date: invoice.due_date, description: `COGS ${line.sku} for ${order.order_no}`, reference: invoice.invoice_no, debit: costAmount, credit: 0, source: "Sales Order Invoice", status: "Posted" });
    rows.push({ entry_date: invoice.invoice_date, posting_date: invoice.invoice_date, account: "Parts Inventory", customer: order.customer, invoice_no: invoice.invoice_no, invoice_date: invoice.invoice_date, due_date: invoice.due_date, description: `Inventory relief ${line.sku} for ${order.order_no}`, reference: invoice.invoice_no, debit: 0, credit: costAmount, source: "Sales Order Invoice", status: "Posted" });
  });
  assertBalancedLedgerRows(rows, `Partial Sales Order invoice ${invoice.invoice_no}`);
  await supabase.from("general_ledger").delete().eq("reference", invoice.invoice_no).eq("source", "Sales Order Invoice");
  if (rows.length) await upsertManyWithOptionalColumns("general_ledger", rows, "id", ["bank_reference"]);
}

async function createSalesOrderDepositInvoice(orderNo) {
  const order = currentRows.find((row) => row.order_no === orderNo);
  if (!order) return;
  if (order.deposit_invoice_no) {
    alert(`Deposit invoice ${order.deposit_invoice_no} already exists.`);
    return;
  }
  const total = salesOrderTotal(order);
  const entered = prompt(`Deposit amount for ${orderNo} (order total ${money(total)}):`, String(total.toFixed(2)));
  if (entered === null) return;
  const amount = Number(String(entered).replace(/[$,]/g, ""));
  if (!Number.isFinite(amount) || amount <= 0 || amount > total) {
    alert("Enter a deposit greater than zero and not more than the order total.");
    return;
  }
  try {
    await requireSalesAccountingAccounts();
    if (isLockedAccountingDate(today())) throw new Error("Today's posting date is inside the closed accounting period.");
    const invoiceNo = await nextInvoiceNoByType("Customer Deposit");
    const paymentMode = String(order.payment_mode || "PO").toLowerCase();
    const invoice = await upsertOneWithOptionalColumns("invoices", {
      invoice_no: invoiceNo,
      invoice_date: today(),
      due_date: today(),
      customer: order.customer,
      customer_po: salesOrderInvoicePoReference(order) || null,
      payment_mode: order.payment_mode || "PO",
      type: "Customer Deposit",
      source_ref: order.order_no,
      status: paymentMode === "po" ? "Open" : "Paid",
      notes: `Deposit for special/backordered sales order ${order.order_no}`,
    }, "invoice_no", ["customer_po", "payment_mode"], "Deposit invoice created, but the database needs the invoice Customer PO update before the Sales Order PO can be stored on the invoice header.");
    await upsertInvoiceLines([{ invoice_id: invoice.id, description: `Customer deposit for ${order.order_no}`, qty: 1, rate: amount }], "id");
    await supabase.from("general_ledger").delete().eq("reference", invoiceNo).eq("source", "Sales Order Deposit");
    const debitAccount = paymentMode === "po" ? "Accounts Receivable (A/R)" : "FHB Checking";
    await upsertManyWithOptionalColumns("general_ledger", [
      { entry_date: today(), posting_date: today(), account: debitAccount, customer: order.customer, invoice_no: invoiceNo, invoice_date: today(), description: `Customer deposit ${order.order_no}`, reference: invoiceNo, bank_reference: paymentMode === "po" ? null : invoiceNo, debit: amount, credit: 0, source: "Sales Order Deposit", status: "Posted" },
      { entry_date: today(), posting_date: today(), account: "Customer Deposit", customer: order.customer, invoice_no: invoiceNo, invoice_date: today(), description: `Customer deposit liability ${order.order_no}`, reference: invoiceNo, debit: 0, credit: amount, source: "Sales Order Deposit", status: "Posted" },
    ], "id", ["bank_reference"]);
    await updateOneWithOptionalColumns("sales_orders", { deposit_invoice_no: invoiceNo, deposit_amount: amount, deposit_posted_at: new Date().toISOString() }, "id", order.id, ["deposit_invoice_no", "deposit_amount", "deposit_posted_at"], "Deposit invoice was created, but run the Special Order SQL update so its link is stored on the sales order.");
    alert(`Deposit invoice ${invoiceNo} created and posted automatically:\nDebit ${debitAccount} ${money(amount)}\nCredit Customer Deposit ${money(amount)}`);
    renderSalesOrdersView();
  } catch (error) {
    alert(error.message || error);
  }
}

async function printSalesOrder(orderNo) {
  const order = currentRows.find((row) => row.order_no === orderNo);
  if (!order) return;
  const title = String(order.status || "").toLowerCase() === "quotation" ? "Sales Quote" : "Sales Order";
  const printLines = (order._lines || []).map((line) => [line.sku, line.description || line.product_name || "", line.unit || "Each", line.qty, line.issued_qty || 0, line.shipped_qty || 0, money(line.price), money(Number(line.qty || 0) * Number(line.price || 0))]);
  if (Number(order.freight_amount || 0) > 0) printLines.push(["", "Freight", "Each", 1, 0, 0, money(order.freight_amount), money(order.freight_amount)]);
  let html = printableDocumentHtml({
    title,
    number: order.order_no,
    date: order.order_date,
    partyLabel: "Customer",
    partyName: order.customer,
    meta: [[paymentReferencePrintLabel(order.payment_mode), order.customer_po || ""], ["Requested By", order.requested_by || ""], ["Payment Mode", order.payment_mode || "PO"], ["Status", order.status || ""]],
    heads: ["SKU", "Item", "UOM", "ORD", "ISS", "SHP", "U.P.", "Amount"],
    lines: printLines,
    total: salesOrderTotal(order),
    notes: order.notes || "",
    salesLayout: true,
    signatureDataUrl: order.signature_data_url || "",
  });
  const [invoices, invoiceLines] = await Promise.all([getAll("invoices"), getAll("invoice_lines")]);
  const relatedInvoices = invoices
    .filter((invoice) => String(invoice.source_ref || "") === String(order.order_no || ""))
    .sort((a, b) => String(a.invoice_date || "").localeCompare(String(b.invoice_date || "")) || String(a.invoice_no || "").localeCompare(String(b.invoice_no || "")));
  relatedInvoices.forEach((invoice) => {
    invoice._lines = invoiceLines.filter((line) => line.invoice_id === invoice.id);
    invoice.customer_po ||= salesOrderInvoicePoReference(order);
    invoice.payment_mode ||= order.payment_mode || "PO";
  });
  if (relatedInvoices.length) {
    const packet = relatedInvoices.map(salesOrderLinkedInvoicePrintableSection).join("");
    html = html.replace("</body>", `<style>.linked-invoice-page{break-before:page;page-break-before:always;padding:18px 0}.linked-invoice-page h1{margin:0;color:#075f6d}.linked-invoice-meta{display:flex;justify-content:space-between;margin:12px 0 18px}.linked-invoice-page table{width:100%;border-collapse:collapse;table-layout:fixed}.linked-invoice-page th,.linked-invoice-page td{padding:5px 4px;border-bottom:1px solid #d8dee8;text-align:left;font-size:8pt;overflow-wrap:anywhere}.linked-invoice-page .num{text-align:right;white-space:nowrap}.linked-invoice-page .invoice-total{font-weight:900!important;font-size:12pt!important;color:#075f6d}.sales-invoice-lines th:nth-child(1),.sales-invoice-lines td:nth-child(1){width:12%}.sales-invoice-lines th:nth-child(2),.sales-invoice-lines td:nth-child(2){width:44%}.sales-invoice-lines th:nth-child(3),.sales-invoice-lines td:nth-child(3){width:5%}.sales-invoice-lines th:nth-child(4),.sales-invoice-lines td:nth-child(4),.sales-invoice-lines th:nth-child(5),.sales-invoice-lines td:nth-child(5),.sales-invoice-lines th:nth-child(6),.sales-invoice-lines td:nth-child(6){width:4%}.sales-invoice-lines th:nth-child(7),.sales-invoice-lines td:nth-child(7){width:12%}.sales-invoice-lines th:nth-child(8),.sales-invoice-lines td:nth-child(8){width:15%}.linked-invoice-page th{font-size:7pt!important;font-weight:800;line-height:1.05;text-transform:uppercase;background:#eef3f6}</style>${packet}</body>`);
  }
  openPrintWindow(html, order.order_no);
}

async function printSalesOrderInvoiceHistory(orderNo) {
  const historyWindow = openInAppDocumentWindow(`Invoice History - ${orderNo}`);
  if (historyWindow) {
    historyWindow.document.write("<!doctype html><title>Loading invoice history...</title><body style='font-family:Arial;padding:32px'>Loading all invoices for this Sales Order...</body>");
    historyWindow.document.close();
  }
  try {
    const [invoices, invoiceLines] = await Promise.all([getAll("invoices"), getAll("invoice_lines")]);
    const related = invoices
      .filter((invoice) => String(invoice.source_ref || "") === String(orderNo || ""))
      .sort((a, b) => String(a.invoice_date || "").localeCompare(String(b.invoice_date || "")) || String(a.invoice_no || "").localeCompare(String(b.invoice_no || "")));
    if (!related.length) {
      if (historyWindow && !historyWindow.closed) historyWindow.close();
      alert(`No invoices are linked to ${orderNo}.`);
      return;
    }
    const sourceOrder = currentRows.find((order) => String(order.order_no || "") === String(orderNo || ""));
    related.forEach((invoice) => {
      invoice._lines = invoiceLines.filter((line) => line.invoice_id === invoice.id);
      invoice.customer_po ||= salesOrderInvoicePoReference(sourceOrder || {});
      invoice.payment_mode ||= sourceOrder?.payment_mode || "PO";
    });
    openPrintWindow(combinedInvoicesHtml(related), `${orderNo}-invoice-history`, historyWindow);
  } catch (error) {
    if (historyWindow && !historyWindow.closed) historyWindow.close();
    alert(error.message || error);
  }
}

function salesOrderLinkedInvoicePrintableSection(invoice = {}) {
  const rows = (invoice._lines || []).map((line) => `<tr><td>${esc(line.sku || "")}</td><td>${esc(line.description || line.product_name || "")}</td><td>${esc(line.unit || "")}</td><td class="num">${esc(line.ordered_qty ?? line.qty ?? "")}</td><td class="num">${esc(line.issued_qty ?? line.qty ?? "")}</td><td class="num">${esc(line.shipped_qty ?? line.qty ?? "")}</td><td class="num">${money(line.rate)}</td><td class="num">${money(Number(line.qty || 0) * Number(line.rate || 0))}</td></tr>`).join("");
  return `<section class="linked-invoice-page"><div class="linked-invoice-meta"><div><h1>Customer Invoice</h1><strong>Sales Order ${esc(invoice.source_ref || "")}</strong></div><div><strong>${esc(invoice.invoice_no || "")}</strong><br>${esc(formatDisplayDate(invoice.invoice_date))}<br>${esc(invoiceDisplayStatus(invoice))}</div></div><div><strong>Customer:</strong> ${esc(invoice.customer || "")} &nbsp; <strong>${esc(paymentReferencePrintLabel(invoice.payment_mode))}:</strong> ${esc(invoice.customer_po || "")} &nbsp; <strong>Due:</strong> ${esc(formatDisplayDate(invoice.due_date))}</div><table class="sales-invoice-lines"><thead><tr><th>SKU</th><th>Item</th><th>UOM</th><th class="num">ORD</th><th class="num">ISS</th><th class="num">SHP</th><th class="num">Rate</th><th class="num">Amount</th></tr></thead><tbody>${rows}<tr><td colspan="7" class="num invoice-total">Invoice Total</td><td class="num invoice-total">${money(invoiceTotal(invoice))}</td></tr></tbody></table></section>`;
}

function exportSalesOrdersCsv() {
  const heads = ["Order", "Customer", "PO / Reference", "Payment Mode", "Pricing Rate", "Markup %", "Date", "Status", "ORD", "ISS", "SHP", "Freight", "Total", "Invoices"];
  const rows = [heads, ...currentRows.map((order) => { const q = salesOrderQuantitySummary(order); return [order.order_no, order.customer, order.customer_po || "", order.payment_mode || "PO", order.pricing_rate_name || "", order.pricing_markup_percent ?? "", order.order_date, salesOrderDisplayStatus(order), q.ordered, q.issued, q.shipped, Number(order.freight_amount || 0), salesOrderTotal(order), order.invoice_no || ""]; })];
  downloadCsv(rows, "sales-orders.csv");
}

function rentalBillingUnits(startDate, endDate, rateType = "Daily") {
  const start = new Date(startDate || today());
  const end = new Date(endDate || startDate || today());
  const days = Math.max(1, Math.ceil((end - start) / 86400000) + 1);
  if (/weekly/i.test(rateType)) return Math.max(1, Math.ceil(days / 7));
  if (/monthly/i.test(rateType)) return Math.max(1, Math.ceil(days / 30));
  if (/flat/i.test(rateType)) return 1;
  return days;
}

function rentalDateRangesOverlap(startA, endA, startB, endB) {
  const aStart = new Date(startA || today());
  const aEnd = new Date(endA || startA || today());
  const bStart = new Date(startB || today());
  const bEnd = new Date(endB || startB || today());
  return aStart <= bEnd && bStart <= aEnd;
}

async function conflictingEquipmentRental(itemRef, startDate, endDate, excludeRentalNo = "") {
  const rentals = await getAll("rentals");
  return rentals.find((row) => String(row.rental_no || "") !== String(excludeRentalNo || "")
    && String(row.item_ref || "").trim().toLowerCase() === String(itemRef || "").trim().toLowerCase()
    && !/returned|cancel|reversed|invoiced/i.test(row.status || "")
    && rentalDateRangesOverlap(startDate, endDate, row.start_date, row.end_date));
}

function equipmentRentalRateValue(rate = {}, rateType = "Daily", withOperator = false) {
  const period = /monthly/i.test(rateType) ? "monthly" : /weekly/i.test(rateType) ? "weekly" : "daily";
  return Number(rate[`${period}_${withOperator ? "with" : "without"}_operator`] || 0);
}

function nextEquipmentRentalBidNo(rows = []) {
  const largest = rows.reduce((max, row) => Math.max(max, Number(String(row.bid_no || "").match(/(\d+)$/)?.[1] || 0)), 1000);
  return `ERB-${largest + 1}`;
}

async function loadEquipmentRentalMeta() {
  const [customers, assets, products, rates] = await Promise.all([getAll("customers"), getAll("assets"), getAll("products"), getAll("equipment_rental_rates")]);
  productMeta.customerRows = customers;
  productMeta.customers = customers.map((row) => row.name).filter(Boolean).sort();
  productMeta.assets = assets;
  productMeta.products = products;
  productMeta.equipmentRentalRates = rates;
  return { customers, assets, products, rates };
}

function rentalRateItemType(row = {}) { return row.item_type || "Asset"; }
function rentalRateItemRef(row = {}) { return row.item_ref || row.asset_tag || ""; }
function rentalRateItemName(row = {}) { return row.item_name || row.equipment_name || ""; }
function rentalMasterItemRef(type, item = {}) { return type === "Product" ? item.sku : item.asset_tag; }
function rentalMasterItemName(item = {}) { return item.name || item.description || item.asset_tag || item.sku || ""; }
function matchingRentalRate(type, item = {}) {
  const ref = rentalMasterItemRef(type, item);
  return (productMeta.equipmentRentalRates || []).find((row) => rentalRateItemType(row) === type && String(rentalRateItemRef(row)).toLowerCase() === String(ref || "").toLowerCase());
}

