function printEquipmentRentalBid(bid) {
  if (!bid) return;
  const customer = (productMeta.customerRows || []).find((row) => normalizedMasterName(row.name || "") === normalizedMasterName(bid.customer || ""));
  openPrintWindow(printableDocumentHtml({
    title: "Rental Bid", number: bid.bid_no, date: bid.bid_date, partyLabel: "Customer", partyName: bid.customer, partyAddress: customer?.address || "",
    meta: [["Valid Until", bid.valid_until], ["Rental Period", `${formatDisplayDate(bid.start_date)} to ${formatDisplayDate(bid.end_date || bid.start_date)}`], ["Operator", bid.with_operator ? bid.operator_name || "Included" : "Without operator"], ["Status", bid.status]],
    heads: ["Category", "Item Ref", "Rentable Item", "Period", "Units", "Rate", "Amount"],
    lines: (bid.lines?.length ? bid.lines : [bid]).map((line) => [line.category || bid.rental_category || rentalRateItemType(line), rentalRateItemRef(line), rentalRateItemName(line), line.rate_type, line.billing_units, money(line.rate), money(line.amount)]), total: Number(bid.amount || 0), totalLabel: "Bid Total", notes: bid.notes || "",
  }), bid.bid_no);
}

const rentalBidCategories = ["Plant Rental", "Equipment Rental", "Tools & Small Equipment", "Container Rental", "Portable Toilet", "Landscape Materials", "Temporary Site Facilities", "Attachments & Accessories"];

function rentalBidCategoryDetails(category = "", details = {}) {
  const field = (label, name, value = "", type = "text") => `<label class="field"><span>${label}</span><input type="${type}" data-rental-detail="${esc(name)}" value="${esc(value ?? "")}"></label>`;
  if (category === "Plant Rental") return field("Plant type / species", "plant_type", details.plant_type) + field("Container / plant size", "plant_size", details.plant_size) + field("Quantity", "quantity", details.quantity || 1, "number") + field("Maintenance included", "maintenance", details.maintenance);
  if (category === "Equipment Rental") return field("Equipment class", "equipment_class", details.equipment_class) + field("Capacity / size", "capacity", details.capacity) + field("Delivery / mobilization", "mobilization", details.mobilization);
  if (category === "Tools & Small Equipment") return field("Tool class", "tool_class", details.tool_class) + field("Power / fuel type", "power_type", details.power_type) + field("Quantity", "quantity", details.quantity || 1, "number");
  if (category === "Container Rental") return field("Container type", "container_type", details.container_type) + field("Size (CY / feet)", "container_size", details.container_size) + field("Allowed material", "allowed_material", details.allowed_material) + field("Hauls / exchanges included", "included_hauls", details.included_hauls || 0, "number");
  if (category === "Portable Toilet") return field("Unit type", "unit_type", details.unit_type) + field("Number of units", "quantity", details.quantity || 1, "number") + field("Service frequency", "service_frequency", details.service_frequency) + field("Handwash station", "handwash_station", details.handwash_station);
  if (category === "Landscape Materials") return field("Material type", "material_type", details.material_type) + field("Quantity", "quantity", details.quantity || 1, "number") + field("Unit (CY, ton, pallet, each)", "unit", details.unit) + field("Delivery included", "delivery", details.delivery);
  if (category === "Temporary Site Facilities") return field("Facility type", "facility_type", details.facility_type) + field("Size / capacity", "capacity", details.capacity) + field("Setup / servicing", "servicing", details.servicing);
  return field("Attachment / accessory type", "accessory_type", details.accessory_type) + field("Compatible equipment", "compatible_equipment", details.compatible_equipment) + field("Quantity", "quantity", details.quantity || 1, "number");
}

function rentalBidLineHtml(line = {}, index = 0) {
  const category = line.category || "Equipment Rental";
  return `<div class="panel rental-bid-line" data-rental-bid-line data-line-no="${index + 1}"><div class="panel-head"><strong>Rental item ${index + 1}</strong><button type="button" class="danger" data-remove-rental-bid-line>Remove</button></div><div class="form-grid">
    ${productSelect("Category", "line_category", rentalBidCategories, category).replaceAll("data-product-field", "data-rental-line-field")}
    <label class="field"><span>Item type</span><select data-rental-line-field="item_type"><option value="Auto" ${!line.item_type || line.item_type === "Auto" ? "selected" : ""}>Auto-detect Asset or Product</option><option value="Asset" ${line.item_type === "Asset" ? "selected" : ""}>Fleet & Equipment</option><option value="Product" ${line.item_type === "Product" ? "selected" : ""}>Product Master</option></select></label>
    <label class="field"><span>Item search</span><input class="suggest-input" data-suggest-source="rental_items" data-rental-line-field="item_lookup" value="${esc(line.item_ref || line.item_lookup || "")}" placeholder="Type SKU, asset #, item name, vendor, make or model" autocomplete="off" inputmode="search"><small>Searches like SKU and displays matching master records.</small></label>
    ${productInput("Start date", "start_date", line.start_date || today(), "date").replaceAll("data-product-field", "data-rental-line-field")}${productInput("End date", "end_date", line.end_date || line.start_date || today(), "date").replaceAll("data-product-field", "data-rental-line-field")}
    ${productSelect("Rate type", "rate_type", ["Daily", "Weekly", "Monthly"], line.rate_type || "Daily").replaceAll("data-product-field", "data-rental-line-field")}${productSelect("Operator option", "operator_option", ["Without Operator", "With Operator"], line.with_operator ? "With Operator" : "Without Operator").replaceAll("data-product-field", "data-rental-line-field")}
    ${productInput("Operator name", "operator_name", line.operator_name || "").replaceAll("data-product-field", "data-rental-line-field")}${productInput("Rate", "rate", line.rate ?? 0, "number").replaceAll("data-product-field", "data-rental-line-field")}${productInput("Billing units", "billing_units", line.billing_units ?? 1, "number").replaceAll("data-product-field", "data-rental-line-field")}${productInput("Amount", "amount", line.amount ?? 0, "number").replaceAll("data-product-field", "data-rental-line-field")}${productInput("Deposit", "deposit", line.deposit ?? 0, "number").replaceAll("data-product-field", "data-rental-line-field")}
    <div class="field wide rental-category-section"><span class="rental-category-title">${esc(category)} details</span><div class="form-grid rental-category-details">${rentalBidCategoryDetails(category, line.details || {})}</div></div>
    <label class="field wide"><span>Line notes</span><textarea data-rental-line-field="notes">${esc(line.notes || "")}</textarea></label>
  </div></div>`;
}

function resolveAnyRentalItem(type, value) {
  if (type === "Asset" || type === "Product") return { type, item: resolveRentalItem(type, value) };
  const asset = resolveRentalItem("Asset", value); if (asset) return { type: "Asset", item: asset };
  const product = resolveRentalItem("Product", value); return product ? { type: "Product", item: product } : { type: "", item: null };
}

async function openEquipmentRentalBidModal(bid = null) {
  editing = bid;
  let lines = bid ? await getAll("equipment_rental_bid_lines").then((rows) => rows.filter((row) => row.bid_no === bid.bid_no).sort((a, b) => a.line_no - b.line_no)).catch(() => []) : [];
  if (!lines.length && bid) lines = [{ ...bid, category: bid.rental_category || "Equipment Rental" }];
  if (!lines.length) lines = [{}];
  $("modalTitle").textContent = bid ? `Edit rental bid ${bid.bid_no}` : "New rental bid";
  $("modalBody").innerHTML = `<div class="form-grid rental-bid-header">${productInput("Bid #", "bid_no", bid?.bid_no || nextEquipmentRentalBidNo(currentRows))}${productInput("Bid date", "bid_date", bid?.bid_date || today(), "date")}${productInput("Valid until", "valid_until", bid?.valid_until || "", "date")}<label class="field"><span>Customer</span><input class="suggest-input" data-suggest-source="customers" data-product-field="customer" value="${esc(bid?.customer || "")}" placeholder="Search Customer Master" autocomplete="off" required></label>${productSelect("Bid category", "rental_category", ["Mixed", ...rentalBidCategories], bid?.rental_category || (lines.length > 1 ? "Mixed" : lines[0]?.category || "Equipment Rental"))}${productSelect("Status", "status", ["Draft", "Sent", "Accepted", "Rejected", "Expired"], bid?.status || "Draft")}<div class="field wide"><label>Notes / inclusions / exclusions</label><textarea data-product-field="notes">${esc(bid?.notes || "")}</textarea></div></div><div id="rentalBidLines">${lines.map(rentalBidLineHtml).join("")}</div><div class="toolbar"><button type="button" id="addRentalBidLineBtn">Add rental item</button><strong id="rentalBidGrandTotal"></strong></div><p class="notice">Choose a bid category to apply its required details to every line. Select Mixed only when individual lines use different categories. Items must come from Fleet & Equipment or Product Master.</p>`;
  const bind = () => bindRentalBidLines();
  $("addRentalBidLineBtn").onclick = () => {
    const host = $("rentalBidLines");
    const selectedCategory = document.querySelector('[data-product-field="rental_category"]')?.value || "Equipment Rental";
    host.insertAdjacentHTML("beforeend", rentalBidLineHtml({ category: selectedCategory === "Mixed" ? "Equipment Rental" : selectedCategory }, host.querySelectorAll("[data-rental-bid-line]").length));
    bind();
  };
  const bidCategory = document.querySelector('[data-product-field="rental_category"]');
  bidCategory.onchange = () => {
    if (bidCategory.value === "Mixed") return;
    document.querySelectorAll('[data-rental-line-field="line_category"]').forEach((select) => {
      select.value = bidCategory.value;
      select.dispatchEvent(new Event("change", { bubbles: true }));
    });
  };
  bind();
  $("modalSave").onclick = saveEquipmentRentalBid;
  $("modal").style.display = "flex";
  enhanceSuggestInputs($("modalBody"));
}

function bindRentalBidLines() {
  const rows = [...$("rentalBidLines").querySelectorAll("[data-rental-bid-line]")];
  rows.forEach((row, index) => {
    row.dataset.lineNo = index + 1; row.querySelector(".panel-head strong").textContent = `Rental item ${index + 1}`;
    row.querySelector("[data-remove-rental-bid-line]").onclick = () => { if (rows.length === 1) return alert("A bid must contain at least one rental item."); row.remove(); bindRentalBidLines(); };
    const recalc = () => recalculateRentalBidLine(row);
    row.querySelectorAll("[data-rental-line-field]").forEach((input) => { input.oninput = recalc; input.onchange = recalc; });
    row.querySelector('[data-rental-line-field="line_category"]').onchange = (event) => {
      const category = event.target.value;
      row.querySelector(".rental-category-details").innerHTML = rentalBidCategoryDetails(category, {});
      const title = row.querySelector(".rental-category-title"); if (title) title.textContent = `${category} details`;
      const typeField = row.querySelector('[data-rental-line-field="item_type"]');
      if (typeField && ["Plant Rental", "Landscape Materials", "Attachments & Accessories"].includes(category)) typeField.value = "Product";
      else if (typeField && ["Equipment Rental", "Container Rental", "Portable Toilet", "Temporary Site Facilities"].includes(category)) typeField.value = "Asset";
      const categories = [...document.querySelectorAll('[data-rental-line-field="line_category"]')].map((select) => select.value);
      const headerCategory = document.querySelector('[data-product-field="rental_category"]');
      if (headerCategory) headerCategory.value = categories.every((value) => value === categories[0]) ? categories[0] : "Mixed";
      recalc();
    };
  });
  recalculateRentalBidTotals();
  enhanceSuggestInputs($("rentalBidLines"));
}

function recalculateRentalBidLine(row) {
  const field = (name) => row.querySelector(`[data-rental-line-field="${name}"]`);
  const resolved = resolveAnyRentalItem(field("item_type")?.value || "Auto", field("item_lookup")?.value || "");
  const rateCard = resolved.item ? matchingRentalRate(resolved.type, resolved.item) : null;
  const rateType = field("rate_type")?.value || "Daily";
  const units = rentalBillingUnits(field("start_date")?.value, field("end_date")?.value, rateType);
  const rate = equipmentRentalRateValue(rateCard, rateType, /with operator/i.test(field("operator_option")?.value || ""));
  if (field("billing_units")) field("billing_units").value = units;
  if (field("rate") && rateCard) field("rate").value = rate;
  if (field("amount")) field("amount").value = Number((units * Number(field("rate")?.value || rate)).toFixed(2));
  recalculateRentalBidTotals();
}

function recalculateRentalBidTotals() {
  const total = [...document.querySelectorAll('[data-rental-bid-line] [data-rental-line-field="amount"]')].reduce((sum, input) => sum + Number(input.value || 0), 0);
  if ($("rentalBidGrandTotal")) $("rentalBidGrandTotal").textContent = `Bid total: ${money(total)}`;
}

function recalculateEquipmentRentalBidForm() {
  const field = (name) => document.querySelector(`[data-product-field="${name}"]`);
  const type = field("item_type")?.value || "Asset";
  const item = resolveRentalItem(type, field("item_lookup")?.value || "");
  const rateCard = matchingRentalRate(type, item);
  const rateType = field("rate_type")?.value || "Daily";
  const withOperator = /with operator/i.test(field("operator_option")?.value || "");
  const units = rentalBillingUnits(field("start_date")?.value, field("end_date")?.value, rateType);
  const rate = equipmentRentalRateValue(rateCard, rateType, withOperator);
  if (field("billing_units")) field("billing_units").value = units;
  if (field("rate") && rateCard) field("rate").value = rate;
  if (field("amount")) field("amount").value = Number((units * Number(field("rate")?.value || rate)).toFixed(2));
}

async function saveEquipmentRentalBid() {
  const record = {};
  document.querySelectorAll("[data-product-field]").forEach((el) => record[el.dataset.productField] = el.value || null);
  const customer = await requirePartyMasterSelection("customers", record.customer, "a customer"); if (!customer) return;
  const lineRows = [...document.querySelectorAll("[data-rental-bid-line]")];
  const lines = [];
  for (let index = 0; index < lineRows.length; index += 1) {
    const row = lineRows[index]; const value = (name) => row.querySelector(`[data-rental-line-field="${name}"]`)?.value || "";
    const resolved = resolveAnyRentalItem(value("item_type") || "Auto", value("item_lookup"));
    if (!resolved.item) return alert(`Rental item ${index + 1}: select a valid Fleet & Equipment or Product Master item.`);
    const details = Object.fromEntries([...row.querySelectorAll("[data-rental-detail]")].map((input) => [input.dataset.rentalDetail, input.value]));
    const line = { bid_no: record.bid_no, line_no: index + 1, category: value("line_category") || "Equipment Rental", item_type: resolved.type, item_id: resolved.item.id, item_ref: rentalMasterItemRef(resolved.type, resolved.item), item_name: rentalMasterItemName(resolved.item), start_date: value("start_date"), end_date: value("end_date") || value("start_date"), rate_type: value("rate_type") || "Daily", with_operator: /with operator/i.test(value("operator_option")), operator_name: value("operator_name") || null, rate: Number(value("rate") || 0), billing_units: rentalBillingUnits(value("start_date"), value("end_date"), value("rate_type")), amount: 0, deposit: Number(value("deposit") || 0), details, notes: value("notes") || null };
    line.amount = Number((line.rate * line.billing_units).toFixed(2));
    if (!line.start_date) return alert(`Rental item ${index + 1}: Start date is required.`);
    const conflict = await conflictingEquipmentRental(line.item_ref, line.start_date, line.end_date);
    if (conflict && !confirm(`${line.item_ref} is already reserved or out under ${conflict.rental_no} for an overlapping period.\n\nKeep this item in the bid anyway?`)) return;
    lines.push(line);
  }
  if (!record.bid_no || !lines.length) return alert("Bid #, customer, and at least one rentable item are required.");
  const first = lines[0]; record.customer = customer.name; record.item_type = first.item_type; record.item_id = first.item_id; record.item_ref = first.item_ref; record.item_name = first.item_name; record.asset_id = first.item_type === "Asset" ? first.item_id : null; record.asset_tag = first.item_ref; record.equipment_name = first.item_name; record.start_date = first.start_date; record.end_date = first.end_date; record.rate_type = first.rate_type; record.rate = first.rate; record.billing_units = first.billing_units; record.with_operator = first.with_operator; record.operator_name = first.operator_name; record.deposit = lines.reduce((sum, line) => sum + line.deposit, 0); record.amount = lines.reduce((sum, line) => sum + line.amount, 0); if (lines.length > 1) record.rental_category = "Mixed";
  try {
    await upsertOne("equipment_rental_bids", record, "bid_no");
    const { error: deleteError } = await supabase.from("equipment_rental_bid_lines").delete().eq("bid_no", record.bid_no); if (deleteError) throw deleteError;
    const { error: lineError } = await supabase.from("equipment_rental_bid_lines").insert(lines); if (lineError) throw lineError;
    closeModal(); await renderEquipmentRentalBidsView();
  } catch (error) { alert(error.message || error); }
}

async function convertEquipmentRentalBid(bidNo) {
  const bid = currentRows.find((row) => row.bid_no === bidNo); if (!bid) return;
  if (!confirm(`Convert ${bid.bid_no} into a rental contract?`)) return;
  try {
    const rentalNo = await nextRefPreview("rental", "R-", "rentals", "rental_no");
    await upsertOneWithOptionalColumns("rentals", { rental_no: rentalNo, bid_no: bid.bid_no, customer: bid.customer, customer_po: bid.customer_po || null, manager_override: false, item_type: rentalRateItemType(bid), item_id: bid.item_id || bid.asset_id, item_ref: rentalRateItemRef(bid), start_date: bid.start_date, end_date: bid.end_date, invoice_timing: "At return", rate_type: bid.rate_type, rate: Number(bid.rate || 0), deposit: Number(bid.deposit || 0), with_operator: Boolean(bid.with_operator), operator_name: bid.operator_name || null, status: "Reserved", notes: bid.notes || null }, "rental_no", ["bid_no", "with_operator", "operator_name"], "Rental created. Run the Rental Operations SQL update to store its bid and operator fields.");
    await incrementSequence("rental");
    await supabase.from("equipment_rental_bids").update({ status: "Converted", rental_no: rentalNo }).eq("id", bid.id);
    alert(`${bid.bid_no} was converted to rental ${rentalNo}.`); await renderEquipmentRentalBidsView();
  } catch (error) { alert(error.message || error); }
}

async function renderRentalsView() {
  currentCfg = tableMap.rentals;
  $("viewTitle").textContent = "Rentals";
  $("viewSub").textContent = "Track rented vehicles, equipment, inventory items, dates, deposits, returns, and billing.";
  const [rentals, customers, assets, products, rentalRates] = await Promise.all([getAll("rentals"), getAll("customers"), getAll("assets"), getAll("products"), getAll("equipment_rental_rates").catch(() => [])]);
  productMeta.customers = customers.map((c) => c.name).filter(Boolean).sort();
  productMeta.customerRows = customers;
  productMeta.assets = assets;
  productMeta.products = products;
  productMeta.equipmentRentalRates = rentalRates;
  currentRows = rentals.sort((a, b) => String(b.start_date || "").localeCompare(String(a.start_date || "")));
  $("content").innerHTML = `
    <div class="toolbar"><input class="searchbox" id="rentalSearch" placeholder="Search rentals by rental number, customer, item, date, status"></div>
    <div class="stats">
      ${statCard("Rental Records", currentRows.length, "All rental activity")}
      ${statCard("Currently Out", currentRows.filter((r) => /out|reserved/i.test(r.status || "")).length, "Open or reserved")}
      ${statCard("Rental Revenue", money(currentRows.reduce((s, r) => s + rentalTotal(r), 0)), "All logged rentals")}
      ${statCard("Deposits", money(currentRows.reduce((s, r) => s + Number(r.deposit || 0), 0)), "Deposit exposure")}
    </div>
    <section class="panel">
      <div class="panel-head"><div class="panel-title"><strong>Rentals</strong><span>Check out assets or inventory items, track returns, deposits, and rental income</span></div><div class="actions"><button id="rentalCsvBtn">Excel</button><button onclick="window.print()">PDF / Print</button><button class="primary" id="newRentalBtn">New rental</button></div></div>
      <div id="rentalTableHost">${rentalTableHtml(currentRows)}</div>
    </section>`;
  $("rentalSearch").oninput = renderFilteredRentals;
  $("rentalCsvBtn").onclick = exportRentalsCsv;
  $("newRentalBtn").onclick = () => openRentalModal();
  bindRentalRows();
}

function statCard(label, value, note) {
  return stat(label, value, note);
}

function renderFilteredRentals() {
  const q = $("rentalSearch").value.toLowerCase();
  const rows = currentRows.filter((r) => !q || [Object.values(r).join(" "), rentalItemName(r)].join(" ").toLowerCase().includes(q));
  $("rentalTableHost").innerHTML = rentalTableHtml(rows);
  bindRentalRows();
}

function rentalTableHtml(rows) {
  const heads = ["Rental", "Bid", "Customer", "Customer PO", "Item", "Start", "End", "Rate", "Operator", "Deposit", "Status", "Total", "Invoice", ""];
  return `<div class="table-wrap"><table><thead><tr>${heads.map((h) => `<th>${esc(h)}</th>`).join("")}</tr><tr>${heads.map((h, i) => h ? `<th><input class="column-filter" data-col="${i}" placeholder="Filter ${esc(h)}"></th>` : "<th></th>").join("")}</tr></thead><tbody>${rows.length ? rows.map(rentalRowHtml).join("") : `<tr><td colspan="${heads.length}" class="empty">No rentals yet.</td></tr>`}</tbody></table></div>`;
}

function rentalRowHtml(r) {
  return `<tr>
    <td>${esc(r.rental_no)}</td>
    <td>${esc(r.bid_no || "")}</td>
    <td>${esc(r.customer || "")}</td>
    <td>${r.customer_po ? badge(r.customer_po) : r.manager_override ? badge(`Override: ${r.override_by || "Manager"}`) : badge("PO Required")}</td>
    <td>${esc(rentalItemName(r))}</td>
    <td>${esc(formatDisplayDate(r.start_date))}</td>
    <td>${esc(formatDisplayDate(r.end_date))}</td>
    <td>${money(r.rate)} / ${esc(r.rate_type || "")}</td>
    <td>${r.with_operator ? esc(r.operator_name || "Included") : "Without operator"}</td>
    <td>${money(r.deposit)}</td>
    <td>${badge(r.status || "Reserved")}</td>
    <td>${money(rentalTotal(r))}</td>
    <td>${esc(r.invoice_no || "")}</td>
    <td><div class="rowactions"><button class="rowbtn" type="button" data-rental-invoice="${esc(r.rental_no)}">Inv</button><button class="rowbtn" type="button" data-rental-return="${esc(r.rental_no)}">Return</button><button class="rowbtn" type="button" data-rental-edit="${esc(r.rental_no)}">Edit</button><button class="rowbtn danger" type="button" data-rental-reverse="${esc(r.rental_no)}">Reverse</button></div></td>
  </tr>`;
}

function rentalItemName(r) {
  if (r.item_type === "Product") {
    const p = (productMeta.products || []).find((item) => item.id === r.item_id || item.sku === r.item_ref);
    return p ? `${p.sku} - ${p.name}` : r.item_ref || "";
  }
  const a = (productMeta.assets || []).find((item) => item.id === r.item_id || item.asset_tag === r.item_ref);
  return a ? `${a.asset_tag} - ${a.name}` : r.item_ref || "";
}

function rentalDays(r) {
  const start = new Date(r.start_date || today());
  const end = new Date(r.end_date || today());
  const diff = Math.ceil((end - start) / 86400000) + 1;
  return Math.max(1, Number.isFinite(diff) ? diff : 1);
}

function rentalTotal(r) {
  return rentalBillingUnits(r.start_date, r.end_date, r.rate_type) * Number(r.rate || 0);
}

function bindRentalRows() {
  document.querySelectorAll("[data-rental-edit]").forEach((b) => b.onclick = () => openRentalModal(currentRows.find((r) => r.rental_no === b.dataset.rentalEdit)));
  document.querySelectorAll("[data-rental-reverse]").forEach((b) => b.onclick = () => reverseRental(b.dataset.rentalReverse));
  document.querySelectorAll("[data-rental-return]").forEach((b) => b.onclick = () => returnRental(b.dataset.rentalReturn));
  document.querySelectorAll("[data-rental-invoice]").forEach((b) => b.onclick = () => invoiceRental(b.dataset.rentalInvoice));
  document.querySelectorAll(".column-filter").forEach((input) => input.oninput = applyColumnFilters);
}

async function openRentalModal(rental = null) {
  editing = rental;
  const rentalNo = rental?.rental_no || await nextRefPreview("rental", "R-", "rentals", "rental_no");
  $("modalTitle").textContent = rental ? `Edit rental ${rental.rental_no}` : "New rental";
  $("modalBody").innerHTML = `
    <div class="form-grid">
      ${productInput("Rental #", "rental_no", rentalNo)}
      ${productSelect("Customer", "customer", productMeta.customers || [], rental?.customer || "", "New customer")}
      ${productInput("Customer PO #", "customer_po", rental?.customer_po || "")}
      ${productSelect("Manager override", "manager_override", ["No", "Yes"], rental?.manager_override ? "Yes" : "No")}
      ${productInput("Override by", "override_by", rental?.override_by || "")}
      ${productSelect("Item type", "item_type", ["Asset", "Product"], rental?.item_type || "Asset")}
      ${rentalItemLookupField(rental)}
      ${productInput("Start date", "start_date", rental?.start_date || today(), "date")}
      ${productInput("End date", "end_date", rental?.end_date || "", "date")}
      ${productSelect("Invoice timing", "invoice_timing", ["At start", "At return", "Manual"], rental?.invoice_timing || "At start")}
      ${productSelect("Rate type", "rate_type", ["Daily", "Weekly", "Monthly", "Flat"], rental?.rate_type || "Daily")}
      ${productSelect("Operator option", "operator_option", ["Without Operator", "With Operator"], rental?.with_operator ? "With Operator" : "Without Operator")}
      ${productInput("Operator name (optional)", "operator_name", rental?.operator_name || "")}
      ${productInput("Rate", "rate", rental?.rate ?? 0, "number")}
      ${productInput("Deposit", "deposit", rental?.deposit ?? 0, "number")}
      ${productSelect("Status", "status", ["Reserved", "Out", "Returned", "Invoiced", "Cancelled"], rental?.status || "Reserved")}
      ${productInput("Checkout reading", "checkout_reading", rental?.checkout_reading || "")}
      ${productInput("Return reading", "return_reading", rental?.return_reading || "")}
      ${productInput("Invoice #", "invoice_no", rental?.invoice_no || "")}
      <div class="field wide"><label>Override reason</label><textarea data-product-field="override_reason">${esc(rental?.override_reason || "")}</textarea></div>
      <div class="field wide"><label>Notes</label><textarea data-product-field="notes">${esc(rental?.notes || "")}</textarea></div>
    </div>
    <p class="notice">Customer PO # is required for rentals unless a manager override is completed with override by and reason.</p>`;
  $("modalSave").onclick = saveRentalModal;
  $("modal").style.display = "flex";
  const recalcRate = () => recalculateRentalContractRate();
  $("modalBody").querySelectorAll('[data-product-field="item_lookup"],[data-product-field="rate_type"],[data-product-field="operator_option"]').forEach((input) => { input.addEventListener("input", recalcRate); input.addEventListener("change", recalcRate); });
  document.querySelectorAll("[data-product-quick]").forEach((b) => b.onclick = () => quickCreateCustomerInOpenModal());
}

function recalculateRentalContractRate() {
  const field = (name) => document.querySelector(`[data-product-field="${name}"]`);
  const type = field("item_type")?.value || "Asset";
  const item = resolveRentalItem(type, field("item_lookup")?.value || "");
  const rateCard = matchingRentalRate(type, item);
  if (!rateCard || !field("rate")) return;
  field("rate").value = equipmentRentalRateValue(rateCard, field("rate_type")?.value || "Daily", /with operator/i.test(field("operator_option")?.value || ""));
}

function rentalItemLookupField(rental = null) {
  const options = [
    ...(productMeta.assets || []).map((a) => `${a.asset_tag} - ${a.name} | ${a.make || ""} ${a.model || ""}`.trim()),
    ...(productMeta.products || []).map((p) => `${p.sku} - ${p.name} | on hand ${p.qty || 0}`),
  ];
  const value = rental?.item_ref || rentalItemName(rental || {});
  return `<div class="field"><label>Item search</label><input class="suggest-input" list="rentalItemOptions" data-product-field="item_lookup" value="${esc(value || "")}" placeholder="Search asset tag, product SKU, name" autocomplete="off"><datalist id="rentalItemOptions">${options.map((o) => `<option value="${esc(o)}"></option>`).join("")}</datalist></div>`;
}

function resolveRentalItem(type, value) {
  const q = String(value || "").toLowerCase();
  const matches = (candidate) => candidate && q.includes(String(candidate).toLowerCase());
  if (type === "Product") return (productMeta.products || []).find((p) => matches(p.sku) || matches(p.name) || matches(p.description));
  return (productMeta.assets || []).find((a) => matches(a.asset_tag) || matches(a.name) || matches(a.description));
}

async function saveRentalModal() {
  const record = {};
  document.querySelectorAll("[data-product-field]").forEach((el) => record[el.dataset.productField] = el.value || null);
  const item = resolveRentalItem(record.item_type || "Asset", record.item_lookup || "");
  record.manager_override = String(record.manager_override || "").toLowerCase() === "yes";
  record.with_operator = /with operator/i.test(record.operator_option || "");
  delete record.operator_option;
  record.item_id = item?.id || null;
  record.item_ref = record.item_type === "Product" ? item?.sku || record.item_lookup : item?.asset_tag || record.item_lookup;
  delete record.item_lookup;
  const selectedCustomerMaster = await requirePartyMasterSelection("customers", record.customer, "a customer");
  if (!selectedCustomerMaster) return;
  record.customer = selectedCustomerMaster.name;
  ["rate", "deposit"].forEach((k) => record[k] = Number(record[k] || 0));
  if (!record.rental_no || !record.customer || !record.item_type || !record.item_ref || !record.start_date) {
    alert("Rental #, customer, item type, item, and start date are required.");
    return;
  }
  if (!record.customer_po && !(record.manager_override && record.override_by && record.override_reason)) {
    alert("Customer PO # is required for rentals unless manager override, override by, and override reason are completed.");
    return;
  }
  if (record.item_type === "Asset") {
    const conflict = await conflictingEquipmentRental(record.item_ref, record.start_date, record.end_date, record.rental_no);
    if (conflict) return alert(`${record.item_ref} is not available for this period.\n\nIt is already reserved or out under ${conflict.rental_no} from ${formatDisplayDate(conflict.start_date)} to ${formatDisplayDate(conflict.end_date)}.`);
  }
  try {
    const wasNew = !editing;
    await upsertOneWithOptionalColumns("rentals", record, "rental_no", ["bid_no", "with_operator", "operator_name"], "Rental saved. Run the Equipment Rental Operations SQL update to store bid and operator details.");
    if (wasNew) await incrementSequence("rental");
    closeModal();
    renderRentalsView();
  } catch (error) {
    alert(error.message || error);
  }
}

async function returnRental(rentalNo) {
  const rental = currentRows.find((r) => r.rental_no === rentalNo);
  if (!rental) return;
  const reading = prompt("Return reading / condition", rental.return_reading || "");
  if (reading === null) return;
  const { error } = await supabase.from("rentals").update({ end_date: rental.end_date || today(), return_reading: reading, status: "Returned" }).eq("id", rental.id);
  if (error) alert(error.message);
  renderRentalsView();
}

async function invoiceRental(rentalNo) {
  const rental = currentRows.find((r) => r.rental_no === rentalNo);
  if (!rental) return;
  if (rental.invoice_no) {
    alert(`Already invoiced as ${rental.invoice_no}.`);
    return;
  }
  try {
    const invoiceNo = await createCustomerInvoice({
      customer: rental.customer,
      type: "Rental",
      source_ref: rental.rental_no,
      invoice_date: rental.start_date || today(),
      due_date: rental.end_date || rental.start_date || today(),
      notes: `Deposit: ${money(rental.deposit)}. ${rental.notes || ""}`.trim(),
      lines: [{ description: `${rentalItemName(rental)} rental (${rental.rate_type}; ${rental.with_operator ? `with operator${rental.operator_name ? ` - ${rental.operator_name}` : ""}` : "without operator"})`, unit: rental.rate_type || "Rental", qty: rentalBillingUnits(rental.start_date, rental.end_date, rental.rate_type), rate: Number(rental.rate || 0) }],
    });
    await supabase.from("rentals").update({ invoice_no: invoiceNo, status: "Invoiced" }).eq("id", rental.id);
    alert(`Invoice ${invoiceNo} created.`);
    renderRentalsView();
  } catch (error) {
    alert(error.message || error);
  }
}

function exportRentalsCsv() {
  const heads = ["Rental", "Bid", "Customer", "Customer PO", "Override", "Override By", "Item Type", "Item", "Start", "End", "Invoice Timing", "Rate Type", "Rate", "With Operator", "Operator", "Deposit", "Status", "Invoice", "Billing Units", "Total"];
  downloadCsv([heads, ...currentRows.map((r) => [r.rental_no, r.bid_no, r.customer, r.customer_po, r.manager_override ? "Yes" : "No", r.override_by, r.item_type, rentalItemName(r), r.start_date, r.end_date, r.invoice_timing, r.rate_type, r.rate, r.with_operator ? "Yes" : "No", r.operator_name, r.deposit, r.status, r.invoice_no, rentalBillingUnits(r.start_date, r.end_date, r.rate_type), rentalTotal(r)])], "rentals.csv");
}

async function renderRepairsView() {
  currentCfg = tableMap.repairs;
  $("viewTitle").textContent = "Repairs";
  $("viewSub").textContent = "Work orders, mechanic time, issue details, parts, labor, and billing.";
  const [workOrders, issues, parts, labor, assets, outsideFleet, mechanics, customers, products, stockMovements, purchaseOrders, purchaseOrderLines] = await Promise.all([
    getAll("work_orders"),
    getAll("work_order_issues"),
    getAll("work_order_parts"),
    getAll("work_order_labor"),
    getAll("assets"),
    getAll("outside_customer_fleet").catch(() => []),
    getAll("mechanics"),
    getAll("customers"),
    getAll("products"),
    getAll("stock_movements"),
    getAll("purchase_orders").catch(() => []),
    getAll("purchase_order_lines").catch(() => []),
  ]);
  productMeta.assets = assets;
  productMeta.outsideFleet = outsideFleet;
  productMeta.mechanicsRows = mechanics;
  productMeta.mechanics = mechanics.map((m) => m.name).filter(Boolean).sort();
  productMeta.customers = customers.map((c) => c.name).filter(Boolean).sort();
  productMeta.products = products.sort((a, b) => String(a.sku || "").localeCompare(String(b.sku || "")));
  currentRows = workOrders.sort((a, b) => String(b.wo_date || "").localeCompare(String(a.wo_date || "")));
  currentRows.forEach((wo) => {
    wo._issues = issues.filter((row) => row.wo_id === wo.id);
    wo._parts = parts.filter((row) => row.wo_id === wo.id);
    wo._labor = labor.filter((row) => row.wo_id === wo.id);
    wo._stockMovements = stockMovements.filter((row) => row.document_no === wo.wo_no);
    const linkedPoLines = purchaseOrderLines.filter((line) => String(line.wo_no || "").trim().toLowerCase() === String(wo.wo_no || "").trim().toLowerCase());
    wo._parts.forEach((part) => {
      const partSku = String(part.sku || "").trim().toLowerCase();
      const refs = linkedPoLines
        .filter((line) => (part.product_id && String(line.product_id || "") === String(part.product_id))
          || (partSku && String(line.sku || "").trim().toLowerCase() === partSku))
        .map((line) => purchaseOrders.find((po) => String(po.id || "") === String(line.po_id || ""))?.po_no || line.po_no)
        .filter(Boolean);
      part._linked_po_numbers = [...new Set(refs)];
    });
  });
  const completedWaitingParts = currentRows.filter((wo) => /waiting parts/i.test(wo.status || "") && !pendingWorkOrderParts(wo).length);
  if (completedWaitingParts.length) {
    await Promise.all(completedWaitingParts.map(async (wo) => {
      const { error } = await supabase.from("work_orders").update({ status: "In Progress" }).eq("id", wo.id);
      if (error) throw error;
      wo.status = "In Progress";
    }));
  }
  if (isMechanicUser()) return renderMechanicRepairPortal();
  const openRows = repairRowsByTab("open");
  $("content").innerHTML = `
    <div class="stats">
      ${statCard("Open WO", openRows.length, "Still active")}
      ${statCard("Ready to Close", repairRowsByTab("ready").length, "Mechanic flagged")}
      ${statCard("Closed Not Invoiced", repairRowsByTab("closed").length, "Ready for billing")}
      ${statCard("Invoiced WO", repairRowsByTab("invoiced").length, "Locked unless reversed")}
      ${statCard("Voided WO", repairRowsByTab("void").length, "Kept for audit trail")}
    </div>
    <div class="toolbar"><input class="searchbox" id="repairSearch" placeholder="Search repairs by WO, asset, mechanic, customer PO, status, issue"></div>
    <section class="panel">
      <div class="panel-head"><div class="panel-title"><strong>Repair & Service History</strong><span>Work orders with mechanic time, inventory parts, labor, and next service</span></div><div class="actions"><button id="repairEmailSelectedBtn">Email Selected PDFs</button><button id="mechanicClosingReportBtn">Mechanic Closing Report</button><button id="repairCsvBtn">Excel</button><button onclick="window.print()">PDF / Print</button><button class="primary" id="newWoBtn">New work order</button></div></div>
      <div class="tabbar"><button class="tabbtn active" data-repair-tab="open">Open WO ${openRows.length}</button><button class="tabbtn" data-repair-tab="ready">Ready to Close ${repairRowsByTab("ready").length}</button><button class="tabbtn" data-repair-tab="closed">Closed Not Invoiced ${repairRowsByTab("closed").length}</button><button class="tabbtn" data-repair-tab="invoiced">Invoiced WO ${repairRowsByTab("invoiced").length}</button><button class="tabbtn" data-repair-tab="void">Voided WO ${repairRowsByTab("void").length}</button></div>
      <div id="repairTableHost">${repairTableHtml(openRows)}</div>
    </section>`;
  $("repairSearch").oninput = renderFilteredRepairs;
  $("repairCsvBtn").onclick = exportCurrentCsv;
  $("mechanicClosingReportBtn").onclick = openMechanicClosingReport;
  $("repairEmailSelectedBtn").onclick = emailSelectedRepairPdfs;
  $("newWoBtn").onclick = () => openNewWorkOrderModal();
  document.querySelectorAll("[data-repair-tab]").forEach((b) => b.onclick = () => {
    document.querySelectorAll("[data-repair-tab]").forEach((x) => x.classList.toggle("active", x === b));
    $("repairTableHost").dataset.tab = b.dataset.repairTab;
    renderFilteredRepairs();
  });
  $("repairTableHost").dataset.tab = "open";
  bindRepairRows();
}

function repairRowsByTab(tab) {
  if (tab === "void") return currentRows.filter((wo) => /void|cancel/i.test(wo.status || ""));
  if (tab === "invoiced") return currentRows.filter((wo) => wo.invoice_no || /invoiced/i.test(wo.status || ""));
  if (tab === "ready") return currentRows.filter((wo) => !wo.invoice_no && /ready to close/i.test(wo.status || ""));
  if (tab === "closed") return currentRows.filter((wo) => !wo.invoice_no && !/void|cancel/i.test(wo.status || "") && /closed|complete/i.test(wo.status || ""));
  return currentRows.filter((wo) => !wo.invoice_no && !/ready to close|closed|complete|invoiced|void|cancel/i.test(wo.status || ""));
}

function renderFilteredRepairs() {
  const previousWrap = $("repairTableHost")?.querySelector(".table-wrap");
  const previousView = previousWrap ? collectCurrentTableView(previousWrap) : null;
  const tab = $("repairTableHost")?.dataset.tab || "open";
  const q = ($("repairSearch")?.value || "").toLowerCase();
  const rows = repairRowsByTab(tab).filter((wo) => !q || [
    Object.values(wo).join(" "),
    (wo._issues || []).map((i) => `${i.issue} ${i.assigned_mechanic} ${i.work_notes}`).join(" "),
    (wo._parts || []).map((p) => `${p.sku} ${p.product_name}`).join(" "),
    (wo._labor || []).map((l) => `${l.mechanic} ${l.issue} ${l.work_done}`).join(" "),
  ].join(" ").toLowerCase().includes(q));
  $("repairTableHost").innerHTML = repairTableHtml(rows);
  bindRepairRows();
  const nextWrap = $("repairTableHost")?.querySelector(".table-wrap");
  if (previousView && nextWrap) restoreTableViewState(nextWrap, previousView);
}

function restoreTableViewState(wrap, view) {
  wrap.querySelectorAll(".column-filter").forEach((input) => {
    const saved = view.filters?.find((item) => item.col === (input.dataset.col || ""));
    input.value = saved?.value || "";
    setSelectedExcelFilterValues(input, saved?.selected || []);
  });
  wrap.querySelectorAll(".column-sort").forEach((select) => {
    select.value = view.sorts?.find((item) => item.col === (select.dataset.col || ""))?.value || "";
  });
  wrap.classList.toggle("filters-hidden", Boolean(view.filtersHidden));
  tableFilterRows(wrap).forEach((row) => { row.hidden = Boolean(view.filtersHidden); });
  applyColumnFilters({ target: wrap.querySelector("table") });
  updateTableState(wrap);
}

function repairTableHtml(rows) {
  const heads = ["Select", "Actions", "WO #", "Date", "Closing Date", "Void Date", "Asset #", "Serial #", "License Plate", "Equipment Name", "Operator", "Requested By", "Customer", "Jobsite", "Actual Location", "Priority", "Issues", "Customer PO", "Mechanic", "Currently Clocked In", "Type", "Parts", "Labor", "Total", "Status", "Invoice"];
  const eligibleCount = rows.filter((wo) => /closed|complete|invoiced/i.test(wo.status || "") && !/void|cancel/i.test(wo.status || "")).length;
  return `<div class="table-wrap"><table><thead><tr>${heads.map((h, index) => index === 0 ? `<th><label class="select-all-header"><input type="checkbox" data-repair-email-select-all ${eligibleCount ? "" : "disabled"} aria-label="Select all visible eligible work orders"><span>Select all</span></label></th>` : `<th>${esc(h)}</th>`).join("")}</tr><tr>${heads.map((h, i) => i === 0 ? "<th></th>" : h ? `<th><input class="column-filter" data-col="${i}" placeholder="Filter ${esc(h)}"></th>` : "<th></th>").join("")}</tr></thead><tbody>${rows.length ? rows.map(repairRowHtml).join("") : `<tr><td colspan="${heads.length}" class="empty">No work orders in this tab.</td></tr>`}</tbody></table></div>`;
}

function repairRowHtml(wo) {
  const assetDetails = workOrderAssetDetails(wo);
  const activeLabor = (wo._labor || []).filter((labor) => labor.clock_in && !labor.clock_out);
  const activeMechanics = [...new Set(activeLabor.map((labor) => labor.mechanic).filter(Boolean))];
  const actualMechanics = [...new Set([
    ...activeMechanics,
    ...(wo._labor || []).map((labor) => labor.mechanic).filter(Boolean),
  ])];
  const openingMechanic = openingMechanicForWorkOrder(wo);
  const mechanics = actualMechanics.length
    ? actualMechanics.join(", ")
    : openingMechanic !== "Not recorded" ? openingMechanic : "";
  const clockedIn = activeLabor.length
    ? activeLabor.map((labor) => `${badge(labor.mechanic || "Mechanic")}<small>Since ${esc(formatDateTime(labor.clock_in))}</small>`).join("<br>")
    : `<span class="muted">None</span>`;
  const voided = /void|cancel/i.test(wo.status || "");
  const locked = wo.invoice_no || /invoiced/i.test(wo.status || "") || voided;
  const canClose = !locked && !/closed|complete|cancel|void/i.test(wo.status || "");
  const canVoid = !wo.invoice_no && !/invoiced|void|cancel/i.test(wo.status || "");
  const canInvoice = !locked && !voided;
  const canReturnIssuedParts = voided && workOrderHasIssuedPartsToReturn(wo);
  const invoiceActions = wo.invoice_no
    ? `<button class="rowbtn" type="button" data-wo-invoice-pdf="${esc(wo.wo_no)}">Invoice PDF</button><button class="rowbtn" type="button" data-wo-invoice-email="${esc(wo.wo_no)}">Email</button><button class="rowbtn danger" type="button" data-wo-invoice-void="${esc(wo.invoice_no)}">Void Invoice</button>`
    : "";
  const workOrderRecordKey = String(wo.id || wo.wo_no || "");
  return `<tr>
    <td>${/closed|complete|invoiced/i.test(wo.status || "") && !voided ? `<input type="checkbox" data-repair-email-select="${esc(wo.wo_no)}" ${selectedRepairWorkOrders.has(String(wo.wo_no || "")) ? "checked" : ""} aria-label="Select ${esc(wo.wo_no)} for email">` : ""}</td>
    <td><div class="rowactions"><button class="rowbtn" type="button" data-wo-pdf-draft="${esc(wo.wo_no)}">PDF Draft</button>${locked ? `<button class="rowbtn" type="button" data-wo-view-id="${esc(workOrderRecordKey)}">View</button>` : `<button class="rowbtn" type="button" data-wo-time-id="${esc(workOrderRecordKey)}">Time</button><button class="rowbtn" type="button" data-wo-edit-id="${esc(workOrderRecordKey)}">Edit</button>${canClose ? `<button class="rowbtn" type="button" data-wo-close="${esc(wo.wo_no)}">Close</button>` : ""}${canVoid ? `<button class="rowbtn danger" type="button" data-wo-void="${esc(wo.wo_no)}">Void</button>` : ""}`}${canReturnIssuedParts ? `<button class="rowbtn" type="button" data-wo-return-parts="${esc(wo.wo_no)}">Return Parts</button>` : ""}${canInvoice ? `<button class="rowbtn" type="button" data-wo-invoice="${esc(wo.wo_no)}">Inv</button>` : ""}${invoiceActions}</div></td>
    <td>${esc(wo.wo_no)}</td><td>${esc(formatDisplayDate(wo.wo_date))}</td><td>${esc(formatDisplayDate(workOrderClosingDate(wo)))}</td><td>${esc(formatDisplayDate(wo.void_date))}</td><td>${esc(wo.asset_tag || "")}</td><td>${esc(assetDetails.serial)}</td><td>${esc(assetDetails.plate)}</td><td>${esc(assetDetails.name)}</td><td>${esc(wo.operator || assetDetails.operator)}</td><td>${esc(wo.requested_by || "")}</td><td>${esc(wo.bill_to_customer || "")}</td><td>${esc(wo.jobsite_location || "")}</td><td>${esc(actualLocationForWorkOrder(wo))}</td><td>${badge(wo.priority || "Medium")}</td>
    <td>${esc((wo._issues || []).map((i) => i.issue).filter(Boolean).join("; ") || wo.description || "")}</td>
    <td>${wo.customer_po ? badge(wo.customer_po) : wo.manager_override ? badge(`Override: ${wo.override_by || "Manager"}`) : ""}</td>
    <td>${esc(mechanics || "")}</td><td>${clockedIn}</td><td>${esc(wo.work_type || "")}</td><td>${money(repairPartsTotal(wo))}</td><td>${repairLaborHours(wo).toFixed(2)} hr<br>${money(repairLaborTotal(wo))}</td><td>${money(repairTotal(wo))}</td><td>${badge(wo.status || "Open")}</td><td>${esc(wo.invoice_no ? wo.wo_no : "")}</td>
  </tr>`;
}

function workOrderFromRecordKey(rows = [], key = "") {
  const normalized = String(key || "");
  return rows.find((wo) => String(wo.id || "") === normalized)
    || rows.find((wo) => String(wo.wo_no || "") === normalized);
}

function workOrderAssetDetails(wo = {}) {
  const key = String(wo.asset_tag || "").trim().toLowerCase();
  const owned = (productMeta.assets || []).find((asset) => [asset.asset_tag, asset.vin_serial, asset.plate].some((value) => String(value || "").trim().toLowerCase() === key));
  if (owned) return { serial: owned.vin_serial || "", plate: owned.plate || "", name: owned.name || "", operator: owned.assigned_operator || "" };
  const outside = (productMeta.outsideFleet || []).find((asset) => [asset.reference, asset.vin, asset.plate].some((value) => String(value || "").trim().toLowerCase() === key));
  return outside ? { serial: outside.vin || "", plate: outside.plate || "", name: outside.description || [outside.make, outside.model].filter(Boolean).join(" "), operator: outside.operator || outside.assigned_operator || "" } : { serial: "", plate: "", name: "", operator: "" };
}

function workOrderAssetDetailsFromLists(wo = {}, assets = [], outsideFleet = []) {
  const key = String(wo.asset_tag || "").trim().toLowerCase();
  const owned = (assets || []).find((asset) => [asset.asset_tag, asset.vin_serial, asset.plate].some((value) => String(value || "").trim().toLowerCase() === key));
  if (owned) return { serial: owned.vin_serial || owned.serial_no || owned.vin || "", plate: owned.plate || "", name: owned.name || owned.description || "", operator: owned.assigned_operator || "" };
  const outside = (outsideFleet || []).find((asset) => [asset.reference, asset.vin, asset.plate].some((value) => String(value || "").trim().toLowerCase() === key));
  return outside
    ? { serial: outside.vin || outside.vin_serial || outside.serial_no || "", plate: outside.plate || "", name: outside.description || [outside.make, outside.model].filter(Boolean).join(" "), operator: outside.operator || outside.assigned_operator || "" }
    : { serial: "", plate: "", name: "", operator: "" };
}

function openingMechanicForWorkOrder(wo) {
  if (String(wo?.opening_mechanic || "").trim()) return String(wo.opening_mechanic).trim();
  const noteMatch = String(wo?.notes || "").match(/Opened by mechanic:\s*([^\r\n]+)/i);
  if (noteMatch?.[1]) return noteMatch[1].trim();
  return (wo?._issues || []).map((issue) => issue.assigned_mechanic).find(Boolean) || "Not recorded";
}

function actualLocationForWorkOrder(wo) {
  if (wo?.actual_location) return wo.actual_location;
  const owned = (productMeta.assets || []).find((asset) => asset.asset_tag === wo?.asset_tag);
  if (owned?.location) return owned.location;
  return (productMeta.outsideFleet || []).find((asset) => asset.reference === wo?.asset_tag)?.location || "";
}

function bindRepairRows() {
  const selectAll = document.querySelector("[data-repair-email-select-all]");
  const visibleSelections = () => [...document.querySelectorAll("[data-repair-email-select]")].filter((input) => input.offsetParent !== null);
  const updateSelectAllState = () => {
    if (!selectAll) return;
    const eligible = visibleSelections();
    const checked = eligible.filter((input) => input.checked).length;
    selectAll.checked = eligible.length > 0 && checked === eligible.length;
    selectAll.indeterminate = checked > 0 && checked < eligible.length;
    selectAll.disabled = eligible.length === 0;
  };
  if (selectAll) selectAll.onchange = () => {
    visibleSelections().forEach((input) => {
      input.checked = selectAll.checked;
      if (input.checked) selectedRepairWorkOrders.add(input.dataset.repairEmailSelect);
      else selectedRepairWorkOrders.delete(input.dataset.repairEmailSelect);
    });
    updateSelectAllState();
  };
  document.querySelectorAll("[data-repair-email-select]").forEach((input) => input.onchange = () => {
    if (input.checked) selectedRepairWorkOrders.add(input.dataset.repairEmailSelect);
    else selectedRepairWorkOrders.delete(input.dataset.repairEmailSelect);
    updateSelectAllState();
  });
  document.querySelectorAll("[data-wo-pdf-draft]").forEach((b) => b.onclick = () => printWorkOrderDraft(b.dataset.woPdfDraft));
  document.querySelectorAll("[data-wo-time-id]").forEach((b) => b.onclick = () => openMechanicTimeModal(workOrderFromRecordKey(currentRows, b.dataset.woTimeId)));
  document.querySelectorAll("[data-wo-edit-id]").forEach((b) => b.onclick = () => openWorkOrderEditModal(workOrderFromRecordKey(currentRows, b.dataset.woEditId)));
  document.querySelectorAll("[data-wo-view-id]").forEach((b) => b.onclick = () => openWorkOrderEditModal(workOrderFromRecordKey(currentRows, b.dataset.woViewId), { readOnly: true }));
  document.querySelectorAll("[data-wo-close]").forEach((b) => b.onclick = () => closeWorkOrder(b.dataset.woClose));
  document.querySelectorAll("[data-wo-void]").forEach((b) => b.onclick = () => voidWorkOrder(b.dataset.woVoid));
  document.querySelectorAll("[data-wo-return-parts]").forEach((b) => b.onclick = () => returnPartsForVoidedWorkOrder(b.dataset.woReturnParts));
  document.querySelectorAll("[data-wo-invoice]").forEach((b) => b.onclick = () => invoiceWorkOrder(b.dataset.woInvoice));
  document.querySelectorAll("[data-wo-invoice-pdf]").forEach((b) => b.onclick = () => printCustomerInvoice(b.dataset.woInvoicePdf));
  document.querySelectorAll("[data-wo-invoice-email]").forEach((b) => b.onclick = () => emailCustomerInvoice(b.dataset.woInvoiceEmail));
  document.querySelectorAll("[data-wo-invoice-void]").forEach((b) => b.onclick = () => reverseInvoice(b.dataset.woInvoiceVoid, { returnToRepairs: true }));
  document.querySelectorAll(".column-filter").forEach((input) => input.oninput = () => {
    applyColumnFilters();
    updateSelectAllState();
  });
  updateSelectAllState();
}

async function emailSelectedRepairPdfs() {
  const selectedNos = [...document.querySelectorAll("[data-repair-email-select]:checked")].map((input) => input.dataset.repairEmailSelect);
  if (!selectedNos.length) return alert("Select at least one work order from Closed Not Invoiced or Invoiced WO.");
  const rows = selectedNos.map((woNo) => currentRows.find((wo) => wo.wo_no === woNo)).filter(Boolean);
  const customerNames = [...new Set(rows.map((wo) => String(wo.bill_to_customer || "").trim()).filter(Boolean))];
  if (customerNames.length > 1) return alert(`Selected work orders belong to different customers:\n\n${customerNames.join("\n")}\n\nSelect work orders for one customer at a time.`);
  const customerName = customerNames[0] || "";
  const customer = (productMeta.customerRows || []).find((row) => String(row.name || "").trim().toLowerCase() === customerName.toLowerCase()) || {};
  const emails = [...new Set(rows.map((wo) => String(wo.requestor_email || "").trim().toLowerCase()).filter(isValidEmail))];
  const recipient = normalizeEmailRecipients(customer.email || emails[0] || "");
  const mixedRequestorEmails = !customer.email && emails.length > 1;
  const documents = rows.map((wo) => ({ wo, label: wo.invoice_no ? `Invoice ${wo.wo_no}` : `Work Order Draft ${wo.wo_no}` }));
  $("modalTitle").textContent = `Email ${documents.length} selected repair PDF${documents.length === 1 ? "" : "s"}`;
  $("modalBody").innerHTML = `
    ${mixedRequestorEmails ? `<div class="notice"><strong>Different requestor emails found.</strong><br>Enter the intended recipient before opening the email draft.</div>` : ""}
    <div class="form-grid"><div class="field wide"><label>Email recipients</label><textarea id="repairBatchEmailTo" placeholder="ap@example.com; manager@example.com">${esc(recipient)}</textarea><small>Enter one or more addresses separated by commas, semicolons, or new lines. Customer Master emails are preferred.</small></div></div>
    <div class="notice"><strong>Mass PDF download</strong><br>Choose individual PDFs to prepare one file per selected work order, or one joint PDF containing every selected document. After saving the PDF file(s), attach them to the prepared email draft.</div>
    <div class="actions batch-download-actions"><button type="button" id="repairBatchIndividualPdf">Mass Download — Individual PDFs</button><button type="button" class="primary" id="repairBatchJointPdf">Download One Joint PDF</button></div>
    <div class="batch-document-list">${documents.map(({ wo, label }) => `<div class="batch-document-row"><span>${esc(label)}</span><button type="button" class="rowbtn" data-open-selected-repair-pdf="${esc(wo.wo_no)}">Open PDF</button></div>`).join("")}</div>`;
  $("modalSave").textContent = "Open Email Draft";
  $("modalCancel").textContent = "Close";
  $("modalSave").onclick = () => {
    const email = String($("repairBatchEmailTo")?.value || "").trim();
    if (!areValidEmailRecipients(email)) return alert("Enter one or more valid email recipients.");
    const normalizedEmail = normalizeEmailRecipients(email);
    const subject = `Repair document submission — ${rows.map((wo) => wo.wo_no).join(", ")}`;
    const body = [
      `Dear ${customerName || "Customer"} Accounts Payable Team,`,
      "",
      "Please find the requested repair document(s) from Landscape Management Systems, Inc.:",
      "",
      ...documents.map(({ label }) => `- ${label}`),
      "",
      "Please review the submitted repair documents at your convenience.",
      "",
      "Sincerely,",
      "Accounts Receivable",
      "Landscape Management Systems, Inc.",
    ].join("\n");
    openEmailDraftPrompt({ title: "Selected repair documents", message: `Open the formal email draft for ${emailRecipientCount(normalizedEmail)} recipient(s)?`, email: normalizedEmail, subject, body });
  };
  $("modal").style.display = "flex";
  $("repairBatchIndividualPdf").onclick = () => downloadSelectedRepairPdfs(documents, false);
  $("repairBatchJointPdf").onclick = () => downloadSelectedRepairPdfs(documents, true);
  document.querySelectorAll("[data-open-selected-repair-pdf]").forEach((button) => {
    button.onclick = () => {
      const wo = currentRows.find((row) => row.wo_no === button.dataset.openSelectedRepairPdf);
      if (wo?.invoice_no) printCustomerInvoice(wo.wo_no);
      else printWorkOrderDraft(wo?.wo_no);
    };
  });
}

async function selectedRepairDocumentHtml(wo) {
  return wo?.invoice_no
    ? printCustomerInvoice(wo.wo_no, { returnHtml: true })
    : printWorkOrderDraft(wo?.wo_no, { returnHtml: true });
}

function combinedRepairDocumentHtml(generatedDocuments = []) {
  const firstHtml = generatedDocuments[0]?.html || "";
  const styles = firstHtml.match(/<style[^>]*>[\s\S]*?<\/style>/i)?.[0] || "";
  const pages = generatedDocuments.map(({ html, label }) => {
    const main = html.match(/<main\b[\s\S]*?<\/main>/i)?.[0] || `<main class="sheet"><h1>${esc(label)}</h1><p>Document could not be rendered.</p></main>`;
    return `<section class="batch-pdf-page">${main}</section>`;
  }).join("");
  return `<!doctype html><html><head><meta charset="utf-8"><title>Selected Repair Documents</title>${styles}<style>.batch-pdf-page{break-after:page;page-break-after:always}.batch-pdf-page:last-child{break-after:auto;page-break-after:auto}.batch-pdf-page>.sheet{margin:0 auto}.print-btn{position:fixed;top:10px;right:10px;z-index:10}@media print{.print-btn{display:none!important}}</style></head><body><button class="print-btn" onclick="window.print()">Print / Save Joint PDF</button>${pages}</body></html>`;
}

async function downloadSelectedRepairPdfs(documents = [], joint = false) {
  if (!documents.length) return alert("No selected documents were found.");
  if (joint) {
    const loadingWindow = openInAppDocumentWindow("Selected Repair Documents");
    if (!loadingWindow) return alert("Allow popups to prepare the joint PDF.");
    loadingWindow.document.write("<p style='font-family:sans-serif;padding:24px'>Preparing joint PDF…</p>");
    try {
      const generated = await Promise.all(documents.map(async ({ wo, label }) => ({ label, html: await selectedRepairDocumentHtml(wo) })));
      openPrintWindow(combinedRepairDocumentHtml(generated), "selected-repair-documents", loadingWindow);
    } catch (error) {
      loadingWindow.close();
      alert(`Could not prepare the joint PDF.\n\n${error.message}`);
    }
    return;
  }
  const previewWindow = openInAppDocumentWindow("Selected Repair Documents");
  previewWindow.document.write("<p style='font-family:sans-serif;padding:24px'>Preparing selected documents…</p>");
  try {
    const generated = await Promise.all(documents.map(async ({ wo, label }) => ({ label, html: await selectedRepairDocumentHtml(wo) })));
    openPrintWindow(combinedRepairDocumentHtml(generated), "selected-repair-documents", previewWindow);
  } catch (error) {
    previewWindow.close();
    alert(`Could not prepare all individual PDFs.\n\n${error.message}`);
  }
}

function dateTextToIso(value = "") {
  const text = String(value || "").trim();
  if (!text) return "";
  const direct = text.match(/^(\d{4}-\d{2}-\d{2})/);
  if (direct) return direct[1];
  const parsed = new Date(text.replace(/,\s*/, " "));
  if (Number.isNaN(parsed.getTime())) return "";
  const year = parsed.getFullYear();
  const month = String(parsed.getMonth() + 1).padStart(2, "0");
  const day = String(parsed.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function workOrderReadyDate(wo = {}) {
  if (wo.ready_to_close_at) return dateTextToIso(wo.ready_to_close_at);
  const match = String(wo.notes || "").match(/\[Ready to Close\s+([^\]]+?)(?:\s+by\s+[^\]]+)?\]/i);
  return match ? dateTextToIso(match[1]) : "";
}

function workOrderLastLaborDate(wo = {}) {
  return (wo._labor || [])
    .filter((labor) => !isReversedLabor(labor) && labor.clock_out && laborHours(labor) > 0)
    .map((labor) => guamDateKey(labor.clock_out, labor.clock_in))
    .filter(Boolean)
    .sort()
    .at(-1) || "";
}

function workOrderClosingDate(wo = {}) {
  const laborDate = workOrderLastLaborDate(wo);
  if (laborDate) return laborDate;
  if (wo.closed_date) return dateTextToIso(wo.closed_date);
  const readyDate = workOrderReadyDate(wo);
  if (readyDate) return readyDate;
  const match = String(wo.notes || "").match(/\[Closed\s+([^\]]+)\]/i);
  return match ? dateTextToIso(match[1]) : "";
}

function workOrderClosingDays(wo = {}) {
  const opened = dateTextToIso(wo.wo_date || wo.created_at);
  const closed = workOrderClosingDate(wo);
  if (!opened || !closed) return null;
  const start = new Date(`${opened}T00:00:00`);
  const end = new Date(`${closed}T00:00:00`);
  return Math.max(0, Math.round((end - start) / 86400000));
}

function mechanicClosingReportData(workOrders = [], filters = {}) {
  const from = filters.from || "";
  const to = filters.to || "";
  const mechanicQuery = String(filters.mechanic || "").trim().toLowerCase();
  const summary = new Map();
  const detail = [];
  for (const wo of workOrders) {
    const status = String(wo.status || "").toLowerCase();
    if (!/ready to close|closed|complete|invoiced/.test(status) || /void|cancel/.test(status)) continue;
    const closedDate = workOrderClosingDate(wo);
    const closingDays = workOrderClosingDays(wo);
    if (!closedDate || closingDays === null || (from && closedDate < from) || (to && closedDate > to)) continue;
    const laborByMechanic = new Map();
    for (const labor of wo._labor || []) {
      const mechanic = String(labor.mechanic || "").trim();
      const hours = Math.max(0, laborHours(labor));
      if (!mechanic || !hours) continue;
      laborByMechanic.set(mechanic, (laborByMechanic.get(mechanic) || 0) + hours);
    }
    if (!laborByMechanic.size) {
      const opening = openingMechanicForWorkOrder(wo);
      if (opening && opening !== "Not recorded") laborByMechanic.set(opening, 0);
    }
    const totalHours = [...laborByMechanic.values()].reduce((sum, hours) => sum + hours, 0);
    const entries = [...laborByMechanic.entries()];
    for (const [mechanic, hours] of entries) {
      if (mechanicQuery && !mechanic.toLowerCase().includes(mechanicQuery)) continue;
      const ratio = totalHours > 0 ? hours / totalHours : 1 / Math.max(1, entries.length);
      const priority = ["low", "medium", "high"].includes(String(wo.priority || "").toLowerCase()) ? String(wo.priority).toLowerCase() : "other";
      const item = summary.get(mechanic) || {
        mechanic,
        workOrders: new Set(),
        hours: 0,
        participation: 0,
        overall: { weightedDays: 0, weight: 0 },
        low: { weightedDays: 0, weight: 0 },
        medium: { weightedDays: 0, weight: 0 },
        high: { weightedDays: 0, weight: 0 },
      };
      item.workOrders.add(wo.wo_no);
      item.hours += hours;
      item.participation += ratio;
      item.overall.weightedDays += closingDays * ratio;
      item.overall.weight += ratio;
      if (item[priority]) {
        item[priority].weightedDays += closingDays * ratio;
        item[priority].weight += ratio;
      }
      summary.set(mechanic, item);
      detail.push({
        wo_no: wo.wo_no,
        mechanic,
        asset_tag: wo.asset_tag || "",
        jobsite: wo.jobsite_location || "",
        work_type: wo.work_type || "",
        issues: (wo._issues || []).map((issue) => issue.issue).filter(Boolean).join("; ") || wo.description || "",
        status: wo.status || "",
        priority: wo.priority || "Medium",
        opened_date: dateTextToIso(wo.wo_date || wo.created_at),
        closed_date: closedDate,
        closing_days: closingDays,
        mechanic_hours: hours,
        total_wo_hours: totalHours,
        labor_ratio: ratio,
      });
    }
  }
  const average = (metric) => metric.weight ? metric.weightedDays / metric.weight : null;
  const rows = [...summary.values()].map((item) => ({
    mechanic: item.mechanic,
    work_orders: item.workOrders.size,
    labor_hours: item.hours,
    weighted_wo_share: item.participation,
    low_average: average(item.low),
    medium_average: average(item.medium),
    high_average: average(item.high),
    overall_average: average(item.overall),
  })).sort((a, b) => a.mechanic.localeCompare(b.mechanic));
  return { rows, detail };
}

function mechanicClosingAverage(value) {
  return value === null || !Number.isFinite(value) ? "—" : `${value.toFixed(2)} days`;
}

function renderMechanicClosingReport() {
  const host = $("mechanicClosingReportHost");
  if (!host) return;
  const from = $("mechanicClosingFrom")?.value || "";
  const to = $("mechanicClosingTo")?.value || "";
  if (from && to && from > to) {
    host.innerHTML = `<div class="notice"><strong>Invalid date range.</strong> From Date cannot be later than To Date.</div>`;
    return;
  }
  const report = mechanicClosingReportData(currentRows, {
    from,
    to,
    mechanic: $("mechanicClosingName")?.value || "",
  });
  const selectedMechanic = String(host.dataset.detailMechanic || "").trim();
  const visibleDetail = selectedMechanic
    ? report.detail.filter((row) => row.mechanic.toLowerCase() === selectedMechanic.toLowerCase())
    : report.detail;
  host.dataset.report = JSON.stringify({ rows: report.rows, detail: report.detail });
  host.innerHTML = `
    <div class="notice">Closing days are calendar days from Work Order Date to Closing Date. When helpers participate, each mechanic receives a weighted share based on that mechanic's labor hours divided by the work order's total labor hours.</div>
    <div class="table-wrap"><table><thead><tr><th>Mechanic</th><th>WO Involvement</th><th>Labor Hours</th><th>Weighted WO Share</th><th>Low Avg.</th><th>Medium Avg.</th><th>High Avg.</th><th>Overall Avg.</th></tr></thead><tbody>
      ${report.rows.length ? report.rows.map((row) => `<tr class="clickable-row" data-closing-mechanic-detail="${esc(row.mechanic)}" title="Click to show ${esc(row.mechanic)} work-order details"><td><button type="button" class="linkbtn" data-closing-mechanic-detail="${esc(row.mechanic)}">${esc(row.mechanic)}</button></td><td>${esc(row.work_orders)}</td><td>${row.labor_hours.toFixed(2)}</td><td>${row.weighted_wo_share.toFixed(2)}</td><td>${mechanicClosingAverage(row.low_average)}</td><td>${mechanicClosingAverage(row.medium_average)}</td><td>${mechanicClosingAverage(row.high_average)}</td><td><strong>${mechanicClosingAverage(row.overall_average)}</strong></td></tr>`).join("") : `<tr><td colspan="8" class="empty">No closed work orders match these filters.</td></tr>`}
    </tbody></table></div>
    <div class="panel-head"><div class="panel-title"><strong>${selectedMechanic ? `${esc(selectedMechanic)} Work Order Details` : "All Work Order Labor Allocation Details"}</strong><span>${visibleDetail.length} filtered detail line${visibleDetail.length === 1 ? "" : "s"}</span></div><div class="actions">${selectedMechanic ? `<button type="button" id="showAllMechanicClosingDetailsBtn">Show All Details</button>` : ""}<button type="button" id="mechanicClosingDetailExcelBtn">Download Detail Excel</button></div></div>
    <div class="table-wrap"><table><thead><tr><th>WO #</th><th>Mechanic</th><th>Asset</th><th>Jobsite</th><th>Work Type</th><th>Issues</th><th>Priority</th><th>Status</th><th>Opened</th><th>Closing Date</th><th>Closing Days</th><th>Mechanic Hours</th><th>Total WO Hours</th><th>Labor Ratio</th></tr></thead><tbody>
      ${visibleDetail.length ? visibleDetail.map((row) => `<tr><td>${esc(row.wo_no)}</td><td>${esc(row.mechanic)}</td><td>${esc(row.asset_tag)}</td><td>${esc(row.jobsite)}</td><td>${esc(row.work_type)}</td><td>${esc(row.issues)}</td><td>${esc(row.priority)}</td><td>${esc(row.status)}</td><td>${esc(formatDisplayDate(row.opened_date))}</td><td>${esc(formatDisplayDate(row.closed_date))}</td><td>${esc(row.closing_days)}</td><td>${row.mechanic_hours.toFixed(2)}</td><td>${row.total_wo_hours.toFixed(2)}</td><td>${(row.labor_ratio * 100).toFixed(2)}%</td></tr>`).join("") : `<tr><td colspan="14" class="empty">No mechanic allocation detail.</td></tr>`}
    </tbody></table></div>`;
  host.querySelectorAll("[data-closing-mechanic-detail]").forEach((element) => {
    element.onclick = (event) => {
      event.preventDefault();
      event.stopPropagation();
      host.dataset.detailMechanic = element.dataset.closingMechanicDetail || "";
      renderMechanicClosingReport();
    };
  });
  $("showAllMechanicClosingDetailsBtn")?.addEventListener("click", () => {
    host.dataset.detailMechanic = "";
    renderMechanicClosingReport();
  });
  $("mechanicClosingDetailExcelBtn")?.addEventListener("click", exportMechanicClosingDetailReport);
}

