function currentMechanicName() {
  const email = String(profile?.email || session?.user?.email || "").toLowerCase();
  const username = String(profile?.username || "").toLowerCase();
  const fullName = String(profile?.full_name || "").toLowerCase();
  const row = (productMeta.mechanicsRows || []).find((m) => [m.email, m.name, m.reference].some((v) => String(v || "").toLowerCase() === email || String(v || "").toLowerCase() === username || String(v || "").toLowerCase() === fullName));
  return row?.name || profile?.full_name || profile?.username || session?.user?.email || "Mechanic";
}

function mechanicVisibleWorkOrders(mechanic) {
  return mechanicPortalRows("open");
}

function mechanicIdentityKeys(mechanic = currentMechanicName()) {
  const values = [
    mechanic,
    profile?.full_name,
    profile?.username,
    profile?.email,
    session?.user?.email,
  ];
  const normalizedSeeds = new Set(values.flatMap(mechanicIdentityVariants));
  (productMeta.mechanicsRows || []).forEach((row) => {
    const aliases = [row?.name, row?.email, row?.reference].flatMap(mechanicIdentityVariants);
    if (aliases.some((alias) => normalizedSeeds.has(alias))) values.push(row?.name, row?.email, row?.reference);
  });
  return new Set(values.flatMap(mechanicIdentityVariants));
}

function mechanicIdentityVariants(value = "") {
  const raw = String(value || "").trim().toLowerCase();
  if (!raw) return [];
  const local = raw.includes("@") ? raw.split("@")[0] : raw;
  const compact = (text) => String(text || "").replace(/[^a-z0-9]/g, "");
  return [...new Set([raw, local, compact(raw), compact(local)].filter(Boolean))];
}

function workOrderAssignmentNames(wo) {
  return [
    wo?.opening_mechanic,
    openingMechanicForWorkOrder(wo) === "Not recorded" ? "" : openingMechanicForWorkOrder(wo),
    ...(wo?._issues || []).map((row) => row.assigned_mechanic),
    ...(wo?._labor || []).filter((row) => !isReversedLabor(row)).map((row) => row.mechanic),
  ].map((value) => String(value || "").trim()).filter(Boolean);
}

function workOrderAssignedToMechanic(wo, mechanic = currentMechanicName()) {
  const keys = mechanicIdentityKeys(mechanic);
  return workOrderAssignmentNames(wo).some((name) => mechanicIdentityVariants(name).some((variant) => keys.has(variant)));
}

function workOrderHasAssignment(wo) {
  return workOrderAssignmentNames(wo).length > 0;
}

function workOrderHasActiveLabor(wo, mechanic = "") {
  const mechanicKey = String(mechanic || "").trim().toLowerCase();
  const identityKeys = mechanicKey ? mechanicIdentityKeys(mechanic) : null;
  return (wo?._labor || []).some((labor) => {
    if (isReversedLabor(labor) || !labor.clock_in || labor.clock_out) return false;
    if (!identityKeys) return true;
    return identityKeys.has(String(labor.mechanic || "").trim().toLowerCase());
  });
}

function mechanicWorkOrderOpenForPortal(wo) {
  if (!wo || wo.invoice_no) return false;
  return !/ready to close|closed|complete|invoiced|void|cancel/i.test(wo.status || "");
}

function mechanicWorkOrderClosedForPortal(wo) {
  if (!wo) return false;
  if (/void|cancel/i.test(wo.status || "")) return false;
  return !!wo.invoice_no || /ready to close|closed|complete|invoiced/i.test(wo.status || "");
}

function mechanicPortalRows(tab = "open") {
  const manager = isMechanicManagerUser();
  const mechanic = currentMechanicName();
  const openRows = currentRows.filter(mechanicWorkOrderOpenForPortal);
  if (tab === "all") return openRows;
  if (tab === "assigned") return openRows.filter((wo) => manager ? workOrderHasAssignment(wo) : workOrderAssignedToMechanic(wo, mechanic));
  if (tab === "working") return openRows.filter((wo) => workOrderHasActiveLabor(wo, manager ? "" : mechanic));
  if (tab === "closed") return currentRows.filter((wo) => mechanicWorkOrderClosedForPortal(wo)
    && (manager || workOrderAssignedToMechanic(wo, mechanic)));
  return openRows;
}

