    const record = { property_no: $("pmPropertyNo").value.trim(), property_name: $("pmPropertyName").value.trim(), property_type: $("pmPropertyType").value.trim() || "Commercial", customer_owner: $("pmPropertyOwner").value.trim(), address: $("pmPropertyAddress").value.trim(), jobsite: $("pmPropertyJobsite").value.trim(), contact_name: $("pmPropertyContact").value.trim(), contact_phone: $("pmPropertyPhone").value.trim(), contact_email: $("pmPropertyEmail").value.trim(), manager_name: $("pmPropertyManager").value.trim(), inspection_frequency: $("pmPropertyFrequency").value.trim(), next_inspection_date: $("pmPropertyNext").value || null, status: $("pmPropertyStatus").value, notes: $("pmPropertyNotes").value.trim(), updated_at: new Date().toISOString() };
