// Keep every general PDF / Print action inside the LMS Imports interface.
// The browser print dialog is available only from the preview toolbar.
window.print = previewCurrentSystemView;

function partNumberWording(value) {
  return String(value ?? "")
    .replace(/Alternative SKUs/g, "Alternate Part Numbers")
    .replace(/ALTERNATIVE SKUS/g, "ALTERNATE PART NUMBERS")
    .replace(/SKUs/g, "Part Numbers")
    .replace(/SKU/g, "Part #");
}

function applyPartNumberWording(root = document) {
  const scope = root?.nodeType === Node.TEXT_NODE ? root.parentElement : root;
  if (!scope) return;
  const walker = document.createTreeWalker(scope, NodeFilter.SHOW_TEXT);
  const textNodes = [];
  while (walker.nextNode()) textNodes.push(walker.currentNode);
  textNodes.forEach((node) => {
    if (node.parentElement?.closest("script,style")) return;
    const updated = partNumberWording(node.nodeValue);
    if (updated !== node.nodeValue) node.nodeValue = updated;
  });
  if (scope.querySelectorAll) {
    const attributedElements = [...(scope.matches?.("[placeholder],[title],[aria-label]") ? [scope] : []), ...scope.querySelectorAll("[placeholder],[title],[aria-label]")];
    attributedElements.forEach((element) => {
      ["placeholder", "title", "aria-label"].forEach((attribute) => {
        if (!element.hasAttribute(attribute)) return;
        const current = element.getAttribute(attribute) || "";
        const updated = partNumberWording(current);
        if (updated !== current) element.setAttribute(attribute, updated);
      });
    });
  }
}

queueMicrotask(() => {
  applyPartNumberWording(document.body);
  const observer = new MutationObserver((mutations) => mutations.forEach((mutation) => mutation.addedNodes.forEach((node) => applyPartNumberWording(node))));
  observer.observe(document.body, { childList: true, subtree: true });
});

