function selectedRepairRequestAsset(value) {
  const exact = String(value || "").trim().toLowerCase();
  const assetTag = exact.split("|")[0].trim();
  return (productMeta.assets || []).find((asset) => {
    const tag = String(asset.asset_tag || "").trim().toLowerCase();
    const label = [asset.asset_tag, asset.name || asset.description].filter(Boolean).join(" | ").toLowerCase();
    return tag === assetTag || label === exact;
  }) || null;
}

function fillEquipmentRepairRequestAsset(input) {
  const asset = selectedRepairRequestAsset(input?.value);
  const detail = $("equipmentRepairRequestAssetDetail");
  if (!detail) return;
  detail.innerHTML = asset ? `
    <div><span>Asset #</span><strong>${esc(asset.asset_tag || "-")}</strong></div>
    <div><span>Equipment</span><strong>${esc(asset.name || asset.description || "-")}</strong></div>
    <div><span>Current location</span><strong>${esc(asset.location || "-")}</strong></div>
    <div><span>Current operator</span><strong>${esc(asset.assigned_operator || "-")}</strong></div>
    <div><span>Plate #</span><strong>${esc(asset.plate || asset.license_plate || "-")}</strong></div>
    <div><span>Serial / VIN</span><strong>${esc(asset.vin_serial || asset.vin || asset.serial_no || "-")}</strong></div>`
    : `<p>Select a valid Fleet &amp; Equipment record to show its details.</p>`;
}

function openEquipmentRepairRequestModal() {
  editing = null;
  $("modalTitle").textContent = "New equipment repair request";
  $("modalBody").innerHTML = `
    <div class="form-grid">
      <div class="field wide"><label>Equipment *</label><input class="suggest-input" data-suggest-source="equipment" data-equipment-source="master" data-repair-request-field="asset_lookup" placeholder="Type asset #, equipment, plate, serial, VIN, type, or location" autocomplete="off" inputmode="search" required><small>Results appear in separate columns after you start typing.</small></div>
      <div class="field wide repair-request-asset-detail" id="equipmentRepairRequestAssetDetail"><p>Select equipment to show its Fleet &amp; Equipment details.</p></div>
      <div class="field"><label>Request date</label><input type="date" data-repair-request-field="request_date" value="${esc(today())}" readonly></div>
      <div class="field"><label>Requested by *</label><input data-repair-request-field="requested_by" value="" placeholder="Name of the person making this request" required></div>
      <div class="field"><label>Email *</label><input type="email" data-repair-request-field="email" value="" placeholder="Email of the person making this request" required></div>
      <div class="field"><label>PO # *</label><input data-repair-request-field="po_no" placeholder="Customer or internal PO number" required></div>
      <div class="field"><label>Priority</label><select data-repair-request-field="priority"><option>Low</option><option selected>Medium</option><option>High</option></select></div>
      <div class="field"><label>Operator</label><input data-repair-request-field="operator" placeholder="Operator using the equipment"></div>
      <div class="field"><label>Equipment location</label><input data-repair-request-field="location" placeholder="Defaults to current Fleet location"></div>
      <div class="field wide"><label>Repair issue / work requested *</label><textarea data-repair-request-field="issue" required placeholder="Describe the problem, symptoms, damage, or repair needed"></textarea></div>
      <div class="field wide"><label>Additional notes</label><textarea data-repair-request-field="notes" placeholder="Add timing, safety, access, or contact instructions"></textarea></div>
    </div>
    <p class="notice">This request goes to Fleet &amp; Repairs → Equipment Repair Requests. It does not create a work order automatically; Fleet staff review it first and assign the work order.</p>`;
  const assetInput = document.querySelector('[data-repair-request-field="asset_lookup"]');
  assetInput.addEventListener("change", () => {
    const asset = selectedRepairRequestAsset(assetInput.value);
    fillEquipmentRepairRequestAsset(assetInput);
    if (asset) {
      document.querySelector('[data-repair-request-field="operator"]').value = asset.assigned_operator || "";
      document.querySelector('[data-repair-request-field="location"]').value = asset.location || "";
    }
  });
  $("modalSave").textContent = "Submit repair request";
  $("modalSave").onclick = saveEquipmentRepairRequestModal;
  $("modalCancel").textContent = "Cancel";
  $("modal").style.display = "flex";
}

async function saveEquipmentRepairRequestModal() {
  const values = {};
  document.querySelectorAll("[data-repair-request-field]").forEach((field) => { values[field.dataset.repairRequestField] = String(field.value || "").trim(); });
  const asset = selectedRepairRequestAsset(values.asset_lookup);
  if (!asset) throw new Error("Select a valid equipment record from Fleet & Equipment.");
  if (!values.requested_by) throw new Error("Requested by is required.");
  if (!values.email || !/^\S+@\S+\.\S+$/.test(values.email)) throw new Error("Enter a valid requestor email address.");
  if (!values.po_no) throw new Error("PO # is required for an equipment repair request.");
  if (!values.issue) throw new Error("Repair issue / work requested is required.");
  const stamp = new Date().toLocaleString();
  const requestNote = [
    `Repair requested ${stamp}: ${values.issue}`,
    `Requestor email: ${values.email}`,
    `Priority: ${values.priority || "Medium"}`,
    values.notes ? `Request notes: ${values.notes}` : "",
  ].filter(Boolean).join(" | ");
  const record = {
    status: "Equipment Repair Request",
    requested_by: values.requested_by,
    repair_po_no: values.po_no,
    assigned_operator: values.operator || asset.assigned_operator || null,
    location: values.location || asset.location || null,
    last_update_date: localToday(),
    notes: [asset.notes || "", requestNote].filter(Boolean).join("\n"),
  };
  const { error } = await supabase.from("assets").update(record).eq("id", asset.id);
  if (error) throw error;
  closeModal(true);
  alert("Equipment repair request submitted successfully.");
  await renderEquipmentRepairRequestMobile();
}

function equipmentRepairQuoteEffectiveStatus(row) {
  const status = String(row?.status || "Pending");
  if (/converted/i.test(status) || row?.work_order_no) return "Converted";
  if (/cancel/i.test(status)) return "Cancelled";
  const expires = row?.expires_on ? new Date(`${row.expires_on}T23:59:59`).getTime() : NaN;
  return Number.isFinite(expires) && expires < Date.now() ? "Expired" : "Pending";
}

function dateAfterDays(dateValue = today(), days = 30) {
  const date = new Date(`${dateValue}T12:00:00`);
  date.setDate(date.getDate() + Number(days || 0));
  return date.toISOString().slice(0, 10);
}

async function renderEquipmentRepairQuotesView() {
  currentCfg = tableMap.equipmentrepairquotes;
  $("viewTitle").textContent = "Equipment Repair Quotes";
  $("viewSub").textContent = "Pending repair estimates move to Expired after their selected expiration date and can be converted into work orders.";
  const [quotes, customers, assets, outsideFleet] = await Promise.all([
    getAll("equipment_repair_quotes").catch((error) => {
      if (/does not exist|schema cache|404/i.test(String(error?.message || error))) return [];
      throw error;
    }),
    getAll("customers").catch(() => []),
    getAll("assets").catch(() => []),
    getAll("outside_customer_fleet").catch(() => []),
  ]);
  productMeta.customers = customers.map((row) => row.name).filter(Boolean).sort();
  productMeta.assets = assets;
  productMeta.outsideFleet = outsideFleet;
  const expiredPending = quotes.filter((row) => String(row.status || "Pending").toLowerCase() === "pending" && equipmentRepairQuoteEffectiveStatus(row) === "Expired");
  if (expiredPending.length) {
    await Promise.all(expiredPending.map((row) => supabase.from("equipment_repair_quotes").update({ status: "Expired" }).eq("id", row.id)));
    expiredPending.forEach((row) => { row.status = "Expired"; });
  }
  currentRows = quotes.sort((a, b) => String(b.quote_date || "").localeCompare(String(a.quote_date || "")) || String(b.quote_no || "").localeCompare(String(a.quote_no || "")));
  const count = (tab) => currentRows.filter((row) => equipmentRepairQuoteEffectiveStatus(row).toLowerCase() === tab).length;
  $("content").innerHTML = `
    <div class="toolbar"><input class="searchbox" id="equipmentRepairQuoteSearch" placeholder="Search quote, customer, asset, VIN, scope, work order"></div>
    <div class="tabbar">
      <button class="tabbtn ${equipmentRepairQuoteTab === "pending" ? "active" : ""}" data-equipment-repair-quote-tab="pending">Pending ${count("pending")}</button>
      <button class="tabbtn ${equipmentRepairQuoteTab === "converted" ? "active" : ""}" data-equipment-repair-quote-tab="converted">Converted ${count("converted")}</button>
      <button class="tabbtn ${equipmentRepairQuoteTab === "expired" ? "active" : ""}" data-equipment-repair-quote-tab="expired">Expired ${count("expired")}</button>
    </div>
    <section class="panel">
      <div class="panel-head"><div class="panel-title"><strong>Equipment Repair Quotes</strong><span>Default validity is 30 days. The expiration date can be changed on each quote.</span></div><div class="actions"><button id="equipmentRepairQuoteCsvBtn">Excel</button><button onclick="window.print()">PDF / Print</button><button class="primary" id="newEquipmentRepairQuoteBtn">New repair quote</button></div></div>
      <div id="equipmentRepairQuoteHost"></div>
    </section>`;
  $("equipmentRepairQuoteSearch").oninput = renderFilteredEquipmentRepairQuotes;
  $("equipmentRepairQuoteCsvBtn").onclick = exportCurrentCsv;
  $("newEquipmentRepairQuoteBtn").onclick = () => openEquipmentRepairQuoteModal();
  document.querySelectorAll("[data-equipment-repair-quote-tab]").forEach((button) => button.onclick = () => {
    equipmentRepairQuoteTab = button.dataset.equipmentRepairQuoteTab;
    document.querySelectorAll("[data-equipment-repair-quote-tab]").forEach((item) => item.classList.toggle("active", item === button));
    renderFilteredEquipmentRepairQuotes();
  });
  renderFilteredEquipmentRepairQuotes();
}

function renderFilteredEquipmentRepairQuotes() {
  const q = ($("equipmentRepairQuoteSearch")?.value || "").toLowerCase();
  const rows = currentRows.filter((row) => equipmentRepairQuoteEffectiveStatus(row).toLowerCase() === equipmentRepairQuoteTab)
    .filter((row) => !q || Object.values(row).join(" ").toLowerCase().includes(q));
  $("equipmentRepairQuoteHost").innerHTML = equipmentRepairQuoteTable(rows);
  bindEquipmentRepairQuoteRows();
}

function equipmentRepairQuoteTable(rows) {
  const heads = ["Quote #", "Date", "Expires", "Customer", "Equipment", "Operator", "Requested By", "Scope of Work", "Parts", "Labor", "Other", "Total", "Status", "Work Order", ""];
  return `<div class="table-wrap"><table><thead><tr>${heads.map((head) => `<th>${esc(head)}</th>`).join("")}</tr><tr>${heads.map((head, i) => head ? `<th><input class="column-filter" data-col="${i}" placeholder="Filter ${esc(head)}"></th>` : "<th></th>").join("")}</tr></thead><tbody>${rows.length ? rows.map((row) => `<tr>
    <td>${esc(row.quote_no || "")}</td><td>${esc(formatDisplayDate(row.quote_date))}</td><td>${esc(formatDisplayDate(row.expires_on))}</td>
    <td>${esc(row.customer_name || "")}</td><td><strong>${esc(row.asset_tag || "")}</strong><br>${esc(row.asset_description || "")}</td><td>${esc(row.operator || "")}</td><td>${esc(row.requested_by || "")}</td>
    <td>${esc(row.scope_of_work || "")}</td><td>${money(row.parts_amount || 0)}</td><td>${money(row.labor_amount || 0)}</td><td>${money(row.other_amount || 0)}</td>
    <td><strong>${money(row.total_amount || 0)}</strong></td><td>${badge(equipmentRepairQuoteEffectiveStatus(row))}</td><td>${esc(row.work_order_no || "")}</td>
    <td><div class="rowactions"><button class="rowbtn" data-repair-quote-pdf="${esc(row.quote_no)}">PDF</button><button class="rowbtn" data-repair-quote-email="${esc(row.quote_no)}">Email</button>${equipmentRepairQuoteEffectiveStatus(row) === "Pending" ? `<button class="rowbtn primary" data-repair-quote-convert="${esc(row.quote_no)}">Convert to Work Order</button>` : ""}<button class="rowbtn" data-repair-quote-edit="${esc(row.quote_no)}">${equipmentRepairQuoteEffectiveStatus(row) === "Expired" ? "View / Renew" : "Edit"}</button></div></td>
  </tr>`).join("") : `<tr><td colspan="${heads.length}" class="empty">No ${esc(equipmentRepairQuoteTab)} equipment repair quotes.</td></tr>`}</tbody></table></div>`;
}

function bindEquipmentRepairQuoteRows() {
  document.querySelectorAll("[data-repair-quote-pdf]").forEach((button) => button.onclick = () => printEquipmentRepairQuote(button.dataset.repairQuotePdf));
  document.querySelectorAll("[data-repair-quote-email]").forEach((button) => button.onclick = () => emailEquipmentRepairQuote(button.dataset.repairQuoteEmail));
  document.querySelectorAll("[data-repair-quote-edit]").forEach((button) => button.onclick = () => openEquipmentRepairQuoteModal(currentRows.find((row) => row.quote_no === button.dataset.repairQuoteEdit)));
  document.querySelectorAll("[data-repair-quote-convert]").forEach((button) => button.onclick = () => convertEquipmentRepairQuote(button.dataset.repairQuoteConvert));
  document.querySelectorAll(".column-filter").forEach((input) => input.oninput = applyColumnFilters);
}

async function emailEquipmentRepairQuote(quoteNo) {
  const quote = currentRows.find((row) => row.quote_no === quoteNo);
  if (!quote) return alert(`Equipment repair quote ${quoteNo} could not be found.`);
  const customers = await getAll("customers").catch(() => []);
  const quoteCustomer = normalizedMasterName(canonicalPartyName(quote.customer_name || ""));
  const customer = customers.find((row) => normalizedMasterName(canonicalPartyName(row.name || "")) === quoteCustomer) || {};
  const email = normalizeEmailRecipients(customer.email || "");
  if (!areValidEmailRecipients(email)) {
    return alert(`Customer ${quote.customer_name || ""} does not have valid email recipients in Customer Master.`);
  }
  const equipment = [quote.asset_tag, quote.asset_description].filter(Boolean).join(" - ");
  const subject = `Equipment repair quote ${quote.quote_no} — ${quote.customer_name || "Customer"}`;
  const body = [
    `Dear ${quote.customer_name || "Customer"} Team,`,
    "",
    `Please accept this formal submission of equipment repair quote ${quote.quote_no} from Landscape Management Systems, Inc.`,
    "",
    equipment ? `Equipment: ${equipment}` : null,
    `Estimated Total: ${money(quote.total_amount || 0)}`,
    quote.expires_on ? `Valid Until: ${formatDisplayDate(quote.expires_on)}` : null,
    "",
    "Please review the quote and let us know if you approve the proposed repair work or require any changes.",
    "",
    "Sincerely,",
    "Service Department",
    "Landscape Management Systems, Inc.",
  ].filter((line) => line !== null).join("\n");
  openEmailDraftDirect({ email, subject, body });
}

function printEquipmentRepairQuote(quoteNo) {
  const quote = currentRows.find((row) => row.quote_no === quoteNo);
  if (!quote) return alert(`Equipment repair quote ${quoteNo} could not be found.`);
  const parts = Array.isArray(quote.parts_details) ? quote.parts_details : [];
  const labor = Array.isArray(quote.labor_details) ? quote.labor_details : [];
  const itemizedLines = [
    ...parts.map((line) => [
      line.sku || "",
      line.product_name || line.description || "Estimated part",
      "Each",
      Number(line.qty || 0),
      money(line.unit_price || 0),
      money(Number(line.qty || 0) * Number(line.unit_price || 0)),
    ]),
    ...labor.map((line) => [
      "",
      line.description || "Estimated labor",
      "Hour",
      Number(line.hours || 0).toFixed(2),
      money(line.rate || 0),
      money(Number(line.hours || 0) * Number(line.rate || 0)),
    ]),
    ...(Number(quote.other_amount || 0) ? [["", "Other Estimated Cost", "Each", 1, money(quote.other_amount || 0), money(quote.other_amount || 0)]] : []),
  ];
  const summaryLines = [
    ...(Number(quote.parts_amount || 0) ? [["", "Estimated Parts", "Each", 1, money(quote.parts_amount || 0), money(quote.parts_amount || 0)]] : []),
    ...(Number(quote.labor_amount || 0) ? [["", "Estimated Labor", "Hour", 1, money(quote.labor_amount || 0), money(quote.labor_amount || 0)]] : []),
    ...(Number(quote.other_amount || 0) ? [["", "Other Estimated Cost", "Each", 1, money(quote.other_amount || 0), money(quote.other_amount || 0)]] : []),
  ];
  const html = printableDocumentHtml({
    title: "Equipment Repair Quote",
    number: quote.quote_no,
    date: quote.quote_date,
    compactHeader: true,
    partyLabel: "Customer",
    partyName: quote.customer_name || "",
    meta: [
      ["Asset #", quote.asset_tag || ""],
      ["Equipment", quote.asset_description || ""],
      ["Operator", quote.operator || ""],
      ["Requested By", quote.requested_by || ""],
      ["Customer PO", quote.customer_po || ""],
      ["Valid Until", quote.expires_on || ""],
      ["Jobsite", quote.jobsite_location || ""],
      ["Work Type", quote.work_type || "Repair"],
    ],
    heads: ["SKU", "Product Name / Description", "UOM", "Qty / Hours", "Rate", "Amount"],
    lines: itemizedLines.length ? itemizedLines : (summaryLines.length ? summaryLines : [["", "No estimated parts or labor entered", "", "", "", money(0)]]),
    total: Number(quote.total_amount || 0),
    totalLabel: "Estimated Total",
    notesLabel: "Scope of Work",
    notes: [
      quote.scope_of_work || "",
      quote.notes ? `Terms / Conditions:\n${quote.notes}` : "",
    ].filter(Boolean).join("\n\n"),
  });
  openPrintWindow(html, quote.quote_no || "equipment-repair-quote");
}

