function recalculateRepairQuotePricing() {
  let partsTotal = 0;
  document.querySelectorAll("#repairQuotePartsBody tr").forEach((tr) => {
    const qty = Number(tr.querySelector('[data-repair-quote-part="qty"]')?.value || 0);
    const price = Number(tr.querySelector('[data-repair-quote-part="unit_price"]')?.value || 0);
    const lineTotal = qty * price;
    partsTotal += lineTotal;
    const host = tr.querySelector("[data-repair-quote-part-total]");
    if (host) host.textContent = money(lineTotal);
  });
  let laborTotal = 0;
  document.querySelectorAll("#repairQuoteLaborBody tr").forEach((tr) => {
    const hours = Number(tr.querySelector('[data-repair-quote-labor="hours"]')?.value || 0);
    const rate = Number(tr.querySelector('[data-repair-quote-labor="rate"]')?.value || 0);
    const lineTotal = hours * rate;
    laborTotal += lineTotal;
    const host = tr.querySelector("[data-repair-quote-labor-total]");
    if (host) host.textContent = money(lineTotal);
  });
  const parts = document.querySelector('[data-product-field="parts_amount"]');
  const labor = document.querySelector('[data-product-field="labor_amount"]');
  const total = document.querySelector('[data-product-field="total_amount"]');
  const other = Number(document.querySelector('[data-product-field="other_amount"]')?.value || 0);
  if (parts) parts.value = partsTotal.toFixed(2);
  if (labor) labor.value = laborTotal.toFixed(2);
  if (total) total.value = (partsTotal + laborTotal + other).toFixed(2);
}

function bindRepairQuotePricingControls() {
  document.querySelectorAll("#repairQuotePartsBody tr").forEach((tr) => {
    const lookup = tr.querySelector('[data-repair-quote-part="lookup"]');
    const description = tr.querySelector('[data-repair-quote-part="description"]');
    const cost = tr.querySelector('[data-repair-quote-part="unit_cost"]');
    const markup = tr.querySelector('[data-repair-quote-part="markup_percent"]');
    const price = tr.querySelector('[data-repair-quote-part="unit_price"]');
    const applyRepairQuoteProduct = () => {
      if (!lookup.value.trim()) {
        [description, cost, markup, price, tr.querySelector('[data-repair-quote-part="qty"]')].filter(Boolean).forEach((input) => input.value = "");
        recalculateRepairQuotePricing();
        return;
      }
      const product = resolveProductLookup(lookup.value);
      if (product) {
        description.value = product.name || "";
        cost.value = Number(product.cost || 0).toFixed(2);
        markup.value = product.markup_percent ?? "";
        price.value = Number(product.price || workOrderPartSellingPrice({}, product) || 0).toFixed(2);
      }
      recalculateRepairQuotePricing();
    };
    if (lookup) {
      lookup.onchange = applyRepairQuoteProduct;
      lookup.oninput = () => {
        if (!lookup.value.trim() || isCommittedProductLookup(lookup.value)) applyRepairQuoteProduct();
      };
    }
    [tr.querySelector('[data-repair-quote-part="qty"]'), cost, markup, price].filter(Boolean).forEach((input) => input.oninput = () => {
      if (input === markup) price.value = (Number(cost.value || 0) * (1 + Number(markup.value || 0) / 100)).toFixed(2);
      recalculateRepairQuotePricing();
    });
  });
  document.querySelectorAll("[data-repair-quote-labor]").forEach((input) => input.oninput = recalculateRepairQuotePricing);
  const other = document.querySelector('[data-product-field="other_amount"]');
  if (other) other.oninput = recalculateRepairQuotePricing;
  recalculateRepairQuotePricing();
}

function parseRepairQuotePartRows() {
  return [...document.querySelectorAll("#repairQuotePartsBody tr")].map((tr) => {
    const get = (field) => tr.querySelector(`[data-repair-quote-part="${field}"]`)?.value || "";
    const lookup = get("lookup").trim();
    const product = resolveProductLookup(lookup);
    return { product_id: product?.id || null, sku: product?.sku || lookup, product_name: get("description").trim() || product?.name || lookup, qty: Number(get("qty") || 0), unit_cost: Number(get("unit_cost") || 0), markup_percent: get("markup_percent") === "" ? null : Number(get("markup_percent")), unit_price: Number(get("unit_price") || 0) };
  }).filter((line) => line.sku || line.product_name || line.qty);
}

function parseRepairQuoteLaborRows() {
  return [...document.querySelectorAll("#repairQuoteLaborBody tr")].map((tr) => {
    const get = (field) => tr.querySelector(`[data-repair-quote-labor="${field}"]`)?.value || "";
    return { description: get("description").trim(), hours: Number(get("hours") || 0), rate: Number(get("rate") || 0) };
  }).filter((line) => line.description || line.hours || line.rate);
}

