      income: allTotals.reduce((sum, row) => sum + row.income, 0), allocated_labor: allTotals.reduce((sum, row) => sum + row.allocated_labor, 0),
      unallocated_labor: allTotals.reduce((sum, row) => sum + row.unallocated_labor, 0), admin_labor: allTotals.reduce((sum, row) => sum + row.admin_labor, 0),
      total_labor: allTotals.reduce((sum, row) => sum + row.total_labor, 0), profit: allTotals.reduce((sum, row) => sum + row.profit, 0), utilization: "100.0% moves / 100.0% hours", is_total: true,
