      const weightFor = (index) => weightTotal > 0 ? Math.max(0, Number(rows[index].parts_revenue || 0)) : Math.abs(Number(rows[index].units || 0)) || 1;
      if (weightTotal <= 0) weightTotal = indexes.reduce((sum, index) => sum + weightFor(index), 0);
