function truckingQuoteLineAmount(line = {}) {
  const quantity = Math.max(0, Number(line.quantity || 0));
  const rate = Math.max(0, Number(line.unit_rate || 0));
  const roundTripMultiplier = String(line.trip_type || "One-Way") === "Round Trip" && !/hour/i.test(String(line.rate_type || "")) ? 2 : 1;
  return Number((quantity * rate * roundTripMultiplier).toFixed(2));
}

function truckingQuoteRateLabel(rate = {}) {
  return [rate.parent_service, rate.subcategory, rate.size_capacity, rate.service].filter(Boolean).join(" → ");
}

function truckingQuoteLineRow(line = {}, index = 0) {
  const activeRates = (productMeta.truckingRates || []).filter((rate) => !/inactive|tipping fee/i.test(`${rate.status || ""} ${rate.category || ""}`));
  const amount = truckingQuoteLineAmount(line);
  return `<tr data-trucking-quote-line>
    <td><select data-quote-line-field="service" required><option value="">Select move</option>${activeRates.map((rate) => `<option value="${esc(rate.service)}" ${rate.service === line.service ? "selected" : ""}>${esc(truckingQuoteRateLabel(rate))}</option>`).join("")}</select><small data-quote-rate-type>${esc(line.rate_type || "")}</small></td>
    <td><input type="date" data-quote-line-field="needed_date" value="${esc(line.needed_date || "")}"><select data-quote-line-field="delivery_period"><option>AM</option><option ${line.delivery_period === "PM" ? "selected" : ""}>PM</option></select></td>
    <td><select data-quote-line-field="trip_type"><option>One-Way</option><option ${line.trip_type === "Round Trip" ? "selected" : ""}>Round Trip</option></select></td>
    <td><input type="number" min="0.01" step="0.01" data-quote-line-field="quantity" value="${esc(line.quantity || 1)}"></td>
    <td><input type="number" min="0" step="0.01" data-quote-line-field="unit_rate" value="${esc(line.unit_rate ?? 0)}"></td>
    <td><input data-quote-line-field="origin" value="${esc(line.origin || "")}" placeholder="Origin"></td>
    <td><input data-quote-line-field="destination" value="${esc(line.destination || "")}" placeholder="Destination"></td>
    <td><textarea data-quote-line-field="description" placeholder="Move description">${esc(line.description || "")}</textarea></td>
    <td><strong data-quote-line-amount>${money(amount)}</strong><button type="button" class="danger" data-remove-trucking-quote-line>×</button></td>
  </tr>`;
}

function collectTruckingQuoteLines() {
  return [...modalBody.querySelectorAll("[data-trucking-quote-line]")].map((row, index) => {
    const get = (name) => row.querySelector(`[data-quote-line-field="${name}"]`)?.value ?? "";
    const rate = (productMeta.truckingRates || []).find((item) => item.service === get("service")) || {};
    const line = {
      line_no: index + 1,
      parent_service: rate.parent_service || rate.service || "",
      subcategory: rate.subcategory || "",
      size_capacity: rate.size_capacity || "",
      service: get("service"),
      rate_type: rate.rate_type || "",
      needed_date: get("needed_date") || null,
      delivery_period: get("delivery_period") || "AM",
      trip_type: get("trip_type") || "One-Way",
      quantity: Number(get("quantity") || 0),
      unit_rate: Number(get("unit_rate") || 0),
      origin: get("origin").trim(),
      destination: get("destination").trim(),
      description: get("description").trim(),
    };
    line.line_total = truckingQuoteLineAmount(line);
    return line;
  });
}

function recalculateTruckingQuotation() {
  const lines = collectTruckingQuoteLines();
  [...modalBody.querySelectorAll("[data-trucking-quote-line]")].forEach((row, index) => {
    const amount = row.querySelector("[data-quote-line-amount]");
    if (amount) amount.textContent = money(lines[index]?.line_total || 0);
  });
  const subtotal = lines.reduce((sum, line) => sum + line.line_total, 0);
  const discountPercent = Math.min(100, Math.max(0, Number(modalBody.querySelector('[name="discount_percent"]')?.value || 0)));
  const discount = Number((subtotal * discountPercent / 100).toFixed(2));
  const total = Number((subtotal - discount).toFixed(2));
  if ($("truckingQuoteSubtotal")) $("truckingQuoteSubtotal").textContent = money(subtotal);
  if ($("truckingQuoteDiscount")) $("truckingQuoteDiscount").textContent = money(discount);
  if ($("truckingQuoteTotal")) $("truckingQuoteTotal").textContent = money(total);
  return { lines, subtotal, discountPercent, discount, total };
}

function bindTruckingQuoteLines() {
  modalBody.querySelectorAll("[data-trucking-quote-line]").forEach((row) => {
    const service = row.querySelector('[data-quote-line-field="service"]');
    service.onchange = () => {
      const rate = (productMeta.truckingRates || []).find((item) => item.service === service.value) || {};
      row.querySelector('[data-quote-line-field="unit_rate"]').value = Number(rate.rate || 0);
      row.querySelector("[data-quote-rate-type]").textContent = rate.rate_type || "";
      const description = row.querySelector('[data-quote-line-field="description"]');
      if (!description.value.trim()) description.value = truckingQuoteRateLabel(rate);
      recalculateTruckingQuotation();
    };
    row.querySelectorAll("input, select, textarea").forEach((input) => {
      if (input !== service) input.oninput = recalculateTruckingQuotation;
    });
    row.querySelector("[data-remove-trucking-quote-line]").onclick = () => {
      if (modalBody.querySelectorAll("[data-trucking-quote-line]").length === 1) return alert("A quotation needs at least one move.");
      row.remove();
      recalculateTruckingQuotation();
    };
  });
}

async function renderTruckingQuotationsView() {
  currentCfg = tableMap.truckingquotes;
  $("viewTitle").textContent = "Trucking Quotations";
  $("viewSub").textContent = "Quote multiple trucking moves, record acceptance, and create dispatch-ready Move Requests.";
  await loadTruckingLookups();
  const [quotes, lines] = await Promise.all([getAll("trucking_quotations").catch(() => []), getAll("trucking_quotation_lines").catch(() => [])]);
  productMeta.truckingQuotationLines = lines;
  currentRows = quotes.map((quote) => ({ ...quote, line_count: lines.filter((line) => line.quote_no === quote.quote_no).length }))
    .sort((a, b) => String(b.quote_date || "").localeCompare(String(a.quote_date || "")) || String(b.quote_no || "").localeCompare(String(a.quote_no || "")));
  $("content").innerHTML = `<div class="toolbar"><input class="searchbox" id="truckingQuoteSearch" placeholder="Search quote, customer, jobsite, or status"></div><section class="panel"><div class="panel-head"><div class="panel-title"><strong>Trucking Quotations</strong><span>${currentRows.length} quotation${currentRows.length === 1 ? "" : "s"}</span></div><div class="actions"><button onclick="exportRowsCsv(currentRows, 'trucking-quotations.csv')">Excel</button><button onclick="window.print()">PDF / Print</button><button class="primary" onclick="openTruckingQuotationModal()">New quotation</button></div></div><div class="notice"><strong>Operational workflow only:</strong> Saving or accepting a trucking quotation creates no invoice, receivable, journal entry, or other accounting transaction. Acceptance creates Move Requests only.</div><div id="truckingQuoteHost"></div></section>`;
  const render = () => {
    const query = String($("truckingQuoteSearch")?.value || "").toLowerCase();
    const rows = currentRows.filter((row) => !query || Object.values(row).join(" ").toLowerCase().includes(query));
    $("truckingQuoteHost").innerHTML = truckingSimpleTable(rows, ["quote_no", "quote_date", "valid_until", "customer", "project_jobsite", "line_count", "subtotal", "discount_amount", "total", "status"], {
      labels: ["Quote #", "Date", "Valid Until", "Customer", "Project / Jobsite", "Moves", "Subtotal", "Discount", "Total", "Status"],
      format: { subtotal: (value) => money(value || 0), discount_amount: (value) => money(value || 0), total: (value) => `<strong>${money(value || 0)}</strong>`, status: (value) => badge(value || "Draft") },
      actions: (row) => `<button onclick="printTruckingQuotation('${esc(row.quote_no)}')">PDF</button><button onclick="openTruckingQuotationModal('${esc(row.quote_no)}')">${/accepted|converted/i.test(row.status || "") ? "View" : "Edit"}</button>${!/accepted|converted|cancelled/i.test(row.status || "") ? `<button class="primary" onclick="acceptTruckingQuotation('${esc(row.quote_no)}')">Accept → Move Requests</button>` : ""}`,
    });
  };
  $("truckingQuoteSearch").oninput = render;
  render();
}

async function openTruckingQuotationModal(quoteNo = "") {
  await loadTruckingLookups();
  const quotes = await getAll("trucking_quotations").catch(() => currentRows || []);
  const quote = quoteNo ? quotes.find((row) => row.quote_no === quoteNo) : null;
  const savedLines = quoteNo ? (await getAll("trucking_quotation_lines").catch(() => productMeta.truckingQuotationLines || [])).filter((line) => line.quote_no === quoteNo).sort((a, b) => a.line_no - b.line_no) : [];
  const number = quote?.quote_no || `TQ-${Math.max(1000, ...quotes.map((row) => Number(String(row.quote_no || "").replace(/\D/g, ""))).filter(Boolean)) + 1}`;
  const readOnly = /accepted|converted|cancelled/i.test(quote?.status || "");
  modalTitle.textContent = quote ? `${readOnly ? "View" : "Edit"} trucking quotation ${number}` : `New trucking quotation ${number}`;
  modalBody.innerHTML = `<div class="form-grid"><label>Quote #<input name="quote_no" value="${esc(number)}" readonly></label><label>Quote date<input type="date" name="quote_date" value="${esc(quote?.quote_date || truckingToday())}"></label><label>Valid until<input type="date" name="valid_until" value="${esc(quote?.valid_until || "")}"></label><label>Customer<input class="suggest-input" name="customer" data-suggest-source="customers" value="${esc(quote?.customer || "")}" autocomplete="off" required></label><label>Project / Jobsite<input name="project_jobsite" list="truckJobsiteOptions" value="${esc(quote?.project_jobsite || "")}" required></label><label>Contact #<input name="contact_no" value="${esc(quote?.contact_no || "")}"></label><label>Requested by<input name="requested_by" value="${esc(quote?.requested_by || profile?.full_name || profile?.username || "")}" required></label><label>Email<input type="email" name="requestor_email" value="${esc(quote?.requestor_email || profile?.email || session?.user?.email || "")}" required></label><label>Mode of payment<select name="payment_mode"><option>PO</option><option>Cash</option><option>Credit Card</option></select></label><label>PO #<input name="po_no" value="${esc(quote?.po_no || "")}"></label><label>Discount %<input type="number" min="0" max="100" step="0.01" name="discount_percent" value="${esc(quote?.discount_percent || 0)}"></label><label>Status<input value="${esc(quote?.status || "Draft")}" readonly></label></div><div class="field wide"><label>Quoted moves</label><div class="table-wrap"><table><thead><tr><th>Move</th><th>Needed / AM-PM</th><th>Trip</th><th>Qty / Hours</th><th>Rate</th><th>Origin</th><th>Destination</th><th>Description</th><th>Amount</th></tr></thead><tbody id="truckingQuoteLineBody">${(savedLines.length ? savedLines : [{}]).map(truckingQuoteLineRow).join("")}</tbody></table></div><button type="button" id="addTruckingQuoteLineBtn">Add move</button></div><label class="wide">Notes<textarea name="notes">${esc(quote?.notes || "")}</textarea></label><div class="summary-cards"><div><span>Subtotal</span><strong id="truckingQuoteSubtotal">${money(quote?.subtotal || 0)}</strong></div><div><span>Discount</span><strong id="truckingQuoteDiscount">${money(quote?.discount_amount || 0)}</strong></div><div><span>Quotation Total</span><strong id="truckingQuoteTotal">${money(quote?.total || 0)}</strong></div></div>${truckingDatalists()}`;
  modalBody.querySelector('[name="payment_mode"]').value = quote?.payment_mode || "PO";
  $("addTruckingQuoteLineBtn").onclick = () => { $("truckingQuoteLineBody").insertAdjacentHTML("beforeend", truckingQuoteLineRow({}, modalBody.querySelectorAll("[data-trucking-quote-line]").length)); bindTruckingQuoteLines(); recalculateTruckingQuotation(); };
  bindTruckingQuoteLines();
  recalculateTruckingQuotation();
  truckingEnhanceSuggestInputs(modalBody);
  modalSave.textContent = readOnly ? "Close" : "Save quotation";
  modalSave.onclick = readOnly ? closeModal : () => saveTruckingQuotation(quoteNo);
  modalBody.querySelectorAll("input, select, textarea, button").forEach((control) => { if (readOnly && control !== modalSave) control.disabled = true; });
  document.querySelector(".modalbox")?.classList.add("wide-modal");
  $("modal").style.display = "flex";
}

async function saveTruckingQuotation(previousNo = "") {
  const values = Object.fromEntries([...modalBody.querySelectorAll(":scope > .form-grid [name], :scope > label [name]")].map((el) => [el.name, el.value]));
  values.valid_until = String(values.valid_until || "").trim() || null;
  const totals = recalculateTruckingQuotation();
  if (!values.customer?.trim()) return alert("Customer is required.");
  if (!values.project_jobsite?.trim()) return alert("Project / Jobsite is required.");
  if (!totals.lines.length || totals.lines.some((line) => !line.service)) return alert("Select a move for every quotation line.");
  if (totals.lines.some((line) => line.quantity <= 0)) return alert("Quantity / Hours must be greater than zero for every move.");
  const header = { ...values, quote_no: previousNo || values.quote_no, status: "Draft", discount_percent: totals.discountPercent, subtotal: totals.subtotal, discount_amount: totals.discount, total: totals.total };
  const { error } = await supabase.from("trucking_quotations").upsert(header, { onConflict: "quote_no" });
  if (error) return alert(error.message || "Could not save the trucking quotation.");
  await supabase.from("trucking_quotation_lines").delete().eq("quote_no", header.quote_no);
  const { error: lineError } = await supabase.from("trucking_quotation_lines").insert(totals.lines.map((line) => ({ ...line, quote_no: header.quote_no })));
  if (lineError) return alert(lineError.message || "Could not save quotation moves.");
  closeModal();
  await renderTruckingQuotationsView();
}

async function acceptTruckingQuotation(quoteNo = "") {
  const quote = (await getAll("trucking_quotations")).find((row) => row.quote_no === quoteNo);
  const lines = (await getAll("trucking_quotation_lines")).filter((line) => line.quote_no === quoteNo).sort((a, b) => a.line_no - b.line_no);
  if (!quote || !lines.length) return alert("This quotation has no saved moves.");
  if (/accepted|converted/i.test(quote.status || "")) return alert("This quotation was already converted.");
  if (!confirm(`Accept ${quoteNo} and create ${lines.length} Move Request${lines.length === 1 ? "" : "s"}?`)) return;
  const requests = await getAll("trucking_requests");
  const created = [];
  for (const line of lines) {
    const requestNo = truckingNextRequestNo([...requests, ...created]);
    const request = { request_no: requestNo, request_date: truckingToday(), customer: quote.customer, project_jobsite: quote.project_jobsite, project: quote.project_jobsite, jobsite: quote.project_jobsite, contact_no: quote.contact_no || "", needed_date: line.needed_date || null, delivery_period: line.delivery_period || "AM", trip_type: line.trip_type || "One-Way", payment_mode: quote.payment_mode || "PO", po_no: quote.po_no || "", service_needed: line.parent_service || line.service, service_subcategory: line.subcategory || "", service_size: line.size_capacity || "", service_option: line.service, origin: line.origin || "", destination: line.destination || "", requested_by: quote.requested_by || "", requestor_email: quote.requestor_email || "", move_description: line.description || truckingQuoteRateLabel(line), notes: line.description || truckingQuoteRateLabel(line), status: "Requested", quote_no: quoteNo };
    const { error } = await supabase.from("trucking_requests").insert(request);
    if (error) return alert(`Could not create Move Request for line ${line.line_no}: ${error.message || error}`);
    const { error: lineError } = await supabase.from("trucking_request_lines").insert({ request_no: requestNo, line_no: 1, service: line.service, origin: line.origin || "", destination: line.destination || "", equipment_label: line.description || truckingQuoteRateLabel(line), notes: `Created from ${quoteNo}`, status: "Requested" });
    if (lineError) return alert(`Move Request ${requestNo} was created, but its move line failed: ${lineError.message || lineError}`);
    await supabase.from("trucking_quotation_lines").update({ request_no: requestNo }).eq("quote_no", quoteNo).eq("line_no", line.line_no);
    created.push(request);
  }
  const { error: statusError } = await supabase.from("trucking_quotations").update({ status: "Converted", accepted_at: new Date().toISOString() }).eq("quote_no", quoteNo);
  if (statusError) return alert(`Move Requests were created, but the quotation status could not be updated: ${statusError.message || statusError}`);
  alert(`${quoteNo} accepted. Created Move Request${created.length === 1 ? "" : "s"}: ${created.map((row) => row.request_no).join(", ")}`);
  await renderTruckingQuotationsView();
}

async function printTruckingQuotation(quoteNo = "") {
  const quote = (await getAll("trucking_quotations")).find((row) => row.quote_no === quoteNo);
  const lines = (await getAll("trucking_quotation_lines")).filter((line) => line.quote_no === quoteNo).sort((a, b) => a.line_no - b.line_no);
  if (!quote) return alert("Quotation not found.");
  const win = openInAppDocumentWindow(`Trucking Quotation ${quoteNo}`);
  if (!win) return alert("Allow popups to print the quotation.");
  win.document.write(`<!doctype html><html><head><title>${esc(quoteNo)}</title><style>@page{size:Letter;margin:.45in}body{font-family:Arial;color:#17212b}h1{margin-bottom:2px}.meta{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:18px 0}table{width:100%;border-collapse:collapse;font-size:10px}th,td{border:1px solid #9aa8b5;padding:6px;text-align:left}th{background:#eaf1f5}.num{text-align:right}.totals{width:42%;margin:12px 0 0 auto}.totals div{display:flex;justify-content:space-between;padding:6px;border-bottom:1px solid #aaa}.grand{font-size:16px;font-weight:900}</style></head><body><h1>Trucking Quotation</h1><strong>${esc(quoteNo)}</strong><div class="meta"><div><b>Customer:</b> ${esc(quote.customer || "")}</div><div><b>Date:</b> ${esc(formatDisplayDate(quote.quote_date))}</div><div><b>Project / Jobsite:</b> ${esc(quote.project_jobsite || "")}</div><div><b>Valid Until:</b> ${esc(formatDisplayDate(quote.valid_until))}</div></div><table><thead><tr><th>#</th><th>Move</th><th>Trip</th><th>Qty / Hours</th><th>Rate</th><th>Description</th><th class="num">Amount</th></tr></thead><tbody>${lines.map((line) => `<tr><td>${line.line_no}</td><td>${esc(truckingQuoteRateLabel(line))}</td><td>${esc(line.trip_type)}</td><td>${esc(line.quantity)}</td><td>${money(line.unit_rate)} ${esc(line.rate_type || "")}</td><td>${esc(line.description || "")}</td><td class="num">${money(line.line_total)}</td></tr>`).join("")}</tbody></table><div class="totals"><div><span>Subtotal</span><b>${money(quote.subtotal)}</b></div><div><span>Discount</span><b>${money(quote.discount_amount)}</b></div><div class="grand"><span>Total</span><b>${money(quote.total)}</b></div></div><p>${esc(quote.notes || "")}</p><script>window.addEventListener('load',()=>window.print())</script></body></html>`);
  win.document.close();
}

async function renderTruckingRatesView() {
  currentCfg = tableMap.truckingrates;
  $("viewTitle").textContent = "Trucking Rate Sheet";
  $("viewSub").textContent = "Rates and tipping fees for trucking support. No accounting entries are created.";
  currentRows = await getAll("trucking_rates").catch(() => []);
  $("content").innerHTML = `
    <div class="toolbar"><input class="searchbox" id="truckRateSearch" placeholder="Search super parent, move type, size, rate key, fee, or category"></div>
    <section class="panel">
      <div class="panel-head">
        <div class="panel-title"><strong>Rate Sheet</strong><span>${esc(currentRows.length)} rates shown.</span></div>
        <div class="actions"><button onclick="exportRowsCsv(currentRows, 'trucking-rates.csv')">Excel</button><button onclick="window.print()">PDF / Print</button><button class="primary" onclick="openTruckingRateForm()">Add rate</button></div>
      </div>
      <div id="truckRateHost">${truckingRatesTable(currentRows)}</div>
    </section>`;
  $("truckRateSearch").oninput = () => $("truckRateHost").innerHTML = truckingRatesTable(currentRows || []);
}

function truckingRatesTable(rows) {
  const sorted = [...rows].sort((a, b) =>
    String(a.parent_service || a.category || "").localeCompare(String(b.parent_service || b.category || ""), undefined, { sensitivity: "base" })
    || String(a.service || "").localeCompare(String(b.service || ""), undefined, { numeric: true, sensitivity: "base" })
  );
  return truckingSimpleTable(sorted.filter((row) => truckingRowMatchesSearch(row, $("truckRateSearch")?.value || "")), ["parent_service", "subcategory", "size_capacity", "service", "reference_label", "requires_equipment", "rate", "rate_type", "additional", "category", "status"], {
    labels: ["Super Parent", "Subcategory / Move Type", "Size / Capacity", "Rate Key", "Required Reference", "Equipment Lookup", "Rate", "Type", "Additional", "Category", "Status"],
    format: { rate: (value) => money(value || 0), status: (value) => badge(value || "Active") },
    actions: (row) => `<button onclick="openTruckingRateForm('${esc(row.service)}')">Edit</button><button onclick="copyTruckingRate('${esc(row.service)}')">Copy</button>${isAdminUser() && !/inactive/i.test(row.status || "") ? `<button class="danger" onclick="deactivateTruckingRate('${esc(row.service)}')">Deactivate</button>` : ""}`,
  });
}

async function deactivateTruckingRate(service = "") {
  if (!isAdminUser()) return alert("Only administrators can deactivate rates.");
  const rate = (await getAll("trucking_rates").catch(() => [])).find((item) => item.service === service);
  if (!rate) return alert("Rate not found.");
  const hierarchy = [rate.parent_service, rate.subcategory, rate.size_capacity, rate.service].filter(Boolean).join(" → ");
  if (!confirm(`Deactivate this rate?\n\n${hierarchy}\n\nExisting requests and tickets will keep their rate history.`)) return;
  const { error } = await supabase.from("trucking_rates").update({ status: "Inactive" }).eq("service", service);
  if (error) return alert(error.message || "Could not deactivate the rate.");
  productMeta.truckingLoaded = false;
  await renderTruckingRatesView();
}

async function copyTruckingRate(service = "") {
  return openTruckingRateForm(service, true);
}

async function openTruckingRateForm(service = "", copyMode = false) {
  const liveRates = await getAll("trucking_rates").catch(() => productMeta.truckingRates || []);
  const row = service ? liveRates.find((item) => item.service === service) : null;
  const standardParents = ["Equipment Move", "Container/Trailer Move", "High Deck Trailer", "Highbed/Chameleon", "Flatrack/Chameleon", "Dump Truck", "End Dump", "Water Service", "Waste Water Pump Services", "Roll Off Service", "Pump Service"];
  const savedParents = liveRates
    .filter((rate) => String(rate.category || "").trim().toLowerCase() !== "tipping fee")
    .map((rate) => String(rate.parent_service || "").trim())
    .filter(Boolean);
  const parentChoices = [...new Set([...standardParents, ...savedParents])].sort((a, b) => a.localeCompare(b, undefined, { sensitivity: "base" }));
  const selectedParent = row?.category === "Tipping Fee" ? "Roll Off Service" : String(row?.parent_service || "");
  modalTitle.textContent = copyMode && row ? `Copy rate ${service}` : (row ? `Edit rate ${service}` : "New trucking rate");
  modalBody.innerHTML = `
    <div class="rate-sheet-form">
    <div class="form-grid">
      <label>Super Parent<select name="parent_service_choice" required>
        <option value="">Select Super Parent</option>
        ${parentChoices.map((value) => `<option value="${esc(value)}" ${value === selectedParent ? "selected" : ""}>${esc(value)}</option>`).join("")}
        ${isAdminUser() ? `<option value="__new__">+ Create new Super Parent</option>` : ""}
      </select><small>This controls which main service dropdown contains this rate.</small></label>
      ${isAdminUser() ? `<label id="newTruckParentField" hidden>New Super Parent<input name="parent_service_new" placeholder="Enter the new main service name"></label>` : ""}
      <label>Subcategory / move type<input name="subcategory" value="${esc(row?.subcategory || "")}" placeholder="Example: Sidelifter"></label>
      <label>Size / capacity<input name="size_capacity" value="${esc(row?.size_capacity || "")}" placeholder="Example: 40 ft or 0-1,000 gallon"></label>
      <label>Rate key (optional)<input name="service" value="${copyMode ? "" : esc(row?.service || "")}" placeholder="Generated from the selections above"><small>Leave blank to generate a unique pricing key from Super Parent, Move Type, and Size.</small></label>
      <label>Required reference label<input name="reference_label" value="${esc(row?.reference_label || "")}" placeholder="Example: Container / Trailer number"></label>
      <label class="remember-login"><input type="checkbox" name="requires_equipment" ${row?.requires_equipment ? "checked" : ""}> Require Equipment Master lookup</label>
      <label>Rate<input type="number" step="0.01" name="rate" value="${esc(row?.rate || 0)}"></label>
      <label>Type<select name="rate_type"><option>Hourly</option><option>Flat Rate</option><option>Daily</option><option>/cy</option><option>/ton</option></select></label>
      <label>Category<select name="category"><option>Service</option><option>Tipping Fee</option><option>Fuel/Water</option></select></label>
      <label>Status<select name="status"><option>Active</option><option>Inactive</option></select></label>
    </div>
    <label class="rate-sheet-notes">Additional / notes<textarea name="additional">${esc(row?.additional || "")}</textarea></label>
    </div>`;
  modalBody.querySelector("[name=rate_type]").value = row?.rate_type || "Hourly";
  modalBody.querySelector("[name=category]").value = row?.category || "Service";
  modalBody.querySelector("[name=status]").value = copyMode ? "Active" : (row?.status || "Active");
  const rateCategoryInput = modalBody.querySelector("[name=category]");
  const parentServiceInput = modalBody.querySelector("[name=parent_service_choice]");
  const newParentField = $("newTruckParentField");
  const syncNewParentField = () => {
    if (newParentField) newParentField.hidden = parentServiceInput.value !== "__new__";
    if (parentServiceInput.value === "__new__") newParentField?.querySelector("input")?.focus();
  };
  parentServiceInput.onchange = syncNewParentField;
  parentServiceInput.oninput = syncNewParentField;
  rateCategoryInput.onchange = () => {
    if (rateCategoryInput.value === "Tipping Fee") {
      parentServiceInput.value = "Roll Off Service";
      parentServiceInput.disabled = true;
      if (newParentField) newParentField.hidden = true;
    } else {
      parentServiceInput.disabled = false;
      syncNewParentField();
    }
  };
  rateCategoryInput.onchange();
  modalSave.onclick = async () => {
    const payload = Object.fromEntries([...modalBody.querySelectorAll("[name]")]
      .filter((el) => el.type !== "checkbox")
      .map((el) => [el.name, el.value]));
    payload.requires_equipment = !!modalBody.querySelector('[name="requires_equipment"]')?.checked;
    payload.parent_service = payload.category === "Tipping Fee"
      ? "Roll Off Service"
      : (payload.parent_service_choice === "__new__" ? String(payload.parent_service_new || "").trim() : String(payload.parent_service_choice || "").trim());
    delete payload.parent_service_choice;
    delete payload.parent_service_new;
    if (!payload.parent_service) {
      if (parentServiceInput.value === "__new__") {
        newParentField?.querySelector("input")?.focus();
        return alert("Enter the name of the new Super Parent.");
      }
      parentServiceInput.focus();
      return alert("Select a Super Parent.");
    }
    payload.service = String(payload.service || "").trim() || [payload.parent_service, payload.subcategory, payload.size_capacity]
      .map((value) => String(value || "").trim())
      .filter(Boolean)
      .join(" | ");
    if (!payload.service) return alert("Enter a Move Type, Size / Capacity, or Rate Key.");
    const duplicate = liveRates.find((rate) => String(rate.service || "").trim().toLowerCase() === payload.service.toLowerCase());
    if ((!row || copyMode) && duplicate) return alert(`A rate with the key "${payload.service}" already exists. Add a Size / Capacity or enter a different Rate Key.`);
    const { error } = await supabase.from("trucking_rates").upsert(payload, { onConflict: "service" });
    if (error) return alert(error.message || "Could not save rate.");
    closeModal();
    productMeta.truckingLoaded = false;
    await renderTruckingRatesView();
  };
  $("modal").style.display = "flex";
}

