async function reverseFuelReport(reportNo) {
  if (!isAdminUser()) return alert("Only administrators can reverse fuel logs.");
  const clean = String(reportNo || "").trim();
  if (!clean) return alert("Missing fuel report number.");
  const reason = prompt(`Reason for reversing fuel report ${clean}`, "Entered in error");
  if (reason === null || !reason.trim()) return;
  if (!confirm(`Reverse fuel report ${clean}? Every line will remain in history as Reversed.`)) return;
  const rows = currentRows.filter((row) => row.report_no === clean);
  const notes = [rows[0]?.notes, `Reversed ${new Date().toLocaleString()}: ${reason.trim()}`].filter(Boolean).join(" | ");
  const { error: tankError } = await supabase.rpc("reverse_fuel_tank_report", {
    p_report_no: clean,
    p_actor: fuelActorName(),
    p_reason: reason.trim(),
  });
  if (tankError) return alert(tankError.message || "Could not restore the fuel tank balance for this reversal.");
  const { error } = await supabase.from("fuel_logs").update({ status: "Reversed", notes }).eq("report_no", clean);
  if (error) return alert(error.message || "Could not reverse fuel report.");
  await renderFuelPortalView();
}

