function motherPartComponentRows(links = [], motherProductId = "") {
  const productsById = new Map((productMeta.products || []).map((product) => [String(product.id), product]));
  const values = [...links.map((link) => ({ ...link, component: productsById.get(String(link.component_product_id)) })), { component: null, quantity_required: 1 }];
  return `<div class="table-wrap"><table class="mini-table"><thead><tr><th>Related Part #</th><th>Suggested qty per mother part</th><th></th></tr></thead><tbody id="motherPartComponentBody">${values.map((value, index) => motherPartComponentRowHtml(value, index)).join("")}</tbody></table></div><div class="actions table-actions"><button class="rowbtn" type="button" id="addMotherComponentBtn">Add related part</button></div><small>Uses the application Part # search. Add as many related parts as needed.</small>`;
}

function motherPartComponentRowHtml(row = {}, index = 0) {
  const component = row.component || (productMeta.products || []).find((product) => String(product.id) === String(row.component_product_id || ""));
  const label = component ? `${component.sku} - ${component.name || ""}` : "";
  return `<tr><td><input class="suggest-input" data-suggest-source="products" data-mother-component="${index}" value="${esc(label)}" placeholder="Type Part #, product name, alternate, cross-reference, or vendor" autocomplete="off" inputmode="search"></td><td><input type="number" min="0.0001" step="0.0001" data-mother-component-qty="${index}" value="${esc(Number(row.quantity_required || 1))}"></td><td><button class="rowbtn danger" type="button" data-remove-mother-component>Remove</button></td></tr>`;
}

function addMotherPartComponentRow() {
  const body = $("motherPartComponentBody");
  if (!body) return;
  const index = document.querySelectorAll("[data-mother-component]").length;
  body.insertAdjacentHTML("beforeend", motherPartComponentRowHtml({}, index));
  document.querySelector(`[data-mother-component="${index}"]`)?.focus();
}

function bindMotherPartComponentRows() {
  const addButton = $("addMotherComponentBtn");
  if (addButton) addButton.onclick = addMotherPartComponentRow;
  const body = $("motherPartComponentBody");
  if (body && !body.dataset.removeBound) {
    body.dataset.removeBound = "true";
    body.addEventListener("click", (event) => {
      const button = event.target.closest("[data-remove-mother-component]");
      if (!button) return;
      const row = button.closest("tr");
      if (!row) return;
      const rows = body.querySelectorAll("tr");
      if (rows.length === 1) {
        row.querySelector("[data-mother-component]").value = "";
        row.querySelector("[data-mother-component-qty]").value = "1";
      } else row.remove();
    });
  }
}

function motherPartDefaultValue(values, preferred) {
  const match = (values || []).find((value) => String(value || "").trim().toLowerCase() === String(preferred || "").toLowerCase());
  return match || (values || []).find((value) => String(value || "").trim()) || "";
}

