async function saveCreateMotherPartModal() {
  const sku = String(document.querySelector('[data-mother-master-field="sku"]')?.value || "").trim();
  const name = String(document.querySelector('[data-mother-master-field="name"]')?.value || "").trim();
  if (!sku || !name) return alert("Mother SKU # and Description are required.");
  const record = {
    sku,
    name,
    category: motherPartDefaultValue(productMeta.categories, "Service Parts"),
    unit: motherPartDefaultValue(productMeta.units, "Each"),
    warehouse: motherPartDefaultValue(productMeta.warehouses, "Mall Lot Parts Shop"),
    qty: 0,
    reorder_point: 0,
    cost: 0,
    selling_price: 0,
    markup_percent: null,
    status: "Active",
    source_vendor: null,
    expiry_date: null,
    notes: "Mother-part grouping SKU",
  };
  if (!record.category || !record.unit || !record.warehouse) return alert("Create at least one Product Category, Unit, and Warehouse before creating a mother part.");
  try {
    if (!await approveProductMasterCreation(record)) return;
    const saved = await insertNewProduct(record);
    await saveProductMotherComponents(saved);
    await incrementSequence("product");
    closeModal();
    alert(`${saved.sku} - ${saved.name} was created as a mother part.`);
    await renderProductsView();
  } catch (error) {
    alert(error.message || error);
  }
}

async function saveProductMotherComponents(product) {
  const links = [...document.querySelectorAll("[data-mother-component]")].map((input) => {
    const index = input.dataset.motherComponent;
    const component = resolveProductLookup(input.value);
    const quantity = Number(document.querySelector(`[data-mother-component-qty="${index}"]`)?.value || 0);
    return { input, component, quantity };
  }).filter((row) => row.input.value.trim());
  const invalid = links.find((row) => !row.component || !(row.quantity > 0));
  if (invalid) throw new Error("Every Mother Part component row needs a valid Product Master SKU and a quantity greater than zero.");
  if (links.some((row) => String(row.component.id) === String(product.id))) throw new Error("A mother part cannot contain itself as a component.");
  const componentIds = links.map((row) => String(row.component.id));
  if (new Set(componentIds).size !== componentIds.length) throw new Error("The same component SKU cannot appear more than once. Combine it into one quantity.");
  const nestedMotherIds = new Set((productMeta.motherPartComponents || []).map((link) => String(link.mother_product_id)));
  const nested = links.find((row) => nestedMotherIds.has(String(row.component.id)));
  if (nested) throw new Error(`${nested.component.sku} is already a mother part. Nested mother-part sets are not supported; link its individual components instead.`);
  if (links.length) {
    const { error } = await supabase.from("product_mother_components").upsert(links.map((row) => ({ mother_product_id: product.id, component_product_id: row.component.id, quantity_required: row.quantity })), { onConflict: "mother_product_id,component_product_id" });
    if (error) throw new Error(`${error.message || error}\n\nRun the Mother Part Components SQL migration before saving this relationship.`);
  }
  const desiredIds = new Set(componentIds);
  const existingLinks = (productMeta.motherPartComponents || []).filter((link) => String(link.mother_product_id) === String(product.id));
  const obsoleteIds = existingLinks.filter((link) => !desiredIds.has(String(link.component_product_id))).map((link) => link.id).filter(Boolean);
  if (obsoleteIds.length) {
    const { error: deleteError } = await supabase.from("product_mother_components").delete().in("id", obsoleteIds);
    if (deleteError) throw deleteError;
  }
  if (!links.length && !existingLinks.length) {
    const { error: probeError } = await supabase.from("product_mother_components").select("id").limit(1);
    if (probeError && !/product_mother_components|schema cache|relation/i.test(String(probeError.message || ""))) throw probeError;
  }
}

async function deductProductWithMotherComponents(product, quantity) {
  const qty = Number(quantity || 0);
  if (!product?.id || !(qty > 0)) throw new Error("Choose a valid product and enter an issue quantity greater than zero.");
  const { data: links, error: linkError } = await supabase.from("product_mother_components").select("component_product_id,quantity_required").eq("mother_product_id", product.id);
  if (linkError && !/product_mother_components|schema cache|relation/i.test(String(linkError.message || ""))) throw linkError;
  if (linkError || !(links || []).length) {
    const nextQty = Number(product.qty || 0) - qty;
    if (nextQty < -0.0001) throw new Error(`${product.sku} has only ${Number(product.qty || 0)} on hand.`);
    const { data, error } = await supabase.from("products").update({ qty: nextQty }).eq("id", product.id).select("id,sku,name,qty").maybeSingle();
    if (error) throw error;
    if (!data) throw new Error(`Inventory for ${product.sku} could not be deducted.`);
    product.qty = Number(data.qty ?? nextQty);
    return [{ product, quantity_deducted: qty, new_quantity: product.qty, is_component: false, mother_sku: product.sku }];
  }
  const allProducts = productMeta.products?.length ? productMeta.products : await getAll("products");
  const selectedComponentIds = await chooseOptionalMotherComponents(product, qty, links, allProducts);
  if (selectedComponentIds == null) throw new Error("Mother-part selection was cancelled. No inventory was deducted.");
  const { data, error } = await supabase.rpc("deduct_product_with_mother_components", { p_product_id: product.id, p_quantity: qty, p_component_ids: selectedComponentIds });
  if (error) throw new Error(`${error.message || error}\n\nThe mother part was not issued. Confirm component stock and run the Mother Part Components SQL migration.`);
  return (data || []).map((deduction) => {
    const matched = allProducts.find((item) => String(item.id) === String(deduction.product_id)) || (String(product.id) === String(deduction.product_id) ? product : { id: deduction.product_id, sku: deduction.sku, name: deduction.product_name });
    matched.qty = Number(deduction.new_quantity || 0);
    return { ...deduction, product: matched };
  });
}

function chooseOptionalMotherComponents(motherProduct, motherQuantity, links = [], products = []) {
  return new Promise((resolve) => {
    const productsById = new Map(products.map((product) => [String(product.id), product]));
    const related = links.map((link) => ({ ...link, product: productsById.get(String(link.component_product_id)) })).filter((link) => link.product);
    if (!related.length) return resolve([]);
    const overlay = document.createElement("div");
    overlay.className = "quick-part-overlay";
    overlay.id = "motherPartSelectionOverlay";
    overlay.innerHTML = `<div class="quick-part-dialog mother-part-selection-dialog" role="dialog" aria-modal="true" aria-labelledby="motherPartSelectionTitle">
      <header><div><h2 id="motherPartSelectionTitle">Choose related parts for ${esc(motherProduct.sku)}</h2><p>The mother part will be issued. Select only the related parts that should also be added and deducted.</p></div></header>
      <div class="quick-part-body"><div class="table-wrap"><table class="mini-table"><thead><tr><th>Add</th><th>Related SKU</th><th>Product</th><th>On Hand</th><th>Qty per Mother</th><th>Total to Deduct</th></tr></thead><tbody>${related.map((link) => {
        const required = Number(link.quantity_required || 1);
        return `<tr><td><input type="checkbox" data-optional-mother-component="${esc(link.component_product_id)}"></td><td><strong>${esc(link.product.sku || "")}</strong></td><td>${esc(link.product.name || "")}</td><td>${esc(Number(link.product.qty || 0))}</td><td>${esc(required)}</td><td>${esc(Number((required * Number(motherQuantity || 0)).toFixed(4)))}</td></tr>`;
      }).join("")}</tbody></table></div><p class="notice">Nothing is selected by default. You may issue the mother part by itself.</p></div>
      <footer><button type="button" data-mother-selection-cancel>Cancel Issue</button><button type="button" data-mother-selection-none>Mother Part Only</button><button class="primary" type="button" data-mother-selection-save>Add Selected Parts</button></footer>
    </div>`;
    const finish = (value) => { overlay.remove(); resolve(value); };
    overlay.querySelector("[data-mother-selection-cancel]").onclick = () => finish(null);
    overlay.querySelector("[data-mother-selection-none]").onclick = () => finish([]);
    overlay.querySelector("[data-mother-selection-save]").onclick = () => finish([...overlay.querySelectorAll("[data-optional-mother-component]:checked")].map((input) => input.dataset.optionalMotherComponent));
    document.body.appendChild(overlay);
  });
}

