async function createQuickPartCategory() {
  const name = String(prompt("New product category") || "").trim();
  if (!name) return;
  try {
    const saved = await upsertOne("categories", { name }, "name");
    const categoryName = String(saved?.name || name).trim();
    productMeta.categories = [...new Set([...(productMeta.categories || []), categoryName])].sort((a, b) => a.localeCompare(b));
    const select = document.querySelector('[data-quick-part="category"]');
    if (select && ![...select.options].some((option) => option.value === categoryName)) select.add(new Option(categoryName, categoryName));
    if (select) select.value = categoryName;
  } catch (error) {
    alert(error.message || error);
  }
}

function closeQuickPartOverlay() {
  document.getElementById("quickPartOverlay")?.remove();
}

function normalizedPartNumber(value, ignoreZeros = false) {
  const compact = String(value || "").toUpperCase().replace(/[^A-Z0-9]/g, "");
  return ignoreZeros ? compact.replace(/0/g, "") : compact;
}

function partNumberEditDistance(left, right) {
  const a = normalizedPartNumber(left);
  const b = normalizedPartNumber(right);
  const rows = Array.from({ length: b.length + 1 }, (_, index) => index);
  for (let i = 1; i <= a.length; i += 1) {
    let previous = rows[0];
    rows[0] = i;
    for (let j = 1; j <= b.length; j += 1) {
      const saved = rows[j];
      rows[j] = Math.min(rows[j] + 1, rows[j - 1] + 1, previous + (a[i - 1] === b[j - 1] ? 0 : 1));
      previous = saved;
    }
  }
  return rows[b.length];
}

async function approveProductMasterCreation(record, editingProduct = null) {
  const products = await getAll("products");
  const candidates = products.filter((product) => String(product.id || "") !== String(editingProduct?.id || ""));
  const enteredSku = String(record.sku || "").trim();
  const exact = candidates.find((product) => String(product.sku || "").trim().toLowerCase() === enteredSku.toLowerCase());
  if (exact) {
    alert(`Duplicate part blocked.\n\n${exact.sku} - ${exact.name || "Product Master item"}\n\nSelect the existing part instead of creating another record.`);
    return false;
  }
  const compactSku = normalizedPartNumber(enteredSku);
  const zeroFreeSku = normalizedPartNumber(enteredSku, true);
  const similar = candidates.filter((product) => {
    const existingSku = normalizedPartNumber(product.sku);
    if (!compactSku || !existingSku) return false;
    if (compactSku === existingSku) return true;
    if (zeroFreeSku.length >= 3 && zeroFreeSku === normalizedPartNumber(product.sku, true)) return true;
    return Math.min(compactSku.length, existingSku.length) >= 4 && partNumberEditDistance(enteredSku, product.sku) <= 1;
  }).slice(0, 8);
  if (!similar.length) return true;
  const samePart = confirm(`Possible matching part${similar.length === 1 ? "" : "s"} found:\n\n${similar.map((product) => `• ${product.sku} - ${product.name || "Unnamed part"}${product.source_vendor ? ` | ${product.source_vendor}` : ""}`).join("\n")}\n\nIs the part you are creating the same as one shown above?\n\nOK = Yes, stop and use the existing part.\nCancel = No, this is a different part and continue creating it.`);
  return !samePart;
}

async function insertNewProduct(record) {
  const { data, error } = await supabase.from("products").insert(record).select().single();
  if (error) {
    if (/duplicate|unique|products.*sku/i.test(String(error.message || ""))) throw new Error(`SKU ${record.sku} already exists. Select the existing Product Master item.`);
    throw error;
  }
  return data;
}

async function saveQuickPartOverlay() {
  const overlay = document.getElementById("quickPartOverlay");
  if (!overlay) return;
  const record = {};
  overlay.querySelectorAll("[data-quick-part]").forEach((input) => record[input.dataset.quickPart] = input.value);
  record.status = "Active";
  record.qty = 0;
  record.expiry_date = null;
  ["qty", "reorder_point", "cost", "selling_price", "markup_percent"].forEach((key) => {
    record[key] = record[key] === "" || record[key] == null ? null : Number(record[key]);
  });
  const validation = validateProductRecord(record);
  if (validation) return alert(validation);
  const saveButton = overlay.querySelector("#saveQuickPartBtn");
  try {
    if (record.cost && record.markup_percent && !record.selling_price) {
      record.selling_price = Number((record.cost * (1 + record.markup_percent / 100)).toFixed(2));
      record.markup_percent = null;
    }
    if (record.source_vendor) {
      const vendor = await requirePartyMasterSelection("vendors", record.source_vendor, "a preferred vendor");
      if (!vendor) return;
      record.source_vendor = vendor.name;
    }
    if (!await approveProductMasterCreation(record)) return;
    saveButton.disabled = true;
    saveButton.textContent = "Saving...";
    const saved = await insertNewProduct(record);
    await incrementSequence("product");
    productMeta.products = [...(productMeta.products || []).filter((product) => product.id !== saved.id && String(product.sku || "").toLowerCase() !== String(saved.sku || "").toLowerCase()), saved]
      .sort((a, b) => String(a.sku || "").localeCompare(String(b.sku || ""), undefined, { numeric: true, sensitivity: "base" }));
    await writeAuditLog({ tableName: "products", action: "Created from transaction", beforeData: null, afterData: saved });
    closeQuickPartOverlay();
    alert(`${saved.sku} - ${saved.name} was created and is now available in the parts search.`);
  } catch (error) {
    alert(error.message || error);
    saveButton.disabled = false;
    saveButton.textContent = "Save part";
  }
}

function productInput(label, field, value, type = "text") {
  const masterSource = type === "text" ? partyMasterSuggestSource(field) : "";
  const pickerAttributes = masterSource ? `class="suggest-input" data-suggest-source="${masterSource}" autocomplete="off" inputmode="search" placeholder="Type name, reference, email, or phone"` : "";
  return `<div class="field"><label>${esc(label)}</label><input ${type === "number" ? 'step="0.01"' : ""} ${pickerAttributes} type="${type}" data-product-field="${field}" value="${esc(value)}">${masterSource ? `<small>Start typing to search ${masterSource === "customers" ? "Customer Master" : "Vendor Master"}.</small>` : ""}</div>`;
}

function partyMasterSuggestSource(field) {
  if (["customer", "customer_name", "bill_to_customer", "linked_customer"].includes(String(field || ""))) return "customers";
  if (["vendor", "source_vendor"].includes(String(field || ""))) return "vendors";
  return "";
}

function productSelect(label, field, values, value, quickLabel = "") {
  const listId = `${field}-${label}`.replace(/[^a-z0-9_-]/gi, "-");
  const unique = [...new Set((values || []).map((v) => String(v ?? "").trim()).filter(Boolean))];
  const masterSource = partyMasterSuggestSource(field);
  const pickerAttributes = masterSource ? `data-suggest-source="${masterSource}" inputmode="search"` : `list="${esc(listId)}"`;
  const datalist = masterSource ? "" : `<datalist id="${esc(listId)}">${unique.map((v) => `<option value="${esc(v)}"></option>`).join("")}</datalist>`;
  const helper = masterSource ? `<small>Start typing to search ${masterSource === "customers" ? "Customer Master" : "Vendor Master"} by reference, name, email, or phone.</small>` : "";
  return `<div class="field"><label>${esc(label)}</label><input class="suggest-input" ${pickerAttributes} data-product-field="${field}" value="${esc(value || "")}" placeholder="Type to search ${esc(label.toLowerCase())}" autocomplete="off">${datalist}${quickLabel ? `<button class="rowbtn" type="button" data-product-quick="${esc(field)}">${esc(quickLabel)}</button>` : ""}${helper}</div>`;
}

function alternateSkuRows(values) {
  const rows = [...values.map((r) => r.alternate_sku), "", "", "", "", ""].slice(0, Math.max(5, values.length + 2));
  return `<div class="table-wrap"><table class="mini-table"><thead><tr><th>Alternate Part #</th></tr></thead><tbody id="altSkuBody">${rows.map((sku, i) => altSkuRowHtml(sku, i)).join("")}</tbody></table></div><div class="actions table-actions"><button class="rowbtn" type="button" id="addAltSkuBtn">Add row</button></div><small>Search Product Master by Part #, name, alternate, cross-reference, or vendor.</small>`;
}

function crossReferenceRows(values = []) {
  const rows = [...values.map((row) => row.reference_no), "", "", "", "", ""].slice(0, Math.max(5, values.length + 2));
  return `<div class="table-wrap"><table class="mini-table"><thead><tr><th>Cross-reference Part #</th></tr></thead><tbody id="crossReferenceBody">${rows.map((value, index) => crossReferenceRowHtml(value, index)).join("")}</tbody></table></div><div class="actions table-actions"><button class="rowbtn" type="button" id="addCrossReferenceBtn">Add row</button></div><small>Search alias only. A cross-reference does not create or look up a separate Product Master record.</small>`;
}

function crossReferenceRowHtml(value = "", index = 0) {
  return `<tr><td><input data-cross-reference="${index}" value="${esc(value || "")}" placeholder="Manufacturer, vendor, or interchange Part #"></td></tr>`;
}

function addCrossReferenceRow() {
  const body = $("crossReferenceBody");
  if (!body) return;
  const index = document.querySelectorAll("[data-cross-reference]").length;
  body.insertAdjacentHTML("beforeend", crossReferenceRowHtml("", index));
  document.querySelector(`[data-cross-reference="${index}"]`)?.focus();
}

function altSkuRowHtml(sku = "", index = 0) {
  const product = resolveProductLookup(sku);
  const value = product ? `${product.sku} - ${product.name || ""}` : sku;
  return `<tr><td><input class="suggest-input" data-suggest-source="products" data-alt-sku="${index}" value="${esc(value || "")}" placeholder="Search compatible alternate Part #" autocomplete="off" inputmode="search"></td></tr>`;
}

function addAlternativeSkuRow() {
  const body = $("altSkuBody");
  if (!body) return;
  const index = document.querySelectorAll("[data-alt-sku]").length;
  body.insertAdjacentHTML("beforeend", altSkuRowHtml("", index));
  const inputs = document.querySelectorAll("[data-alt-sku]");
  inputs[inputs.length - 1]?.focus();
}

